function MCPV5CapabilityAuthority(plan, capability) {
  const field = MCPV5_CAPABILITY_PLAN_FIELDS[capability];
  return field && plan ? String(plan[field] || "") : "";
}

function MCPV5CapabilityRole(moduleId, capability, plan) {
  if (
    !plan ||
    !plan.effective ||
    plan.effective[moduleId] !== true ||
    !MCPV5ModuleCapabilities(moduleId).includes(capability)
  ) return "disabled";

  if (plan.dependencyOnly && plan.dependencyOnly[moduleId]) {
    return "observer";
  }

  const authority = MCPV5CapabilityAuthority(plan, capability);
  if (!authority || authority === moduleId) return "authority";
  return plan.authorityEnforcement === "Strict"
    ? "observer"
    : "contributor";
}

function MCPV5PrimaryContextRole(moduleId, plan) {
  const capability = MCPV5_PRIMARY_CONTEXT_CAPABILITY[moduleId];
  return capability
    ? MCPV5CapabilityRole(moduleId, capability, plan)
    : "contributor";
}

function MCPV5AutoCardsState() {
  const candidate = (
    state.LSIv2 && typeof state.LSIv2 === "object"
  ) ? state.LSIv2 : (
    state.AutoCards && typeof state.AutoCards === "object"
  ) ? state.AutoCards : null;
  return candidate && !Array.isArray(candidate) ? candidate : null;
}

function MCPV5AutoCardsTaskActive(plan) {
  if (
    !plan ||
    !plan.effective ||
    plan.effective.auto_cards !== true
  ) return false;

  const ac = MCPV5AutoCardsState();
  if (!ac) return false;

  const queued = !!(
    ac.generation &&
    Array.isArray(ac.generation.pending) &&
    ac.generation.pending.length
  );
  const workpiece = ac.generation && ac.generation.workpiece;
  const generation = !!(
    workpiece &&
    typeof workpiece === "object" &&
    !Array.isArray(workpiece) &&
    Object.keys(workpiece).length
  );
  const compression = !!(
    ac.compression &&
    typeof ac.compression.titleKey === "string" &&
    ac.compression.titleKey.length
  );
  return queued || generation || compression;
}

function MCPV5AutoCardsTransactionOwner(plan) {
  return (
    plan &&
    plan.effective &&
    plan.effective.inner_self === true &&
    !(plan.dependencyOnly && plan.dependencyOnly.inner_self)
  ) ? "inner_self" : "auto_cards";
}

function MCPV5InnerSelfTaskActive(plan) {
