function MCPV5HasVisibleText(value) {
  return (
    typeof value === "string" &&
    value.replace(/[\s\u200B-\u200D\uFEFF]/g, "").length > 0
  );
}


const MCPV5_PROTECTED_GLOBALS = new Set([
  "state", "storyCards", "history", "info", "text", "stop",
  "log", "console", "addStoryCard", "updateStoryCard",
  "removeStoryCard"
]);

const MCPV5_KNOWN_MUTABLE_GLOBALS = [
  "MainSettings", "InnerSelf", "AutoCards", "LiveScriptInterface",
  "InformationFirewall", "LivingCharacters", "ChaosGoblinV2",
  "CharacterContinuity", "raceNames", "modKeys", "race",
  "plotEssentials", "playerClass", "classNames"
];

function MCPV5SnapshotModuleGlobals(fullScan) {
  const keys = fullScan
    ? Object.getOwnPropertyNames(globalThis)
    : MCPV5_KNOWN_MUTABLE_GLOBALS.slice();
  const values = Object.create(null);
  const present = new Set();

  for (let i = 0; i < keys.length; i++) {
    const key = keys[i];
    if (
      MCPV5_PROTECTED_GLOBALS.has(key) ||
      key.startsWith("MCPV5")
    ) continue;
    if (Object.prototype.hasOwnProperty.call(globalThis, key)) {
      present.add(key);
      try { values[key] = globalThis[key]; } catch {}
    }
  }

  return {
    fullScan: !!fullScan,
    initialKeys: fullScan
      ? new Set(Object.getOwnPropertyNames(globalThis))
      : null,
    present,
    values
  };
}

function MCPV5RestoreModuleGlobals(snapshot) {
  if (!snapshot) return;

  if (snapshot.fullScan && snapshot.initialKeys) {
    const current = Object.getOwnPropertyNames(globalThis);
    for (let i = 0; i < current.length; i++) {
      const key = current[i];
      if (
        MCPV5_PROTECTED_GLOBALS.has(key) ||
        key.startsWith("MCPV5") ||
        snapshot.initialKeys.has(key)
      ) continue;
      try { delete globalThis[key]; } catch {}
    }
  }

  for (let i = 0; i < MCPV5_KNOWN_MUTABLE_GLOBALS.length; i++) {
    const key = MCPV5_KNOWN_MUTABLE_GLOBALS[i];
    if (snapshot.present.has(key)) {
      try { globalThis[key] = snapshot.values[key]; } catch {}
    } else {
      try { delete globalThis[key]; } catch {}
    }
  }
}

function MCPV5ModuleVaultKey(moduleId) {
  return moduleId === "inner_self" || moduleId === "auto_cards"
    ? "inner_package"
    : moduleId;
}

function MCPV5ActivateModuleGlobals(moduleId) {
  const key = MCPV5ModuleVaultKey(moduleId);
  const vault = MCPV5_MODULE_GLOBAL_VAULT[key];
  if (!vault) return;
  const names = Object.keys(vault);
  for (let i = 0; i < names.length; i++) {
    try { globalThis[names[i]] = vault[names[i]]; } catch {}
  }
}

function MCPV5StoreModuleGlobals(moduleId) {
  const key = MCPV5ModuleVaultKey(moduleId);
  const vault = Object.create(null);
  for (let i = 0; i < MCPV5_KNOWN_MUTABLE_GLOBALS.length; i++) {
    const name = MCPV5_KNOWN_MUTABLE_GLOBALS[i];
    if (Object.prototype.hasOwnProperty.call(globalThis, name)) {
      try { vault[name] = globalThis[name]; } catch {}
    }
  }

  // Some original modules intentionally create undeclared shared tables.
  // Capture those only when a complete diagnostic snapshot is available.
  const extra = [
    "raceNames", "modKeys", "race", "plotEssentials",
    "playerClass", "classNames"
  ];
  for (let i = 0; i < extra.length; i++) {
    const name = extra[i];
    if (Object.prototype.hasOwnProperty.call(globalThis, name)) {
      try { vault[name] = globalThis[name]; } catch {}
    }
  }
  MCPV5_MODULE_GLOBAL_VAULT[key] = vault;
}

function MCPV5HashString(value) {
  const source = String(value || "");
  let hash = 2166136261;
  for (let i = 0; i < source.length; i++) {
    hash ^= source.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16);
}

function MCPV5CloneStateValue(value, maxChars) {
  try {
    // Fast-path immutable JSON primitives. Keep a conservative escaped-string
    // bound so this never bypasses the original serialized-size limit.
    const cap = Number.isFinite(maxChars) ? maxChars : 300000;
    if (value === null || typeof value === "boolean") {
      return { ok: true, value };
    }
    if (typeof value === "number" && Number.isFinite(value)) {
      return { ok: true, value };
    }
    if (typeof value === "string" && value.length * 6 + 2 <= cap) {
      return { ok: true, value };
    }
    const json = JSON.stringify(value);
    if (
      typeof json !== "string" ||
      json.length > (Number.isFinite(maxChars) ? maxChars : 300000)
    ) {
      return { ok: false, value: null };
    }
    return { ok: true, value: JSON.parse(json) };
  } catch {
    return { ok: false, value: null };
  }
}

const MCPV5_ENGINE_STATE_KEYS = new Set([
  "memory", "message", "placeholders", "mcpCompatibilityHost",
  "mcpExactCollection"
]);

function MCPV5ModuleTrackedKeys(moduleId, snapshot) {
  const keys = (MCPV5_MODULE_STATE_KEYS[moduleId] || []).slice();
  const before = snapshot && Array.isArray(snapshot.__presentKeys)
    ? new Set(snapshot.__presentKeys)
    : new Set();
  const current = Object.keys(state);

  for (let i = 0; i < current.length; i++) {
    const key = current[i];
    if (
      before.has(key) ||
      MCPV5_ENGINE_STATE_KEYS.has(key) ||
      keys.includes(key)
    ) continue;
    keys.push(key);
  }
  return keys;
}

function MCPV5NormalizeModuleState(moduleId, snapshot) {
  const keys = MCPV5ModuleTrackedKeys(moduleId, snapshot);

  for (let i = 0; i < keys.length; i++) {
    const key = keys[i];
    if (!Object.prototype.hasOwnProperty.call(state, key)) continue;

    const clone = MCPV5CloneStateValue(state[key], 1800000);
    if (clone.ok) {
      state[key] = clone.value;
      continue;
    }

    const record = snapshot && snapshot[key];
    if (record && record.ok === true && record.exists) {
      state[key] = record.value;
    } else {
      try { delete state[key]; } catch {}
    }

    MCPV5RecordDiagnostic(
      "noncloneable-state-rolled-back",
      MCPV5Name(moduleId) + " / state." + key
    );
    return false;
  }
  return true;
}

function MCPV5NormalizeHostState() {
  if (
    !state.mcpCompatibilityHost ||
    typeof state.mcpCompatibilityHost !== "object"
  ) return true;

  const clone = MCPV5CloneStateValue(
    state.mcpCompatibilityHost,
    900000
  );
  if (!clone.ok) {
    const old = state.mcpCompatibilityHost;
    state.mcpCompatibilityHost = {
      version: MCPV5_VERSION,
      schemaVersion: MCPV5_SCHEMA_VERSION,
      buildVersion: MCPV5_BUILD_VERSION,
      enabled: old && old.enabled && typeof old.enabled === "object"
        ? Object.assign({}, old.enabled)
        : {},
      settings: old && old.settings && typeof old.settings === "object"
        ? Object.assign({}, old.settings)
        : {},
      status: "Host state recovered from a non-cloneable value.",
      conflictStatus: [],
      planSummary: [],
      lastNotice: "",
      diagnostics: [{
        action: Number.isFinite(info && info.actionCount)
          ? info.actionCount
          : -1,
        build: MCPV5_BUILD_VERSION,
        kind: "host-state-recovered",
        data: "Transient host bookkeeping was reset."
      }],
      scheduler: { actionCursor: 0 },
      timings: { input: {}, context: {}, output: {} },
      actionSchedule: null,
      transaction: null,
      inventoryLedger: {
        version: 2,
        pending: [],
        events: [],
        recent: [],
        items: {},
        currency: {},
        authority: "",
        action: -1,
        hash: ""
      }
    };
    return false;
  }

  state.mcpCompatibilityHost = clone.value;
  return true;
}


function MCPV5NormalizeSharedPersistentState() {
  if (
    state.memory &&
    typeof state.memory === "object" &&
    !Array.isArray(state.memory)
  ) {
    const clone = MCPV5CloneStateValue(state.memory, 700000);
    if (clone.ok) {
      state.memory = clone.value;
    } else {
      const safeMemory = {};
      for (const key of ["context", "authorsNote", "frontMemory"]) {
        if (typeof state.memory[key] === "string") {
          safeMemory[key] = state.memory[key];
        }
      }
      state.memory = safeMemory;
      MCPV5RecordDiagnostic(
        "noncloneable-memory-recovered",
        "Only string memory fields were retained."
      );
    }
  }

  if (
    Object.prototype.hasOwnProperty.call(state, "message") &&
    typeof state.message !== "string"
  ) {
    try {
      state.message = String(state.message == null ? "" : state.message);
    } catch {
      state.message = "";
    }
  }
}

function MCPV5SnapshotModuleState(moduleId) {
  const keys = MCPV5_MODULE_STATE_KEYS[moduleId] || [];
  const records = Object.create(null);
  records.__presentKeys = Object.keys(state);

  for (let i = 0; i < keys.length; i++) {
    const key = keys[i];
    const exists = Object.prototype.hasOwnProperty.call(state, key);
    if (!exists) {
      records[key] = { exists: false, ok: true, value: null };
      continue;
    }
    const clone = MCPV5CloneStateValue(state[key], 900000);
    records[key] = {
      exists: true,
      ok: clone.ok,
      value: clone.value
    };
  }
  return records;
}

function MCPV5RestoreModuleState(snapshot) {
  if (!snapshot) return;

  const before = Array.isArray(snapshot.__presentKeys)
    ? new Set(snapshot.__presentKeys)
    : null;
  if (before) {
    const current = Object.keys(state);
    for (let i = 0; i < current.length; i++) {
      const key = current[i];
      if (
        before.has(key) ||
        MCPV5_ENGINE_STATE_KEYS.has(key)
      ) continue;
      try { delete state[key]; } catch {}
    }
  }

  const keys = Object.keys(snapshot).filter(key => key !== "__presentKeys");
  for (let i = 0; i < keys.length; i++) {
    const key = keys[i];
    const record = snapshot[key];
    if (!record || record.ok !== true) continue;
    if (record.exists) {
      state[key] = record.value;
    } else {
      try { delete state[key]; } catch {}
    }
  }
}

function MCPV5Root() {
  if (
    !state.mcpCompatibilityHost ||
    typeof state.mcpCompatibilityHost !== "object" ||
    Array.isArray(state.mcpCompatibilityHost)
  ) {
    const oldEnabled = (
      state.mcpExactCollection &&
      typeof state.mcpExactCollection === "object" &&
      state.mcpExactCollection.enabled &&
      typeof state.mcpExactCollection.enabled === "object"
    ) ? state.mcpExactCollection.enabled : {};

    state.mcpCompatibilityHost = {
      version: MCPV5_VERSION,
      schemaVersion: MCPV5_SCHEMA_VERSION,
      buildVersion: MCPV5_BUILD_VERSION,
      enabled: Object.assign({}, oldEnabled),
      settings: {},
      status: "",
      conflictStatus: [],
      planSummary: [],
      lastNotice: "",
      diagnostics: [],
      scheduler: { actionCursor: 0 },
      timings: { input: {}, context: {}, output: {} },
      actionSchedule: null,
      transaction: null,
      inventoryLedger: {
        version: 2,
        pending: [],
        events: [],
        recent: [],
        items: {},
        currency: {},
        authority: "",
        action: -1,
        hash: ""
      }
    };
  }

  const root = state.mcpCompatibilityHost;

  if (!Number.isInteger(root.schemaVersion) || root.schemaVersion < 2) {
    const legacyScheduler = root.scheduler;
    root.scheduler = {
      actionCursor: legacyScheduler && Number.isInteger(legacyScheduler.input)
        ? Math.max(0, legacyScheduler.input)
        : 0
    };
    root.actionSchedule = null;
    root.timings = { input: {}, context: {}, output: {} };
    root.transaction = null;
    root.schemaVersion = 2;
  }

  if (root.schemaVersion < 3) {
    root.actionSchedule = null;
    root.transaction = null;
    if (
      !root.inventoryLedger ||
      typeof root.inventoryLedger !== "object" ||
      Array.isArray(root.inventoryLedger)
    ) {
      root.inventoryLedger = {};
    }
    root.inventoryLedger.version = 2;
    root.inventoryLedger.pending = [];
    root.inventoryLedger.events = Array.isArray(root.inventoryLedger.events)
      ? root.inventoryLedger.events.slice(-80)
      : [];
    root.inventoryLedger.recent = Array.isArray(root.inventoryLedger.recent)
      ? root.inventoryLedger.recent.slice(-20)
      : [];
    root.inventoryLedger.items = {};
    root.inventoryLedger.currency = {};
    root.schemaVersion = 3;
  }

  root.version = MCPV5_VERSION;
  root.schemaVersion = MCPV5_SCHEMA_VERSION;
  root.buildVersion = MCPV5_BUILD_VERSION;

  if (!root.enabled || typeof root.enabled !== "object" || Array.isArray(root.enabled)) {
    root.enabled = {};
  }
  if (!root.settings || typeof root.settings !== "object" || Array.isArray(root.settings)) {
    root.settings = {};
  }
  if (!Array.isArray(root.planSummary)) root.planSummary = [];
  if (!Array.isArray(root.conflictStatus)) root.conflictStatus = [];
  if (!Array.isArray(root.diagnostics)) root.diagnostics = [];
  if (!root.scheduler || typeof root.scheduler !== "object") {
    root.scheduler = { actionCursor: 0 };
  }
  if (!Number.isInteger(root.scheduler.actionCursor)) {
    root.scheduler.actionCursor = 0;
  }
  if (!root.timings || typeof root.timings !== "object") {
    root.timings = { input: {}, context: {}, output: {} };
  }
  for (const tab of ["input", "context", "output"]) {
    if (!root.timings[tab] || typeof root.timings[tab] !== "object") {
      root.timings[tab] = {};
    }
  }

  if (
    !root.inventoryLedger ||
    typeof root.inventoryLedger !== "object" ||
    Array.isArray(root.inventoryLedger)
  ) {
    root.inventoryLedger = {};
  }
  const ledger = root.inventoryLedger;
  ledger.version = 2;
  if (!Array.isArray(ledger.pending)) ledger.pending = [];
  if (!Array.isArray(ledger.events)) ledger.events = [];
  if (!Array.isArray(ledger.recent)) ledger.recent = [];
  if (!ledger.items || typeof ledger.items !== "object" || Array.isArray(ledger.items)) {
    ledger.items = {};
  }
  if (!ledger.currency || typeof ledger.currency !== "object" || Array.isArray(ledger.currency)) {
    ledger.currency = {};
  }
  ledger.pending = ledger.pending.slice(-36);
  ledger.events = ledger.events.slice(-80);
  ledger.recent = ledger.recent.slice(-20);

  const itemClone = MCPV5CloneStateValue(ledger.items, 300000);
  const currencyClone = MCPV5CloneStateValue(ledger.currency, 100000);
  ledger.items = itemClone.ok ? itemClone.value : {};
  ledger.currency = currencyClone.ok ? currencyClone.value : {};

  root.diagnostics = root.diagnostics.slice(-40);
  return root;
}

function MCPV5FindControlCardIndex() {
  if (!Array.isArray(storyCards)) return -1;
  return storyCards.findIndex(card => (
    card &&
    typeof card === "object" &&
    card.keys === MCPV5_CARD_KEYS
  ));
}

function MCPV5DefaultSettings() {
  return {
    compatibilityMode: "Balanced",
    policy: "Automatic",
    authorityEnforcement: "Balanced",
    inventoryAuthority: "Automatic",
    npcFactsAuthority: "Automatic",
    npcMindAuthority: "Automatic",
    npcActionAuthority: "Automatic",
    macroPacingAuthority: "Automatic",
    scenePacingAuthority: "Automatic",
    relationshipPacingAuthority: "Automatic",
    outcomeRollAuthority: "Automatic",
    workloadGuard: true,
    hookBudgetMs: 1450,
    hookSafetyMarginMs: 180,
    diagnostics: false
  };
}

function MCPV5DefaultEntry() {
  const enabled = {};
  for (let i = 0; i < MCPV5_PROFILE_ORDER.length; i++) {
    enabled[MCPV5_PROFILE_ORDER[i]] = false;
  }
  return MCPV5CanonicalEntry(
    enabled,
    MCPV5DefaultSettings(),
    null,
    "No scripts enabled."
  );
}

function MCPV5EnsureControlCard() {
  let index = MCPV5FindControlCardIndex();

  if (index < 0 && typeof addStoryCard === "function") {
    try {
      addStoryCard(MCPV5_CARD_KEYS, MCPV5DefaultEntry(), MCPV5_CARD_TYPE);
    } catch (error) {
      log("MCP V5 control card create error:", error);
    }
    index = MCPV5FindControlCardIndex();
  }

  if (index < 0 || !storyCards[index]) return null;
  const card = storyCards[index];

  try { card.title = MCPV5_CARD_TITLE; } catch {}
  try {
    card.description = (
      "Edit toggles in Entry. Balanced is recommended. Leave authorities on Automatic unless needed."
    );
  } catch {}

  return card;
}

function MCPV5EscapeRegExp(value) {
  return String(value || "").replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function MCPV5ReadBoolean(entry, label, fallback) {
  const match = String(entry || "").match(
    new RegExp(
      "^\\s*" + MCPV5EscapeRegExp(label) +
      "\\s*:\\s*(true|false)\\s*$",
      "im"
    )
  );
  return match ? match[1].toLowerCase() === "true" : fallback;
}

function MCPV5ReadString(entry, label, fallback) {
  const match = String(entry || "").match(
    new RegExp(
      "^\\s*" + MCPV5EscapeRegExp(label) +
      "\\s*:\\s*(.*?)\\s*$",
      "im"
    )
  );
  return match && match[1] ? match[1].trim() : fallback;
}

function MCPV5ReadInteger(entry, label, fallback, lower, upper) {
  const raw = MCPV5ReadString(entry, label, String(fallback));
  const value = parseInt(String(raw).replace(/[^\d-]/g, ""), 10);
  if (!Number.isFinite(value)) return fallback;
  return Math.min(Math.max(lower, value), upper);
}

function MCPV5NormalizeChoice(value, allowed, fallback) {
  const target = String(value || "").trim().toLowerCase();
  for (let i = 0; i < allowed.length; i++) {
    if (allowed[i].toLowerCase() === target) return allowed[i];
  }
  return fallback;
}

function MCPV5ProfileIdFromName(value) {
  const target = String(value || "").trim().toLowerCase();
  if (!target || target === "automatic") return "";
  for (let i = 0; i < MCPV5_PROFILE_ORDER.length; i++) {
    const id = MCPV5_PROFILE_ORDER[i];
    if (
      id.toLowerCase() === target ||
      MCPV5_PROFILE_NAMES[id].toLowerCase() === target
    ) return id;
  }
  return "";
}

function MCPV5Choose(enabled, preferredName, priorities) {
  const preferred = MCPV5ProfileIdFromName(preferredName);
  if (preferred && enabled[preferred] === true && priorities.includes(preferred)) {
    return preferred;
  }
  for (let i = 0; i < priorities.length; i++) {
    if (enabled[priorities[i]] === true) return priorities[i];
  }
  return "";
}

function MCPV5BuildPlan(enabled, settings) {
  const selected = MCPV5_PROFILE_ORDER.filter(id => enabled[id] === true);
  const effective = Object.assign({}, enabled);
  const dependencies = [];
  const dependencyOnly = {};

  // Stackable Inventory keeps its original bundled Inner Self dependency,
  // but the dependency does not become a separately scheduled module or win
  // unrelated capability elections.
  if (enabled.stackable_inventory === true && effective.inner_self !== true) {
    effective.inner_self = true;
    dependencyOnly.inner_self = true;
    dependencies.push("Inner Self (private Stackable Inventory dependency)");
  }

  const mode = MCPV5NormalizeChoice(
    settings.compatibilityMode,
    ["Legacy Exact", "Balanced", "Strict"],
    "Balanced"
  );
  const cooperative = mode !== "Legacy Exact" && selected.length > 1;
  const enforcement = mode === "Strict"
    ? "Strict"
    : mode === "Legacy Exact"
    ? "Advisory"
    : settings.authorityEnforcement;

  const plan = {
    selected,
    effective,
    dependencyOnly,
    dependencies,
    cooperative,
    mode,
    policy: mode === "Legacy Exact" ? "Legacy Sequential" : "Automatic",
    authorityEnforcement: enforcement,
    inventoryAuthority: MCPV5Choose(
      enabled,
      settings.inventoryAuthority,
      ["stackable_inventory", "true_auto_stats", "realmheart"]
    ),
    inventoryCardAuthority: MCPV5Choose(
      enabled,
      settings.inventoryAuthority,
      ["stackable_inventory", "realmheart"]
    ),
    statsAuthority: enabled.true_auto_stats === true
      ? "true_auto_stats"
      : "",
    economyAuthority: enabled.realmheart === true
      ? "realmheart"
      : "",
    storyCardAuthority: enabled.auto_cards === true
      ? "auto_cards"
      : "",
    npcFactsAuthority: MCPV5Choose(
      enabled,
      settings.npcFactsAuthority,
      ["character_continuity", "living_characters", "inner_self"]
    ),
    npcMindAuthority: MCPV5Choose(
      enabled,
      settings.npcMindAuthority,
      ["inner_self", "living_characters", "character_continuity"]
    ),
    npcActionAuthority: MCPV5Choose(
      enabled,
      settings.npcActionAuthority,
      ["living_characters", "inner_self", "character_continuity"]
    ),
    macroPacingAuthority: MCPV5Choose(
      enabled,
      settings.macroPacingAuthority,
      ["story_arc_engine", "narrative_governor"]
    ),
    scenePacingAuthority: MCPV5Choose(
      enabled,
      settings.scenePacingAuthority,
      ["narrative_governor", "story_arc_engine"]
    ),
    relationshipPacingAuthority: MCPV5Choose(
      enabled,
      settings.relationshipPacingAuthority,
      ["slow_burn", "narrative_governor"]
    ),
    outcomeRollAuthority: MCPV5Choose(
      enabled,
      settings.outcomeRollAuthority,
      ["dice_roll", "coin_flip"]
    ),
    inventoryCardCooperative: false,
    overlaps: {},
    capabilityRoles: {}
  };

  const cardOwners = MCPV5_INVENTORY_CARD_MODULES.filter(
    id => enabled[id] === true
  );
  plan.inventoryCardCooperative = cooperative && cardOwners.length > 1;

  plan.overlaps.inventory = [
    "true_auto_stats", "stackable_inventory", "realmheart"
  ].filter(id => enabled[id] === true);
  plan.overlaps.npc = [
    "inner_self", "living_characters", "character_continuity"
  ].filter(id => enabled[id] === true);
  plan.overlaps.pacing = [
    "story_arc_engine", "narrative_governor", "slow_burn"
  ].filter(id => enabled[id] === true);
  plan.overlaps.outcome = [
    "dice_roll", "coin_flip"
  ].filter(id => enabled[id] === true);

  for (let i = 0; i < selected.length; i++) {
    const id = selected[i];
    const roles = {};
    const caps = MCPV5ModuleCapabilities(id);
    for (let c = 0; c < caps.length; c++) {
      roles[caps[c]] = MCPV5CapabilityRole(id, caps[c], plan);
    }
    plan.capabilityRoles[id] = roles;
  }

  return plan;
}

function MCPV5Name(id) {
  return id && MCPV5_PROFILE_NAMES[id]
    ? MCPV5_PROFILE_NAMES[id]
    : "None";
}

function MCPV5PlanSummary(plan) {
  if (!plan || !plan.selected.length) return ["No active compatibility plan."];

  const lines = [
    "Mode: " + plan.mode,
    "Authority enforcement: " + plan.authorityEnforcement,
    "Inventory: " + MCPV5Name(plan.inventoryAuthority),
    "Stats: " + MCPV5Name(plan.statsAuthority),
    "Economy: " + MCPV5Name(plan.economyAuthority),
    "Character facts: " + MCPV5Name(plan.npcFactsAuthority),
    "NPC mind: " + MCPV5Name(plan.npcMindAuthority),
    "NPC action: " + MCPV5Name(plan.npcActionAuthority),
    "Macro pacing: " + MCPV5Name(plan.macroPacingAuthority),
    "Scene pacing: " + MCPV5Name(plan.scenePacingAuthority),
    "Relationship pacing: " + MCPV5Name(plan.relationshipPacingAuthority),
    "Outcome roll: " + MCPV5Name(plan.outcomeRollAuthority),
    "Visible output: Compatibility Host broker"
  ];

  if (plan.dependencies.length) {
    lines.push("Private dependencies: " + plan.dependencies.join(", "));
  }
  if (plan.inventoryCardCooperative) {
    lines.push(
      "Inventory cards: virtualized; visible authority = " +
      MCPV5Name(plan.inventoryCardAuthority)
    );
  }
  return lines.slice(0, 16);
}

function MCPV5ConflictStatus(plan) {
  if (!plan || !plan.selected.length) return ["No active overlaps."];

  const lines = [];
  const inventory = plan.overlaps.inventory || [];
  const npc = plan.overlaps.npc || [];
  const pacing = plan.overlaps.pacing || [];
  const outcome = plan.overlaps.outcome || [];

  if (inventory.length > 1) {
    lines.push(
      "Resolved: inventory Story Card ownership (" +
      MCPV5Name(plan.inventoryCardAuthority || plan.inventoryAuthority) + ")."
    );
    lines.push(
      "Resolved: inventory changes are normalized into one capped action ledger."
    );
  }
  if (npc.length > 1) {
    lines.push(
      "Resolved: NPC facts, mind, and action use separate authorities."
    );
  }
  if (pacing.length > 1) {
    lines.push(
      "Resolved: macro, scene, and relationship pacing use separate authorities."
    );
  }
  if (outcome.length > 1) {
    lines.push(
      "Resolved: one Outcome Roll authority decorates each visible response (" +
      MCPV5Name(plan.outcomeRollAuthority) + ")."
    );
  }
  if (plan.mode === "Legacy Exact" && (inventory.length > 1 || npc.length > 1 || pacing.length > 1 || outcome.length > 1)) {
    lines.push("Warning: Legacy Exact permits original sequential overlap.");
  }
  if (!lines.length) lines.push("No overlapping capability groups selected.");
  return lines.slice(0, 8);
}

function MCPV5CanonicalEntry(enabled, settings, plan, status) {
  const LIMIT = MCPV5_CONTROL_ENTRY_LIMIT;
  const enabledNames = [];
  for (let i = 0; i < MCPV5_PROFILE_ORDER.length; i++) {
    const id = MCPV5_PROFILE_ORDER[i];
    if (enabled[id] === true) enabledNames.push(MCPV5_PROFILE_NAMES[id]);
  }

  const field = (value, fallback, max) => {
    const clean = String(value === undefined || value === null ? fallback : value)
      .replace(/[\r\n\t]+/g, " ")
      .replace(/\s{2,}/g, " ")
      .trim();
    return (clean || String(fallback)).slice(0, Math.max(1, max || 40));
  };

  const bool = value => value === true ? "true" : "false";

  const prefixLines = [
    "╔══════════════════════════════════════════════════════╗",
    "║              MASTER SCRIPT CONTROL PANEL             ║",
    "╚══════════════════════════════════════════════════════╝",
    "Build 5.4.0  •  " + enabledNames.length + "/" + MCPV5_PROFILE_ORDER.length + " scripts enabled",
    "",
    "⚡ QUICK ACTIONS",
    "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━",
    "# One-shot switches. They reset to false after being applied.",
    "Enable All: false",
    "Disable All: false",
    "",
    "🧩 SCRIPT TOGGLES",
    "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━",
    "# CHARACTERS • MEMORY • CONTINUITY",
    "Inner Self: " + bool(enabled.inner_self),
    "Auto-Cards: " + bool(enabled.auto_cards),
    "Living Characters: " + bool(enabled.living_characters),
    "Character Continuity: " + bool(enabled.character_continuity),
    "Slow Burn: " + bool(enabled.slow_burn),
    "",
    "# STORY • WORLD • PACING",
    "Story Card Extension: " + bool(enabled.story_card_extension),
    "Story Arc Engine: " + bool(enabled.story_arc_engine),
    "Narrative Governor: " + bool(enabled.narrative_governor),
    "",
    "# GAMEPLAY • RESOURCES • INVENTORY",
    "Living Meters: " + bool(enabled.living_meters),
    "True Automatic Stats: " + bool(enabled.true_auto_stats),
    "Stackable Inventory: " + bool(enabled.stackable_inventory),
    "RealmHeart: " + bool(enabled.realmheart),
    "",
    "# OUTPUT CLEANUP • OUTCOME",
    "# AR/USC-E clean prose. Dice/Coin are mutually arbitrated.",
    "AR: " + bool(enabled.ar),
    "USC-E: " + bool(enabled.usc_e),
    "Dice Roll: " + bool(enabled.dice_roll),
    "Coin Flip: " + bool(enabled.coin_flip),
    "",
    "🛡️ RECOMMENDED COMPATIBILITY SETTINGS",
    "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━",
    "# Recommended for mixed-script setups: Balanced / Balanced / true.",
    "Compatibility Mode: " + field(settings.compatibilityMode, "Balanced", 24),
    "Authority Enforcement: " + field(settings.authorityEnforcement, "Balanced", 24),
    "Workload Guard: " + bool(settings.workloadGuard),
    "",
    "🎛️ ADVANCED AUTHORITY SETTINGS",
    "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━",
    "# Usually leave these on Automatic.",
    "Compatibility Policy: " + field(settings.policy, "Automatic", 24),
    "Inventory Authority: " + field(settings.inventoryAuthority, "Automatic", 40),
    "NPC Facts Authority: " + field(settings.npcFactsAuthority, "Automatic", 40),
    "NPC Mind Authority: " + field(settings.npcMindAuthority, "Automatic", 40),
    "NPC Action Authority: " + field(settings.npcActionAuthority, "Automatic", 40),
    "Macro Pacing Authority: " + field(settings.macroPacingAuthority, "Automatic", 40),
    "Scene Pacing Authority: " + field(settings.scenePacingAuthority, "Automatic", 40),
    "Relationship Pacing Authority: " + field(settings.relationshipPacingAuthority, "Automatic", 40),
    "Outcome Roll Authority: " + field(settings.outcomeRollAuthority, "Automatic", 40),
    "",
    "⏱️ PERFORMANCE & TROUBLESHOOTING",
    "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━",
    "# Defaults are safe for most adventures. Diagnostics adds host logging.",
    "Hook Budget Milliseconds: " + Math.max(1, Number(settings.hookBudgetMs) || 1450),
    "Hook Safety Margin Milliseconds: " + Math.max(0, Number(settings.hookSafetyMarginMs) || 180),
    "Diagnostics: " + bool(settings.diagnostics),
    "",
    "📊 LIVE STATUS",
    "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"
  ];

  const cleanOneLine = (value, fallback) => {
    const clean = String(value === undefined || value === null ? fallback : value)
      .replace(/[\r\n\t]+/g, " ")
      .replace(/\s{2,}/g, " ")
      .trim();
    return clean || fallback;
  };

  let statusText = enabledNames.length
    ? cleanOneLine(status, "Ready.")
    : "No scripts enabled.";
  let enabledText = enabledNames.length ? enabledNames.join(", ") : "None";

  let planText = "No active compatibility plan.";
  let checkText = "No active overlaps.";

  if (plan && Array.isArray(plan.selected) && plan.selected.length) {
    const summary = MCPV5PlanSummary(plan);
    if (summary.length) planText = summary.join(" | ");
    const conflicts = MCPV5ConflictStatus(plan);
    if (conflicts.length) checkText = conflicts.join(" | ");
  }

  const buildTail = () => [
    "Status: " + statusText,
    "Enabled Scripts: " + enabledText,
    "",
    "CURRENT PLAN",
    "• " + planText,
    "",
    "COMPATIBILITY CHECK",
    "• " + checkText
  ].join("\n");

  const prefix = prefixLines.join("\n") + "\n";
  let tail = buildTail();

  if ((prefix + tail).length > LIMIT) {
    const fixedTailChars = buildTail()
      .length - statusText.length - enabledText.length - planText.length - checkText.length;
    let room = Math.max(4, LIMIT - prefix.length - fixedTailChars);

    const desired = [statusText, enabledText, planText, checkText];
    const minimum = [18, 18, 18, 18];
    const clipped = [];

    for (let i = 0; i < desired.length; i++) {
      const remainingMin = minimum.slice(i + 1).reduce((a, b) => a + b, 0);
      const allowance = Math.max(minimum[i], room - remainingMin);
      const value = desired[i];
      if (value.length <= allowance) {
        clipped.push(value);
        room -= value.length;
      } else {
        const use = Math.max(4, allowance);
        clipped.push(value.slice(0, use - 3).trimEnd() + "...");
        room -= use;
      }
    }

    statusText = clipped[0];
    enabledText = clipped[1];
    planText = clipped[2];
    checkText = clipped[3];
    tail = buildTail();
  }

  return (prefix + tail).slice(0, LIMIT);
}

function MCPV5WriteControlCard(card, entry) {
  if (!card || card.entry === entry) return;
  const index = storyCards.indexOf(card);
  if (index < 0) return;

  try {
    updateStoryCard(
      index,
      MCPV5_CARD_KEYS,
      MCPV5SafeText(entry, " "),
      MCPV5_CARD_TYPE
    );
  } catch (error) {
    log("MCP V5 control card update error:", error);
  }
}

function MCPV5SyncControls() {
  const root = MCPV5Root();
  const card = MCPV5EnsureControlCard();

  if (!card) {
    root.enabled = {};
    root.status = "Control card unavailable.";
    return MCPV5BuildPlan({}, MCPV5DefaultSettings());
  }

  const entry = MCPV5SafeText(card.entry, MCPV5DefaultEntry());
  const enableAll = MCPV5ReadBoolean(entry, "Enable All", false);
  const disableAll = MCPV5ReadBoolean(entry, "Disable All", false);
  const enabled = {};

  for (let i = 0; i < MCPV5_PROFILE_ORDER.length; i++) {
    const id = MCPV5_PROFILE_ORDER[i];
    enabled[id] = disableAll
      ? false
      : enableAll
      ? true
      : MCPV5ReadBoolean(entry, MCPV5_PROFILE_NAMES[id], false);
  }

  const defaults = MCPV5DefaultSettings();
  const legacyPolicy = MCPV5NormalizeChoice(
    MCPV5ReadString(entry, "Compatibility Policy", defaults.policy),
    ["Automatic", "Legacy Sequential"],
    defaults.policy
  );
  const inferredMode = legacyPolicy === "Legacy Sequential"
    ? "Legacy Exact"
    : defaults.compatibilityMode;
  const compatibilityMode = MCPV5NormalizeChoice(
    MCPV5ReadString(entry, "Compatibility Mode", inferredMode),
    ["Legacy Exact", "Balanced", "Strict"],
    inferredMode
  );

  const settings = {
    compatibilityMode,
    policy: compatibilityMode === "Legacy Exact"
      ? "Legacy Sequential"
      : "Automatic",
    authorityEnforcement: MCPV5NormalizeChoice(
      MCPV5ReadString(
        entry,
        "Authority Enforcement",
        compatibilityMode === "Strict"
          ? "Strict"
          : defaults.authorityEnforcement
      ),
      ["Advisory", "Balanced", "Strict"],
      compatibilityMode === "Strict"
        ? "Strict"
        : defaults.authorityEnforcement
    ),
    inventoryAuthority: MCPV5ReadString(
      entry, "Inventory Authority", defaults.inventoryAuthority
    ),
    npcFactsAuthority: MCPV5ReadString(
      entry, "NPC Facts Authority", defaults.npcFactsAuthority
    ),
    npcMindAuthority: MCPV5ReadString(
      entry, "NPC Mind Authority", defaults.npcMindAuthority
    ),
    npcActionAuthority: MCPV5ReadString(
      entry, "NPC Action Authority", defaults.npcActionAuthority
    ),
    macroPacingAuthority: MCPV5ReadString(
      entry, "Macro Pacing Authority", defaults.macroPacingAuthority
    ),
    scenePacingAuthority: MCPV5ReadString(
      entry, "Scene Pacing Authority", defaults.scenePacingAuthority
    ),
    relationshipPacingAuthority: MCPV5ReadString(
      entry,
      "Relationship Pacing Authority",
      defaults.relationshipPacingAuthority
    ),
    outcomeRollAuthority: MCPV5ReadString(
      entry,
      "Outcome Roll Authority",
      defaults.outcomeRollAuthority
    ),
    workloadGuard: MCPV5ReadBoolean(
      entry, "Workload Guard", defaults.workloadGuard
    ),
    hookBudgetMs: MCPV5ReadInteger(
      entry,
      "Hook Budget Milliseconds",
      defaults.hookBudgetMs,
      500,
      1800
    ),
    hookSafetyMarginMs: MCPV5ReadInteger(
      entry,
      "Hook Safety Margin Milliseconds",
      defaults.hookSafetyMarginMs,
      80,
      400
    ),
    diagnostics: MCPV5ReadBoolean(
      entry, "Diagnostics", defaults.diagnostics
    )
  };

  if (compatibilityMode === "Strict") {
    settings.authorityEnforcement = "Strict";
  } else if (compatibilityMode === "Legacy Exact") {
    settings.authorityEnforcement = "Advisory";
  }

  const plan = MCPV5BuildPlan(enabled, settings);
  const status = plan.selected.length
    ? (
        "Enabled (" + plan.selected.length + "): " +
        plan.selected.map(MCPV5Name).join(", ")
      )
    : "No scripts enabled.";

  root.enabled = enabled;
  root.settings = settings;
  root.status = status;
  root.planSummary = MCPV5PlanSummary(plan).slice(0, 16);
  root.conflictStatus = MCPV5ConflictStatus(plan).slice(0, 8);

  MCPV5WriteControlCard(
    card,
    MCPV5CanonicalEntry(enabled, settings, plan, status)
  );

  if (disableAll && root.lastNotice !== "disable-all") {
    root.lastNotice = "disable-all";
    try { state.message = "All MCP V5 scripts disabled."; } catch {}
  } else if (enableAll && root.lastNotice !== "enable-all") {
    root.lastNotice = "enable-all";
    try { state.message = "All MCP V5 scripts enabled."; } catch {}
  } else if (!enableAll && !disableAll) {
    root.lastNotice = "";
  }

  MCPV5_ACTIVE_PLAN = plan;
  return plan;
}

function MCPV5InventoryMarker(moduleId) {
  return moduleId === "stackable_inventory"
    ? "__MCPV5_SIS_INVENTORY__"
    : "__MCPV5_REALMHEART_INVENTORY__";
}

function MCPV5InventoryOwner(keys) {
  const value = String(keys || "");
  if (value.includes("__MCPV5_SIS_INVENTORY__")) {
    return "stackable_inventory";
  }
  if (value.includes("__MCPV5_REALMHEART_INVENTORY__")) {
    return "realmheart";
  }
  return "";
}

function MCPV5IsPlainInventoryKey(keys) {
  return String(keys || "").trim().toLowerCase() === "inventory";
}

function MCPV5InventoryPhysicalKey(moduleId, visible) {
  const marker = MCPV5InventoryMarker(moduleId);
  return visible ? ("Inventory," + marker) : marker;
}

function MCPV5PrepareInventoryCards(plan) {
  if (!plan || !Array.isArray(storyCards)) return;

  const selectedOwners = MCPV5_INVENTORY_CARD_MODULES.filter(
    id => plan.effective[id] === true
  );

  if (!plan.inventoryCardCooperative) {
    if (selectedOwners.length === 1) {
      const owner = selectedOwners[0];
      const marked = storyCards.find(card => (
        card &&
        typeof card === "object" &&
        MCPV5InventoryOwner(card.keys) === owner
      ));
      const plain = storyCards.find(card => (
        card &&
        typeof card === "object" &&
        MCPV5IsPlainInventoryKey(card.keys)
      ));
      const target = plain || marked;
      if (target && marked === target) {
        try { target.keys = "Inventory"; } catch {}
      }
    }
    return;
  }

  const authority = plan.inventoryCardAuthority || selectedOwners[0] || "";
  const plain = storyCards.find(card => (
    card &&
    typeof card === "object" &&
    MCPV5IsPlainInventoryKey(card.keys)
  ));

  if (plain && authority) {
    try {
      plain.keys = MCPV5InventoryPhysicalKey(authority, true);
    } catch {}
  }

  for (let i = 0; i < storyCards.length; i++) {
    const card = storyCards[i];
    if (!card || typeof card !== "object") continue;
    const owner = MCPV5InventoryOwner(card.keys);
    if (!owner) continue;
    const shouldBeVisible = owner === authority;
    const wanted = MCPV5InventoryPhysicalKey(owner, shouldBeVisible);
    if (card.keys !== wanted) {
      try { card.keys = wanted; } catch {}
    }
  }
}


function MCPV5StoryCardExtensionState() {
  if (
    !state.mcpStoryCardExtension ||
    typeof state.mcpStoryCardExtension !== "object" ||
    Array.isArray(state.mcpStoryCardExtension)
  ) {
    state.mcpStoryCardExtension = {};
  }
  return state.mcpStoryCardExtension;
}

function MCPV5StoryCardExtensionStateView() {
  return new Proxy(Object.create(null), {
    get(_target, property) {
      return MCPV5StoryCardExtensionState()[property];
    },
    set(_target, property, value) {
      MCPV5StoryCardExtensionState()[property] = value;
      return true;
    },
    deleteProperty(_target, property) {
      try { delete MCPV5StoryCardExtensionState()[property]; } catch {}
      return true;
    },
    has(_target, property) {
      return property in MCPV5StoryCardExtensionState();
    }
  });
}

function MCPV5HideFromStoryCardExtension(card) {
  if (!card || typeof card !== "object") return false;
  const keys = String(card.keys || "");
  const title = String(card.title || "").trim();
  const lowerKeys = keys.toLowerCase();
  const lowerTitle = title.toLowerCase();

  // Host/control/private machine cards are never lore-recall candidates.
  if (keys === MCPV5_CARD_KEYS || title === MCPV5_CARD_TITLE) return true;
  if (keys === "%RM%" || title === "⚙️ Living Meters") return true;
  if (keys === "[CONFIG] Banned words") return true;
  if (lowerTitle === "gambling hall" && String(card.type || "").toLowerCase() === "realmheart") return true;
  if (
    typeof card.entry === "string" &&
    card.entry.includes("Evolution Stages") &&
    /Character Name\s*:/i.test(card.entry)
  ) return true;
  if (typeof card.entry === "string" && card.entry.includes("# Put phrases in this story card to remove them.")) return true;
  if (keys.startsWith("__CC_STABLE_CARD__:")) return true;
  if (lowerKeys.startsWith("lc-thoughts:")) return true;
  if (lowerKeys.startsWith("chaos-v2:")) return true;
  if ([
    "living-characters-config",
    "living-characters-relationships",
    "living-thoughts-config",
    "lc-debug"
  ].includes(lowerKeys)) return true;
  if (
    lowerKeys.includes('"agent"') ||
    lowerTitle === "configure inner self" ||
    lowerTitle === "configure auto-cards" ||
    lowerTitle === "edit to enable auto-cards" ||
    lowerTitle === "debug data" ||
    lowerTitle === "critical data"
  ) return true;
  if (
    lowerTitle === "cc — settings" ||
    lowerTitle === "cc — status" ||
    lowerTitle === "cc — debug" ||
    lowerTitle === "cc — active npcs" ||
    lowerTitle === "player's identity"
  ) return true;
  return false;
}

function MCPV5CreateCardSandbox(moduleId) {
  const actualCards = MCPV5_NATIVE_STORY_CARDS;
  const proxyCache = new Map();
  const rawByProxy = new Map();
  const arrayTarget = [];
  const objectSnapshots = new Map();
  let arraySnapshot = null;

  function isCooperative() {
    return !!(
      MCPV5_ACTIVE_PLAN &&
      MCPV5_ACTIVE_PLAN.inventoryCardCooperative
    );
  }

  function inventoryAuthority() {
    return (
      MCPV5_ACTIVE_PLAN &&
      MCPV5_ACTIVE_PLAN.inventoryCardAuthority
    ) || "stackable_inventory";
  }

  function moduleIsInventoryOwner() {
    return MCPV5_INVENTORY_CARD_MODULES.includes(moduleId);
  }

  function visibleInventoryOwner() {
    return moduleIsInventoryOwner() ? moduleId : inventoryAuthority();
  }

  function recordArray() {
    if (!arraySnapshot) arraySnapshot = actualCards.slice();
  }

  function recordObject(card) {
    if (
      !card ||
      typeof card !== "object" ||
      objectSnapshots.has(card)
    ) return;
    const snapshot = Object.create(null);
    const keys = Object.keys(card);
    for (let i = 0; i < keys.length; i++) {
      snapshot[keys[i]] = card[keys[i]];
    }
    objectSnapshots.set(card, snapshot);
  }

  function translateKeys(keys) {
    if (!MCPV5IsPlainInventoryKey(keys) || !isCooperative()) {
      return keys;
    }
    const owner = visibleInventoryOwner();
    const visible = owner === inventoryAuthority();
    return MCPV5InventoryPhysicalKey(owner, visible);
  }

  function isVisible(card) {
    if (!card || typeof card !== "object") return false;
    if (
      moduleId === "story_card_extension" &&
      MCPV5HideFromStoryCardExtension(card)
    ) return false;
    if (!isCooperative()) return true;
    const owner = MCPV5InventoryOwner(card.keys);
    if (!owner) {
      return !MCPV5IsPlainInventoryKey(card.keys);
    }
    return owner === visibleInventoryOwner();
  }

  function logicalKeys(card) {
    if (!card || typeof card !== "object") return "";
    const owner = MCPV5InventoryOwner(card.keys);
    if (owner && owner === visibleInventoryOwner()) return "Inventory";
    return card.keys;
  }

  function normalizeInsertedCard(value) {
    if (!value || typeof value !== "object") return value;

    // SCE intentionally pushes a new plain card object and then continues
    // editing that same reference. Preserve that identity inside its module
    // transaction; makeCloneSafe() detaches non-cloneable data before commit.
    const proxiedRaw = rawByProxy.get(value);
    if (moduleId === "story_card_extension" && !proxiedRaw) {
      if (Object.prototype.hasOwnProperty.call(value, "keys")) {
        value.keys = translateKeys(value.keys);
      }
      return value;
    }

    // Never place one of this sandbox's Proxy wrappers into the physical
    // Story Card array. Detach all other inserted objects into ordinary data.
    const raw = proxiedRaw || value;
    const clone = MCPV5CloneStateValue(raw, 350000);
    value = clone.ok ? clone.value : {
      keys: MCPV5SafeText(raw.keys, " "),
      entry: MCPV5SafeText(raw.entry, " "),
      type: typeof raw.type === "string" ? raw.type : ""
    };

    if (Object.prototype.hasOwnProperty.call(value, "keys")) {
      value.keys = translateKeys(value.keys);
    }
    if (
      MCPV5InventoryOwner(value.keys) &&
      (!value.title || value.title === "Inventory")
    ) {
      value.title = "Inventory";
    }
    return value;
  }

  function cardProxy(card) {
    if (!card || typeof card !== "object") return card;
    if (proxyCache.has(card)) return proxyCache.get(card);

    const proxy = new Proxy(card, {
      get(target, property) {
        if (property === "keys") return logicalKeys(target);
        return target[property];
      },
      set(target, property, value) {
        recordObject(target);
        target[property] = property === "keys"
          ? translateKeys(value)
          : value;
        return true;
      },
      deleteProperty(target, property) {
        recordObject(target);
        try { delete target[property]; } catch {}
        return true;
      },
      defineProperty(target, property, descriptor) {
        recordObject(target);
        const next = Object.assign({}, descriptor);
        if (property === "keys" && "value" in next) {
          next.value = translateKeys(next.value);
        }
        try { Object.defineProperty(target, property, next); } catch {}
        return true;
      }
    });

    proxyCache.set(card, proxy);
    rawByProxy.set(proxy, card);
    return proxy;
  }

  function visibleState() {
    const refs = [];
    const cards = [];
    const actualIndexes = [];

    for (let i = 0; i < actualCards.length; i++) {
      const card = actualCards[i];
      if (!isVisible(card)) continue;
      refs.push(card);
      cards.push(cardProxy(card));
      actualIndexes.push(i);
    }
    try { arrayTarget.length = cards.length; } catch {}
    return { refs, cards, actualIndexes };
  }

  function normalizeIndex(value, length, allowEnd) {
    let index = Number(value);
    if (!Number.isFinite(index)) index = 0;
    index = Math.trunc(index);
    if (index < 0) index = Math.max(0, length + index);
    const max = allowEnd ? length : Math.max(0, length - 1);
    return Math.min(Math.max(0, index), max);
  }

  function physicalInsertIndex(visibleIndex, stateView) {
    if (!stateView.actualIndexes.length) return actualCards.length;
    if (visibleIndex >= stateView.actualIndexes.length) {
      return stateView.actualIndexes[stateView.actualIndexes.length - 1] + 1;
    }
    return stateView.actualIndexes[Math.max(0, visibleIndex)];
  }

  function spliceVisible(startValue, deleteValue) {
    const stateView = visibleState();
    const length = stateView.cards.length;
    const start = normalizeIndex(startValue, length, true);
    const deleteCount = arguments.length < 2
      ? length - start
      : Math.min(
          Math.max(0, Math.trunc(Number(deleteValue) || 0)),
          length - start
        );
    const items = Array.prototype.slice.call(arguments, 2)
      .map(normalizeInsertedCard);
    const removed = stateView.cards.slice(start, start + deleteCount);

    recordArray();
    const removalIndexes = stateView.actualIndexes
      .slice(start, start + deleteCount)
      .sort((a, b) => b - a);

    for (let i = 0; i < removalIndexes.length; i++) {
      actualCards.splice(removalIndexes[i], 1);
    }

    const refreshed = visibleState();
    const insertAt = physicalInsertIndex(start, refreshed);
    if (items.length) {
      actualCards.splice.apply(actualCards, [insertAt, 0].concat(items));
    }
    return removed;
  }

  function reorderVisible(sortedProxies) {
    const stateView = visibleState();
    if (sortedProxies.length !== stateView.refs.length) return;
    const raws = sortedProxies.map(value => rawByProxy.get(value) || value);
    recordArray();
    for (let i = 0; i < stateView.actualIndexes.length; i++) {
      actualCards[stateView.actualIndexes[i]] = raws[i];
    }
  }

  const arrayProxy = new Proxy(arrayTarget, {
    get(target, property) {
      const stateView = visibleState();

      if (property === "length") return stateView.cards.length;
      if (property === Symbol.iterator) {
        return stateView.cards[Symbol.iterator].bind(stateView.cards);
      }
      if (property === "__mcpPhysicalCards") return actualCards;
      if (property === "__mcpSandboxModule") return moduleId;

      if (typeof property === "string" && /^\d+$/.test(property)) {
        return stateView.cards[Number(property)];
      }

      if (property === "push") {
        return function () {
          const items = Array.prototype.slice.call(arguments);
          spliceVisible.apply(null, [stateView.cards.length, 0].concat(items));
          return visibleState().cards.length;
        };
      }
      if (property === "unshift") {
        return function () {
          const items = Array.prototype.slice.call(arguments);
          spliceVisible.apply(null, [0, 0].concat(items));
          return visibleState().cards.length;
        };
      }
      if (property === "pop") {
        return function () {
          const now = visibleState();
          if (!now.cards.length) return undefined;
          return spliceVisible(now.cards.length - 1, 1)[0];
        };
      }
      if (property === "shift") {
        return function () {
          const now = visibleState();
          if (!now.cards.length) return undefined;
          return spliceVisible(0, 1)[0];
        };
      }
      if (property === "splice") {
        return function () {
          return spliceVisible.apply(null, arguments);
        };
      }
      if (property === "sort") {
        return function (compareFn) {
          const sorted = visibleState().cards.slice().sort(compareFn);
          reorderVisible(sorted);
          return arrayProxy;
        };
      }
      if (property === "reverse") {
        return function () {
          const reversed = visibleState().cards.slice().reverse();
          reorderVisible(reversed);
          return arrayProxy;
        };
      }
      if (property === "copyWithin") {
        return function () {
          const copied = visibleState().cards.slice();
          Array.prototype.copyWithin.apply(copied, arguments);
          reorderVisible(copied);
          return arrayProxy;
        };
      }
      if (property === "fill") {
        return function (value, start, end) {
          const copied = visibleState().cards.slice();
          copied.fill(normalizeInsertedCard(value), start, end);
          reorderVisible(copied);
          return arrayProxy;
        };
      }

      const native = Array.prototype[property];
      if (typeof native === "function") {
        return function () {
          const current = visibleState().cards;
          return native.apply(current, arguments);
        };
      }
      return target[property];
    },

    set(target, property, value) {
      if (property === "length") {
        const wanted = Math.max(0, Math.trunc(Number(value) || 0));
        const now = visibleState();
        if (wanted < now.cards.length) {
          spliceVisible(wanted, now.cards.length - wanted);
        } else {
          while (visibleState().cards.length < wanted) {
            spliceVisible(visibleState().cards.length, 0, undefined);
          }
        }
        return true;
      }

      if (typeof property === "string" && /^\d+$/.test(property)) {
        const index = Number(property);
        const now = visibleState();
        if (index < now.cards.length) {
          recordArray();
          actualCards[now.actualIndexes[index]] = normalizeInsertedCard(value);
        } else {
          while (visibleState().cards.length < index) {
            spliceVisible(visibleState().cards.length, 0, undefined);
          }
          spliceVisible(index, 0, value);
        }
        return true;
      }

      target[property] = value;
      return true;
    },

    deleteProperty(target, property) {
      if (typeof property === "string" && /^\d+$/.test(property)) {
        const index = Number(property);
        const now = visibleState();
        if (index < now.cards.length) spliceVisible(index, 1);
        return true;
      }
      try { delete target[property]; } catch {}
      return true;
    },

    has(target, property) {
      if (property === "length") return true;
      if (typeof property === "string" && /^\d+$/.test(property)) {
        return Number(property) < visibleState().cards.length;
      }
      return property in target;
    },

    ownKeys() {
      const length = visibleState().cards.length;
      const keys = [];
      for (let i = 0; i < length; i++) keys.push(String(i));
      keys.push("length");
      return keys;
    },

    getOwnPropertyDescriptor(target, property) {
      if (property === "length") {
        return {
          configurable: false,
          enumerable: false,
          writable: true,
          value: visibleState().cards.length
        };
      }
      if (typeof property === "string" && /^\d+$/.test(property)) {
        const index = Number(property);
        const cards = visibleState().cards;
        if (index < cards.length) {
          return {
            configurable: true,
            enumerable: true,
            writable: true,
            value: cards[index]
          };
        }
      }
      return Object.getOwnPropertyDescriptor(target, property);
    }
  });

  function viewIndexForActualIndex(actualIndex) {
    if (!Number.isInteger(actualIndex) || actualIndex < 0) return false;
    const stateView = visibleState();
    const index = stateView.actualIndexes.indexOf(actualIndex);
    return index < 0 ? false : index;
  }

  function add(keys, entry, type) {
    if (typeof MCPV5_NATIVE_ADD_STORY_CARD !== "function") return false;
    recordArray();
    const physicalKeys = translateKeys(keys);
    const extra = Array.prototype.slice.call(arguments, 3);
    const result = MCPV5_NATIVE_ADD_STORY_CARD.apply(
      null,
      [physicalKeys, MCPV5SafeText(entry, " "), type].concat(extra)
    );
    if (result === false) return false;

    // Preserve both supported addStoryCard return modes. Most scripts expect
    // the new card's array index; Inner Self requests the card object itself
    // with { returnCard: true }. V5.2.1 incorrectly treated that object as an
    // array index, leaving the initialized brain card detached from its Agent.
    const returnedRaw = (
      result &&
      typeof result === "object"
    ) ? (rawByProxy.get(result) || result) : null;
    const actualIndex = returnedRaw
      ? actualCards.indexOf(returnedRaw)
      : (Number.isInteger(result) ? result : -1);
    if (
      moduleId === "living_meters" &&
      actualIndex >= 0 &&
      actualCards[actualIndex] &&
      typeof actualCards[actualIndex] === "object"
    ) {
      if (typeof extra[0] === "string" && extra[0].length) {
        try { actualCards[actualIndex].title = extra[0]; } catch {}
      }
      if (typeof extra[1] === "string") {
        try { actualCards[actualIndex].description = extra[1]; } catch {}
      }
    }

    const options = extra.length ? extra[extra.length - 1] : null;
    const wantsCard = !!(
      options &&
      typeof options === "object" &&
      options.returnCard === true
    );

    if (
      MCPV5IsPlainInventoryKey(keys) &&
      actualIndex >= 0 &&
      actualCards[actualIndex] &&
      typeof actualCards[actualIndex] === "object"
    ) {
      try { actualCards[actualIndex].title = "Inventory"; } catch {}
    }

    if (wantsCard) {
      const card = actualIndex >= 0
        ? actualCards[actualIndex]
        : returnedRaw;
      return card && typeof card === "object"
        ? cardProxy(card)
        : false;
    }

    if (actualIndex >= 0) {
      return viewIndexForActualIndex(actualIndex);
    }
    return returnedRaw ? cardProxy(returnedRaw) : false;
  }

  function update(index, keys, entry, type) {
    if (typeof MCPV5_NATIVE_UPDATE_STORY_CARD !== "function") {
      throw new Error("updateStoryCard unavailable");
    }
    const stateView = visibleState();
    let actualIndex = stateView.actualIndexes[index];

    // Compatibility fallback for original scripts that accidentally pass a
    // Story Card id instead of the required array index.
    if (!Number.isInteger(actualIndex)) {
      actualIndex = actualCards.findIndex(card => (
        card &&
        typeof card === "object" &&
        card.id === index &&
        isVisible(card)
      ));
    }
    if (!Number.isInteger(actualIndex) || actualIndex < 0) {
      throw new Error("Story Card index does not exist");
    }

    recordArray();
    recordObject(actualCards[actualIndex]);
    const extra = Array.prototype.slice.call(arguments, 4);
    return MCPV5_NATIVE_UPDATE_STORY_CARD.apply(
      null,
      [
        actualIndex,
        translateKeys(keys),
        MCPV5SafeText(entry, " "),
        type
      ].concat(extra)
    );
  }

  function remove(index) {
    if (typeof MCPV5_NATIVE_REMOVE_STORY_CARD !== "function") {
      throw new Error("removeStoryCard unavailable");
    }
    const stateView = visibleState();
    let actualIndex = stateView.actualIndexes[index];

    if (!Number.isInteger(actualIndex)) {
      actualIndex = actualCards.findIndex(card => (
        card &&
        typeof card === "object" &&
        card.id === index &&
        isVisible(card)
      ));
    }
    if (!Number.isInteger(actualIndex) || actualIndex < 0) {
      throw new Error("Story Card index does not exist");
    }

    recordArray();
    return MCPV5_NATIVE_REMOVE_STORY_CARD(actualIndex);
  }

  function makeCloneSafe() {
    const candidates = [];
    const seen = new Set();

    if (arraySnapshot) {
      for (let i = 0; i < actualCards.length; i++) candidates.push(i);
    } else {
      objectSnapshots.forEach((_, card) => {
        const index = actualCards.indexOf(card);
        if (index >= 0) candidates.push(index);
      });
    }

    const replacements = [];
    for (let i = 0; i < candidates.length; i++) {
      const index = candidates[i];
      if (seen.has(index)) continue;
      seen.add(index);

      const raw = rawByProxy.get(actualCards[index]) || actualCards[index];
      const clone = MCPV5CloneStateValue(raw, 500000);
      if (!clone.ok) {
        MCPV5RecordDiagnostic(
          "noncloneable-card-rolled-back",
          MCPV5Name(moduleId) + " / card index " + index
        );
        return false;
      }
      replacements.push([index, raw, clone.value]);
    }

    for (let i = 0; i < replacements.length; i++) {
      const index = replacements[i][0];
      const raw = replacements[i][1];
      const clean = replacements[i][2];

      // Preserve object identity so original modules that retain a card
      // reference across hooks do not point at a detached stale object.
      if (raw && typeof raw === "object" && !Array.isArray(raw)) {
        try {
          const oldKeys = Object.keys(raw);
          for (let k = 0; k < oldKeys.length; k++) {
            if (!Object.prototype.hasOwnProperty.call(clean, oldKeys[k])) {
              delete raw[oldKeys[k]];
            }
          }
          const cleanKeys = Object.keys(clean);
          for (let k = 0; k < cleanKeys.length; k++) {
            raw[cleanKeys[k]] = clean[cleanKeys[k]];
          }
          actualCards[index] = raw;
          continue;
        } catch {}
      }
      actualCards[index] = clean;
    }
    return true;
  }

  function commit() {
    arraySnapshot = null;
    objectSnapshots.clear();
  }

  function rollback() {
    objectSnapshots.forEach((snapshot, card) => {
      const currentKeys = Object.keys(card);
      for (let i = 0; i < currentKeys.length; i++) {
        if (!Object.prototype.hasOwnProperty.call(snapshot, currentKeys[i])) {
          try { delete card[currentKeys[i]]; } catch {}
        }
      }
      const keys = Object.keys(snapshot);
      for (let i = 0; i < keys.length; i++) {
        try { card[keys[i]] = snapshot[keys[i]]; } catch {}
      }
    });

    if (arraySnapshot) {
      actualCards.splice.apply(
        actualCards,
        [0, actualCards.length].concat(arraySnapshot)
      );
    }
    commit();
  }

  const api = {
    storyCards: arrayProxy,
    addStoryCard: add,
    updateStoryCard: update,
    removeStoryCard: remove,
    makeCloneSafe,
    commit,
    rollback,
    refresh() { return visibleState().cards; }
  };

  MCPV5_CARD_SANDBOXES[moduleId] = api;
  return api;
}

function MCPV5SnapshotSharedState() {
  const memoryExists = !!(
    state.memory &&
    typeof state.memory === "object" &&
    !Array.isArray(state.memory)
  );

  return {
    memoryExists,
    memory: memoryExists ? Object.assign({}, state.memory) : null,
    messageExists: Object.prototype.hasOwnProperty.call(state, "message"),
    message: state.message
  };
}

function MCPV5RestoreSharedState(snapshot) {
  if (!snapshot) return;
  if (snapshot.memoryExists) {
    state.memory = Object.assign({}, snapshot.memory);
  } else {
    try { delete state.memory; } catch { state.memory = {}; }
  }

  if (snapshot.messageExists) {
    state.message = snapshot.message;
  } else {
    try { delete state.message; } catch {}
  }
}

function MCPV5ClassifySharedMemoryChange(base, value) {
  const source = typeof base === "string" ? base : "";
  const next = typeof value === "string" ? value : "";

  if (next === source) return null;
  if (!next && source) {
    return { mode: "remove", before: "", after: "", text: "" };
  }
  if (!source && next) {
    return { mode: "append", before: "", after: next.trim(), text: "" };
  }
  if (next.startsWith(source)) {
    return {
      mode: "append",
      before: "",
      after: next.slice(source.length).trim(),
      text: ""
    };
  }
  if (next.endsWith(source)) {
    return {
      mode: "prepend",
      before: next.slice(0, next.length - source.length).trim(),
      after: "",
      text: ""
    };
  }

  const sourceIndex = next.indexOf(source);
  if (sourceIndex !== -1) {
    return {
      mode: "surround",
      before: next.slice(0, sourceIndex).trim(),
      after: next.slice(sourceIndex + source.length).trim(),
      text: ""
    };
  }

  return { mode: "replace", before: "", after: "", text: next.trim() };
}

function MCPV5UniqueStrings(values) {
  const seen = new Set();
  const out = [];
  for (let i = 0; i < values.length; i++) {
    const value = String(values[i] || "").trim();
    if (!value || seen.has(value)) continue;
    seen.add(value);
    out.push(value);
  }
  return out;
}

function MCPV5TrimTextBoundary(value, cap, keepEnd) {
  const source = String(value || "");
  if (!Number.isFinite(cap) || cap <= 0) return "";
  if (source.length <= cap) return source;

  let out = keepEnd ? source.slice(-cap) : source.slice(0, cap);
  const boundary = keepEnd
    ? out.search(/(?:^|[\n.!?]\s+)/)
    : Math.max(
        out.lastIndexOf("\n"),
        out.lastIndexOf(". "),
        out.lastIndexOf("! "),
        out.lastIndexOf("? ")
      );

  if (keepEnd && boundary > 0 && boundary < Math.floor(cap * 0.35)) {
    out = out.slice(boundary).trimStart();
  } else if (!keepEnd && boundary > Math.floor(cap * 0.55)) {
    out = out.slice(0, boundary + 1).trimEnd();
  }
  return out;
}

function MCPV5MemoryBudget() {
  if (!Number.isFinite(info && info.maxChars)) return 1800;
  const maxChars = Math.max(0, Math.floor(info.maxChars));
  const used = Number.isFinite(info && info.memoryLength)
    ? Math.max(0, Math.floor(info.memoryLength))
    : 0;
  const reserve = Math.max(250, Math.floor(maxChars * 0.08));
  const remaining = Math.max(0, maxChars - used - reserve);
  return Math.min(5000, Math.floor(remaining * 0.25));
}

function MCPV5DeduplicateMemoryField(field, value) {
  let source = String(value || "").replace(/\r/g, "").trim();
  if (!source) return "";

  if (field === "authorsNote") {
    const markerPattern = /\[[^\]\n]{1,120}'s State:\s*[^\]\n]{0,400}\(\s*-?\d+(?:\.\d+)?\s*\/\s*100\s*\)\]/g;
    const markers = source.match(markerPattern) || [];
    if (markers.length) {
      source = source.replace(markerPattern, "").trim();
      source = source
        ? source + "\n\n" + markers[markers.length - 1].trim()
        : markers[markers.length - 1].trim();
    }
  }

  const paragraphs = source
    .split(/\n{2,}/)
    .map(value => value.trim())
    .filter(Boolean);
  const seen = new Set();
  const out = [];

  for (let i = 0; i < paragraphs.length; i++) {
    const key = paragraphs[i].replace(/\s+/g, " ").toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(paragraphs[i]);
  }
  return out.join("\n\n");
}

const MCPV5_LM_FRONT_MEMORY_BEGIN = "<LM_FRONT_MEMORY>";
const MCPV5_LM_FRONT_MEMORY_END = "</LM_FRONT_MEMORY>";
const MCPV5_CC_FRONT_MEMORY_BEGIN = "<CC_FRONT_MEMORY>";
const MCPV5_CC_FRONT_MEMORY_END = "</CC_FRONT_MEMORY>";

function MCPV5StripOwnedFrontMemoryBlock(value, begin, end) {
  const source = String(value || "");
  const esc = text => text.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return source
    .replace(new RegExp(esc(begin) + "[\\s\\S]*?" + esc(end), "g"), "")
    .replace(/\n{3,}/g, "\n\n")
    .trimEnd();
}

function MCPV5ExtractOwnedFrontMemoryBlock(value, begin, end) {
  const source = String(value || "");
  const esc = text => text.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const match = source.match(
    new RegExp(esc(begin) + "[\\s\\S]*?" + esc(end))
  );
  return match ? match[0].trim() : "";
}

function MCPV5StripKnownOwnedFrontMemory(value) {
  return MCPV5StripOwnedFrontMemoryBlock(
    MCPV5StripOwnedFrontMemoryBlock(
      value,
      MCPV5_LM_FRONT_MEMORY_BEGIN,
      MCPV5_LM_FRONT_MEMORY_END
    ),
    MCPV5_CC_FRONT_MEMORY_BEGIN,
    MCPV5_CC_FRONT_MEMORY_END
  ).trim();
}

function MCPV5ComposeOwnedFrontMemory(baseValue, records, plan) {
  const source = String(baseValue || "");
  let lmBlock = MCPV5ExtractOwnedFrontMemoryBlock(
    source,
    MCPV5_LM_FRONT_MEMORY_BEGIN,
    MCPV5_LM_FRONT_MEMORY_END
  );
  let ccBlock = MCPV5ExtractOwnedFrontMemoryBlock(
    source,
    MCPV5_CC_FRONT_MEMORY_BEGIN,
    MCPV5_CC_FRONT_MEMORY_END
  );
  let external = MCPV5StripKnownOwnedFrontMemory(source);
  let handled = !!(lmBlock || ccBlock);

  const prepends = [];
  const appends = [];
  const replacements = [];

  for (let i = 0; i < records.length; i++) {
    const record = records[i] || {};
    const snap = record.after;
    const value = (
      snap &&
      snap.memoryExists &&
      snap.memory &&
      typeof snap.memory.frontMemory === "string"
    ) ? snap.memory.frontMemory : source;

    if (record.id === "living_meters") {
      const nextBlock = MCPV5ExtractOwnedFrontMemoryBlock(
        value,
        MCPV5_LM_FRONT_MEMORY_BEGIN,
        MCPV5_LM_FRONT_MEMORY_END
      );
      if (nextBlock || lmBlock) {
        lmBlock = nextBlock;
        handled = true;
      }
    }

    if (record.id === "character_continuity") {
      const nextBlock = MCPV5ExtractOwnedFrontMemoryBlock(
        value,
        MCPV5_CC_FRONT_MEMORY_BEGIN,
        MCPV5_CC_FRONT_MEMORY_END
      );
      if (nextBlock || ccBlock) {
        ccBlock = nextBlock;
        handled = true;
      }
    }

    const externalValue = MCPV5StripKnownOwnedFrontMemory(value);
    const change = MCPV5ClassifySharedMemoryChange(
      MCPV5StripKnownOwnedFrontMemory(source),
      externalValue
    );
    if (!change) continue;

    if (change.mode === "replace" || change.mode === "remove") {
      replacements.push({
        id: record.id || "",
        text: change.mode === "remove" ? "" : change.text,
        score: MCPV5AuthorityScore(record.id || "", plan)
      });
    } else {
      if (change.before) prepends.push(change.before);
      if (change.after) appends.push(change.after);
    }
  }

  replacements.sort((a, b) => b.score - a.score);
  if (replacements.length) external = replacements[0].text;

  const uniquePrepends = MCPV5UniqueStrings(prepends)
    .filter(value => !external.includes(value));
  const uniqueAppends = MCPV5UniqueStrings(appends)
    .filter(value => !external.includes(value));
  if (uniquePrepends.length) {
    external = uniquePrepends.join("\n\n") + (external ? "\n\n" + external : "");
  }
  if (uniqueAppends.length) {
    external = external
      ? external + "\n\n" + uniqueAppends.join("\n\n")
      : uniqueAppends.join("\n\n");
  }

  const parts = [external.trim(), lmBlock, ccBlock].filter(Boolean);
  return {
    handled,
    text: parts.join("\n\n")
  };
}

function MCPV5NormalizeLivingMetersFrontMemory(beforeValue) {
  if (
    !state.memory ||
    typeof state.memory !== "object" ||
    Array.isArray(state.memory) ||
    typeof state.memory.frontMemory !== "string"
  ) return;

  const before = String(beforeValue || "");
  const after = String(state.memory.frontMemory || "");
  if (after === before) return;

  const external = MCPV5StripOwnedFrontMemoryBlock(
    before,
    MCPV5_LM_FRONT_MEMORY_BEGIN,
    MCPV5_LM_FRONT_MEMORY_END
  ).trim();
  const rawDirective = MCPV5StripOwnedFrontMemoryBlock(
    after,
    MCPV5_LM_FRONT_MEMORY_BEGIN,
    MCPV5_LM_FRONT_MEMORY_END
  ).trim();
  if (!rawDirective) {
    state.memory.frontMemory = external;
    return;
  }

  const block = [
    MCPV5_LM_FRONT_MEMORY_BEGIN,
    rawDirective,
    MCPV5_LM_FRONT_MEMORY_END
  ].join("\n");
  state.memory.frontMemory = external
    ? external + "\n\n" + block
    : block;
}

function MCPV5CommitSharedState(base, records, plan) {
  if (!base || !Array.isArray(records) || !records.length) return;

  const memory = base.memoryExists
    ? Object.assign({}, base.memory)
    : {};
  const fields = ["context", "authorsNote", "frontMemory"];
  const totalBudget = MCPV5MemoryBudget();
  const contextCap = Math.floor(totalBudget * 0.55);
  const authorsCap = Math.floor(totalBudget * 0.25);
  const fieldCaps = {
    context: contextCap,
    authorsNote: authorsCap,
    frontMemory: Math.max(0, totalBudget - contextCap - authorsCap)
  };

  for (let f = 0; f < fields.length; f++) {
    const field = fields[f];
    const baseValue = typeof memory[field] === "string" ? memory[field] : "";

    if (field === "frontMemory") {
      const owned = MCPV5ComposeOwnedFrontMemory(baseValue, records, plan);
      if (owned.handled) {
        // CC v2.02 and the MMS Living Meters wrapper use atomic tagged blocks.
        // Never truncate through one of those blocks: both modules budget their
        // own payloads, and broken begin/end markers make later ownership
        // recovery unsafe.
        memory[field] = owned.text;
        continue;
      }
    }

    const prepends = [];
    const appends = [];
    const replacements = [];

    for (let i = 0; i < records.length; i++) {
      const snap = records[i].after;
      const value = (
        snap &&
        snap.memoryExists &&
        snap.memory &&
        typeof snap.memory[field] === "string"
      ) ? snap.memory[field] : "";

      const change = MCPV5ClassifySharedMemoryChange(baseValue, value);
      if (!change) continue;

      if (change.mode === "replace" || change.mode === "remove") {
        replacements.push({
          id: records[i].id || "",
          text: change.mode === "remove" ? "" : change.text,
          mode: change.mode,
          score: MCPV5AuthorityScore(records[i].id || "", plan)
        });
      } else {
        if (change.before) prepends.push(change.before);
        if (change.after) appends.push(change.after);
      }
    }

    replacements.sort((a, b) => b.score - a.score);
    const replacement = replacements.length ? replacements[0] : null;
    let merged = replacement ? replacement.text : baseValue;
    const cap = fieldCaps[field];

    if (replacement && replacements.length > 1) {
      for (let i = 1; i < replacements.length; i++) {
        if (replacements[i].text !== replacement.text) {
          MCPV5RecordDiagnostic(
            "shared-memory-conflict",
            field + ": " + MCPV5Name(replacements[i].id) +
            " deferred to " + MCPV5Name(replacement.id)
          );
        }
      }
    }

    if (cap > 0) {
      const uniquePrepends = MCPV5UniqueStrings(prepends)
        .filter(value => !merged.includes(value));
      const uniqueAppends = MCPV5UniqueStrings(appends)
        .filter(value => !merged.includes(value));

      const prependBudget = uniquePrepends.length && uniqueAppends.length
        ? Math.floor(cap * 0.4)
        : cap;
      const prependText = uniquePrepends.length
        ? MCPV5TrimTextBoundary(
            uniquePrepends.join("\n\n"),
            prependBudget,
            false
          )
        : "";

      const remaining = Math.max(0, cap - prependText.length);
      const appendText = uniqueAppends.length
        ? MCPV5TrimTextBoundary(
            uniqueAppends.join("\n\n"),
            remaining,
            field === "frontMemory"
          )
        : "";

      if (prependText && !merged.includes(prependText)) {
        merged = merged ? prependText + "\n\n" + merged : prependText;
      }
      if (appendText && !merged.includes(appendText)) {
        merged = merged ? merged + "\n\n" + appendText : appendText;
      }
    }

    merged = MCPV5DeduplicateMemoryField(field, merged);

    // The broker may add no more than its exact field allocation. Existing
    // user content is not shortened merely because it already exceeds it.
    const maximum = Math.max(baseValue.length, baseValue.length + cap);
    if (maximum > 0 && merged.length > maximum) {
      merged = MCPV5TrimTextBoundary(
        merged,
        maximum,
        field === "frontMemory"
      );
    }

    if (merged !== baseValue || replacement) {
      memory[field] = merged;
    }

    if (replacement) {
      MCPV5RecordDiagnostic(
        replacement.mode === "remove"
          ? "shared-memory-removal"
          : "shared-memory-replacement",
        MCPV5Name(replacement.id) + " changed " + field + "."
      );
    }
  }

  // Preserve clone-safe nonstandard memory fields, last writer wins.
  for (let i = 0; i < records.length; i++) {
    const snap = records[i].after;
    if (!snap || !snap.memoryExists || !snap.memory) continue;
    const keys = Object.keys(snap.memory);
    for (let k = 0; k < keys.length; k++) {
      const key = keys[k];
      if (fields.includes(key)) continue;
      const clone = MCPV5CloneStateValue(snap.memory[key], 120000);
      if (clone.ok) memory[key] = clone.value;
    }
  }

  if (Object.keys(memory).length) state.memory = memory;

  const messages = [];
  for (let i = 0; i < records.length; i++) {
    const snap = records[i].after;
    if (
      snap &&
      snap.messageExists &&
      typeof snap.message === "string" &&
      snap.message.trim() &&
      snap.message !== base.message
    ) {
      messages.push(snap.message.trim());
    }
  }

  const uniqueMessages = MCPV5UniqueStrings(messages);
  if (uniqueMessages.length) {
    state.message = MCPV5TrimTextBoundary(
      uniqueMessages.join("\n"),
      1200,
      false
    );
  } else if (base.messageExists) {
    state.message = base.message;
  }
}

function MCPV5TrackSharedMemoryOwnership(base, records) {
  if (!base || !Array.isArray(records) || !records.length) return;
  const root = MCPV5Root();
  const memory = state.memory && typeof state.memory === "object"
    ? state.memory : {};
  const previous = root.memoryOwnership &&
    typeof root.memoryOwnership === "object" ? root.memoryOwnership : {};
  const next = {};
  for (const field of ["context", "authorsNote", "frontMemory"]) {
    const baseline = base.memory && typeof base.memory[field] === "string"
      ? base.memory[field] : "";
    const contributors = [];
    for (const record of records) {
      const snap = record && record.after;
      if (!snap || !snap.memory || typeof snap.memory[field] !== "string") continue;
      if (snap.memory[field] !== baseline && !contributors.includes(record.id)) {
        contributors.push(record.id);
      }
    }
    next[field] = contributors.length ? {
      action: Number.isFinite(info && info.actionCount) ? info.actionCount : -1,
      contributors: contributors.slice(0, 16),
      committedHash: MCPV5HashString(memory[field] || "")
    } : previous[field] || null;
  }
  root.memoryOwnership = next;
}

function MCPV5FitContext(candidate, before) {
  const next = MCPV5SafeText(candidate, before);
  if (!Number.isFinite(info && info.maxChars) || info.maxChars < 500) {
    return next;
  }

  const budget = Math.max(500, Math.floor(info.maxChars));
  if (next.length <= budget) return next;

  const base = MCPV5SafeText(before, "\u200B");

  // Never truncate AI Dungeon's original context. Only module additions may be
  // reduced; AI Dungeon remains responsible for trimming its own base context.
  if (base.length >= budget) return base;

  const position = next.indexOf(base);
  if (position < 0) {
    MCPV5RecordDiagnostic(
      "context-structural-overflow",
      "Rejected structural rewrite larger than info.maxChars."
    );
    return base;
  }

  const prefix = next.slice(0, position);
  const suffix = next.slice(position + base.length);
  const room = Math.max(0, budget - base.length);
  if (!room) return base;

  const totalAdded = prefix.length + suffix.length;
  if (!totalAdded) return base;

  const prefixCap = Math.floor(room * (prefix.length / totalAdded));
  const suffixCap = Math.max(0, room - prefixCap);
  const fittedPrefix = MCPV5TrimTextBoundary(prefix, prefixCap, true);
  const fittedSuffix = MCPV5TrimTextBoundary(suffix, suffixCap, false);

  return fittedPrefix + base + fittedSuffix;
}

function MCPV5ForceInnerSelfSettings(enableInnerSelf, enableAutoCards) {
  try {
    if (
      globalThis.MainSettings &&
      MainSettings.InnerSelf &&
      typeof MainSettings.InnerSelf === "object"
    ) {
      MainSettings.InnerSelf.IS_INNER_SELF_ENABLED_BY_DEFAULT =
        enableInnerSelf === true;
      MainSettings.InnerSelf.IS_AC_ENABLED_BY_DEFAULT =
        enableAutoCards === true;
    }
  } catch (error) {
    log("MCP V5 Inner Self settings error:", error);
  }

  if (!Array.isArray(storyCards)) return;
  const configKey = "play.aidungeon.com/profile/LewdLeah";
  const index = storyCards.findIndex(card => (
    card &&
    typeof card === "object" &&
    (
      card.keys === configKey ||
      card.title === "Configure Inner Self" ||
      card.title === "Edit to enable Inner Self"
    )
  ));
  if (index < 0 || !storyCards[index]) return;

  const card = storyCards[index];
  const originalEntry = typeof card.entry === "string" ? card.entry : "";
  let nextEntry = originalEntry;

  nextEntry = nextEntry.replace(
    /^(\s*>?\s*Enable Inner Self:\s*)(true|false)\s*$/im,
    "$1" + (enableInnerSelf === true ? "true" : "false")
  );
  nextEntry = nextEntry.replace(
    /^(\s*>?\s*Install Auto-Cards:\s*)(true|false)\s*$/im,
    "$1" + (enableAutoCards === true ? "true" : "false")
  );

  if (nextEntry !== originalEntry) {
    try { card.entry = nextEntry; } catch (error) {
      log("MCP V5 Inner Self card control error:", error);
    }
  }
}

function MCPV5RecordDiagnostic(kind, data) {
  const root = MCPV5Root();
  const row = {
    action: Number.isFinite(info && info.actionCount)
      ? info.actionCount
      : -1,
    build: MCPV5_BUILD_VERSION,
    kind: String(kind || "").slice(0, 48),
    data: String(data || "").slice(0, 320)
  };
  root.diagnostics.push(row);
  root.diagnostics = root.diagnostics.slice(-30);
  if (root.settings && root.settings.diagnostics) {
    log("MCP V5.3.10", row.kind, row.data);
  }
}


function MCPV5InventoryAuditSnapshot(moduleId) {
  const rows = [];
  for (let i = 0; i < MCPV5_NATIVE_STORY_CARDS.length; i++) {
    const card = MCPV5_NATIVE_STORY_CARDS[i];
    if (!card || typeof card !== "object") continue;
    const owner = MCPV5InventoryOwner(card.keys);
    const title = String(card.title || "");
    const relevant = (
      (moduleId === "stackable_inventory" && owner === "stackable_inventory") ||
      (moduleId === "realmheart" && owner === "realmheart") ||
      (
        moduleId === "true_auto_stats" &&
        /\bInventory$/i.test(title) &&
        String(card.type || "").toLowerCase().includes("player")
      )
    );
    if (!relevant) continue;
    rows.push(
      String(card.keys || "") + "\u241F" +
      title + "\u241F" +
      String(card.entry || "")
    );
  }
  rows.sort();
  const joined = rows.join("\u241E");
  return {
    hash: MCPV5HashString(joined),
    preview: joined.slice(0, 4000),
    count: rows.length
  };
}

function MCPV5CanonicalInventoryFromState(moduleId) {
  const items = {};
  const currency = {};
  let initialized = false;

  function addItem(name, quantity) {
    const label = String(name || "").trim();
    const qty = Math.floor(Number(quantity) || 0);
    if (!label || qty === 0) return;
    const existing = Object.keys(items).find(
      key => key.toLowerCase() === label.toLowerCase()
    );
    const key = existing || label;
    items[key] = (items[key] || 0) + qty;
    if (items[key] === 0) delete items[key];
  }

  function addCurrency(name, quantity) {
    const label = String(name || "balance").trim() || "balance";
    const qty = Number(quantity);
    if (!Number.isFinite(qty)) return;
    const existing = Object.keys(currency).find(
      key => key.toLowerCase() === label.toLowerCase()
    );
    currency[existing || label] = qty;
  }

  if (
    moduleId === "stackable_inventory" &&
    state.vars &&
    typeof state.vars === "object"
  ) {
    initialized = true;
    const inventory = Array.isArray(state.vars.inventory)
      ? state.vars.inventory
      : [];
    for (let i = 0; i < inventory.length; i++) addItem(inventory[i], 1);
    if (state.vars.wallet && typeof state.vars.wallet === "object") {
      const keys = Object.keys(state.vars.wallet);
      for (let i = 0; i < keys.length; i++) {
        addCurrency(keys[i], state.vars.wallet[keys[i]]);
      }
    }
  } else if (
    moduleId === "realmheart" &&
    state.ubis &&
    typeof state.ubis === "object"
  ) {
    initialized = true;
    const inventory = state.ubis.inventory;
    if (inventory && typeof inventory === "object") {
      const keys = Object.keys(inventory);
      for (let i = 0; i < keys.length; i++) {
        addItem(keys[i], inventory[keys[i]]);
      }
    }
    if (Number.isFinite(Number(state.ubis.balance))) {
      addCurrency("balance", state.ubis.balance);
    }
  } else if (
    moduleId === "true_auto_stats" &&
    state.players &&
    typeof state.players === "object"
  ) {
    initialized = true;
    const players = Object.keys(state.players);
    for (let p = 0; p < players.length; p++) {
      const inv = state.players[players[p]] && state.players[players[p]].inv;
      if (!inv || !Array.isArray(inv.item)) continue;
      for (let i = 0; i < inv.item.length; i++) {
        const qty = Array.isArray(inv.amt) ? inv.amt[i] : 1;
        addItem(inv.item[i], qty);
      }
    }
  }

  return {
    initialized,
    items,
    currency,
    hash: MCPV5HashString(JSON.stringify({ items, currency }))
  };
}

function MCPV5InventoryMapDelta(beforeMap, afterMap) {
  const rows = [];
  const names = new Map();

  function ingest(map, side) {
    const keys = Object.keys(map || {});
    for (let i = 0; i < keys.length; i++) {
      const label = String(keys[i] || "").trim();
      if (!label) continue;
      const key = label.toLowerCase().replace(/\s+/g, " ");
      if (!names.has(key)) names.set(key, { name: label, before: 0, after: 0 });
      names.get(key)[side] = Number(map[keys[i]]) || 0;
      if (side === "after") names.get(key).name = label;
    }
  }

  ingest(beforeMap, "before");
  ingest(afterMap, "after");
  names.forEach((row, key) => {
    const delta = row.after - row.before;
    if (delta) rows.push({ key, name: row.name, delta });
  });
  rows.sort((a, b) => a.key.localeCompare(b.key));
  return rows;
}

function MCPV5RecordInventoryProposal(moduleId, before, after, plan) {
  if (
    !before ||
    !after ||
    before.hash === after.hash ||
    !["true_auto_stats", "stackable_inventory", "realmheart"].includes(moduleId)
  ) return;

  const root = MCPV5Root();

  // Initialization establishes a private module baseline; it is not a
  // narrative inventory transaction and must not be propagated to peers.
  if (before.initialized !== true) {
    root.inventoryLedger.recent.push({
      action: Number.isFinite(info && info.actionCount)
        ? info.actionCount
        : -1,
      module: moduleId,
      baseline: true,
      after: after.hash
    });
    root.inventoryLedger.recent = root.inventoryLedger.recent.slice(-20);
    return;
  }
  const action = Number.isFinite(info && info.actionCount)
    ? info.actionCount
    : -1;
  const proposal = {
    action,
    module: moduleId,
    authority: !!(plan && plan.inventoryAuthority === moduleId),
    items: MCPV5InventoryMapDelta(before.items, after.items),
    currency: MCPV5InventoryMapDelta(before.currency, after.currency),
    beforeHash: before.hash,
    afterHash: after.hash,
    after: {
      items: after.items,
      currency: after.currency
    }
  };

  root.inventoryLedger.pending.push(proposal);
  root.inventoryLedger.pending = root.inventoryLedger.pending.slice(-36);
  root.inventoryLedger.recent.push({
    action,
    module: moduleId,
    before: before.hash,
    after: after.hash
  });
  root.inventoryLedger.recent = root.inventoryLedger.recent.slice(-20);
}

function MCPV5ApplyInventoryEvent(moduleId, event, amount) {
  const delta = Number.isFinite(amount) ? amount : event.delta;
  if (!delta) return false;

  if (moduleId === "stackable_inventory") {
    if (!state.vars || typeof state.vars !== "object") return false;

    if (event.kind === "item") {
      if (!Array.isArray(state.vars.inventory)) state.vars.inventory = [];
      const inventory = state.vars.inventory;
      if (delta > 0) {
        for (let i = 0; i < delta; i++) inventory.push(event.name);
      } else {
        let remaining = Math.abs(delta);
        for (let i = inventory.length - 1; i >= 0 && remaining > 0; i--) {
          if (String(inventory[i]).toLowerCase() === event.key) {
            inventory.splice(i, 1);
            remaining--;
          }
        }
      }
      return true;
    }

    if (!state.vars.wallet || typeof state.vars.wallet !== "object") {
      state.vars.wallet = {};
    }
    const wallet = state.vars.wallet;
    const existing = Object.keys(wallet).find(
      key => key.toLowerCase() === event.key
    );
    const label = existing || event.name;
    wallet[label] = (Number(wallet[label]) || 0) + delta;
    return true;
  }

  if (moduleId === "realmheart") {
    if (!state.ubis || typeof state.ubis !== "object") return false;

    if (event.kind === "item") {
      if (!state.ubis.inventory || typeof state.ubis.inventory !== "object") {
        state.ubis.inventory = {};
      }
      const inventory = state.ubis.inventory;
      const existing = Object.keys(inventory).find(
        key => key.toLowerCase() === event.key
      );
      const label = existing || event.name;
      inventory[label] = Math.max(0, (Number(inventory[label]) || 0) + delta);
      if (inventory[label] <= 0) delete inventory[label];
      return true;
    }

    state.ubis.balance = (Number(state.ubis.balance) || 0) + delta;
    return true;
  }

  // TAS inventory is per-character. The host records it as a contributor but
  // never guesses which character should receive a synchronized item.
  return false;
}

function MCPV5FinalizeInventoryLedger(plan) {
  if (!plan || !plan.cooperative) return;

  const root = MCPV5Root();
  const ledger = root.inventoryLedger;
  const action = Number.isFinite(info && info.actionCount)
    ? info.actionCount
    : -1;
  const proposals = ledger.pending.filter(row => row.action === action);
  ledger.pending = ledger.pending.filter(row => row.action !== action);

  if (!proposals.length) {
    const authority = plan.inventoryAuthority;
    if (authority) {
      const snapshot = MCPV5CanonicalInventoryFromState(authority);
      ledger.authority = authority;
      ledger.action = action;
      ledger.hash = snapshot.hash;
      ledger.items = snapshot.items;
      ledger.currency = snapshot.currency;
    }
    return;
  }

  const groups = new Map();
  function addRows(kind, proposal, rows) {
    for (let i = 0; i < rows.length; i++) {
      const row = rows[i];
      const groupKey = kind + "\u241F" + row.key;
      if (!groups.has(groupKey)) {
        groups.set(groupKey, {
          kind,
          key: row.key,
          name: row.name,
          rows: []
        });
      }
      groups.get(groupKey).rows.push({
        module: proposal.module,
        delta: row.delta,
        authority: proposal.authority
      });
    }
  }

  for (let i = 0; i < proposals.length; i++) {
    addRows("item", proposals[i], proposals[i].items || []);
    addRows("currency", proposals[i], proposals[i].currency || []);
  }

  const committed = [];
  groups.forEach(group => {
    let winner = group.rows.find(row => row.authority);
    if (!winner) {
      const counts = new Map();
      for (let i = 0; i < group.rows.length; i++) {
        const key = String(group.rows[i].delta);
        counts.set(key, (counts.get(key) || 0) + 1);
      }
      winner = group.rows.slice().sort((a, b) => {
        const countA = counts.get(String(a.delta)) || 0;
        const countB = counts.get(String(b.delta)) || 0;
        if (countA !== countB) return countB - countA;
        return MCPV5AuthorityScore(b.module, plan) -
          MCPV5AuthorityScore(a.module, plan);
      })[0];
    }
    if (!winner || !winner.delta) return;

    const event = {
      id: MCPV5HashString(
        action + "|" + group.kind + "|" + group.key + "|" + winner.delta
      ),
      action,
      kind: group.kind,
      key: group.key,
      name: group.name,
      delta: winner.delta,
      authority: winner.module,
      sources: MCPV5UniqueStrings(
        group.rows
          .filter(row => row.delta === winner.delta)
          .map(row => row.module)
      )
    };

    if (!ledger.events.some(old => old.id === event.id)) {
      ledger.events.push(event);
      committed.push(event);
    }

    if (group.rows.some(row => row.delta !== winner.delta)) {
      MCPV5RecordDiagnostic(
        "inventory-conflict-arbitrated",
        event.name + " -> " + winner.delta + " by " +
        MCPV5Name(winner.module)
      );
    }
  });

  ledger.events = ledger.events.slice(-80);

  // Synchronize only the two unambiguous global inventory stores. TAS is
  // intentionally excluded because its inventory belongs to a named player.
  const syncTargets = ["stackable_inventory", "realmheart"].filter(
    id => plan.effective[id] === true
  );
  for (let e = 0; e < committed.length; e++) {
    const event = committed[e];
    for (let t = 0; t < syncTargets.length; t++) {
      const target = syncTargets[t];
      const proposal = proposals.find(row => row.module === target);
      const rows = proposal
        ? (event.kind === "item" ? proposal.items : proposal.currency)
        : [];
      const reflected = rows.find(row => row.key === event.key);
      const actual = reflected ? reflected.delta : 0;
      let correction = event.delta - actual;

      if (
        actual !== 0 &&
        actual !== event.delta &&
        plan.authorityEnforcement !== "Strict"
      ) {
        MCPV5RecordDiagnostic(
          "inventory-sync-deferred",
          MCPV5Name(target) + " disagreed on " + event.name
        );
        continue;
      }

      if (correction && MCPV5ApplyInventoryEvent(target, event, correction)) {
        MCPV5RecordDiagnostic(
          "inventory-observer-synchronized",
          MCPV5Name(target) + " / " + event.name + " / " + correction
        );
      }
    }
  }

  const authority = plan.inventoryAuthority;
  if (authority) {
    const snapshot = MCPV5CanonicalInventoryFromState(authority);
    ledger.authority = authority;
    ledger.action = action;
    ledger.hash = snapshot.hash;
    ledger.items = snapshot.items;
    ledger.currency = snapshot.currency;
  }
}

function MCPV5RecordInventoryAudit(moduleId, before, after, plan) {
  MCPV5RecordInventoryProposal(moduleId, before, after, plan);
}

function MCPV5ExpectedTiming(tab, moduleId) {
  const root = MCPV5Root();
  const measured = (
    root.timings &&
    root.timings[tab] &&
    Number.isFinite(root.timings[tab][moduleId])
  ) ? root.timings[tab][moduleId] : null;
  if (measured !== null) return Math.max(1, measured);
  return (
    MCPV5_DEFAULT_TIMINGS[tab] &&
    MCPV5_DEFAULT_TIMINGS[tab][moduleId]
  ) || 80;
}

function MCPV5UpdateTiming(tab, moduleId, elapsed) {
  const root = MCPV5Root();
  const value = Math.min(1800, Math.max(1, Math.floor(elapsed)));
  const old = Number.isFinite(root.timings[tab][moduleId])
    ? root.timings[tab][moduleId]
    : value;
  root.timings[tab][moduleId] = Math.round((old * 0.7) + (value * 0.3));
}

function MCPV5PlanSignature(plan, settings) {
  return MCPV5HashString(JSON.stringify({
    selected: plan ? plan.selected : [],
    effective: plan ? plan.effective : {},
    mode: plan ? plan.mode : "",
    policy: plan ? plan.policy : "",
    enforcement: plan ? plan.authorityEnforcement : "",
    inventory: plan ? plan.inventoryAuthority : "",
    npcFacts: plan ? plan.npcFactsAuthority : "",
    npcMind: plan ? plan.npcMindAuthority : "",
    npcAction: plan ? plan.npcActionAuthority : "",
    macro: plan ? plan.macroPacingAuthority : "",
    scene: plan ? plan.scenePacingAuthority : "",
    relationship: plan ? plan.relationshipPacingAuthority : "",
    outcome: plan ? plan.outcomeRollAuthority : "",
    guard: settings ? settings.workloadGuard : false,
    budget: settings ? settings.hookBudgetMs : 0,
    safety: settings ? settings.hookSafetyMarginMs : 0
  }));
}

function MCPV5EligibleModules(plan) {
  const out = [];
  for (let i = 0; i < MCPV5_PROFILE_ORDER.length; i++) {
    const id = MCPV5_PROFILE_ORDER[i];
    if (!plan || !plan.effective || plan.effective[id] !== true) continue;
    if (plan.dependencyOnly && plan.dependencyOnly[id]) continue;
    if (
      id === "auto_cards" &&
      plan.effective.inner_self === true &&
      !(plan.dependencyOnly && plan.dependencyOnly.inner_self)
    ) continue;
    if (
      (id === "dice_roll" || id === "coin_flip") &&
      id !== plan.outcomeRollAuthority
    ) continue;
    out.push(id);
  }
  return out;
}

function MCPV5LooksLikeLivingMetersSlashInput(value) {
  let text = String(value || "");
  text = text.replace(/^\s*>\s*/, "");
  text = text.replace(/^[^\s]+\s+(?:say|says|said)[,:]?\s*/i, "");
  text = text.replace(/^["'“”]+|["'“”\s]+$/g, "").trim();
  return /^\/\S+/.test(text);
}

function MCPV5LooksLikeRealmHeartSlashInput(inputText) {
  // Follow v2.5's Input normalization. /help remains intentionally ambiguous.
  const clean = String(inputText || "")
    .replace(/^[>\s]+/, "")
    .replace(/^you\s+/i, "")
    .replace(/^say,?\s+/i, "")
    .replace(/^["']+/, "")
    .trim();
  const slash = clean.indexOf("/");
  if (slash < 0 || slash >= 4) return false;
  return /^(?:rh\s+|ubis\s+|balance\b|inventory\b|ledger\b|time\b|weather\b|holidays\b|events\b|keywords\b|pay\s+|earn\s+|additem\s+|removeitem\s+|jackpot\s+start\b|coinflip\s+start\b|dice\s+start\b|highstakes\s+start\b|gamble\s+end\b)/i.test(clean.slice(slash + 1));
}

function MCPV5CommandHint(value, plan) {
  const effective = plan && plan.effective ? plan.effective : {};
  let clean = String(value || "")
    .replace(/^\s*>\s*/, "")
    .replace(/^you\s+/i, "")
    .replace(/^say,?\s+/i, "")
    .replace(/^["'“”]+/, "")
    .trim();
  // Original Auto-Cards also accepts the older AC/ spelling in Story actions.
  if (/^(?:\/ac(?:\s|\/|$)|ac\/(?:\s|$))/i.test(clean)) {
    if (effective.inner_self === true &&
        !(plan.dependencyOnly && plan.dependencyOnly.inner_self)) {
      return "inner_self";
    }
    if (effective.auto_cards === true) return "auto_cards";
  }
  if (effective.realmheart === true &&
      MCPV5LooksLikeRealmHeartSlashInput(value)) return "realmheart";
  // /help, /inventory and user-defined meter commands can be shared. Do not
  // preclaim or reinterpret them; original source handlers remain authoritative.
  if (effective.living_meters === true &&
      /^\/status(?:\s|$)/i.test(clean)) return "living_meters";
  return "";
}

function MCPV5CommandAmbiguous(value, plan) {
  if (!plan || !plan.effective) return false;
  const clean = String(value || "").replace(/^[>\s"'“”]+/, "").trim();
  return /^\/(?:help|inventory)(?:\s|$)/i.test(clean) &&
    [plan.effective.living_meters, plan.effective.realmheart,
     plan.effective.auto_cards, plan.effective.inner_self]
       .filter(Boolean).length > 1;
}

function MCPV5LooksLikeRealmHeartGambleAction(inputText) {
  const raw = String(inputText || "").trim();
  const wager = /\b(?:bet|gamble|wager|stake|risk|throw down|lay down|place a bet|quit|stop|end|give up)\b/i.test(raw);
  if (!wager) return false;
  const ubis = state && state.ubis;
  if (ubis && typeof ubis === "object" &&
      typeof ubis.activeGamble === "string" && ubis.activeGamble.length) {
    return true;
  }
  return /\b(?:coin\s*flip|coinflip|jackpot|dice|high\s*stakes|highstakes)\b/i.test(raw);
}

function MCPV5RealmHeartCommandReply(value) {
  return typeof value === "string" &&
    value.startsWith("=== REALMHEART ===\n") &&
    value.includes("\n=== END ===");
}

function MCPV5RealmHeartControlFeedback(inputText, reply) {
  const source = MCPV5SafeText(reply, " ");
  try {
    const ubis = state.ubis;
    if (
      !ubis || !ubis.settings ||
      ubis.settings.gamblingEnabled !== false ||
      !MCPV5LooksLikeRealmHeartSlashInput(inputText) ||
      !/\/(?:jackpot|coinflip|dice|highstakes)\s+start\b/i.test(String(inputText || "")) ||
      !MCPV5RealmHeartCommandReply(source)
    ) return source;
    const warning = "Gambling Auto is OFF. Enable Gambling auto in RealmHeart settings to resolve wagers.";
    if (source.includes(warning)) return source;
    const marker = "\n=== END ===";
    const at = source.lastIndexOf(marker);
    if (at < 0) return source;
    return source.slice(0, at) + "\n" + warning + source.slice(at);
  } catch {
    return source;
  }
}

function MCPV5RealmHeartReplyForAction(root, schedule) {
  const record = root && root.realmheartCommand;
  return record &&
    record.signature === (schedule && schedule.signature) &&
    record.action === (schedule && schedule.action) &&
    typeof record.reply === "string" &&
    record.reply.length
      ? record.reply
      : "";
}

function MCPV5BuildActionSchedule(plan, settings, inputText) {
  const root = MCPV5Root();
  const eligible = MCPV5EligibleModules(plan);
  // RealmHeart advances world time and recurring bills; unlike a lightweight
  // observer it must be scheduled on every ordinary narrative lifecycle.
  const fixedOutput = eligible.filter(id => (
    id === "realmheart" ||
    id === "ar" ||
    id === "usc_e" ||
    id === "slow_burn" ||
    id === plan.outcomeRollAuthority
  ));
  const fixedOutputSet = new Set(fixedOutput);
  const ordinary = eligible.filter(id => !fixedOutputSet.has(id));
  const cursor = ordinary.length
    ? root.scheduler.actionCursor % ordinary.length
    : 0;
  const rotated = ordinary
    .slice(cursor)
    .concat(ordinary.slice(0, cursor));
  // Oldest deferred work goes first, but never bypasses the hook budget.
  const heartbeat = root.scheduler && root.scheduler.heartbeat;
  const aged = rotated.map((id, index) => ({
    id, index,
    streak: heartbeat && heartbeat[id] &&
      Number.isFinite(heartbeat[id].deferStreak)
      ? Math.min(100, heartbeat[id].deferStreak) : 0
  }));
  aged.sort((a, b) => b.streak - a.streak || a.index - b.index);
  const prioritized = aged.map(record => record.id);

  let selected = rotated.slice();
  const skipped = [];
  const projectedTotals = {
    input: fixedOutput.reduce(
      (total, id) => total + MCPV5ExpectedTiming("input", id),
      0
    ),
    context: fixedOutput.reduce(
      (total, id) => total + MCPV5ExpectedTiming("context", id),
      0
    ),
    output: fixedOutput.reduce(
      (total, id) => total + MCPV5ExpectedTiming("output", id),
      0
    )
  };

  if (plan.cooperative && settings.workloadGuard && prioritized.length > 1) {
    selected = [];
    const limit = Math.max(
      250,
      settings.hookBudgetMs - settings.hookSafetyMarginMs
    );

    for (let i = 0; i < prioritized.length; i++) {
      const id = prioritized[i];
      const projected = {
        input: projectedTotals.input + MCPV5ExpectedTiming("input", id),
        context: projectedTotals.context + MCPV5ExpectedTiming("context", id),
        output: projectedTotals.output + MCPV5ExpectedTiming("output", id)
      };
      const fits = (
        projected.input <= limit &&
        projected.context <= limit &&
        projected.output <= limit
      );

      if (fits || selected.length === 0) {
        selected.push(id);
        projectedTotals.input = projected.input;
        projectedTotals.context = projected.context;
        projectedTotals.output = projected.output;
      } else {
        skipped.push(id);
      }
    }
  } else {
    for (let i = 0; i < prioritized.length; i++) {
      const id = prioritized[i];
      projectedTotals.input += MCPV5ExpectedTiming("input", id);
      projectedTotals.context += MCPV5ExpectedTiming("context", id);
      projectedTotals.output += MCPV5ExpectedTiming("output", id);
    }
  }

  if (ordinary.length) {
    const ordinarySelected = selected.length;
    root.scheduler.actionCursor = (
      cursor + Math.max(1, ordinarySelected)
    ) % ordinary.length;
  }

  // Reserved lifecycle modules (including RealmHeart) run on every ordinary
  // turn. Their costs were included before optional-module scheduling.
  selected = selected.concat(fixedOutput);

  // Living Meters v1.2 command replies are queued in Input and delivered in
  // Output. A slash action must therefore never lose LM merely because the
  // workload rotation deferred it. LM itself decides whether the slash command
  // is actually one of its own; unknown slash commands remain available to
  // other modules.
  if (
    plan &&
    plan.effective &&
    plan.effective.living_meters === true &&
    MCPV5LooksLikeLivingMetersSlashInput(inputText) &&
    !selected.includes("living_meters")
  ) {
    selected.push("living_meters");
    const skippedIndex = skipped.indexOf("living_meters");
    if (skippedIndex >= 0) skipped.splice(skippedIndex, 1);
  }

  // Auto-Cards' explicit command must not disappear when it is workload-
  // deferred. Inner Self owns its package whenever Inner Self is active.
  const commandHint = MCPV5CommandHint(inputText, plan);
  if (
    (commandHint === "inner_self" || commandHint === "auto_cards") &&
    !selected.includes(commandHint)
  ) {
    selected.push(commandHint);
    const skippedIndex = skipped.indexOf(commandHint);
    if (skippedIndex >= 0) skipped.splice(skippedIndex, 1);
  }

  // Preserve RealmHeart's own command lifecycle under Workload Guard.
  if (
    plan && plan.effective && plan.effective.realmheart === true &&
    (MCPV5LooksLikeRealmHeartSlashInput(inputText) ||
     MCPV5LooksLikeRealmHeartGambleAction(inputText)) &&
    !selected.includes("realmheart")
  ) {
    selected.push("realmheart");
    const skippedIndex = skipped.indexOf("realmheart");
    if (skippedIndex >= 0) skipped.splice(skippedIndex, 1);
  }

  const action = Number.isFinite(info && info.actionCount)
    ? info.actionCount
    : -1;
  return {
    version: 3,
    action,
    signature: MCPV5PlanSignature(plan, settings),
    modules: selected,
    skipped,
    projectedTotals,
    inputText: String(inputText || "").slice(0, 800),
    commandHint: MCPV5CommandHint(inputText, plan),
    commandOwner: "",
    controlOutput: "",
    stages: { input: false, context: false, output: false },
    completed: false
  };
}

function MCPV5EnsureActionSchedule(tab, plan, settings, inputText) {
  const root = MCPV5Root();
  const action = Number.isFinite(info && info.actionCount)
    ? info.actionCount
    : -1;
  const signature = MCPV5PlanSignature(plan, settings);
  let schedule = root.actionSchedule;

  const invalid = !schedule || (
    schedule.version !== 3 ||
    schedule.signature !== signature ||
    schedule.completed === true ||
    !schedule.stages ||
    (
      action >= 0 &&
      Number.isFinite(schedule.action) &&
      Math.abs(action - schedule.action) > 1
    )
  );

  if (tab === "input" || invalid) {
    schedule = MCPV5BuildActionSchedule(plan, settings, inputText);
    root.actionSchedule = schedule;
  }

  // Context or Output may be Script-Tested without Input. The same generated
  // schedule is still retained for the rest of that synthetic lifecycle.
  if (!Array.isArray(schedule.modules)) schedule.modules = [];
  if (!Array.isArray(schedule.skipped)) schedule.skipped = [];
  if (!schedule.stages || typeof schedule.stages !== "object") {
    schedule.stages = { input: false, context: false, output: false };
  }
  return schedule;
}

function MCPV5MarkScheduleStage(schedule, tab) {
  if (!schedule || !schedule.stages) return;
  schedule.stages[tab] = true;
  if (tab === "output") {
    schedule.completed = true;
  }
}

function MCPV5ActiveTransaction(tab, plan) {
  const root = MCPV5Root();
  const action = Number.isFinite(info && info.actionCount)
    ? info.actionCount
    : -1;
  const stored = root.transaction;

  if (
    stored &&
    typeof stored === "object" &&
    typeof stored.owner === "string"
  ) {
    const enabled = !!(
      plan &&
      plan.effective &&
      plan.effective[stored.owner] === true
    );
    const expired = (
      Number.isFinite(stored.expiresAction) &&
      action >= 0 &&
      action > stored.expiresAction
    );

    if (enabled && !expired && tab !== "input") {
      return {
        name: String(stored.name || "Protected model task"),
        owner: stored.owner,
        persistent: true
      };
    }
    root.transaction = null;
  }

  for (let i = 0; i < MCPV5_TRANSACTION_DETECTORS.length; i++) {
    const detector = MCPV5_TRANSACTION_DETECTORS[i];
    try {
      if (detector.active(tab, plan)) {
        const owner = typeof detector.owner === "function"
          ? detector.owner(plan)
          : detector.owner;
        if (!owner) continue;
        return {
          name: detector.name,
          owner,
          persistent: false
        };
      }
    } catch (error) {
      MCPV5RecordDiagnostic(
        "transaction-detector-error",
        detector.name + ": " + String(error && error.message || error)
      );
    }
  }
  return null;
}

function MCPV5RegisterTransaction(transaction, tab) {
  if (!transaction || !transaction.owner) return;
  const root = MCPV5Root();
  const action = Number.isFinite(info && info.actionCount)
    ? info.actionCount
    : -1;
  root.transaction = {
    version: 1,
    name: String(transaction.name || "Protected model task").slice(0, 80),
    owner: String(transaction.owner),
    startedAction: action,
    expiresAction: action < 0 ? 2 : action + 2,
    phase: tab === "context" ? "awaiting-output" : String(tab || "")
  };
}

function MCPV5ClearTransaction(owner) {
  const root = MCPV5Root();
  if (
    !root.transaction ||
    !owner ||
    root.transaction.owner === owner
  ) {
    root.transaction = null;
  }
}


function MCPV5CommonEdges(base, candidate) {
  const a = String(base || "");
  const b = String(candidate || "");
  const maxPrefix = Math.min(a.length, b.length);
  let prefix = 0;
  while (prefix < maxPrefix && a.charCodeAt(prefix) === b.charCodeAt(prefix)) {
    prefix++;
  }

  let suffix = 0;
  const maxSuffix = Math.min(a.length - prefix, b.length - prefix);
  while (
    suffix < maxSuffix &&
    a.charCodeAt(a.length - 1 - suffix) ===
      b.charCodeAt(b.length - 1 - suffix)
  ) {
    suffix++;
  }
  return { prefix, suffix };
}

function MCPV5AnalyzeProposal(baseText, candidateText) {
  const base = String(baseText || "");
  const candidate = String(candidateText || "");
  if (candidate === base) {
    return {
      mode: "same",
      candidate,
      prefix: "",
      suffix: "",
      preservation: 1,
      start: 0,
      end: 0,
      replacement: ""
    };
  }

  const position = candidate.indexOf(base);
  if (base && position >= 0) {
    return {
      mode: "additive",
      candidate,
      prefix: candidate.slice(0, position),
      suffix: candidate.slice(position + base.length),
      preservation: 1,
      start: 0,
      end: 0,
      replacement: ""
    };
  }

  const edges = MCPV5CommonEdges(base, candidate);
  const preservation = base.length
    ? Math.min(1, (edges.prefix + edges.suffix) / base.length)
    : 0;
  const start = edges.prefix;
  const end = Math.max(start, base.length - edges.suffix);
  const replacementEnd = Math.max(
    start,
    candidate.length - edges.suffix
  );
  const replacement = candidate.slice(start, replacementEnd);

  return {
    mode: preservation >= 0.25 ? "localized" : "structural",
    candidate,
    prefix: "",
    suffix: "",
    preservation,
    start,
    end,
    replacement
  };
}

function MCPV5AuthorityScore(moduleId, plan) {
  let score = 10;
  if (!plan || !moduleId) return score;

  const primary = MCPV5_PRIMARY_CONTEXT_CAPABILITY[moduleId];
  if (primary) {
    const role = MCPV5CapabilityRole(moduleId, primary, plan);
    if (role === "authority") score += 80;
    else if (role === "contributor") score += 30;
    else if (role === "observer") score -= 10;
  }

  const caps = MCPV5ModuleCapabilities(moduleId);
  for (let i = 0; i < caps.length; i++) {
    if (caps[i] === primary) continue;
    const role = MCPV5CapabilityRole(moduleId, caps[i], plan);
    if (role === "authority") score += 15;
    else if (role === "contributor") score += 5;
  }

  if (plan.dependencyOnly && plan.dependencyOnly[moduleId]) score -= 60;
  return score;
}

function MCPV5ComposeContextProposals(baseText, proposals, plan) {
  const base = MCPV5SafeText(baseText, "\u200B");
  if (!Array.isArray(proposals) || !proposals.length) return base;

  const additive = [];
  const localized = [];
  const structural = [];

  for (let i = 0; i < proposals.length; i++) {
    const proposal = proposals[i];
    const analysis = MCPV5AnalyzeProposal(base, proposal.text);
    proposal.analysis = analysis;
    proposal.score = MCPV5AuthorityScore(proposal.id, plan);
    proposal.role = MCPV5PrimaryContextRole(proposal.id, plan);

    if (
      plan &&
      plan.authorityEnforcement === "Strict" &&
      proposal.role === "observer"
    ) {
      MCPV5RecordDiagnostic(
        "context-observer-suppressed",
        MCPV5Name(proposal.id)
      );
      continue;
    }

    if (analysis.mode === "additive") additive.push(proposal);
    else if (analysis.mode === "localized") localized.push(proposal);
    else if (analysis.mode === "structural") structural.push(proposal);
  }

  let chosenBase = base;

  if (structural.length) {
    structural.sort((a, b) => {
      if (a.score !== b.score) return b.score - a.score;
      return b.analysis.preservation - a.analysis.preservation;
    });
    const winner = structural[0];
    const authorized = (
      plan.authorityEnforcement === "Advisory" ||
      winner.role === "authority" ||
      winner.analysis.preservation >= 0.70
    );

    if (authorized && MCPV5HasVisibleText(winner.text)) {
      chosenBase = winner.text;
    } else {
      MCPV5RecordDiagnostic(
        "context-structural-rejected",
        MCPV5Name(winner.id)
      );
    }

    for (let i = 1; i < structural.length; i++) {
      MCPV5RecordDiagnostic(
        "context-conflict-arbitrated",
        MCPV5Name(structural[i].id) + " deferred to " +
        MCPV5Name(winner.id)
      );
    }
  } else if (localized.length) {
    localized.sort((a, b) => {
      if (a.score !== b.score) return b.score - a.score;
      return b.analysis.preservation - a.analysis.preservation;
    });

    const accepted = [];
    for (let i = 0; i < localized.length; i++) {
      const proposal = localized[i];
      const overlaps = accepted.some(other => !(
        proposal.analysis.end <= other.analysis.start ||
        proposal.analysis.start >= other.analysis.end
      ));
      if (overlaps) {
        MCPV5RecordDiagnostic(
          "context-localized-conflict",
          MCPV5Name(proposal.id) + " deferred."
        );
        continue;
      }
      accepted.push(proposal);
    }

    accepted.sort((a, b) => b.analysis.start - a.analysis.start);
    for (let i = 0; i < accepted.length; i++) {
      const edit = accepted[i].analysis;
      chosenBase = (
        chosenBase.slice(0, edit.start) +
        edit.replacement +
        chosenBase.slice(edit.end)
      );
    }
  }

  const prefixes = [];
  const suffixes = [];
  for (let i = 0; i < additive.length; i++) {
    const proposal = additive[i];
    if (proposal.analysis.prefix.trim()) {
      prefixes.push(proposal.analysis.prefix.trim());
    }
    if (proposal.analysis.suffix.trim()) {
      suffixes.push(proposal.analysis.suffix.trim());
    }
  }

  const uniquePrefixes = MCPV5UniqueStrings(prefixes);
  const uniqueSuffixes = MCPV5UniqueStrings(suffixes);
  let out = chosenBase;
  if (uniquePrefixes.length) {
    out = uniquePrefixes.join("\n\n") + "\n\n" + out;
  }
  if (uniqueSuffixes.length) {
    out = out + "\n\n" + uniqueSuffixes.join("\n\n");
  }
  return MCPV5FitContext(out, base);
}

function MCPV5SelectOutputProposal(baseText, proposals, plan, commandOwner) {
  const base = MCPV5SafeText(baseText, "\u200B");
  if (!Array.isArray(proposals) || !proposals.length) return base;

  const changed = [];
  const additions = [];
  for (let i = 0; i < proposals.length; i++) {
    const proposal = proposals[i];
    proposal.analysis = MCPV5AnalyzeProposal(base, proposal.text);
    proposal.score = MCPV5AuthorityScore(proposal.id, plan);
    proposal.role = MCPV5PrimaryContextRole(proposal.id, plan);

    if (proposal.analysis.mode === "additive") additions.push(proposal);
    else if (proposal.analysis.mode !== "same") changed.push(proposal);
  }

  let selected = base;
  if (changed.length) {
    changed.sort((a, b) => {
      if (commandOwner) {
        if (a.id === commandOwner && b.id !== commandOwner) return -1;
        if (b.id === commandOwner && a.id !== commandOwner) return 1;
      }
      if (a.score !== b.score) return b.score - a.score;
      return b.analysis.preservation - a.analysis.preservation;
    });

    const winner = changed[0];
    const commandAuthorized = commandOwner && winner.id === commandOwner;
    const strictBlocked = (
      plan &&
      plan.authorityEnforcement === "Strict" &&
      winner.role === "observer" &&
      !commandAuthorized
    );

    if (
      !strictBlocked &&
      (
        commandAuthorized ||
        winner.analysis.mode === "localized" ||
        winner.role === "authority" ||
        winner.score >= 50
      )
    ) {
      selected = MCPV5ApplyOutputGuard(
        winner.id,
        winner.text,
        base,
        base
      );
    } else {
      MCPV5RecordDiagnostic(
        "output-structural-rejected",
        MCPV5Name(winner.id)
      );
    }
  }

  const prefix = [];
  const suffix = [];
  for (let i = 0; i < additions.length; i++) {
    const proposal = additions[i];
    if (
      plan &&
      plan.authorityEnforcement === "Strict" &&
      proposal.role === "observer"
    ) continue;

    const analysis = proposal.analysis;
    if (analysis.prefix.trim()) prefix.push(analysis.prefix.trim());
    if (analysis.suffix.trim()) suffix.push(analysis.suffix.trim());
  }

  const uniquePrefix = MCPV5UniqueStrings(prefix);
  const uniqueSuffix = MCPV5UniqueStrings(suffix);
  if (uniquePrefix.length) {
    selected = uniquePrefix.join("\n\n") + "\n\n" + selected;
  }
  if (uniqueSuffix.length) {
    selected = selected + "\n\n" + uniqueSuffix.join("\n\n");
  }
  return MCPV5HasVisibleText(selected) ? selected : base;
}

