          get card() {
              if (this.#card !== null) {

                  return this.#card;
              }

              const buildCard = (name = this.name) => addStoryCard(
                  JSON.stringify({ agent: this.name }),
                  (() => {

                      const time = new Date();
                      const match = time.toLocaleString("en-US", {
                          timeZone: "UTC",
                          year: "numeric",
                          month: "2-digit",
                          day: "2-digit",
                          hour: "numeric",
