          ) {
              const actionText = history[i]?.text ?? history[i]?.rawText;
              if ((typeof actionText !== "string") || (actionText.indexOf(">>>") !== -1)) {

                  continue;
              }
              scan: {

                  for (let j = actionText.length - 1; -1 < j; j--) {
                      const c = actionText.charCodeAt(j);
                      if ((0x20 < c) && (c !== 0x200B) && (c !== 0x200C) && (c !== 0x200D)) {

