          const agent = new Agent(IS.agent, { percent: config.percent, indicator: config.indicator });

          const whitelist = new Set();

          const mind = (() => {

              const direction = (Math.random() < 0.7) ? 1 : -1;
              const brain = agent.brain;

              const unknowns = [];
              const numbered = [];

              for (const key in brain) {
