          if (luckRoll <= plrLck && luckRoll >= 1) {
            defendFlavorText += ` ${toCoOpLang(plr, `${graspPhrases[randomInt(0, graspPhrases.length - 1)]} ${luckyPhrases[randomInt(0, luckyPhrases.length - 1)]}.`)}`;
            statUp(plr, "lck", randomFloat(0.01, 2));
          }

          storeStatsToSC();
        }

        newText += plrText[plr] + defendFlavorText;
      });
    }

    if (!newText == "") {
      return newText;
    }
    else {
      return text;
    }
  }

  function detectExercise(text) {
    let newText = "";

    dialogueFlag = true;
    dialoguePhrases.forEach(phrase => {
      if (text.toLowerCase().includes(phrase.toLowerCase())) {
        dialogueFlag = false;
      }
    });

    if (dialogueFlag == true) {

      const result = separateByPlr(text);
      const plrsDetected = Object.keys(result);
      const plrText = {};

      plrsDetected.forEach(plr => {
        plrText[plr] = result[plr].join(" ").replace(/(?<!>)>(?!>)/g, "").trim();
      });

      plrsDetected.forEach(plr => {
        let startExercise = false;
        let isDoing = false;
        let exerciseFlavorText = "";

        exerciseTextInput = [];

        exerciseTextInput = findTargetsThenSplit(plrText[plr], exerciseWords, true);
        log("exerciseTextInput simplified: " + exerciseTextInput);

        if (exerciseTextInput != null) {
          allExerciseWordIndices = [];
          allExerciseWordIndices = indicesOfTargets(exerciseTextInput, exerciseWords);
          log("allExerciseWordIndices:" + allExerciseWordIndices);

          if (allExerciseWordIndices != null) {
            startExercise = checkYouBeforeIndicesArr(plr, exerciseTextInput, allExerciseWordIndices, 3) || checkAndBeforeIndicesArr(exerciseTextInput, allExerciseWordIndices, 2);
            log("startExercise: " + startExercise);

            isDoing = cleanStringCheckForTargets(doWords, plrText[plr]);
          }
        }

        if (isDoing && startExercise) {
          totalReps = 0;
          finishedReps = 0;
          epCost = 0;
          hpCost = 0;
          atkGain = 0;
          defGain = 0;
          spdGain = 0;
          maxEpGain = 0;

          allExerciseWordIndices.forEach(exercise => {
            totalReps += findClosestNumberBefore(exerciseTextInput, exercise) ?? 1;
          });
          log("totalReps: " + totalReps);

          for (let i = 0; i < totalReps; i++) {
            if (state.players[plr].stats.ep > epCost + 15) {
              epCost += randomFloat(5, 15);
              hpCost += randomFloat(0, 0.3);
              atkGain += randomFloat(0, 0.5);
              defGain += randomFloat(0, 0.5);
              spdGain += randomFloat(0, 0.5);

              maxEpGain += randomFloat(0, 0.5);

              finishedReps = i + 1;

              log("epCost: " + epCost);
            }
            else {
              finishedReps = i;

              break;
            }
          }
          log("finishedReps: " + finishedReps);

          statUp(plr, "ep", -1 * epCost);
          statUp(plr, "hp", -1 * hpCost);
          statUp(plr, "atk", atkGain);
          statUp(plr, "def", defGain);
          statUp(plr, "spd", spdGain);

          state.players[plr].stats.maxEp += maxEpGain;
          state.players[plr].stats.maxEp = Math.floor(state.players[plr].stats.maxEp * 100) / 100;

          storeStatsToSC();

          exerciseFlavorText = toCoOpLang(plr, `${exerciseResultPhrases[randomInt(0, exerciseResultPhrases.length - 1)].replace("[num]", `${finishedReps}`)}`);

        }

        newText += plrText[plr] + exerciseFlavorText;
      });
    }

    if (!newText == "") {
      return newText;
    }
    else {
      return text;
    }
  }

  function run(tab) {
    if (tab === "input") {
      return (function () {

        const modifier = (text) => {
          text = onInput_TAS(text);

          return { text }
        }

        return modifier(text);
      })();
    }
    if (tab === "context") {
      return (function () {

        const modifier = (text) => {
          text = onContext_TAS(text);

          return { text }
        }

        return modifier(text);
      })();
    }
    if (tab === "output") {
      return (function () {

        const modifier = (text) => {
          text = onOutput_TAS(text);

          return { text }
        }

        return modifier(text);
      })();
    }
    return { text: MCPV5SafeText(globalThis.text, "\u200B") };
  }

  return { run };
}

function MCPV5Create_story_arc_engine() {

  onLibrary_SAE();
  function onLibrary_SAE(){

    createIfNoSettingsSC();
    retrieveSettingsFromSC();
    storeSettingsToSC();

    createIfNoArcSC();
    retrieveArcFromSC();
    storeArcToSC();
  }

  function onInput_SAE(text) {
    if (state.stop_SAE == true) {
      return text
    }

    text = helpCommandInput_SAE(text);

    text = detectRedoStoryArc(text);

    text = detectStopGenerating(text);

    return text;
  }

  function onContext_SAE(text) {
    if (state.stop_SAE == true) {
      return text
    }

    text = removeAngleText(text);

    text = feedAIPrompt(text);

    text = feedStoryArc(text);

    text = logContextToSettingsSC(text);

    return text;
  }

  function onOutput_SAE(text) {
    if (state.stop_SAE == true) {
      return text
    }

    text = helpCommandOutput_SAE(text);

    text = saveStoryArc(text);

    text = callAIForArc(text);

    arcElementRemoval();

    turnCounter_SAE();

    return text;
  }

  function helpCommandInput_SAE(text){
    if(text.includes("/help sae")){
      text = " ";

      state.commandCenter_SAE =
      `
      <<
      STORY ARC ENGINE By Yi1i1i
      - Story Arc Engine calls the AI to create a story arc in the Author's notes to better guide future storytelling.
      - Type "Story Arc" into story cards to access and modify settings. Logs are logged in the notes.
      - Input "/redo arc" to call the AI to regen the story arc.
      - Text encased in << >> are auto cleared from context.
      - Repeated attempts for generating story arcs may be due to AI failing to fulfill instructions or low response length (< 125). Troubleshoot by stopping and retrying in a few turns, or edit your arc prompt in "Story Arc Settings".

      - stop_SAE: Type "true" to disable SAE
      - turnsPerAICall: Number of turns before calling AI to update the story arc. Takes in an integer.
      - arcPrompt: Prompt that is fed to the AI to generate a story arc. Must be encased in << >>.
      - attemptLimit: Number of attempts at generating story arc before stopping.
      - turnsPerElemRemoval: Number of turns before removing the first plot point to progress the arc. Set to 0 to turn off removal.
      >>
      `
    }

    return text;
  }

  function helpCommandOutput_SAE(text){
    if(state.commandCenter_SAE){
      text = state.commandCenter_SAE;
    }
    delete state.commandCenter_SAE
    return text;
  }

  state.arcPrompt = state.arcPrompt || [`
  <<</SYSTEM>
  - Stop the story.
  - Only write a structured story arc outline for the future succeeding the current story by following these strict instructions:
  - Write a numbered list of 11 major events within the story arc.
  - Each event must be under 7 words.
  - Events must be in chronological order.
  - Each event must build on the last and be further in the future.
  - Dont write clichés, dialogue, description, and prose.
  - Dont write the protagonist, main character, and player.
  - Use only brief, non rigid, high-level story developments.
  - Events contain turning points, twists, discoveries, conflicts, motives, and lore.
  - Maintain immersion and consistent narrative tone.>>`
  ];

  if(state.stop_SAE == undefined){
    state.stop_SAE = false
  }

  if(state.unlockFeedAIPrompt == undefined){
    state.unlockFeedAIPrompt = false;
  }

  if(state.saveOutput == undefined){
    state.saveOutput = false;
  }

  if(state.storyArc == undefined){
    state.storyArc = "";
  }

  if(state.attemptCounter == undefined){
    state.attemptCounter = 0;
  }

  if (state.turnNum_SAE == undefined) {
    state.turnNum_SAE = 1;
  }

  state.attemptLimit = state.attemptLimit || 3;

  state.turnsPerElemRemoval = state.turnsPerElemRemoval || 3;

  state.turnsPerAICall = state.turnsPerAICall || 35;
  log("state.turnsPerAICall: " + state.turnsPerAICall);

  function turnCounter_SAE(){
    state.turnNum_SAE += 1;
    log("state.turnNum_SAE: " + state.turnNum_SAE);
  }

  function removeAngleText(text) {
    return text.replace(/<<[\s\S]*?>>/g, '');
  }

  function createIfNoArcSC(){
    if (!storyCards.find(sc => sc.title === "Current Story Arc")) {

      addStoryCard("Current Story Arc", "", "Current Story Arc");

      const arcSC = storyCards.find(sc => sc.title === "Current Story Arc");
      arcSC.keys = "/Current Story Arc"
      arcSC.description = "SPOILERS! This story card stores the story arc being fed to the AI to improve storytelling. Feel free to modify the contents.";
    }
  }

  function storeArcToSC(){

    const arcSC = storyCards.find(sc => sc.title === "Current Story Arc");

    arcSC.entry = state.storyArc;
  }

  function retrieveArcFromSC(){

    const arcSC = storyCards.find(sc => sc.title === "Current Story Arc");

    state.storyArc = arcSC.entry;
  }

  function createIfNoSettingsSC(){
    if (!storyCards.find(sc => sc.title === "Story Arc Settings")) {

      addStoryCard("Story Arc Settings", "", "Story Arc Settings");

      const settingsSC = storyCards.find(sc => sc.title === "Story Arc Settings");
      settingsSC.description = `
      Type /help sae for more info.
      stop_SAE: Type "true" to disable SAE.
      turnsPerAICall: Number of turns before calling AI to update the story arc. Takes in an integer.
      arcPrompt: Prompt that is fed to the AI to generate a story arc. Must be encased in << >>.
      attemptLimit: Number of attempts at generating story arc before stopping.
      turnsPerElemRemoval: Number of turns before removing the first plot point to progress the arc. Set to 0 to turn off removal.
      `;
    }
  }

  function storeSettingsToSC(){

    const settingsSC = storyCards.find(sc => sc.title === "Story Arc Settings");

    settingsSC.entry = `stop_SAE = ${state.stop_SAE}\nturnsPerAICall = ${state.turnsPerAICall}\nattemptLimit = ${state.attemptLimit}\nturnsPerElemRemoval = ${state.turnsPerElemRemoval}\narcPrompt = ${state.arcPrompt}`
  }

  function retrieveSettingsFromSC(){

    const settingsSC = storyCards.find(sc => sc.title === "Story Arc Settings");

    const stopSAEMatch = settingsSC.entry.match(/stop_SAE\s*=\s*([A-Za-z]+)/);
    if(stopSAEMatch == null){
    }
    else if (stopSAEMatch[1].toLowerCase() == "true") {
      state.stop_SAE = true
    }
    else if (stopSAEMatch[1].toLowerCase() == "false"){
      state.stop_SAE = false
    }
    log("state.stop_SAE: " + state.stop_SAE)

    const turnsMatch = settingsSC.entry.match(/turnsPerAICall\s*=\s*(\d+)/);
    if (turnsMatch) {
      state.turnsPerAICall = Number(turnsMatch[1]) ?? state.turnsPerAICall;
    }

    const limitMatch = settingsSC.entry.match(/attemptLimit\s*=\s*(\d+)/);
    if (limitMatch) {
      state.attemptLimit = Number(limitMatch[1]) ?? state.attemptLimit;
    }

    const removalMatch = settingsSC.entry.match(/turnsPerElemRemoval\s*=\s*(\d+)/);
    if (removalMatch) {
      state.turnsPerElemRemoval = Number(removalMatch[1]) ?? state.turnsPerElemRemoval;
    }

    const promptMatch = settingsSC.entry.match(/arcPrompt\s*=\s*(<<[\s\S]*?>>)/);
    if (promptMatch) {
      state.arcPrompt = promptMatch[1];
    }

  }

  function callAIForArc(text){
    if (state.turnNum_SAE == 1 || state.turnNum_SAE % state.turnsPerAICall === 0) {

      text = text + "\n\n<< ⚠️ Updating Story Arc Next Turn! Click 'Continue' or type '/stop'. >>";

      state.unlockFeedAIPrompt = true;
      log("state.unlockFeedAIPrompt: " + state.unlockFeedAIPrompt);

      state.saveOutput = true;
      log("state.saveOutput: " + state.saveOutput);
    }

    return text;
  }

  function feedAIPrompt(text){
    if(state.unlockFeedAIPrompt){
      text = text + " " + state.arcPrompt;

      state.unlockFeedAIPrompt = false;
    }

    return text;
  }

  function saveStoryArc(text){
    if(state.saveOutput){

      outputtedArc = text;

      log("Before: ", outputtedArc);
      outputtedArc = outputtedArc.replace(/\n?\d+\.\s*$/, '');
      outputtedArc = outputtedArc
        .split('\n')
        .filter(line => /^\d+\.\s/.test(line.trim()))
        .join('\n');
      log("After: ", outputtedArc);

      if (!/[89]/.test(outputtedArc)) {

        if (state.attemptCounter == state.attemptLimit) {
          state.saveOutput = false;

          state.attemptCounter = 0;

          text = `\n<< 🧱 Attempt Limit Reached: Keeping Current Arc. Type '/redo arc' or wait for next AI call. >>`

        }
        else {
          state.unlockFeedAIPrompt = true;
          state.saveOutput = true;

          state.attemptCounter += 1;

          text = `\n<< ⏳ Generating Story Arc (Attempt ${state.attemptCounter}/${state.attemptLimit})... Click 'Continue' or type '/stop'. >>`;
        }
      }

      else {
        state.attemptCounter = 0;

        state.storyArc = "Write the story in the following direction:\n" + outputtedArc;

        text = "\n<< ✅ Story Arc generated and saved! Click 'Continue'. >>\n\n";

        const arcSC = storyCards.find(sc => sc.title === "Current Story Arc");
        arcSC.description = `Log ${state.turnNum_SAE} | Previous Story Arc:\n${arcSC.entry}\n` + arcSC.description;

        if (arcSC.description.length > 3000) {
          halfIndex = Math.floor(arcSC.description.length / 2);
          arcSC.description = arcSC.description.slice(0, halfIndex);

          console.log("Trimming arcSC description to prevent memory overload.");
        }

        storeArcToSC();

        state.saveOutput = false;

      }
    }

    return text;
  }

  function feedStoryArc(text){

    if(state.saveOutput == false){
      text = text.replace(
        /(\[Author's note: [\s\S]*?)(])/,
        (_, noteStart, noteEnd) => noteStart + "\n" + state.storyArc + noteEnd
      );
    }

    return text;
  }

  function detectRedoStoryArc(text){
    if(text.includes("/redo arc")){
      state.unlockFeedAIPrompt = true;
      state.saveOutput = true;

      text = "<< ➰ Regenerating Story Arc... >>"
    }

    return text;
  }

  // Function to allow player to stop story arc generating
  function detectStopGenerating(text){
    if(text.includes("/stop") && state.unlockFeedAIPrompt == true){
      state.unlockFeedAIPrompt = false;
      state.saveOutput = false;

      state.attemptCounter = 0;

      text = "<< ⛔ Story Arc Generation Stopped. >>";
    }

    return text;
  }

  function logContextToSettingsSC(text){
    // Fetch the sc
    const settingsSC = storyCards.find(sc => sc.title === "Story Arc Settings");

    // Trim notes on char limit to prevent memory overfill
    if(settingsSC.description.length > 3000){
      halfIndex = Math.floor(settingsSC.description.length / 2);
      settingsSC.description = settingsSC.description.slice(0, halfIndex);

      console.log("Trimming settingsSC description to prevent memory overload.");
    }

    // Log to setting sc notes
    settingsSC.description = `Context Log ${state.turnNum_SAE} | ${text}\n` + settingsSC.description;

    return text;
  }

  function removeFirstListItem(text) {
    // Match numbered list using regex, starting from a line that begins with a number
    const lines = text.split('\n');

    // Find the index where the numbered list starts
    const startIndex = lines.findIndex(line => /^\d+\.\s/.test(line));
    if (startIndex === -1) return text; // No list found

    // Extract text before the list and the list itself
    const beforeList = lines.slice(0, startIndex);
    const listLines = lines.slice(startIndex);

    // Remove first list item
    listLines.shift();

    // Renumber the remaining list
    const renumberedList = listLines.map((line, idx) => {
      return `${idx + 1}. ${line.replace(/^\d+\.\s*/, '')}`;
    });

    // Reassemble the full text
    return [...beforeList, ...renumberedList].join('\n');
  }

  // Remove the first plot element in story arc every set turn to help clean and progress story arc
  function arcElementRemoval(){
    if(state.saveOutput == false
    && state.turnNum_SAE >= 5
    && state.turnNum_SAE % state.turnsPerElemRemoval == 0
    && state.turnsPerElemRemoval !== 0
    ){
      // Fetch the sc and log the previous arc in sc notes
      const arcSC = storyCards.find(sc => sc.title === "Current Story Arc");

      // Get first plot element to be removed and log to sc description
      match = state.storyArc.match(/^1\.\s.*$/m);
      if(match){
        arcSC.description = `Log ${state.turnNum_SAE} | Plot Element Removed:\n${match[0]}\n` + arcSC.description;
      }

      // Remove first plot element and save the rest of the story arc
      state.storyArc = removeFirstListItem(state.storyArc);
      storeArcToSC();
      log("\narcElementRemoval ran.")
    }
  }

  function run(tab) {
    if (tab === "input") {
      return (function () {
        //Input Script

        // Every script needs a modifier function
        const modifier = (text) => {
          text = onInput_SAE(text);

          return { text }
        }

        // Don't modify this part
        return modifier(text);
      })();
    }
    if (tab === "context") {
      return (function () {

        const modifier = (text) => {
          text = onContext_SAE(text);

          return { text }
        }

        return modifier(text);
      })();
    }
    if (tab === "output") {
      return (function () {

        const modifier = (text) => {
          text = onOutput_SAE(text);

          return { text }
        }

        return modifier(text);
      })();
    }
    return { text: MCPV5SafeText(globalThis.text, "\u200B") };
  }

  return { run };
}

function MCPV5Create_narrative_governor() {

  function run(tab) {
    if (tab === "input") {
      return (function () {

        state.initialHeatValue = 0
        state.initialTemperatureValue = 1
        state.temperatureIncreaseChance = 15

        state.heatIncreaseValue = 1
        state.temperatureIncreaseValue = 1

        state.playerIncreaseHeatImpact = 2
        state.playerDecreaseHeatImpact = 2
        state.playerIncreaseTemperatureImpact = 1
        state.playerDecreaseTemperatureImpact = 1
        state.threshholdPlayerIncreaseTemperature = 2
        state.threshholdPlayerDecreaseTemperature = 2

        state.modelIncreaseHeatImpact = 1
        state.modelDecreaseHeatImpact = 2
        state.modelIncreaseTemperatureImpact = 1
        state.modelDecreaseTemperatureImpact = 1
        state.threshholdModelIncreaseTemperature = 3
        state.threshholdModelDecreaseTemperature = 3

        state.maximumTemperature = 12
        state.trueMaximumTemperature = 15

        state.minimumTemperature = 1
        state.trueMinimumTemperature = 1

        state.overheatTimer = 4
        state.overheatReductionForHeat = 5
        state.overheatReductionForTemperature = 1

        state.cooldownTimer = 5
        state.cooldownRate = 2

        state.randomExplosionChance = 3
        state.randomExplosionHeatIncreaseValue = 5
        state.randomExplosionTemperatureIncreaseValue = 2

        function randomint(min, max) {
          min = Math.ceil(min)
          max = Math.floor(max)
          return Math.floor(Math.random() * (max - min + 1)) + min
        }

        const conflictWords = ["attack", "stab", "destroy", "break", "steal", "ruin", "burn", "smash", "sabotage", "disrupt", "vandalize", "overthrow", "assassinate", "plunder", "rob", "ransack", "raid", "hijack", "detonate", "explode", "ignite", "collapse", "demolish", "shatter", "strike", "slap", "obliterate", "annihilate", "corrupt", "infect", "poison", "curse", "hex", "summon", "conjure", "mutate", "provoke", "riot", "revolt", "mutiny", "rebel", "resist", "intimidate", "blackmail", "manipulate", "brainwash", "lie", "cheat", "swindle", "disarm", "fire", "hack", "overload", "flood", "drown", "rot", "dissolve", "slaughter", "terminate", "execute", "drama", "conflict", "evil", "kill", "slay", "defeat", "fight", "doom", "slice", "pain", "dying", "die", "perish", "blood"]

        const calmingWords = ["calm", "rest", "relax", "meditate", "sleep", "comfort", "hug", "smile", "forgive", "mend", "repair", "plant", "sing", "dance", "celebrate", "collaborate", "share", "give", "donate", "protect", "shelter", "trust", "hope", "dream", "revive", "eat", "drink", "balance", "cheer", "laugh", "play", "build", "bake", "craft", "cook", "empathize", "apologize", "befriend", "admire", "sympathize", "thank", "appreciate", "cherish", "love", "pet", "respect", "restore", "guide", "teach", "learn", "daydream", "wander", "explore", "discover", "reflect", "happy", "joy", "kind", "heal", "help", "assist"]

        const modifier = (text) => {
          state.originalAuthorsNote = ""

          if (state.heat == undefined){
            state.heat = state.initialHeatValue
            state.cooldownMode = false
            state.overheatMode = false
          }
          if (state.storyTemperature == undefined){
            state.storyTemperature = state.initialTemperatureValue
          }
          const lowerText = text.toLowerCase()
          const words = lowerText.split(/\s+/)
          let conflictCount = 0
          let calmingCount = 0

          words.forEach(word => {
            const fixedWord = word.replace(/^[^\w]+|[^\w]+$/g, '')
            if (conflictWords.includes(fixedWord)) {
              conflictCount++
            }
            if (calmingWords.includes(fixedWord)) {
              calmingCount++
            }
          })

          if (state.cooldownMode == false){
            if (conflictCount > 0) {
              state.heat += conflictCount * state.playerIncreaseHeatImpact
              if (conflictCount >= state.threshholdPlayerIncreaseTemperature){
                state.storyTemperature += conflictCount * state.playerIncreaseTemperatureImpact
                log(`Detected ${conflictCount} conflict words (Player). Increasing heat & temperature.`)
              }
              else{
                log(`Detected ${conflictCount} conflict words (Player). Increasing heat.`)
              }
            }

            if (calmingCount > 0) {
              state.heat -= conflictCount * state.playerDecreaseHeatImpact
              if (calmingCount >= state.threshholdPlayerDecreaseTemperature){
                state.storyTemperature -= calmingCount * state.playerDecreaseTemperatureImpact
                log(`Detected ${calmingCount} calming words (Player). Decreasing heat & temperature.`)
              }
              else{
                log(`Detected ${calmingCount} calming words (Player). Decreasing heat.`)
              }
            }
          }

          state.chance = randomint(1, 100)
          if (state.chance <= state.randomExplosionChance){
            state.heat = state.heat + state.randomExplosionHeatIncreaseValue
            state.storyTemperature = state.storyTemperature + state.randomExplosionTemperatureIncreaseValue
            log("!WARNING! Explosion Occured! (+" + state.randomExplosionHeatIncreaseValue + " heat) (+" + state.randomExplosionTemperatureIncreaseValue + " temperature)")
          }
          if(state.cooldownMode == false && state.overheatMode == false){
            state.heat = state.heat + state.heatIncreaseValue
            log("Heat: " + state.heat)
          }
          state.chance = randomint(1, state.temperatureIncreaseChance)
          if (state.chance <= state.heat){
            state.heat = 0
            state.storyTemperature = state.storyTemperature + state.temperatureIncreaseValue
            log("Temperature Increased. Temperature is now " + state.storyTemperature)
          }
          if (state.storyTemperature >= state.maximumTemperature){
            if (state.cooldownMode == false && state.overheatMode == false){
              state.overheatMode = true
              state.overheatTurnsLeft = state.overheatTimer
              log("Overheat Mode Activated")
            }
          }
          if (state.cooldownMode == true){
            state.cooldownTurnsLeft --
            log("Cooldown Timer: " + state.cooldownTurnsLeft)
            state.storyTemperature = state.storyTemperature - state.cooldownRate
            if(state.cooldownTurnsLeft <= 0){
              state.cooldownMode = false
              log("Cooldown Mode Disabled")
            }
          }
          else{
            if(state.overheatMode == true){
              state.overheatTurnsLeft --
              log("Overheat Timer: " + state.overheatTurnsLeft)
              if (state.overheatTurnsLeft <= 0){
                state.storyTemperature = state.storyTemperature - state.overheatReductionForTemperature
                state.heat = state.heat - state.overheatReductionForHeat
                state.overheatMode = false
                state.cooldownMode = true
                state.cooldownTurnsLeft = state.cooldownTimer
                log("Cooldown Mode Activated")
              }
            }
          }

          if (state.storyTemperature > state.trueMaximumTemperature){
