      if (derivedIds.some(id => !frozenPacket.some(source => source && source.id === id))) return false;
    }
    const frozenPacketCandidates = pendingRetryPacketCandidates(plan, kind);
    return !!modelAnswerTaskForCandidate(
      owner,
      plan.retryTargets,
      frozenPacketCandidates,
      "",
      "",
      plan.relationshipPace || runtime.relationshipPace,
      plan.selectedCandidate,
      plan.retryEvidenceIds
    );
  }

  function updatePendingOperationRetry(plan, outcome) {
