      const target = targetForCode(plan, candidate.subjectCode);
      if (!target || target.nameSubject !== true || target.mode !== "known") {
        return { ok: false, error: "Name used a Subject code outside the supplied identity map." };
      }
      selected = {
        ...selected,
        targetKey: target.key,
        nameAlias: candidate.alias,
        nameTransition: candidate.transition,
        nameReplacedAlias: candidate.replacedAlias || "",
        nameUse: candidate.useField,
        gain: candidate.transition === "Observed"
          ? settings.OPERATION_POINTS.SUPPORTING_EVIDENCE_GAIN
          : settings.OPERATION_POINTS.EXPLICIT_DIRECT_GAIN
      };
    } else if (kind === "relationship") {
      const target = targetForCode(plan, candidate.targetCode);
      if (!target || target.relationship !== true || target.key === "self") {
        return { ok: false, error: "Relationship used a Target code outside the supplied directional map." };
      }
      if (candidate.eventKind !== "D") {
        return { ok: false, error: "The raw evidence assessment authorizes completed direct Relationship movement with D." };
      }
      const destination = relationshipDestination(candidate.field, candidate.destination);
      if (!destination) {
        return { ok: false, error: "Relationship supplied a destination outside its field's legal stages." };
      }
      selected = {
        ...selected,
        targetKey: target.key,
        field: candidate.field,
        destination: destination.label,
        direct: true,
        gain: settings.OPERATION_POINTS.EXPLICIT_DIRECT_GAIN
      };
    } else if (kind === "view") {
      const target = targetForCode(plan, textOf(candidate.targetField).trim().toUpperCase());
      if (!target) {
        return { ok: false, error: "View used a Target code outside the supplied target map." };
      }
      const destination = canonicalViewDestination(candidate.destination);
      const mode = canonicalViewOperationMode(candidate.severity);
      if (!destination || !mode || !viewOperationDestinations(target, null).includes(destination)) {
        return { ok: false, error: "View supplied a destination or mode outside the target's legal mechanics." };
      }
      const mechanicalMode = viewOperationModeForCandidate(candidate, target);
      selected = {
        ...selected,
        targetKey: target.key,
        field: "Category",
        destination,
        allowedModes: [mechanicalMode],
        gain: settings.OPERATION_POINTS.EXPLICIT_VIEW_GAIN
      };
    } else if (kind === "turning") {
      const target = targetForCode(plan, candidate.targetCode);
      const choice = assessmentTurningPointChoices(owner).find(item => item.id === candidate.turningPointId
        && item.modes.includes(candidate.mode));
      if (!target || target.key !== "self" || !choice) {
        return { ok: false, error: "Turning Point used a StableID or Movement outside the supplied current mechanics." };
      }
      selected = {
        ...selected,
        targetKey: "self",
        field: choice.id,
        destination: candidate.mode,
        managedSignature: choice.managedSignature,
        gain: candidate.mode === "Support"
          ? settings.OPERATION_POINTS.SUPPORTING_EVIDENCE_GAIN
          : (candidate.mode === "Breakthrough"
            ? settings.OPERATION_POINTS.EXPLICIT_DIRECT_GAIN
            : settings.OPERATION_POINTS.STRONG_STATE_GAIN)
      };
    }
    selected.evidenceSignature = operationEvidenceSignature(selected, items);
    if (!selected.evidenceSignature) {
      return { ok: false, error: "The model-authored operation could not form a stable evidence signature." };
    }
    selected.drain = operationDrainForCandidate(selected, plan.ownerOpportunity);
    selected.net = selected.gain - selected.drain;
    plan.selectedOperationKind = kind;
    plan.selectedCandidate = clone(selected);
    plan.selectedEvidenceSignature = selected.evidenceSignature;
    plan.selectedGain = selected.gain;
    plan.selectedDrain = selected.drain;
    plan.selectedNet = selected.net;
    plan.semanticAssessmentResolved = true;
    return { ok: true, selected };
  }

  function targetForCode(plan, code) {
    return (plan.targets || []).find(target => target.code === code) || null;
  }

  function directPrivateThought(value, owner) {
    const thought = line(value, settings.MAX_STATE_VALUE_CHARS);
    if (!thought) return false;
    if (!/\b(?:I|me|my|mine|myself|we|us|our|ours|ourselves)\b/i.test(thought)) return false;
    const ownerNames = uniqueNameForms([owner && owner.name].concat((owner && owner.aliases) || []), 120)
      .map(name => line(name, 120))
      .filter(Boolean);
    if (ownerNames.length) {
      const ownerPattern = ownerNames.map(escapeRegExp).join("|");
      const narratedState = "(?:thinks?|feels?|worries?|hopes?|wants?|fears?|believes?|wonders?|remembers?|realizes?|seems?|appears?|is\\s+(?:feeling|thinking|worried|afraid|anxious|hopeful|angry|sad|uncertain))";
      if (new RegExp("^(?:" + ownerPattern + ")\\s+" + narratedState + "\\b", "i").test(thought)) return false;
      if (new RegExp("^(?:" + ownerPattern + ")['’]s\\s+(?:thought|feeling|goal|tension)\\b", "i").test(thought)) return false;
    }
    if (/^(?:(?:the|this|that)\s+)?(?:npc|character|owner)\b/i.test(thought)) return false;
    return true;
  }

  function derivedStateFromTriggers(triggers) {
    const rules = triggers.map(code => TRIGGER_RULES[code]).filter(Boolean);
    const feelings = unique(rules.map(rule => rule.feeling).filter(Boolean), 60).slice(0, 2);
    const goals = unique(rules.map(rule => rule.goal).filter(Boolean), 96);
    const tensions = unique(rules.map(rule => rule.tension).filter(Boolean), 120);
    const positive = triggers.some(code => ["affection", "hope", "relief", "reconnect", "trust_gain", "closeness_gain", "boundary_respected", "repair"].includes(code));
    const negative = triggers.some(code => ["anger", "anxiety", "grief", "hurt", "uncertainty", "withdraw", "conflict", "trust_loss", "closeness_loss", "boundary_crossed", "betrayal"].includes(code));
    return {
      feeling: feelings.join(" and "),
      goal: goals[0] || "",
      tension: tensions[0] || (positive && negative ? "competing impulses remain unresolved" : "")
    };
  }

  function targetGroundingError(candidate, target, plan) {
    const thought = line(candidate && candidate.thought, settings.MAX_STATE_VALUE_CHARS);
    if (!thought || !target) return "";
    const profile = stateTargetPronounProfile(null, target);
    if (profile && profile.family) {
      const mentionedFamilies = STATE_PRONOUN_FAMILIES.filter(family =>
        family.forms.some(form => aliasMentioned(thought, form))
      );
      const expectedMentioned = mentionedFamilies.some(family => family.key === profile.family);
      const mismatched = mentionedFamilies.filter(family => family.key !== profile.family);
      const groupReference = [thought, line(candidate && candidate.situation, settings.MAX_STATE_VALUE_CHARS)]
        .filter(Boolean).join(" ");
      const groupCue = /\b(?:both|all|everyone|everybody|others|people|group|staff|team|crew|keepers|council|committee|audience|community|household|family|friends|guests|crowd|colleagues|classmates|parents|children|siblings|couple|pair|together|those two|the two of them)\b/i.test(groupReference);
      const targetNpcKey = target.key && target.key.startsWith("npc:") ? target.key.slice(4) : "";
      const otherNpcNamed = characters.some(character => character.key !== (plan && plan.ownerKey)
        && character.key !== targetNpcKey
        && characterMentioned(thought, character, false, CC.activeKeys));
      const playerNamedAsOther = target.key !== "player"
        && (aliasMentioned(thought, player.name) || /\byou\b/i.test(thought));
      if (!expectedMentioned && mismatched.length === 1 && !groupCue && !otherNpcNamed && !playerNamedAsOther) {
        return "State Thought used " + mismatched[0].label + " for the sole unambiguous About target "
          + target.name + ", whose configured pronouns are " + profile.display + ".";
      }
    }
    const firstPerson = /\b(?:I|me|my|mine|myself|we|us|our|ours|ourselves)\b/i.test(thought);
    if (firstPerson) return "";
    const explicitlyMentioned = (plan.targets || []).filter(item =>
      item.key !== "self" && item.name && aliasMentioned(thought, item.name)
    );
    if (explicitlyMentioned.length === 1 && explicitlyMentioned[0].key !== target.key) {
      return "State About conflicted with the only person explicitly named in Thought.";
    }
    const thirdPerson = /\b(?:he|him|his|himself|she|her|hers|herself|they|them|their|theirs|themself|themselves)\b/i.test(thought);
    if (target.key === "self" && thirdPerson) {
      return "Self About was rejected because the direct Thought concerned another person without any self-reference.";
    }
    return "";
  }

  function stateMechanicalContractError(candidate, selected) {
    const frozenTriggers = triggerList(selected && selected.stateTriggers || []);
    if (!frozenTriggers.length || JSON.stringify(triggerList(candidate.triggers)) !== JSON.stringify(frozenTriggers)) {
      return "State TriggerList did not match the scheduled operation contract.";
    }
    return "";
  }

  function applyStateCandidate(owner, candidate, nextClock, plan, evidenceItems) {
    if (!owner || !candidate) return { ok: false, error: "State operation lacked its fixed owner or content." };
    const npc = CC.npcs[owner.key];
    if (!npc) return { ok: false, error: "State owner was not registered." };
    npc.state = normalizeState(npc.state, CC.stateClock);
    const target = targetForCode(plan, candidate.targetCode);
    if (!target) return { ok: false, error: "State used an About code that was not authorized for this owner." };
    const storedTarget = { ...target, name: storedTargetName(target.key, target.name) };
    const priorSituation = npc.state.situation;
    const triggers = triggerList(candidate.triggers);
    if (!triggers.length) return { ok: false, error: "State contained no supported triggers." };
    const selected = plan && plan.selectedCandidate && typeof plan.selectedCandidate === "object"
      ? plan.selectedCandidate
      : {};
    if (normalizedTargetKey(selected.targetKey) !== normalizedTargetKey(target.key)) {
      return { ok: false, error: "State About target did not match the frozen operation target." };
    }
    const contractError = stateMechanicalContractError(candidate, selected);
    if (contractError) return { ok: false, error: contractError };
    const frozenConfirmationSituation = situationPhrase(selected.confirmSituation);
    const frozenConfirmation = keyOf(selected.stateMode) === "confirm"
      && !!frozenConfirmationSituation
      && normalizedTargetKey(selected.targetKey) === normalizedTargetKey(target.key);
    const suppliedSituation = situationPhrase(candidate.situation);
    const requestedKeep = keyOf(suppliedSituation) === "keep";
    if (frozenConfirmation) {
      const suppliedCurrent = requestedKeep
        || keyOf(suppliedSituation) === keyOf(frozenConfirmationSituation);
      if (!suppliedCurrent) {
        return { ok: false, error: "The frozen State confirmation required KEEP or the exact supplied Current Situation." };
      }
      if (!priorSituation.value
        || keyOf(priorSituation.value) !== keyOf(frozenConfirmationSituation)
        || normalizedTargetKey(priorSituation.targetKey) !== normalizedTargetKey(target.key)) {
        return { ok: false, error: "The frozen State confirmation no longer matched the active Situation and About target." };
      }
    } else if (requestedKeep) {
      return { ok: false, error: "KEEP was available only for a frozen State confirmation." };
    }
    const situation = frozenConfirmation ? priorSituation.value : suppliedSituation;
    if (!situation || /[{}|\r\n]/.test(situation)) {
      return { ok: false, error: "State contained no complete safe Situation phrase." };
    }
    const thought = line(candidate.thought, settings.MAX_STATE_VALUE_CHARS);
    const directThought = directPrivateThought(thought, owner);
    const groundingError = directThought
      ? targetGroundingError({ ...candidate, situation }, target, plan)
      : "";
    const validThought = directThought && !groundingError;

    const citedIds = unique((Array.isArray(evidenceItems) ? evidenceItems : []).map(item => item && item.id), 20)
      .map(value => value.toUpperCase())
      .filter(value => /^E\d+$/.test(value));
    if (!citedIds.length) return { ok: false, error: "State Situation confirmation lacked completed evidence." };
    const sameSituation = keyOf(priorSituation.value) === keyOf(situation)
      && normalizedTargetKey(priorSituation.targetKey) === normalizedTargetKey(target.key);
    const novelIds = citedIds.filter(id => !priorSituation.evidenceIds.includes(id));
    if (sameSituation && !novelIds.length) {
      return { ok: false, error: "The same Situation required distinct later evidence for another confirmation." };
    }
    const threshold = settings.SITUATION_EXPERIENCE_CONFIRMATIONS;
    const confirmations = sameSituation
      ? Math.min(threshold, priorSituation.confirmations + 1)
      : 1;
    const situationEvidenceIds = sameSituation
      ? unique(priorSituation.evidenceIds.concat(citedIds), 20)
      : citedIds;
    const signature = experienceSignature(owner.key, target.key, situation);
    let promotedSignature = sameSituation ? priorSituation.promotedSignature : "";
    const shouldPromote = confirmations >= threshold && promotedSignature !== signature;

    const priorStateSnapshot = clone(npc.state);
    const priorProvenance = clone(CC.provenance);
    const priorProvenanceCreated = CC.last.provenanceCreated;
    const priorExperienceCards = captureManagedExperienceCards();
    const priorStateCard = captureStateCard(owner);
    const stateTitleKey = stateTitle(owner);
    const priorHashPresent = Object.prototype.hasOwnProperty.call(CC.cardHashes, stateTitleKey);
    const priorHash = CC.cardHashes[stateTitleKey];
    const rollback = error => {
      npc.state = normalizeState(priorStateSnapshot, CC.stateClock);
      CC.provenance = normalizeProvenanceLedger(priorProvenance);
      CC.last.provenanceCreated = priorProvenanceCreated;
      const experiencesRestored = restoreManagedExperienceCards(priorExperienceCards);
      const stateRestored = restoreStateCard(owner, priorStateCard);
      if (stateRestored && priorHashPresent) CC.cardHashes[stateTitleKey] = priorHash;
      else delete CC.cardHashes[stateTitleKey];
      const restored = experiencesRestored && stateRestored;
      const reported = textOf(error).replace(/[.;\s]+$/g, "")
        + (restored ? "." : "; rollback was incomplete.");
      CC.last.provenanceDiagnostics = unique((CC.last.provenanceDiagnostics || []).concat(
        "State provenance transaction rolled back: " + reported
      ), 500).slice(-20);
      return { ok: false, error: reported };
    };

    let promotion = null;

    const derived = derivedStateFromTriggers(triggers);
    const changed = [];
    [["feeling", derived.feeling], ["goal", derived.goal], ["tension", derived.tension]].forEach(([field, value]) => {
      if (npc.state[field].value !== value) changed.push(field);
      npc.state[field] = { value, updatedClock: nextClock };
    });
    if (validThought) {
      if (npc.state.thought.value !== thought) changed.push("thought");
      npc.state.thought = { value: thought, updatedClock: nextClock };
    }
    if (npc.state.target.key !== target.key) changed.push("about");
    if (npc.state.triggers.value.join(",") !== triggers.join(",")) changed.push("triggers");
    if (!sameSituation) changed.push("situation");
    npc.state.target = { key: target.key, name: storedTarget.name, updatedClock: nextClock };
    npc.state.triggers = { value: triggers, updatedClock: nextClock };
    npc.state.situation = {
      value: sameSituation ? priorSituation.value : situation,
      updatedClock: nextClock,
      confirmations,
      evidenceIds: situationEvidenceIds,
      targetKey: target.key,
      targetName: storedTarget.name,
      promotedSignature
    };

    if (!writeStateCard(owner)) {
      return rollback("The managed State card could not be saved and verified.");
    }

    const stateProvenance = appendProvenanceRecord({
      prefix: "S",
      ownerKey: owner.key,
      targetKey: target.key,
      targetName: storedTarget.name,
      signature,
      managedSignature: stateSituationSignature(owner.key, target.key, situation),
      confirmation: confirmations,
      sourceIds: citedIds,
      storyEvidenceIds: citedIds,
      triggers,
      value: situation,
      thought: validThought ? thought : derived.feeling,
      explanation: validThought ? thought : derived.feeling,
      createdClock: nextClock,
      ownerOpportunity: plan && plan.ownerOpportunity || CC.ownerOpportunities[owner.key] || 0,
      active: true
    });
    if (!stateProvenance.ok) {
      return rollback("State changed but S# provenance could not commit: " + stateProvenance.error);
    }

    if (shouldPromote) {
      promotion = promoteExperienceWithProvenance(owner, storedTarget, situation, plan);
      if (!promotion.ok) {
        return rollback("Situation reached " + threshold + "/" + threshold
          + " but its Experience provenance transaction could not commit: " + promotion.error);
      }
      promotedSignature = signature;
      npc.state.situation.promotedSignature = promotedSignature;
      if (!writeStateCard(owner)) {
        return rollback("Experience and X# committed but the promoted State marker could not be saved and verified.");
      }
    }

    const stateChange = unique(changed, 30).join(",") || "refreshed";
    const confirmationSummary = "Situation " + confirmations + "/" + threshold
      + (promotion ? (promotion.deduplicated ? " deduplicated in Experiences" : " promoted to Experiences") : "")
      + "; provenance " + stateProvenance.record.id
      + (promotion && promotion.provenanceRecord ? ", " + promotion.provenanceRecord.id : "");
    return {
      ok: true,
      summary: owner.name + "/State " + stateChange + "; " + confirmationSummary,
      provenanceIds: [stateProvenance.record.id]
        .concat(promotion && promotion.provenanceRecord ? promotion.provenanceRecord.id : []),
      warning: validThought ? "" : "Applied trigger-derived State but ignored a Thought that was unavailable or unsuitable for direct storage."
    };
  }

  function viewOperationModeForCandidate(candidate, target) {
    const destination = canonicalViewDestination(candidate && candidate.destination);
    if (destination === "Buried") return "Buried";
    if (destination === "Recovered") return "Recovered";
    if (target && target.mode === "recovering") return "Reconciled";
    return canonicalViewOperationMode(candidate && candidate.severity);
  }

  function viewInterpretationKeyForCandidate(candidate, target) {
    const destination = canonicalViewDestination(candidate && candidate.destination);
    const operationMode = viewOperationModeForCandidate(candidate, target);
    const targetMode = line(target && target.mode, 40);
    return destination && operationMode
      ? [destination, operationMode, targetMode || ""].join("|")
      : "";
  }

  function citedEvidenceForOperation(owner, candidate, plan, targetKey) {
    const operationKind = keyOf(candidate && candidate.kind);
    const normalizedTarget = normalizedTargetKey(targetKey);
    const suppliedPacket = Array.isArray(plan.sourcePacket) ? plan.sourcePacket : [];
    const suppliedById = Object.create(null);
    suppliedPacket.forEach(source => {
      const id = continuitySourceId(source && source.id);
      if (id) suppliedById[id] = source;
    });
    const items = [];
    const relationshipTarget = operationKind === "relationship"
      ? targetForCode(plan, candidate && candidate.targetCode)
      : null;
    const viewResolution = operationKind === "view"
      ? resolveViewTarget(owner, candidate, plan)
      : null;
    const viewTarget = viewResolution && viewResolution.ok ? viewResolution.target : null;
    if (operationKind === "relationship" && (!relationshipTarget || relationshipTarget.relationship !== true
      || relationshipTarget.key === "self" || relationshipTarget.key !== normalizedTarget)) {
      return { ok: false, error: "Relationship citations did not resolve to the exact frozen directional target." };
    }
    if (operationKind === "view" && (!viewResolution || !viewResolution.ok || !viewTarget
      || normalizedTargetKey(viewTarget.key) !== normalizedTarget)) {
      return { ok: false, error: "View citations did not resolve to the exact frozen owner-target state." };
    }
    if (operationKind === "turning" && normalizedTarget !== "self") {
      return { ok: false, error: "Turning Point citations did not resolve to the fixed owner's Self target." };
    }
    if (operationKind === "relationship" && candidate.eventKind === "D"
      && (candidate.evidenceIds || []).some(value => /^[SX]\d+$/i.test(textOf(value).trim()))) {
      return { ok: false, error: "Direct Relationship movement may cite completed raw E# evidence only; S# and X# authorise A only." };
    }
    if (operationKind === "relationship" && candidate.eventKind === "A"
      && (candidate.evidenceIds || []).some(value => /^E\d+$/i.test(textOf(value).trim()))) {
      return { ok: false, error: "Accumulated Relationship movement may cite accepted S# and X# evidence only; raw E# evidence authorises D only." };
    }
    refreshProvenanceActivity();
    for (const rawId of candidate.evidenceIds || []) {
      const id = continuitySourceId(rawId);
      if (!id || !sourceIdLegalForOperation(operationKind, id)) {
        return { ok: false, error: textOf(rawId) + " was not a legal source for the frozen "
          + operationKindLabel(operationKind) + " operation." };
      }
      const frozenSource = suppliedById[id];
      if (!frozenSource) return { ok: false, error: id + " was not supplied in the frozen operation source packet." };
      const eligibility = plan.evidenceEligibility && plan.evidenceEligibility[id];
      if (operationKind === "state" && (!eligibility || eligibility.state !== true || frozenSource.state !== true)) {
        return { ok: false, error: id + " was not supplied as State-eligible evidence." };
      }
      if (operationKind === "view" && (!eligibility || eligibility.view !== true || frozenSource.view !== true)) {
        return { ok: false, error: id + " was not supplied as View-eligible evidence." };
      }
      if (operationKind === "relationship" && (!eligibility || eligibility.relationship !== true || frozenSource.relationship !== true)) {
        return { ok: false, error: id + " was not supplied as Relationship-eligible evidence." };
      }
      if (operationKind === "name" && (!eligibility || eligibility.name !== true || frozenSource.name !== true)) {
        return { ok: false, error: id + " was not supplied as Name-eligible evidence." };
      }
      if (operationKind === "turning" && (!eligibility || eligibility.turning !== true || frozenSource.turning !== true)) {
        return { ok: false, error: id + " was not supplied as Turning Point-eligible evidence." };
      }

      if (id.charAt(0) === "E") {
        const item = evidenceForId(id);
        if (!item) return { ok: false, error: id + " was no longer present in the evidence ledger." };
        if (operationKind === "state" && item.usedStateBy[owner.key]) {
          return { ok: false, error: id + " was already consumed for this owner's State." };
        }
        if (operationKind === "view") {
          const ownerUses = item.usedViewsBy[owner.key];
          if (ownerUses && ownerUses[normalizedTarget]) {
            return { ok: false, error: id + " was already consumed for this owner-target View." };
          }
        }
        if (operationKind === "relationship") {
          const ownerUses = item.usedRelationshipsBy[owner.key];
          if (ownerUses && ownerUses[normalizedTarget]) {
            return { ok: false, error: id + " was already consumed for this owner-target Relationship." };
          }
          if (candidate.eventKind !== "D") {
            return { ok: false, error: id + " was raw evidence and may authorise direct Relationship movement only." };
          }
        }
        if (operationKind === "name") {
          const subjectUses = item.usedNamesBy[normalizedTarget];
          if (subjectUses && subjectUses[nameKeyOf(candidate.alias)]) {
            return { ok: false, error: id + " was already consumed for this identity-alias Name record." };
          }
        }
        if (operationKind === "turning") {
          const turningId = canonicalTurningPointId(candidate.turningPointId);
          const ownerUses = item.usedTurningPointsBy[owner.key];
          if (!turningId || (ownerUses && ownerUses[turningId])) {
            return { ok: false, error: id + " was already consumed for this owner's Turning Point record." };
          }
        }
        items.push({
          ...item,
          text: textOf(frozenSource.text)
        });
        continue;
      }

      if (operationKind === "relationship" && /^[SX]\d+$/.test(id)) {
        if (candidate.eventKind !== "A") {
          return { ok: false, error: id + " is derived continuity and may authorise accumulated Relationship movement only." };
        }
        const record = provenanceRecordById(id);
        if (!record || !["state", "experience"].includes(record.kind)) {
          return { ok: false, error: id + " did not resolve to an accepted State or Experience provenance record." };
        }
        if (frozenSource.source !== "provenance" || frozenSource.prefix !== id.charAt(0)) {
          return { ok: false, error: id + " did not match its frozen derived-source type." };
        }
        if (record.ownerKey !== owner.key || line(frozenSource.ownerKey, 160) !== owner.key) {
          return { ok: false, error: id + " belonged to a different Relationship owner." };
        }
        if (record.targetKey !== normalizedTarget || normalizedTargetKey(frozenSource.targetKey) !== normalizedTarget) {
          return { ok: false, error: id + " belonged to a different Relationship target." };
        }
        if (record.active === false || !managedSignatureStillValid(record)
          || record.managedSignature !== frozenSource.managedSignature) {
          return { ok: false, error: id + " was inactive or its managed continuity signature had become stale." };
        }
        if (Math.max(0, Number(frozenSource.age) || 0) >= settings.RELATIONSHIP_EVIDENCE_OPPORTUNITIES) {
          return { ok: false, error: id + " had aged outside the frozen Relationship evidence window." };
        }
        const allowedFields = (Array.isArray(frozenSource.allowedFields) ? frozenSource.allowedFields : [])
          .map(canonicalRelationshipFieldName).filter(Boolean);
        if (!allowedFields.includes(candidate.field)) {
          return { ok: false, error: id + " did not authorise the proposed " + candidate.field + " field." };
        }
        const recomputedUse = relationshipUseSignatureForRecord(record, owner.key, normalizedTarget, candidate.field);
        const frozenUse = frozenSource.useSignatures && frozenSource.useSignatures[candidate.field];
        if (!recomputedUse || !frozenUse || recomputedUse !== frozenUse) {
          return { ok: false, error: id + " did not match the frozen narrow Relationship-use signature." };
        }
        if (provenanceUseCommitted(record, recomputedUse)) {
          return { ok: false, error: id + " had already succeeded for this exact Relationship field interpretation." };
        }
        const currentLineage = storyLineageForSources(record.sourceIds.concat(record.storyEvidenceIds || []));
        const frozenLineage = provenanceSourceIds(frozenSource.rawLineage || []).filter(value => /^E\d+$/.test(value));
        if (JSON.stringify(currentLineage) !== JSON.stringify(frozenLineage)) {
          return { ok: false, error: id + " no longer matched its frozen raw story lineage." };
        }
        items.push({
          id,
          number: 1000000 + Math.max(0, Number(record.createdClock) || 0) * 1000
            + Math.max(0, Number(id.slice(1)) || 0),
          source: "provenance",
          text: line(frozenSource.text, settings.MAX_EVIDENCE_ITEM_CHARS),
          ownerKey: record.ownerKey,
          targetKey: record.targetKey,
          targetName: record.targetName,
          allowedFields,
          managedSignature: record.managedSignature,
          rawLineage: currentLineage,
          useSignature: recomputedUse,
          provenanceRecord: record,
          directAllowed: false
        });
        continue;
      }

      if (operationKind === "view" && /^[RX]\d+$/.test(id)) {
        const record = provenanceRecordById(id);
        if (!record || !["relationship", "experience"].includes(record.kind)) {
          return { ok: false, error: id + " did not resolve to an accepted Relationship or Experience provenance record." };
        }
        if (frozenSource.source !== "provenance" || frozenSource.prefix !== id.charAt(0)) {
          return { ok: false, error: id + " did not match its frozen derived View-source type." };
        }
        if (record.ownerKey !== owner.key || line(frozenSource.ownerKey, 160) !== owner.key) {
          return { ok: false, error: id + " belonged to a different View owner." };
        }
        if (record.targetKey !== normalizedTarget || normalizedTargetKey(frozenSource.targetKey) !== normalizedTarget) {
          return { ok: false, error: id + " belonged to a different View target." };
        }
        if (record.active === false || !managedSignatureStillValid(record)
          || record.managedSignature !== frozenSource.managedSignature) {
          return { ok: false, error: id + " was inactive or its managed continuity signature had become stale." };
        }
        if (Math.max(0, Number(frozenSource.age) || 0) >= settings.VIEW_EVIDENCE_OPPORTUNITIES) {
          return { ok: false, error: id + " had aged outside the frozen View evidence window." };
        }
        const destination = canonicalViewDestination(candidate.destination);
        const operationMode = viewOperationModeForCandidate(candidate, viewTarget);
        const interpretationKey = viewInterpretationKeyForCandidate(candidate, viewTarget);
        if (!destination || !operationMode || !interpretationKey) {
          return { ok: false, error: id + " could not resolve the proposed View destination and operation mode." };
        }
        const frozenInterpretations = Array.isArray(frozenSource.interpretations)
          ? frozenSource.interpretations.map(item => ({
            destination: canonicalViewDestination(item && item.destination),
            operationMode: canonicalViewOperationMode(item && item.operationMode),
            targetMode: line(item && item.targetMode, 40)
          }))
          : [];
        if (!frozenInterpretations.some(item => item.destination === destination
          && item.operationMode === operationMode && item.targetMode === line(viewTarget.mode, 40))) {
          return { ok: false, error: id + " did not authorise this exact View destination and mode interpretation." };
        }
        const recomputedUse = viewUseSignatureForRecord(record, owner.key, normalizedTarget, destination, operationMode);
        const frozenUse = frozenSource.useSignatures && frozenSource.useSignatures[interpretationKey];
        if (!recomputedUse || !frozenUse || recomputedUse !== frozenUse) {
          return { ok: false, error: id + " did not match the frozen narrow View-use signature." };
        }
        if (provenanceUseCommitted(record, recomputedUse)) {
          return { ok: false, error: id + " had already succeeded for this exact View destination and mode." };
        }
        const currentLineage = storyLineageForSources(record.sourceIds.concat(record.storyEvidenceIds || []));
        const frozenLineage = provenanceSourceIds(frozenSource.rawLineage || []).filter(value => /^E\d+$/.test(value));
        if (JSON.stringify(currentLineage) !== JSON.stringify(frozenLineage)) {
          return { ok: false, error: id + " no longer matched its frozen raw story lineage." };
        }
        items.push({
          id,
          number: 2000000 + Math.max(0, Number(record.createdClock) || 0) * 1000
            + Math.max(0, Number(id.slice(1)) || 0),
          source: "provenance",
          text: line(frozenSource.text, settings.MAX_EVIDENCE_ITEM_CHARS),
          ownerKey: record.ownerKey,
          targetKey: record.targetKey,
          targetName: record.targetName,
          destination,
          operationMode,
          targetMode: line(viewTarget.mode, 40),
          managedSignature: record.managedSignature,
          rawLineage: currentLineage,
          useSignature: recomputedUse,
          provenanceRecord: record,
          directAllowed: false
        });
        continue;
      }

      return { ok: false, error: id + " was not a compatible derived source for this model-facing operation." };
    }
    return { ok: true, items };
  }

  function categoryDistance(left, right) {
    const leftIndex = VIEW_CATEGORY_INDEX[keyOf(left)];
    const rightIndex = VIEW_CATEGORY_INDEX[keyOf(right)];
    return Number.isInteger(leftIndex) && Number.isInteger(rightIndex)
      ? Math.abs(leftIndex - rightIndex)
      : Infinity;
  }

  function resolveViewTarget(owner, candidate, plan) {
    const field = textOf(candidate.targetField).trim();
    const fresh = field.match(/^NEW=(.+)$/i);
    if (fresh) {
      const suppliedName = line(fresh[1], 120);
      if (!suppliedName || /[{}|()\r\n]/.test(suppliedName)) {
        return { ok: false, error: "The NEW target name was empty or used reserved characters." };
      }
      const target = canonicalViewTarget(owner, suppliedName);
      if (!target) return { ok: false, error: "The NEW target could not be normalized." };
      refreshViewsStore(false);
      const ownerData = viewsForOwner(owner.key);
      const active = ownerData && ownerData.activeRecords.find(record => record.targetKey === target.key);
      if (active) return { ok: false, error: "The NEW target already had an active View record." };
      const storedActive = ownerData && ownerData.activePages.flatMap(page => page.records)
        .find(record => record.targetKey === target.key);
      const storedBuried = ownerData && ownerData.buriedPages.flatMap(page => page.records)
        .find(record => record.targetKey === target.key);
      if (storedActive || storedBuried) {
        return {
          ok: false,
          error: "The NEW target already existed on a preserved but excluded Views page; repair that page before updating it."
        };
      }
      const knownTarget = (plan.targets || []).find(item => item.key === target.key && item.mode !== "buried");
      if (knownTarget) return { ok: false, error: "The NEW target already had the authorized code " + knownTarget.code + "." };
      return { ok: true, target: { key: target.key, name: target.name, mode: "new", code: "NEW" }, fresh: true };
    }
    const code = field.toUpperCase();
    const target = targetForCode(plan, code);
    return target
      ? { ok: true, target, fresh: false }
      : { ok: false, error: "The View target code was not present in the frozen owner-specific target map." };
  }

  function relationshipStageLabels() {
    return unique(RELATIONSHIP_FIELDS.flatMap(field => (RELATIONSHIP_STAGES[field] || []).map(stage => stage.label))
      .concat(["Former", "Released"]), 120).sort((left, right) => right.length - left.length);
  }

  function correctedRelationshipExplanation(value, actualStage) {
    let result = line(value, 2000);
    const actualKey = keyOf(actualStage);
    const stageLabels = relationshipStageLabels();
    const stageAlternation = stageLabels.map(escapeRegExp).join("|");
    const actualMarker = "\uE000CCACTUAL\uE001";
    const neutral = {
      "severe distrust": "distrust", "distrust": "distrust", "guarded": "trust",
      "unproven": "trust", "cautious trust": "trust", "trust": "trust", "deep trust": "trust",
      "disconnected": "connection", "distant": "connection", "acquainted": "connection",
      "familiar": "connection", "close": "connection", "deeply close": "closeness", "intimate": "connection",
      "implied": "boundary", "explicit": "boundary", "reinforced": "boundary", "released": "boundary",
      "clear": "conflict", "friction": "conflict", "strain": "conflict", "open conflict": "conflict", "rupture": "conflict",
      "emerging": "role", "established": "role", "former": "role"
    };
    if (stageAlternation) {
      const transitionClaim = new RegExp(
        "\\b(moving|moves?|moved|movement|advancing|advances?|advanced|advance|shifting|shifts?|shifted|shift|transitioning|transitions?|transitioned|transition|changing|changes?|changed|change)"
          + "\\b[^.!?…\\n]{0,60}\\bfrom\\s+(?:the\\s+)?(" + stageAlternation + ")(?:\\s+stage)?"
          + "\\s+to\\s+(?:the\\s+)?(" + stageAlternation + ")(?:\\s+stage)?\\b",
        "gi"
      );
      result = result.replace(transitionClaim, (match, motion, fromStage, toStage) =>
        keyOf(toStage) === actualKey
          ? match
          : motion + " within the " + actualMarker + " stage"
      );
    }
    if (actualStage && stageAlternation) {
      result = result.replace(new RegExp("\\b(" + stageAlternation + ")\\b", "gi"), match =>
        keyOf(match) === actualKey ? actualMarker : match
      );
    }
    stageLabels.forEach(labelValue => {
      if (keyOf(labelValue) === actualKey) return;
      const escaped = escapeRegExp(labelValue);
      const neutralWord = neutral[keyOf(labelValue)] || "the relationship";
      const levelClaim = new RegExp(
        "\\b(?:a|an|the)\\s+" + escaped
          + "\\s+(level|degree)\\s+of\\s+(trust|closeness|connection|distance|conflict|friction|boundaries|boundary|role|reliance|intimacy)\\b",
        "gi"
      );
      result = result.replace(levelClaim, (match, measure, dimension) =>
        "the " + actualMarker + " " + measure + " of " + dimension
      );
      const labelledStage = new RegExp(
        "\\b((?:relationship|trust|closeness|boundary|boundaries|conflict|role)\\s+stage\\s+(?:is|was|became|reached|remains|at)?\\s*)"
          + escaped + "\\b",
        "gi"
      );
      result = result.replace(labelledStage, (match, prefix) => prefix + actualMarker);
      const stageCue = "(?:reached|became|is|was|now|remains|moved\\s+to|advanced\\s+to|fell\\s+to|returned\\s+to|at|into|has|holds|shows|demonstrates|indicates?|marks|signals)";
      const contextualClaim = new RegExp(
        "(\\b" + stageCue + "\\s+(?:the\\s+)?)" + escaped + "(\\s+stage)?\\b",
        "gi"
      );
      result = result.replace(contextualClaim, (match, prefix, stageWord) =>
        prefix + (stageWord ? actualMarker + stageWord : neutralWord)
      );
      result = result.replace(new RegExp("\\b" + escaped + "\\s+stage\\b", "gi"), actualMarker + " stage");
    });
    result = result.split(actualMarker).join(actualStage);
    result = result.replace(/\s{2,}/g, " ").replace(/\s+([,.;:!?])/g, "$1").trim();
    return line(result || ("The cited completed evidence changed the Relationship within the actual " + actualStage + " stage."), 2000);
  }

  function viewCategoryRegard(category) {
    return {
      Loves: "deeply positive regard",
      Likes: "positive regard",
      Neutrals: "neutral regard",
      Dislikes: "negative regard",
      Hates: "strongly negative regard"
    }[canonicalViewDestination(category)] || "durable regard";
  }

  function correctedViewExplanation(value, actualCategory) {
    let result = line(value, 2000);
    const regard = viewCategoryRegard(actualCategory);
    const stageLabels = relationshipStageLabels();
    const stageAlternation = stageLabels.map(escapeRegExp).join("|");
    if (stageAlternation) {
      const transitionClaim = new RegExp(
        "\\b(?:moving|moves?|moved|movement|advancing|advances?|advanced|advance|shifting|shifts?|shifted|shift|transitioning|transitions?|transitioned|transition|changing|changes?|changed|change)"
          + "[^.!?…\\n]{0,60}\\bfrom\\s+(?:the\\s+)?(" + stageAlternation + ")(?:\\s+stage)?"
          + "\\s+to\\s+(?:the\\s+)?(" + stageAlternation + ")(?:\\s+stage)?\\b",
        "gi"
      );
      result = result.replace(transitionClaim, "reinforcing " + regard);
    }
    stageLabels.forEach(labelValue => {
      const escaped = escapeRegExp(labelValue);
      const levelClaim = new RegExp(
        "\\b(?:a|an|the)\\s+" + escaped
          + "\\s+(?:level|degree)\\s+of\\s+(?:trust|closeness|connection|distance|conflict|friction|boundaries|boundary|role|reliance|intimacy)\\b",
        "gi"
      );
      result = result.replace(levelClaim, regard);
      const labelledStage = new RegExp(
        "\\b(?:relationship|trust|closeness|boundary|boundaries|conflict|role)\\s+(?:level|stage)"
          + "\\s+(?:is|was|became|reached|remains|at)?\\s*" + escaped + "\\b",
        "gi"
      );
      result = result.replace(labelledStage, regard);
      result = result.replace(
        new RegExp("\\b" + escaped + "\\s+(?:relationship\\s+)?stage\\b", "gi"),
        regard
      );
    });
    result = result.replace(/\s{2,}/g, " ").replace(/\s+([,.;:!?])/g, "$1").trim();
    return line(result || ("The cited evidence supports " + regard + "."), 2000);
  }

  function relationshipStartingScore(field) {
    const startingLabels = {
      Role: "Emerging",
      Trust: "Guarded",
      Closeness: "Acquainted",
      Boundaries: "Implied",
      Conflict: "Clear"
    };
    const stage = (RELATIONSHIP_STAGES[field] || [])
      .find(item => keyOf(item.label) === keyOf(startingLabels[field]));
    return stage ? stage.midpoint : 0;
  }

  function nameSubjectForCandidate(owner, candidate, plan) {
    const target = targetForCode(plan, candidate.subjectCode);
    if (!target || target.nameSubject !== true) {
      return { ok: false, error: "Name used a Subject code not authorized for identity updates." };
    }
    const selectedTargetKey = normalizedTargetKey(plan && plan.selectedCandidate && plan.selectedCandidate.targetKey);
    if (selectedTargetKey && normalizedTargetKey(target.key) !== selectedTargetKey) {
      return { ok: false, error: "Name used a Subject code other than the frozen identity target." };
    }
    const identityKey = target.key === "self" ? "npc:" + owner.key : target.key;
    const identity = nameIdentityForKey(identityKey);
    return identity
      ? { ok: true, target, identity }
      : { ok: false, error: "Name Subject was not Player or a registered NPC identity." };
  }

  function resolveNameUseField(owner, value, plan) {
    const raw = line(value, 1000);
    const normalized = nameKeyOf(raw);
    if (normalized === "general") {
      return { ok: true, text: "General", permissions: [{ key: "general", name: "General" }] };
    }
    if (normalized === "none") {
      return { ok: true, text: "None", permissions: [{ key: "none", name: "None" }] };
    }
    const codes = raw.split(/\s*,\s*/).map(code => code.toUpperCase()).filter(Boolean);
    if (!codes.length) return { ok: false, error: "Name Use supplied no valid permission code." };
    const permissions = [];
    for (const code of codes) {
      const target = targetForCode(plan, code);
      if (!target || target.nameSubject !== true) {
        return { ok: false, error: "Name Use code " + code + " was outside the frozen identity target map." };
      }
      const identityKey = target.key === "self" ? "npc:" + owner.key : target.key;
      const identity = nameIdentityForKey(identityKey);
      if (!identity) return { ok: false, error: "Name Use code " + code + " did not resolve to Player or a registered NPC." };
      const permission = { key: identity.key, name: identity.player ? "Player" : identity.canonical };
      if (!permissions.some(existing => existing.key === permission.key)) permissions.push(permission);
    }
    return { ok: true, text: permissions.map(permission => permission.name).join(", "), permissions };
  }

  function formatNameProgress(progress) {
    const threshold = settings.NAME_ESTABLISHMENT_CONFIRMATIONS;
    return (Array.isArray(progress) ? progress : [])
      .filter(item => item && item.key !== "none" && item.count > 0 && item.count < threshold)
      .map(item => item.name + " " + item.count + "/" + threshold)
      .join("; ");
  }

  function permissionText(permissions) {
    const list = Array.isArray(permissions) ? permissions : [];
    if (list.some(permission => permission.key === "general")) return "General";
    if (!list.length || list.every(permission => permission.key === "none")) return "None";
    return list.filter(permission => permission.key !== "none")
      .map(permission => permission.name).join(", ");
  }

  function addPlannedNameRecord(identity, pages, record) {
    if (!record) return { ok: false, error: "The Alias record could not be formed safely." };
    let page = pages.find(item => item.movable && !item.remove);
    if (!page) page = createPlannedNamesPage(identity, pages);
    if (!plannedNamesPageFits(identity, page, page.items.concat(record))) {
      page = createPlannedNamesPage(identity, pages);
    }
    if (!plannedNamesPageFits(identity, page, page.items.concat(record))) {
      return { ok: false, error: "The complete Alias record could not fit an empty Names page." };
    }
    page.items.push(record);
    page.dirty = true;
    return { ok: true, page, record };
  }

  function setPlannedNameRecord(identity, found, status, use, progress, reason) {
    if (!found || !found.page.movable || !found.record.writable || Object.keys(found.record.fieldUnsafe).length) {
      return { ok: false, error: "The Alias record was structurally or field-level unsafe." };
    }
    found.record.values = {
      Status: status,
      Use: use,
      Progress: progress || "",
      Reason: line(reason, 2000)
    };
    if (!reparsePlannedNameRecord(identity, found.record)) {
      return { ok: false, error: "The updated Alias record could not be normalized safely." };
    }
    found.page.dirty = true;
    return { ok: true, record: found.record };
  }

  function applyNameCandidate(owner, candidate, plan, evidenceItems) {
    const subject = nameSubjectForCandidate(owner, candidate, plan);
    if (!subject.ok) return subject;
    const identity = subject.identity;
    const selected = plan && plan.selectedCandidate && typeof plan.selectedCandidate === "object"
      ? plan.selectedCandidate
      : {};
    const frozenTransition = line(selected.nameTransition, 40);
    const frozenReplacement = line(selected.nameReplacedAlias, 160);
    if (!selected.nameAlias || !frozenTransition || !selected.nameUse
      || !sameNameForm(candidate.alias, selected.nameAlias)
      || candidate.transition !== frozenTransition
      || nameKeyOf(candidate.replacedAlias || "") !== nameKeyOf(frozenReplacement || "")
      || nameKeyOf(candidate.useField) !== nameKeyOf(selected.nameUse)) {
      return { ok: false, error: "Name Alias, Transition, old Alias, or Use did not match the scheduled operation contract." };
    }
    if (!candidate.alias || sameNameForm(candidate.alias, identity.canonical)) {
      return { ok: false, error: "A Name operation cannot replace or duplicate the canonical name." };
    }
    if (identity.player && candidate.transition === "Observed") {
      return { ok: false, error: "Repeated NPC usage cannot establish a Player alias without Player-supplied acceptance." };
    }
    const use = resolveNameUseField(owner, candidate.useField, plan);
    if (!use.ok) return use;
    const isInactive = ["Retired", "Rejected"].includes(candidate.transition);
    if (isInactive && use.text !== "None") {
      return { ok: false, error: candidate.transition + " required Use=None." };
    }
    if (["Observed", "Adopted", "Reactivated", "Replace"].includes(candidate.transition) && use.text === "None") {
      return { ok: false, error: candidate.transition + " required General or named usage permission." };
    }
    return transactNames(identity, ({ pages }) => {
      const aliasResult = plannedNameAlias(pages, candidate.alias);
      if (!aliasResult.ok) return aliasResult;
      let found = aliasResult.found;
      const oldRecord = found ? copyNameItem(found.record) : null;
      const oldStatus = oldRecord ? oldRecord.status : "absent";
      const direct = candidate.transition !== "Observed";

      if (candidate.transition === "Observed") {
        if (found && ["Retired", "Rejected"].includes(found.record.status)) {
          return { ok: false, error: "A Retired or Rejected Alias requires explicit Reactivated evidence." };
        }
        if (!found) {
          const progress = use.permissions.filter(permission => permission.key !== "none")
            .map(permission => ({ ...permission, count: Math.min(
              settings.NAME_ESTABLISHMENT_CONFIRMATIONS,
              Math.max(1, evidenceItems.length)
            ) }));
          const completed = progress.filter(item => item.count >= settings.NAME_ESTABLISHMENT_CONFIRMATIONS);
          const activePermissions = completed.map(item => ({ key: item.key, name: item.name }));
          const pending = progress.filter(item => item.count < settings.NAME_ESTABLISHMENT_CONFIRMATIONS);
          const status = activePermissions.length ? "Active" : "Emerging";
          const record = baseNameRecord(
            identity,
            candidate.alias,
            status,
            permissionText(activePermissions),
            formatNameProgress(pending),
            candidate.explanation
          );
          const added = addPlannedNameRecord(identity, pages, record);
          if (!added.ok) return added;
          found = { page: added.page, record: added.record };
        } else {
          const existingPermissions = (found.record.use.permissions || []).filter(permission => permission.key !== "none");
          const existingProgress = (found.record.progress.progress || []).map(item => ({ ...item }));
          let changed = false;
          use.permissions.filter(permission => permission.key !== "none").forEach(permission => {
            if (existingPermissions.some(item => item.key === "general" || item.key === permission.key)) return;
            let progress = existingProgress.find(item => item.key === permission.key);
            if (!progress) {
              progress = { ...permission, count: 0 };
              existingProgress.push(progress);
            }
            progress.count = Math.min(settings.NAME_ESTABLISHMENT_CONFIRMATIONS, progress.count + Math.max(1, evidenceItems.length));
            changed = true;
            if (progress.count >= settings.NAME_ESTABLISHMENT_CONFIRMATIONS) {
              existingPermissions.push({ key: permission.key, name: permission.name });
            }
          });
          if (!changed) return { ok: false, unchanged: true, error: "" };
          const completedGeneral = existingPermissions.some(permission => permission.key === "general");
          const pending = completedGeneral ? [] : existingProgress.filter(progress =>
            progress.count < settings.NAME_ESTABLISHMENT_CONFIRMATIONS
              && !existingPermissions.some(permission => permission.key === progress.key)
          );
          const nextUse = permissionText(existingPermissions);
          const nextStatus = nextUse === "None" ? "Emerging" : "Active";
          const updated = setPlannedNameRecord(
            identity, found, nextStatus, nextUse, formatNameProgress(pending),
            nextStatus !== found.record.status ? candidate.explanation : found.record.reason
          );
          if (!updated.ok) return updated;
        }
      } else if (candidate.transition === "Retired") {
        if (!found) return { ok: false, error: "Retiring an Alias required an existing record." };
        const updated = setPlannedNameRecord(identity, found, "Retired", "None", "", candidate.explanation);
        if (!updated.ok) return updated;
      } else if (candidate.transition === "Rejected") {
        if (!found) {
          const record = baseNameRecord(identity, candidate.alias, "Rejected", "None", "", candidate.explanation);
          const added = addPlannedNameRecord(identity, pages, record);
          if (!added.ok) return added;
          found = { page: added.page, record: added.record };
        } else {
          const updated = setPlannedNameRecord(identity, found, "Rejected", "None", "", candidate.explanation);
          if (!updated.ok) return updated;
        }
      } else if (candidate.transition === "Adopted") {
        if (!found) {
          const record = baseNameRecord(identity, candidate.alias, "Active", use.text, "", candidate.explanation);
          const added = addPlannedNameRecord(identity, pages, record);
          if (!added.ok) return added;
          found = { page: added.page, record: added.record };
        } else {
          const updated = setPlannedNameRecord(identity, found, "Active", use.text, "", candidate.explanation);
          if (!updated.ok) return updated;
        }
      } else if (candidate.transition === "Reactivated") {
        if (!found || !["Retired", "Rejected"].includes(found.record.status)) {
          return { ok: false, error: "Reactivated required an existing Retired or Rejected Alias." };
        }
        const updated = setPlannedNameRecord(identity, found, "Active", use.text, "", candidate.explanation);
        if (!updated.ok) return updated;
      } else if (candidate.transition === "Replace") {
        if (!candidate.replacedAlias || sameNameForm(candidate.alias, candidate.replacedAlias)
          || sameNameForm(candidate.replacedAlias, identity.canonical)) {
          return { ok: false, error: "Replace required distinct noncanonical old and new Alias forms." };
        }
        const oldResult = plannedNameAlias(pages, candidate.replacedAlias);
        if (!oldResult.ok) return oldResult;
        if (!oldResult.found) return { ok: false, error: "Replace required the old Alias record to exist." };
        const retired = setPlannedNameRecord(
          identity,
          oldResult.found,
          "Retired",
          "None",
          "",
          "Replaced by " + candidate.alias + " — " + candidate.explanation
        );
        if (!retired.ok) return retired;
        if (!found) {
          const record = baseNameRecord(identity, candidate.alias, "Active", use.text, "", candidate.explanation);
          const added = addPlannedNameRecord(identity, pages, record);
          if (!added.ok) return added;
          found = { page: added.page, record: added.record };
        } else {
          const updated = setPlannedNameRecord(identity, found, "Active", use.text, "", candidate.explanation);
          if (!updated.ok) return updated;
        }
      }

      const nextRecord = found && found.record;
      if (!nextRecord) return { ok: false, error: "The Name transition produced no Alias record." };
      if (oldRecord && nameRecordSignature(oldRecord) === nameRecordSignature(nextRecord)
        && oldRecord.alias === nextRecord.alias && candidate.transition !== "Replace") {
        return { ok: false, unchanged: true, error: "" };
      }
      const detail = identity.canonical + " alias " + candidate.alias + " " + oldStatus + " → " + nextRecord.status
        + " (" + nameUseModelText(nextRecord) + "; " + (candidate.evidenceIds || []).join(",") + ")";
      return {
        ok: true,
        subjectKey: identity.key,
        aliasKey: nameKeyOf(candidate.alias),
        summary: detail,
        nameDetail: detail,
        direct
      };
    });
  }

  function baseRelationshipRecord(target) {
    const record = {
      kind: "record",
      targetKey: target.key,
      targetName: target.key === "player" ? "Player" : target.name,
      targetCorrected: false,
      values: RELATIONSHIP_FIELDS.reduce((result, field) => {
        result[field] = "";
        return result;
      }, {}),
      parsedFields: {},
      fieldUnsafe: {},
      page: 0,
      card: null,
      line: 0,
      duplicate: false,
      conflict: false,
      oversize: false,
      writable: true
    };
    return reparsePlannedRelationshipRecord(record);
  }

  function relationshipStoredValue(field, destination, score, description) {
    const safeDescription = wholeLine(description, 0);
    if (field === "Role" && destination === "Former") {
      return "Former" + (safeDescription ? " — " + safeDescription : "");
    }
    const stage = relationshipStage(field, score);
    if (!stage) return "";
    return score + " (" + stage.label + ")" + (safeDescription ? " — " + safeDescription : "");
  }

  function fitRelationshipDescription(owner, record, field, destination, score, description) {
    const probe = copyRelationshipItem(record);
    probe.values[field] = relationshipStoredValue(field, destination, score, "");
    reparsePlannedRelationshipRecord(probe);
    const baseChars = renderRelationshipsPage(owner, 1, [probe]).length;
    if (baseChars > settings.MAX_RELATIONSHIPS_CARD_CHARS) {
      return { ok: false, description: "", error: "The Relationship record's fixed fields exceeded the 1,000-character page limit." };
    }
    const capacity = Math.min(
      settings.MAX_STORED_RELATIONSHIP_EXPLANATION_CHARS,
      Math.max(0, settings.MAX_RELATIONSHIPS_CARD_CHARS - baseChars - 3)
    );
    const compacted = compactLineAtBoundary(description, capacity);
    if (description && !compacted) {
      return { ok: false, description: "", error: "No complete Relationship Explanation could fit the remaining page capacity." };
    }
    return { ok: true, description: compacted };
  }

  function relationshipScoreLabel(parsed) {
    if (!parsed || parsed.blank) return "blank";
    return parsed.special || textOf(parsed.score);
  }

  function applyRelationshipCandidate(owner, candidate, plan, evidenceItems) {
    if (!owner || !candidate) return { ok: false, error: "Relationship operation lacked its fixed owner or content." };
    const target = targetForCode(plan, candidate.targetCode);
    if (!target || target.relationship !== true) {
      return { ok: false, error: "Relationship used a target code not authorized for directional Relationships." };
    }
    const validTarget = target.key === "player"
      || (target.key.startsWith("npc:") && characters.some(character => "npc:" + character.key === target.key && character.key !== owner.key));
    if (!validTarget) return { ok: false, error: "Relationship target must be Player or another registered NPC, never Self." };
    const selected = plan && plan.selectedCandidate && typeof plan.selectedCandidate === "object"
      ? plan.selectedCandidate
      : {};
    if (normalizedTargetKey(selected.targetKey) !== normalizedTargetKey(target.key)) {
      return { ok: false, error: "Relationship target did not match the frozen operation target." };
    }
    const selectedDestination = relationshipDestination(selected.field, selected.destination);
    if (!selectedDestination || candidate.field !== selected.field
      || keyOf(candidate.destination) !== keyOf(selectedDestination.label)
      || candidate.eventKind !== (selected.direct === true ? "D" : "A")) {
      return { ok: false, error: "Relationship field, A/D flag, or destination did not match the scheduled operation contract." };
    }
    const relationshipItems = Array.isArray(evidenceItems) ? evidenceItems : [];
    const derivedItems = relationshipItems.filter(item => item && item.source === "provenance");
    const rawItems = relationshipItems.filter(item => item && item.source !== "provenance");
    if (derivedItems.length && candidate.eventKind !== "A") {
      return { ok: false, error: "Derived State and Experience sources authorise accumulated Relationship movement only." };
    }
    if (rawItems.length && candidate.eventKind !== "D") {
      return { ok: false, error: "Raw completed evidence authorises direct Relationship movement only." };
    }
    if (candidate.field === "Role" && candidate.destination === "Former" && candidate.eventKind !== "D") {
      return { ok: false, error: "Former Role requires a completed direct event." };
    }
    if (candidate.field === "Boundaries" && candidate.destination === "Released" && candidate.eventKind !== "D") {
      return { ok: false, error: "Released Boundaries require a completed direct event." };
    }
    const destination = relationshipDestination(candidate.field, candidate.destination);
    if (!destination) return { ok: false, error: "Relationship destination did not belong to its field." };
    const pace = plan && plan.relationshipPace && typeof plan.relationshipPace === "object"
      ? plan.relationshipPace
      : runtime.relationshipPace;
    const magnitude = (candidate.eventKind === "D" ? pace.direct : pace.accumulated)
      * Math.max(1, (Array.isArray(evidenceItems) ? evidenceItems.length : 0));

    return transactRelationships(owner, ({ pages }) => {
      const targetResult = plannedRelationshipTarget(pages, target.key);
      if (!targetResult.ok) return targetResult;
      let found = targetResult.found;
      let record = found ? found.record : null;
      if (!record) {
        record = baseRelationshipRecord(target);
        let page = pages.find(item => item.movable && !item.remove);
        if (!page) page = createPlannedRelationshipsPage(owner, pages);
        page.items.push(record);
        page.dirty = true;
        found = { page, record };
      }
      const prior = record.parsedFields[candidate.field] || parseRelationshipField(candidate.field, record.values[candidate.field]);
      if (!prior.safe) {
        return { ok: false, error: candidate.field + " is unsafe and must be repaired before that field can update." };
      }

      const oldStage = prior.special || prior.stage || "blank";
      const oldScoreLabel = relationshipScoreLabel(prior);
      const priorStoredValue = canonicalRelationshipManagedValue(
        candidate.field,
        record.values[candidate.field]
      );
      let nextValue = "";
      let nextScore = null;
      let nextStage = "blank";
      let nextDescription = "";
      let descriptionChanged = false;
      let stageChanged = false;
      const directLifecycle = candidate.eventKind === "D"
        && (candidate.field === "Role" || candidate.field === "Boundaries");
      const directResolution = candidate.eventKind === "D"
        && candidate.field === "Conflict" && candidate.destination === "Clear";

      if (candidate.field === "Boundaries" && destination.special === "Released") {
        nextValue = "";
        nextStage = "Released";
        nextDescription = "";
        stageChanged = !prior.blank;
        descriptionChanged = !prior.blank;
      } else if (candidate.field === "Role" && destination.special === "Former") {
        nextStage = "Former";
        nextDescription = correctedRelationshipExplanation(candidate.explanation, nextStage);
        const fitted = fitRelationshipDescription(owner, record, "Role", "Former", null, nextDescription);
        if (!fitted.ok) return fitted;
        nextDescription = fitted.description;
        nextValue = relationshipStoredValue("Role", "Former", null, nextDescription);
        stageChanged = oldStage !== nextStage;
        descriptionChanged = keyOf(prior.description) !== keyOf(nextDescription);
      } else {
        const targetScore = destination.midpoint;
        if (prior.blank || prior.special) {
          if (directLifecycle || directResolution) {
            nextScore = targetScore;
          } else {
            const startingScore = relationshipStartingScore(candidate.field);
            const difference = targetScore - startingScore;
            if (difference !== 0 && magnitude <= 0) {
              if (!targetResult.found) removePlannedRelationshipItem(found.page, record);
              return { ok: false, unchanged: true, error: "" };
            }
            const movement = difference === 0
              ? 0
              : Math.min(Math.abs(difference), magnitude, Math.max(1, Number(pace.maxStages) || 1) * 10);
            nextScore = startingScore + Math.sign(difference) * movement;
            const range = relationshipRange(candidate.field);
            nextScore = Math.max(range.minimum, Math.min(range.maximum, nextScore));
          }
          const stage = relationshipStage(candidate.field, nextScore);
          if (!stage) return { ok: false, error: "The initialized Relationship score had no valid fixed stage." };
          nextStage = stage.label;
          nextDescription = correctedRelationshipExplanation(candidate.explanation, nextStage);
          const fitted = fitRelationshipDescription(owner, record, candidate.field, nextStage, nextScore, nextDescription);
          if (!fitted.ok) return fitted;
          nextDescription = fitted.description;
          nextValue = relationshipStoredValue(candidate.field, nextStage, nextScore, nextDescription);
          stageChanged = oldStage !== nextStage;
          descriptionChanged = true;
        } else if (directLifecycle || directResolution) {
          nextScore = targetScore;
          nextStage = destination.label;
          nextDescription = correctedRelationshipExplanation(candidate.explanation, nextStage);
          const fitted = fitRelationshipDescription(owner, record, candidate.field, destination.label, nextScore, nextDescription);
          if (!fitted.ok) return fitted;
          nextDescription = fitted.description;
          nextValue = relationshipStoredValue(candidate.field, destination.label, nextScore, nextDescription);
          stageChanged = oldStage !== nextStage;
          descriptionChanged = keyOf(prior.description) !== keyOf(nextDescription);
        } else {
          const difference = targetScore - prior.score;
          if (difference === 0 || magnitude <= 0) {
            if (!targetResult.found) removePlannedRelationshipItem(found.page, record);
            return { ok: false, unchanged: true, error: "" };
          }
          const movement = Math.min(Math.abs(difference), magnitude, Math.max(1, Number(pace.maxStages) || 1) * 10);
          nextScore = prior.score + Math.sign(difference) * movement;
          const range = relationshipRange(candidate.field);
          nextScore = Math.max(range.minimum, Math.min(range.maximum, nextScore));
          const stage = relationshipStage(candidate.field, nextScore);
          if (!stage) return { ok: false, error: "The computed Relationship score had no valid fixed stage." };
          nextStage = stage.label;
          stageChanged = keyOf(oldStage) !== keyOf(nextStage);
          nextDescription = stageChanged
            ? correctedRelationshipExplanation(candidate.explanation, nextStage)
            : prior.description;
          if (stageChanged) {
            const fitted = fitRelationshipDescription(owner, record, candidate.field, nextStage, nextScore, nextDescription);
            if (!fitted.ok) return fitted;
            nextDescription = fitted.description;
          }
          nextValue = relationshipStoredValue(candidate.field, nextStage, nextScore, nextDescription);
        }
      }

      if (record.values[candidate.field] === nextValue) {
        if (!targetResult.found) removePlannedRelationshipItem(found.page, record);
        return { ok: false, unchanged: true, error: "" };
      }
      record.values[candidate.field] = nextValue;
      reparsePlannedRelationshipRecord(record);
      const compactRecordChars = renderRelationshipsPage(owner, 1, [record]).length;
      if (compactRecordChars > settings.MAX_RELATIONSHIPS_CARD_CHARS) {
        return {
          ok: false,
          error: "The Relationship record remained " + compactRecordChars + "/"
            + settings.MAX_RELATIONSHIPS_CARD_CHARS
            + " characters after applying the compact Explanation limit; no Relationship change was written."
        };
      }
      found.page.dirty = true;
      const recordRemoved = RELATIONSHIP_FIELDS.every(field => !textOf(record.values[field]).trim());
      if (recordRemoved) removePlannedRelationshipItem(found.page, record);
      const nextParsed = recordRemoved
        ? { blank: true }
        : record.parsedFields[candidate.field];
      const nextScoreLabel = recordRemoved
        ? "blank"
        : relationshipScoreLabel(nextParsed);
      const evidenceLabel = (candidate.evidenceIds || []).join(",");
      const stageLabel = recordRemoved ? "Released" : (nextParsed.special || nextParsed.stage || nextStage);
      const correctedExplanation = recordRemoved ? "" : wholeLine(nextParsed.description || nextDescription, 0);
      descriptionChanged = recordRemoved
        ? !!textOf(prior.description)
        : textOf(prior.description) !== textOf(nextParsed.description);
      const resultingStoredValue = recordRemoved
        ? ""
        : canonicalRelationshipManagedValue(candidate.field, record.values[candidate.field]);
      const baselineScore = !prior.blank && !prior.special && Number.isFinite(Number(prior.score))
        ? Number(prior.score)
        : relationshipStartingScore(candidate.field);
      const actualChange = Number.isFinite(Number(nextScore))
        ? Math.trunc(Number(nextScore) - baselineScore)
        : 0;
      const sourceIds = provenanceSourceIds((Array.isArray(evidenceItems) ? evidenceItems : [])
        .map(item => item && item.id));
      const storyEvidenceIds = unique((Array.isArray(evidenceItems) ? evidenceItems : [])
        .flatMap(item => {
          if (!item) return [];
          if (item.source === "provenance") return item.rawLineage || [];
          return /^E\d+$/.test(textOf(item.id)) ? [item.id] : [];
        }), 40).map(value => textOf(value).trim().toUpperCase()).filter(value => /^E\d+$/.test(value));
      const narrowUses = derivedItems.map(item => ({
        sourceId: provenanceId(item.id),
        signature: line(item.useSignature, 500),
        field: candidate.field
      })).filter(item => item.sourceId && item.signature);
      const paceValue = candidate.eventKind === "D" ? pace.direct : pace.accumulated;
      return {
        ok: true,
        targetKey: target.key,
        targetName: target.key === "player" ? "Player" : target.name,
        field: candidate.field,
        eventKind: candidate.eventKind,
        sourceIds,
        storyEvidenceIds,
        narrowUses,
        priorValue: oldScoreLabel,
        priorStoredValue: priorStoredValue === null ? "" : priorStoredValue,
        resultingValue: recordRemoved ? "Released" : nextScoreLabel,
        resultingStoredValue: resultingStoredValue === null ? "" : resultingStoredValue,
        actualChange,
        numericChange: actualChange,
        actualStage: stageLabel,
        actualScore: recordRemoved || nextParsed.special ? null : nextParsed.score,
        correctedExplanation,
        managedSignature: relationshipManagedSignature(
          owner.key,
          target.key,
          candidate.field,
          resultingStoredValue === null ? "" : resultingStoredValue
        ),
        paceValue: Math.max(0, Number(paceValue) || 0),
        pace: {
          name: line(pace.name, 80),
          value: Math.max(0, Number(paceValue) || 0),
          maxStages: Math.max(1, Number(pace.maxStages) || 1)
        },
        derivedUseSignatures: narrowUses.map(item => item.signature),
        summary: owner.name + "→" + target.name + " " + candidate.field + " "
          + oldScoreLabel + "→" + nextScoreLabel + " (" + stageLabel + ")",
        relationshipDetail: owner.name + " → " + (target.key === "player" ? "Player" : target.name)
          + " " + candidate.field + " " + oldScoreLabel + " → " + nextScoreLabel
          + " (" + stageLabel + "; " + evidenceLabel + ", " + candidate.eventKind + ")",
        stageChanged,
        descriptionChanged,
        recordRemoved
      };
    });
  }

  function captureRelationshipProvenanceTransaction() {
    return {
      cards: captureManagedRelationshipsCards(),
      provenance: clone(CC.provenance),
      provenanceCreated: CC.last.provenanceCreated,
      provenanceDiagnostics: clone(CC.last.provenanceDiagnostics || []),
      sourceDiagnostics: clone(CC.last.relationshipSourceDiagnostics || []),
      useDiagnostics: clone(CC.last.relationshipUseDiagnostics || []),
      transactionDiagnostics: clone(CC.relationshipTransactionDiagnostics || [])
    };
  }

  function restoreRelationshipProvenanceTransaction(snapshot, reason) {
    if (!snapshot) return false;
    const cardsRestored = restoreManagedRelationshipsCards(snapshot.cards);
    CC.provenance = normalizeProvenanceLedger(snapshot.provenance);
    CC.last.provenanceCreated = line(snapshot.provenanceCreated, 500) || "None";
    CC.last.provenanceDiagnostics = unique(snapshot.provenanceDiagnostics || [], 500).slice(-20);
    CC.last.relationshipSourceDiagnostics = unique(snapshot.sourceDiagnostics || [], 500).slice(-40);
    CC.last.relationshipUseDiagnostics = unique((snapshot.useDiagnostics || []).concat(
      "Relationship provenance/use rollback: " + reason
    ), 500).slice(-40);
    CC.relationshipTransactionDiagnostics = unique((snapshot.transactionDiagnostics || []).concat(
      "Rolled back Relationship cards, provenance, counters, and narrow uses: " + reason
        + (cardsRestored ? "" : " (managed-card rollback was incomplete)")
    ), 500).slice(-30);
    refreshRelationshipsStore();
    refreshProvenanceActivity();
    return cardsRestored;
  }

  function relationshipEventSignature(owner, result) {
    if (!owner || !result) return "";
    return line(JSON.stringify([
      "relationship-event",
      owner.key,
      normalizedTargetKey(result.targetKey),
      canonicalRelationshipFieldName(result.field),
      result.eventKind,
      result.priorValue,
      result.resultingValue,
      result.actualStage,
      Math.trunc(Number(result.actualChange) || 0),
      provenanceSourceIds(result.sourceIds).join(","),
      result.managedSignature
    ]), 500);
  }

  function commitRelationshipProvenance(owner, result, plan) {
    if (!owner || !result || !result.ok || !result.managedSignature) {
      return { ok: false, error: "The committed Relationship result lacked provenance metadata." };
    }
    const field = canonicalRelationshipFieldName(result.field);
    const targetKey = normalizedTargetKey(result.targetKey);
    const sourceIds = provenanceSourceIds(result.sourceIds);
    const storyEvidenceIds = unique((Array.isArray(result.storyEvidenceIds) ? result.storyEvidenceIds : [])
      .map(value => textOf(value).trim().toUpperCase())
      .filter(value => /^E\d+$/.test(value)), 40);
    if (!field || !targetKey || targetKey === "self" || !sourceIds.length) {
      return { ok: false, error: "The committed Relationship result had incomplete owner, target, field, or source metadata." };
    }
    const eventSignature = relationshipEventSignature(owner, result);
    if (!eventSignature) return { ok: false, error: "The Relationship provenance signature could not be created." };

    const provenance = appendProvenanceRecord({
      prefix: "R",
      ownerKey: owner.key,
      targetKey,
      targetName: storedTargetName(targetKey, result.targetName),
      field,
      destination: line(result.actualStage, 120),
      eventKind: result.eventKind,
      actualChange: Math.trunc(Number(result.actualChange) || 0),
      numericChange: Math.trunc(Number(result.actualChange) || 0),
      priorValue: line(result.priorValue, 240),
      resultingValue: line(result.resultingValue, 240),
      resultingStage: line(result.actualStage, 120),
      paceValue: Math.max(0, Number(result.paceValue) || 0),
      pace: clone(result.pace),
      signature: eventSignature,
      managedSignature: result.managedSignature,
      sourceIds,
      storyEvidenceIds,
      uses: (result.narrowUses || []).map(use => use.signature),
      value: line(result.resultingValue, 240),
      explanation: line(result.correctedExplanation, 500),
      createdClock: CC.stateClock + 1,
      ownerOpportunity: plan && plan.ownerOpportunity || CC.ownerOpportunities[owner.key] || 0,
      active: true
    });
    if (!provenance.ok) {
      return { ok: false, error: "R# provenance could not commit: " + provenance.error };
    }

    for (const use of result.narrowUses || []) {
      const sourceRecord = provenanceRecordById(use.sourceId);
      if (!sourceRecord || !["state", "experience"].includes(sourceRecord.kind)) {
        return { ok: false, error: "Narrow use source " + use.sourceId + " disappeared during R# creation." };
      }
      if (!sourceRecord.active || !managedSignatureStillValid(sourceRecord)) {
        return { ok: false, error: "Narrow use source " + use.sourceId + " became stale before use commit." };
      }
      const recomputed = relationshipUseSignatureForRecord(sourceRecord, owner.key, targetKey, field);
      if (!recomputed || recomputed !== use.signature) {
        return { ok: false, error: "Narrow use signature for " + use.sourceId + " changed before commit." };
      }
      if (provenanceUseCommitted(sourceRecord, recomputed)) {
        return { ok: false, error: "Narrow use signature for " + use.sourceId + " was already committed." };
      }
      const committedUse = commitProvenanceUse(sourceRecord, recomputed);
      if (!committedUse.ok || committedUse.duplicate
        || !provenanceUseCommitted(sourceRecord, recomputed)) {
        return { ok: false, error: "Narrow use signature for " + use.sourceId + " could not commit exactly once." };
      }
    }

    refreshProvenanceActivity();
    const committed = provenanceRecordById(provenance.record.id);
    if (!committed || !committed.active || !managedSignatureStillValid(committed)) {
      return { ok: false, error: "The new R# could not bind to the committed managed Relationship value." };
    }
    CC.last.relationshipUseDiagnostics = unique((CC.last.relationshipUseDiagnostics || []).concat(
      "Committed " + committed.id + " after managed Relationship success"
        + ((result.narrowUses || []).length
          ? "; narrow uses " + result.narrowUses.map(use => use.sourceId + ":" + field).join(", ")
          : "; no derived uses")
    ), 500).slice(-40);
    CC.last.provenanceDiagnostics = unique((CC.last.provenanceDiagnostics || []).concat(
      "Relationship provenance committed: " + committed.id + " from "
        + (sourceIds.join(",") || "None")
        + " with raw lineage " + (storyEvidenceIds.join(",") || "None")
        + "; actual stage " + result.actualStage
        + "; actual change " + Math.trunc(Number(result.actualChange) || 0)
    ), 500).slice(-20);
    return { ok: true, record: committed };
  }

  function captureViewProvenanceTransaction() {
    return {
      cards: captureManagedViewsCards(),
      recoveringViews: clone(CC.recoveringViews),
      provenance: clone(CC.provenance),
      provenanceCreated: CC.last.provenanceCreated,
      provenanceDiagnostics: clone(CC.last.provenanceDiagnostics || []),
      sourceDiagnostics: clone(CC.last.viewSourceDiagnostics || []),
      useDiagnostics: clone(CC.last.viewUseDiagnostics || []),
      transactionDiagnostics: clone(CC.viewTransactionDiagnostics || [])
    };
  }

  function restoreViewProvenanceTransaction(snapshot, reason) {
    if (!snapshot) return false;
    const cardsRestored = restoreManagedViewsCards(snapshot.cards);
    CC.recoveringViews = snapshot.recoveringViews && typeof snapshot.recoveringViews === "object"
      ? clone(snapshot.recoveringViews)
      : {};
    CC.provenance = normalizeProvenanceLedger(snapshot.provenance);
    CC.last.provenanceCreated = line(snapshot.provenanceCreated, 500) || "None";
    CC.last.provenanceDiagnostics = unique(snapshot.provenanceDiagnostics || [], 500).slice(-20);
    CC.last.viewSourceDiagnostics = unique(snapshot.sourceDiagnostics || [], 500).slice(-40);
    CC.last.viewUseDiagnostics = unique((snapshot.useDiagnostics || []).concat(
      "View provenance/use rollback: " + reason
    ), 500).slice(-40);
    CC.viewTransactionDiagnostics = unique((snapshot.transactionDiagnostics || []).concat(
      "Rolled back View, V#, counter, recovering state, and narrow uses: " + reason
    ), 300).slice(-30);
    refreshViewsStore(false);
    refreshProvenanceActivity();
    return cardsRestored;
  }

  function viewEventSignature(owner, result) {
    if (!owner || !result) return "";
    return line(JSON.stringify([
      "view-event",
      owner.key,
      normalizedTargetKey(result.targetKey),
      canonicalViewDestination(result.destination),
      canonicalViewOperationMode(result.operationMode),
      canonicalViewOperationMode(result.severity),
      result.priorCategory,
      result.resultingCategory,
      result.priorViewState,
      result.resultingViewState,
      provenanceSourceIds(result.sourceIds).join(","),
      result.managedSignature
    ]), 500);
  }

  function finalizeViewMutationResult(owner, target, candidate, evidenceItems, priorState, result) {
    if (!result || !result.ok) return result;
    refreshViewsStore(false);
    const resultingState = viewManagedStateSnapshot(owner.key, target.key);
    const operationMode = viewOperationModeForCandidate(candidate, target);
    const derivedItems = (Array.isArray(evidenceItems) ? evidenceItems : [])
      .filter(item => item && item.source === "provenance");
    const sourceIds = provenanceSourceIds((Array.isArray(evidenceItems) ? evidenceItems : [])
      .map(item => item && item.id));
    const storyEvidenceIds = unique((Array.isArray(evidenceItems) ? evidenceItems : []).flatMap(item => {
      if (!item) return [];
      if (item.source === "provenance") return item.rawLineage || [];
      return /^E\d+$/.test(textOf(item.id)) ? [item.id] : [];
    }), 40).map(value => textOf(value).trim().toUpperCase()).filter(value => /^E\d+$/.test(value));
    const narrowUses = derivedItems.map(item => ({
      sourceId: provenanceId(item.id),
      signature: line(item.useSignature, 500),
      destination: canonicalViewDestination(item.destination || candidate.destination),
      operationMode: canonicalViewOperationMode(item.operationMode || operationMode)
    })).filter(item => item.sourceId && item.signature && item.destination && item.operationMode);
    const priorCategory = priorState.activeCategory || priorState.buriedCategory || "";
    const resultingCategory = resultingState.activeCategory || resultingState.buriedCategory || "";
    const destination = canonicalViewDestination(candidate.destination);
    let committedStateMatches = false;
    if (destination === "Buried") {
      committedStateMatches = !resultingState.activeCategory
        && resultingState.buriedCategory === priorState.activeCategory
        && keyOf(resultingState.buriedExplanation) === keyOf(priorState.activeExplanation);
    } else if (destination === "Recovered") {
      committedStateMatches = priorState.activeCategory && priorState.buriedCategory
        ? resultingState.recovering === true
          && resultingState.activeCategory === priorState.activeCategory
          && resultingState.buriedCategory === priorState.buriedCategory
        : resultingState.activeCategory === priorState.buriedCategory
          && !resultingState.buriedCategory && resultingState.recovering === false;
    } else if (operationMode === "Reconciled") {
      committedStateMatches = resultingState.activeCategory === destination
        && keyOf(resultingState.activeExplanation) === keyOf(candidate.explanation)
        && !resultingState.buriedCategory && resultingState.recovering === false;
    } else {
      committedStateMatches = resultingState.activeCategory === destination
        && keyOf(resultingState.activeExplanation) === keyOf(candidate.explanation);
    }
    if (!committedStateMatches || !resultingState.signature) {
      return {
        ok: false,
        rollbackRequired: true,
        error: "The managed View write did not persist the exact expected active, buried, recovered, or reconciled state."
      };
    }
    return {
      ...result,
      targetKey: target.key,
      targetName: target.key === "player" ? "Player" : (target.key === "self" ? "Self" : target.name),
      destination,
      operationMode,
      severity: canonicalViewOperationMode(candidate.severity),
      sourceIds,
      storyEvidenceIds,
      narrowUses,
      priorCategory,
      resultingCategory,
      priorViewState: priorState.description,
      resultingViewState: resultingState.description,
      managedSignature: resultingState.signature,
      correctedExplanation: line(candidate.explanation, 500),
      derivedUseSignatures: narrowUses.map(item => item.signature)
    };
  }

  function commitViewProvenance(owner, result, plan) {
    if (!owner || !result || !result.ok || !result.managedSignature) {
      return { ok: false, error: "The committed View result lacked provenance metadata." };
    }
    const targetKey = normalizedTargetKey(result.targetKey);
    const destination = canonicalViewDestination(result.destination);
    const operationMode = canonicalViewOperationMode(result.operationMode);
    const severity = canonicalViewOperationMode(result.severity);
    const sourceIds = provenanceSourceIds(result.sourceIds);
    const storyEvidenceIds = unique((Array.isArray(result.storyEvidenceIds) ? result.storyEvidenceIds : [])
      .map(value => textOf(value).trim().toUpperCase())
      .filter(value => /^E\d+$/.test(value)), 40);
    if (!targetKey || !destination || !operationMode || !sourceIds.length) {
      return { ok: false, error: "The committed View result had incomplete target, destination, mode, or source metadata." };
    }
    const eventSignature = viewEventSignature(owner, result);
    if (!eventSignature) return { ok: false, error: "The View provenance signature could not be created." };

    const provenance = appendProvenanceRecord({
      prefix: "V",
      ownerKey: owner.key,
      targetKey,
      targetName: storedTargetName(targetKey, result.targetName),
      destination,
      priorCategory: result.priorCategory,
      resultingCategory: result.resultingCategory,
      priorViewState: result.priorViewState,
      resultingViewState: result.resultingViewState,
      viewOperationMode: operationMode,
      viewSeverity: severity,
      signature: eventSignature,
      managedSignature: result.managedSignature,
      sourceIds,
      storyEvidenceIds,
      uses: (result.narrowUses || []).map(use => use.signature),
      value: result.resultingCategory || destination,
      explanation: line(result.correctedExplanation, 500),
      createdClock: CC.stateClock + 1,
      ownerOpportunity: plan && plan.ownerOpportunity || CC.ownerOpportunities[owner.key] || 0,
      active: true
    });
    if (!provenance.ok) {
      return { ok: false, error: "V# provenance could not commit: " + provenance.error };
    }

    for (const use of result.narrowUses || []) {
      const sourceRecord = provenanceRecordById(use.sourceId);
      if (!sourceRecord || !["relationship", "experience"].includes(sourceRecord.kind)) {
        return { ok: false, error: "Narrow View-use source " + use.sourceId + " disappeared during V# creation." };
      }
      if (!sourceRecord.active || !managedSignatureStillValid(sourceRecord)) {
        return { ok: false, error: "Narrow View-use source " + use.sourceId + " became stale before use commit." };
      }
      const recomputed = viewUseSignatureForRecord(
        sourceRecord, owner.key, targetKey, destination, operationMode
      );
      if (!recomputed || recomputed !== use.signature) {
        return { ok: false, error: "Narrow View-use signature for " + use.sourceId + " changed before commit." };
      }
      if (provenanceUseCommitted(sourceRecord, recomputed)) {
        return { ok: false, error: "Narrow View-use signature for " + use.sourceId + " was already committed." };
      }
      const committedUse = commitProvenanceUse(sourceRecord, recomputed);
      if (!committedUse.ok || committedUse.duplicate
        || !provenanceUseCommitted(sourceRecord, recomputed)) {
        return { ok: false, error: "Narrow View-use signature for " + use.sourceId + " could not commit exactly once." };
      }
    }

    refreshProvenanceActivity();
    const committed = provenanceRecordById(provenance.record.id);
    if (!committed || !committed.active || !managedSignatureStillValid(committed)) {
      return { ok: false, error: "The new V# could not bind to the committed managed View state." };
    }
    CC.last.viewUseDiagnostics = unique((CC.last.viewUseDiagnostics || []).concat(
      "Committed " + committed.id + " after managed View success"
        + ((result.narrowUses || []).length
          ? "; narrow uses " + result.narrowUses.map(use =>
            use.sourceId + ":" + destination + ":" + operationMode).join(", ")
          : "; no derived uses")
    ), 500).slice(-40);
    CC.last.provenanceDiagnostics = unique((CC.last.provenanceDiagnostics || []).concat(
      "View provenance committed: " + committed.id + " from "
        + (sourceIds.join(",") || "None")
        + " with raw lineage " + (storyEvidenceIds.join(",") || "None")
        + "; " + result.priorViewState + " -> " + result.resultingViewState
        + "; mode " + operationMode
    ), 500).slice(-20);
    CC.viewTransactionDiagnostics = unique((CC.viewTransactionDiagnostics || []).concat(
      "Committed " + committed.id + " transactionally for " + owner.name + " -> "
        + modelTargetName(targetKey, result.targetName)
        + " via " + operationMode
    ), 300).slice(-30);
    return { ok: true, record: committed };
  }

  function baseViewRecord(target, category, explanation, buried) {
    return {
      targetKey: target.key,
      targetName: target.key === "player" ? "Player" : (target.key === "self" ? "Self" : target.name),
      category,
      explanation,
      buried: !!buried,
      page: 0,
      card: null,
      line: 0,
      duplicate: false,
      conflict: false,
      oversize: false,
      writable: true
    };
  }

  function applyTurningPointCandidate(owner, candidate, plan, evidenceItems) {
    if (!owner || !candidate) return { ok: false, error: "Turning Point operation lacked its fixed owner or content." };
    if (runtime.turningPointMode === "disabled") {
      return { ok: false, error: "Turning Point operations are disabled in CC — Settings." };
    }
    refreshTurningPointsStore();
    const selected = plan && plan.selectedCandidate && typeof plan.selectedCandidate === "object"
      ? plan.selectedCandidate
      : {};
    const id = canonicalTurningPointId(candidate.turningPointId);
    const selectedId = canonicalTurningPointId(selected.field);
    const selectedMode = ["Support", "Breakthrough", "Integration"].find(value =>
      keyOf(value) === keyOf(selected.destination)
    ) || "";
    if (!id || id !== selectedId || candidate.mode !== selectedMode) {
      return { ok: false, error: "The Turning Point ID or movement mode did not match the scheduled operation contract." };
    }
    const record = turningPointRecordFor(owner.key, id);
    if (!record) return { ok: false, error: "The creator-defined Turning Point record was missing, unsafe, or ambiguous." };
    if (!turningPointDirectionAllowed(record)) {
      return { ok: false, error: "The Turning Point Direction is unavailable under the current mode." };
    }
    const currentSignature = turningPointManagedSignature(owner.key, record);
    if (!selected.managedSignature || currentSignature !== selected.managedSignature) {
      return { ok: false, error: "The Turning Point router changed after selection; the stale operation was rejected." };
    }
    const score = record.progress.score;
    if (candidate.mode === "Support" && score === TURNING_POINT_STAGES[2].maximum) {
      return { ok: false, unchanged: true, error: "" };
    }
    if (candidate.mode === "Support" && score >= 30) {
      return { ok: false, error: "Support cannot alter an achieved Turning Point; use completed Integration evidence." };
    }
    if (candidate.mode === "Breakthrough" && score >= 30) {
      return { ok: false, unchanged: true, error: "" };
    }
    if (candidate.mode === "Integration" && score < 30) {
      return { ok: false, error: "Integration requires an explicitly achieved Turning Point." };
    }
    if (candidate.mode === "Integration" && score >= TURNING_POINT_STAGES[4].maximum) {
      return { ok: false, unchanged: true, error: "" };
    }
    let nextScore = score;
    if (candidate.mode === "Support") {
      nextScore = Math.min(29, score + settings.TURNING_POINT_SUPPORT_VALUE);
    } else if (candidate.mode === "Breakthrough") {
      nextScore = Math.max(score, TURNING_POINT_STAGES[3].midpoint);
    } else {
      nextScore = Math.min(49, score + settings.TURNING_POINT_INTEGRATION_VALUE);
    }
    if (nextScore === score) return { ok: false, unchanged: true, error: "" };
    const priorStage = record.progress.stage;
    const committed = commitTurningPointProgress(owner, record, nextScore, candidate.explanation);
    if (!committed.ok) return committed;
    return {
      ok: true,
      summary: owner.name + "/Turning Point " + record.title + " moved to " + nextScore + " (" + committed.stage + ")",
      turningPointId: id,
      turningPointTitle: record.title,
      priorScore: score,
      score: nextScore,
      priorStage,
      stage: committed.stage,
      mode: candidate.mode,
      activeCard: committed.record.values["Active card"],
      stageTrigger: committed.record.values["Stage trigger"],
      description: candidate.explanation
    };
  }

  function applyViewCandidate(owner, candidate, plan, evidenceItems) {
    const resolved = resolveViewTarget(owner, candidate, plan);
    if (!resolved.ok) return resolved;
    const target = resolved.target;
    const selected = plan && plan.selectedCandidate && typeof plan.selectedCandidate === "object"
      ? plan.selectedCandidate
      : {};
    if (normalizedTargetKey(selected.targetKey) !== normalizedTargetKey(target.key)) {
      return { ok: false, error: "View target did not match the frozen operation target." };
    }
    const frozenModes = unique(selected.allowedModes || [], 20).map(canonicalViewOperationMode).filter(Boolean);
    const candidateMode = viewOperationModeForCandidate(candidate, target);
    if (!selected.destination || canonicalViewDestination(candidate.destination) !== canonicalViewDestination(selected.destination)
      || frozenModes.length !== 1 || candidateMode !== frozenModes[0]) {
      return { ok: false, error: "View destination or operation mode did not match the scheduled operation contract." };
    }
    refreshViewsStore(false);
    const ownerData = viewsForOwner(owner.key);
    const activeRecord = ownerData && ownerData.activeRecords.find(record => record.targetKey === target.key);
    const buriedRecord = ownerData && ownerData.buriedRecords.find(record => record.targetKey === target.key);
    const categoryDestination = VIEW_CATEGORIES.includes(candidate.destination);
    if (categoryDestination) {
      candidate = {
        ...candidate,
        explanation: correctedViewExplanation(candidate.explanation, candidate.destination)
      };
    }
    const priorState = viewManagedStateSnapshot(owner.key, target.key);

    if (candidate.destination === "Buried") {
      if (!activeRecord) return { ok: false, error: "Burial required one valid active View record." };
      if (buriedRecord) return { ok: false, error: "A prior buried View for this owner–target must be recovered and reconciled before another burial." };
      const result = transactViews(owner, ({ activePages, buriedPages }) => {
        const active = plannedRecord(activePages, target.key);
        if (!active || !active.page.safe || !active.record.writable) return { ok: false, error: "The active View could not be moved safely from its page." };
        removePlannedRecord(active);
        const placed = placePlannedRecord(owner, true, buriedPages, { ...active.record, buried: true }, 0);
        return placed.ok ? { ok: true, summary: owner.name + " buried the View of " + target.name } : placed;
      });
      return result.ok
        ? finalizeViewMutationResult(owner, target, candidate, evidenceItems, priorState, result)
        : result;
    }

    if (candidate.destination === "Recovered") {
      if (!buriedRecord) return { ok: false, error: "Recovery required one valid buried View record." };
      if (activeRecord) {
        if (!activeRecord.writable || !buriedRecord.writable) {
          return { ok: false, error: "The active or buried recovery source belonged to an unsafe page." };
        }
        const markerKey = recoveringViewKey(owner.key, target.key);
        if (CC.recoveringViews[markerKey]) return { ok: false, unchanged: true, error: "" };
        CC.recoveringViews[markerKey] = {
          ownerKey: owner.key,
          targetKey: target.key
        };
        return finalizeViewMutationResult(owner, target, candidate, evidenceItems, priorState, {
          ok: true,
          summary: owner.name + " recovered an earlier View of " + target.name + " for reconciliation"
        });
      }
      const result = transactViews(owner, ({ activePages, buriedPages }) => {
        const buried = plannedRecord(buriedPages, target.key);
        if (!buried || !buried.page.safe || !buried.record.writable) return { ok: false, error: "The buried View could not be restored safely from its page." };
        removePlannedRecord(buried);
        const placed = placePlannedRecord(owner, false, activePages, { ...buried.record, buried: false }, 0);
        return placed.ok ? { ok: true, summary: owner.name + " restored the View of " + target.name } : placed;
      });
      return result.ok
        ? finalizeViewMutationResult(owner, target, candidate, evidenceItems, priorState, result)
        : result;
    }

    if (!categoryDestination) return { ok: false, error: "The View destination was not a supported category or memory operation." };
    const marker = recoveringMarker(owner.key, target.key);
    if (target.mode === "recovering" || marker) {
      if (!marker || !activeRecord || !buriedRecord) return { ok: false, error: "Reconciliation required an intact active/buried recovering pair." };
      if (candidate.severity === "O" && categoryDistance(activeRecord.category, candidate.destination) > 1) {
        return { ok: false, error: "Ordinary reconciliation may retain the current category or move one adjacent step." };
      }
      const result = transactViews(owner, ({ activePages, buriedPages }) => {
        const active = plannedRecord(activePages, target.key);
        const buried = plannedRecord(buriedPages, target.key);
        if (!active || !buried) return { ok: false, error: "The recovering pair changed before reconciliation could commit." };
        const updated = updatePlannedRecord(owner, false, activePages, active, {
          category: candidate.destination,
          explanation: candidate.explanation
        });
        if (!updated.ok) return updated;
        if (!buried.page.safe || !buried.record.writable) return { ok: false, error: "The recovered buried record belonged to an unsafe page." };
        removePlannedRecord(buried);
        return { ok: true, summary: owner.name + " reconciled the View of " + target.name + " as " + candidate.destination };
      });
      if (result.ok) delete CC.recoveringViews[recoveringViewKey(owner.key, target.key)];
      return result.ok
        ? finalizeViewMutationResult(owner, target, candidate, evidenceItems, priorState, result)
        : result;
    }

    if (target.mode === "buried") {
      return { ok: false, error: "A buried target code authorizes recovery, not an active category update." };
    }

    if (activeRecord) {
      if (activeRecord.category === candidate.destination && keyOf(activeRecord.explanation) === keyOf(candidate.explanation)) {
        return { ok: false, unchanged: true, error: "" };
      }
      if (candidate.severity === "O" && categoryDistance(activeRecord.category, candidate.destination) > 1) {
        return { ok: false, error: "An ordinary View operation may retain its category or move one adjacent step." };
      }
      const result = transactViews(owner, ({ activePages }) => {
        const active = plannedRecord(activePages, target.key);
        if (!active) return { ok: false, error: "The active target changed before its update could commit." };
        const updated = updatePlannedRecord(owner, false, activePages, active, {
          category: candidate.destination,
          explanation: candidate.explanation
        });
        return updated.ok
          ? { ok: true, summary: owner.name + " moved the View of " + target.name + " to " + candidate.destination }
          : updated;
      });
      return result.ok
        ? finalizeViewMutationResult(owner, target, candidate, evidenceItems, priorState, result)
        : result;
    }

    // Every sibling path guards this; only the create branch did not, so a buried
    // View plus a fresh active one could coexist for the same owner and target.
    // That pair permanently blocks future burial and makes Recovered reconcile
    // against a memory that was supposed to be put away.
    if (buriedRecord) {
      return {
        ok: false,
        error: "A buried View of " + target.name + " already exists, so a second active View cannot be created."
      };
    }

    const result = transactViews(owner, ({ activePages }) => {
      const record = baseViewRecord(target, candidate.destination, candidate.explanation, false);
      const placed = placePlannedRecord(owner, false, activePages, record, 0);
      return placed.ok
        ? { ok: true, summary: owner.name + " added " + target.name + " to " + candidate.destination }
        : placed;
    });
    return result.ok
      ? finalizeViewMutationResult(owner, target, candidate, evidenceItems, priorState, result)
      : result;
  }

  function resetLastForContext() {
    Object.assign(CC.last, {
      warning: "", error: "", rulesTokens: 0, outerTokens: 0, innerTokens: 0, stateTokens: 0,
      namesTokens: 0, relationshipsTokens: 0, turningPointsTokens: 0, viewsTokens: 0, experiencesTokens: 0, evidenceTokens: 0, taskTokens: 0,
      injectedTokens: 0, effectiveBudget: runtime.continuityBudget, headroomTokens: runtime.continuityBudget, recentStoryChars: 0,
      contextBaseChars: 0, contextMaxChars: 0, cacheOverflowActive: false,
      cacheOverflowUsedTokens: 0, cacheOverflowRemainingTokens: 0,
      portrayalTier: "none",
      task: "none", owner: "", candidate: "not requested", update: "None",
      protocol: "None", cast: "None", timeJumpReset: false, gracefulFallback: false,
      selectedNames: [], omittedNames: [], selectedRelationships: [], omittedRelationships: [],
      selectedTurningPoints: [], omittedTurningPoints: [],
      selectedViews: [], omittedViews: [], selectedExperiences: [], omittedExperiences: [],
      suppliedEvidence: [], suppliedTargets: [],
      operationOutcome: "None", operationDrainChange: "No drain change", operationDecay: "None",
      outputRawChars: 0, outputStoryChars: 0, outputRecordChars: 0, outputRecordPosition: "none",
      nameDiagnostics: [], relationshipSourceDiagnostics: [], viewSourceDiagnostics: [], modelOmitted: []
    });
  }

  function buildContext() {
    resetLastForContext();
    const frontMemory = beginFrontMemoryContext(originalText);
    const commitFrontMemory = (instructionText, preparedContext = frontMemory.baseText) => {
      return frontMemory.commit(instructionText, preparedContext);
    };
    if (!frontMemory.ok) {
      CC.last.context = "Front Memory suffix could not be identified safely; Character Continuity made no context change.";
      CC.last.error = "The current state.memory.frontMemory value was not found as the actual context suffix.";
      return originalText;
    }
    refreshViewsStore(false);
    refreshNamesStore();
    applyManagedNameForms();
    refreshRelationshipsStore();
    refreshTurningPointsStore();
    refreshExperiencesStore(false);
    const plan = beginContinueIfNeeded(originalText);
    const observedActionCount = platformActionCount();
    if (plan.opportunity === true && !plan.retry && observedActionCount !== null) {
      plan.actionCount = observedActionCount;
    }
    if (!plan.relationshipPace || typeof plan.relationshipPace !== "object") {
      plan.relationshipPace = clone(runtime.relationshipPace);
    }
    const recent = recentStoryFromContext(originalText);
    const currentInput = plan.kind === "input" || plan.retry ? CC.lastInput : "";
    const source = [currentInput, recent].filter(Boolean).join("\n").slice(-16000);
    if (plan.opening) {
      plan.task = "none";
      plan.taskDelivered = false;
      plan.activeKeys = [];
      CC.last.context = "Opening prompt retained; only its immediate automatic output will be suppressed.";
      return commitFrontMemory("").text;
    }
    expireTemporaryState(CC.stateClock);
    if (!plan.retry && plan.inputEvidenceId && plan.inputEvidenceId !== CC.lastTimeJumpEvidenceId && TIME_JUMP.test(currentInput)) {
      resetSceneForTimeJump(plan.inputEvidenceId);
      CC.lastTimeJumpEvidenceId = plan.inputEvidenceId;
    }
    let active = selectActive(source, currentInput, plan);
    if (plan.retry && Array.isArray(plan.retryActiveKeys) && plan.retryActiveKeys.length) {
      const repeated = plan.retryActiveKeys
        .map(key => characters.find(character => character.key === key))
        .filter(Boolean)
        .slice(0, runtime.maxActive);
      if (repeated.length) active = repeated;
    }
    let focus = selectFocus(active, currentInput);
    if (plan.pendingOperationRetry === true
      && (!focus || focus.key !== plan.retryFocusKey
        || !active.some(character => character.key === plan.retryFocusKey))) {
      cancelPendingOperationRetry(plan);
    }
    if (plan.pendingOperationRetry === true && !pendingOperationRetryStillEligible(plan)) {
      cancelPendingOperationRetry(plan);
      CC.last.warning = [CC.last.warning,
        "A queued operation retry was canceled because its frozen owner, evidence, or model-answer template was no longer valid; this action was rescored normally."
      ].filter(Boolean).join(" ");
    }
    if (plan.retry && plan.retryFocusKey) {
      const frozenFocus = active.find(character => character.key === plan.retryFocusKey)
        || characters.find(character => character.key === plan.retryFocusKey) || null;
      if (frozenFocus) {
        focus = frozenFocus;
        if (!active.some(character => character.key === frozenFocus.key)) {
          active = [frozenFocus].concat(active).slice(0, runtime.maxActive);
        }
      }
    }
    if (!active.length || !focus) {
      CC.activeKeys = [];
      CC.modelActiveKeys = [];
      CC.focusKey = "";
      plan.activeKeys = [];
      plan.task = "none";
      plan.taskDelivered = false;
      CC.last.context = "No predetermined active NPC was detected.";
      recordGenuineContextPlan(plan, "no predetermined active NPC was detected");
      return commitFrontMemory("").text;
    }
    CC.activeKeys = active.map(character => character.key);
    CC.focusKey = focus.key;

    if (plan.opportunity) {
    const scoringFrozenEvidenceIds = (plan.retry || plan.pendingOperationRetry)
      && Array.isArray(plan.retryEvidenceIds) && plan.retryEvidenceIds.length
      ? plan.retryEvidenceIds
      : (operationOpportunityFrozen(plan) && Array.isArray(plan.evidenceIds) ? plan.evidenceIds : []);
    const scoringFrozenEligibility = (plan.retry || plan.pendingOperationRetry) && plan.retryEvidenceEligibility
      ? plan.retryEvidenceEligibility
      : (operationOpportunityFrozen(plan) && plan.evidenceEligibility ? plan.evidenceEligibility : null);
    const scoringFrozenOpportunity = operationOpportunityFrozen(plan) && Number.isFinite(Number(plan.ownerOpportunity))
      ? Math.max(0, Number(plan.ownerOpportunity) - 1)
      : null;
    const scoringEvidence = availableEvidence(
      focus,
      recent,
      plan.inputEvidenceId || "",
      scoringFrozenEvidenceIds,
      scoringFrozenOpportunity,
      scoringFrozenEligibility
    );
    const scoringRelationships = relevantRelationshipRecords(focus, active, currentInput, recent);
    const scoringActiveViews = relevantViewRecords(focus, active, currentInput, recent, scoringEvidence, false);
    const scoringBuriedViews = relevantViewRecords(focus, active, currentInput, recent, scoringEvidence, true);
    const scoringTargets = operationTargetMap(
      focus,
      active,
      scoringActiveViews,
      scoringBuriedViews,
      scoringRelationships,
      currentInput,
      scoringEvidence,
      recent
    );
    const scoringFrozenSourcePacket = (plan.retry || plan.pendingOperationRetry) && Array.isArray(plan.retrySourcePacket)
      ? plan.retrySourcePacket
      : (operationOpportunityFrozen(plan) && Array.isArray(plan.sourcePacket) ? plan.sourcePacket : null);
    const scoringDerivedRelationships = relationshipDerivedEvidenceCandidates(
      focus,
      scoringTargets,
      scoringFrozenOpportunity,
      scoringFrozenSourcePacket
    );
    const scoringDerivedViews = viewDerivedEvidenceCandidates(
      focus,
      scoringTargets,
      scoringFrozenOpportunity,
      scoringFrozenSourcePacket
    );
    const scoringSources = semanticAssessmentEvidence(
      focus,
      recent,
      plan.inputEvidenceId || "",
      scoringFrozenEvidenceIds,
      scoringFrozenOpportunity
    );
    freezeOperationSelection(plan, focus, scoringTargets, scoringSources, plan.inputEvidenceId || "", recent);
    }

    const attempt = assembleContext(
      frontMemory.baseText,
      active,
      focus,
      currentInput,
      recent,
      plan,
      frontMemory.externalFrontMemory
    );
    if (!attempt.ok) {
      CC.last.effectiveBudget = Math.max(0, Number(attempt.effectiveBudget) || 0);
      CC.last.headroomTokens = CC.last.effectiveBudget;
      CC.last.recentStoryChars = Math.max(0, Number(attempt.recentChars) || 0);
      CC.last.contextBaseChars = Math.max(0, Number(attempt.baseChars) || textOf(frontMemory.baseText).length);
      CC.last.contextMaxChars = Math.max(0, Number(attempt.maxChars) || 0);
      CC.last.cacheOverflowActive = attempt.cacheOverflowActive === true;
      CC.last.cacheOverflowUsedTokens = Math.max(0, Number(attempt.cacheOverflowUsedTokens) || 0);
      CC.last.cacheOverflowRemainingTokens = Math.max(0, Number(attempt.cacheOverflowRemainingTokens) || 0);
      if (appendOnlyContext) {
        CC.last.gracefulFallback = true;
        CC.last.context = "Cache-compatible append capacity could not hold a complete continuity packet; injection was skipped this turn.";
        CC.last.warning = "Cache-compatible append capacity was exhausted safely: " + attempt.reason;
        CC.last.error = "";
      } else {
        CC.last.context = "Distinct portrayal could not fit safely: " + attempt.reason;
        CC.last.error = attempt.reason;
      }
      plan.activeKeys = active.map(character => character.key);
      plan.modelActiveKeys = [];
      plan.focusKey = focus.key;
      plan.recentStory = recent;
      plan.task = "none";
      plan.taskDelivered = false;
      plan.ownerKey = focus.key;
      plan.focusKey = focus.key;
      if (plan.opportunity === true && !operationOpportunityFrozen(plan)) {
        plan.opportunityPrepared = true;
        plan.ownerOpportunity = Math.max(0, Number(CC.ownerOpportunities[focus.key]) || 0) + 1;
      }
      plan.targets = [];
      plan.evidenceIds = [];
      plan.operationTaskText = "";
      plan.operationTaskKind = "";
      plan.operationTaskTokens = 0;
      plan.sourcePacket = [];
      plan.sourcePacketText = "";
      plan.sourcePacketTokens = 0;
      CC.modelActiveKeys = [];
      recordGenuineContextPlan(plan, attempt.reason || "the continuity packet could not fit safely");
      return commitFrontMemory("").text;
    }

    const requestedFrontInstruction = textOf(attempt.frontTaskText);
    const committedFrontMemory = commitFrontMemory(requestedFrontInstruction, attempt.text);
    if (!committedFrontMemory.ok) {
      plan.task = "none";
      plan.taskDelivered = false;
      plan.operationTaskText = "";
      plan.operationTaskKind = "";
      plan.operationTaskTokens = 0;
      CC.last.context = "The operation was withheld because its Front Memory instruction could not be verified.";
      CC.last.error = "Front Memory instruction verification failed; no operation was marked delivered.";
      recordGenuineContextPlan(plan, "Front Memory instruction verification failed");
      return originalText;
    }
    const returnedBeforeFrontMemory = committedFrontMemory.frontMemory
      ? committedFrontMemory.text.slice(0, committedFrontMemory.text.lastIndexOf(committedFrontMemory.frontMemory))
      : committedFrontMemory.text;
    const operationPacketVerified = !attempt.taskDelivered
      || returnedBeforeFrontMemory.trimEnd().endsWith(textOf(attempt.taskText).trimEnd());
    attempt.taskDelivered = attempt.taskDelivered
      && committedFrontMemory.delivered
      && operationPacketVerified;
    if (requestedFrontInstruction && !attempt.taskDelivered) {
      const restored = commitFrontMemory("", frontMemory.baseText);
      plan.task = "none";
      plan.taskDelivered = false;
      plan.operationTaskText = "";
      plan.operationTaskKind = "";
      plan.operationTaskTokens = 0;
      CC.last.context = "The operation was withheld because its ordinary Context packet and Front Memory instruction were not both verified.";
      CC.last.error = "Operation delivery verification failed; no operation was marked delivered.";
      recordGenuineContextPlan(plan, "operation delivery verification failed");
      return restored.ok ? restored.text : originalText;
    }

    plan.task = attempt.taskDelivered ? "operation" : (CC.recoveryPending ? "recovery" : "none");
    plan.taskDelivered = attempt.taskDelivered;
    plan.ownerKey = focus.key;
    plan.focusKey = focus.key;
    plan.targets = clone(attempt.targets || []);
    plan.evidenceIds = clone(attempt.evidenceIds || []);
    plan.operationTaskText = textOf(attempt.taskText);
    plan.operationTaskKind = line(attempt.taskKind, 40);
    plan.operationTaskTokens = Math.max(0, Math.floor(Number(attempt.taskTokens) || 0));
    if (attempt.taskDelivered && attempt.operationEvidenceSignature) {
      plan.selectedEvidenceSignature = line(attempt.operationEvidenceSignature, 500);
    }
    plan.evidenceEligibility = {};
    (attempt.evidenceCandidates || []).forEach(candidate => {
      const assessment = attempt.taskKind === ASSESSMENT_OPERATION_KIND;
      plan.evidenceEligibility[candidate.item.id] = {
        name: (assessment || attempt.taskKind === "name") && candidate.nameEligible === true,
        state: (assessment || attempt.taskKind === "state") && candidate.stateEligible === true,
        relationship: (assessment || attempt.taskKind === "relationship") && candidate.relationshipEligible === true,
        view: (assessment || attempt.taskKind === "view") && candidate.viewEligible === true,
        turning: (assessment || attempt.taskKind === "turning") && candidate.turningEligible === true,
        age: candidate.age
      };
    });
    const freshSourcePacket = (attempt.evidenceCandidates || []).map(candidate => {
      const prefix = candidate.item.id.charAt(0);
      const derived = candidate.item.source === "provenance";
      const packetTarget = (attempt.targets || [])[0] || null;
      const assessment = attempt.taskKind === ASSESSMENT_OPERATION_KIND;
      return {
        id: candidate.item.id,
        prefix,
        text: operationEvidencePacketSnippet(
          focus, packetTarget, attempt.taskKind, candidate, plan.selectedCandidate
        ),
        source: candidate.item.source,
        name: (assessment || attempt.taskKind === "name") && candidate.nameEligible === true,
        state: (assessment || attempt.taskKind === "state") && candidate.stateEligible === true,
        relationship: (assessment || attempt.taskKind === "relationship") && candidate.relationshipEligible === true,
        view: (assessment || attempt.taskKind === "view") && candidate.viewEligible === true,
        turning: (assessment || attempt.taskKind === "turning") && candidate.turningEligible === true,
        age: candidate.age,
        ownerKey: derived ? candidate.ownerKey : focus.key,
        targetKey: derived ? candidate.targetKey : "",
        targetName: derived ? candidate.targetName : "",
        allowedFields: derived ? clone(candidate.allowedFields || []) : [],
        allowedDestinations: derived ? clone(candidate.allowedDestinations || []) : [],
        allowedModes: derived ? clone(candidate.allowedModes || []) : [],
        interpretations: derived ? clone(candidate.interpretations || []) : [],
        managedSignature: derived ? candidate.managedSignature : "",
        rawLineage: derived ? clone(candidate.rawLineage || []) : [candidate.item.id],
        gain: derived ? Math.max(0, Number(candidate.gain) || 0) : 0,
        useSignatures: derived ? clone(candidate.useSignatures || {}) : {},
        directAllowed: derived ? false : true,
        reason: derived ? candidate.eligibilityReason || "" : ""
      };
    });
    plan.sourcePacket = attempt.taskDelivered ? freshSourcePacket : [];
    plan.sourcePacketText = attempt.taskDelivered
      ? ((plan.retry || plan.pendingOperationRetry) && textOf(plan.retrySourcePacketText)
        ? textOf(plan.retrySourcePacketText)
        : (attempt.taskKind === ASSESSMENT_OPERATION_KIND
          ? (attempt.evidenceCandidates || []).map(candidate => candidate.item.id + "["
            + assessmentEvidenceCodes(candidate).join("") + "]: "
            + operationEvidenceSnippet(focus, null, "", candidate.item.text, null)).join("\n")
          : evidencePacketForKind(
            focus,
            attempt.taskKind,
            attempt.evidenceCandidates || [],
            plan.inputEvidenceId || "",
            recent,
            attempt.targets[0] || null,
            plan.selectedCandidate
          )))
      : "";
    plan.sourcePacketTokens = estimateTokens(plan.sourcePacketText);
    plan.activeKeys = active.map(character => character.key);
    plan.modelActiveKeys = attempt.modelActive.map(character => character.key);
    plan.recentStory = recent;
    if (plan.pendingOperationRetry && attempt.taskDelivered) {
      CC.pendingOperationRetry = blankPendingOperationRetry();
    }
    if (plan.opportunity === true && !operationOpportunityFrozen(plan)) {
      plan.opportunityPrepared = true;
      plan.ownerOpportunity = Math.max(0, Number(CC.ownerOpportunities[focus.key]) || 0) + 1;
    }
    CC.modelActiveKeys = plan.modelActiveKeys.slice();

    Object.assign(CC.last, {
      rulesTokens: attempt.rulesTokens,
      outerTokens: attempt.outerTokens,
      namesTokens: attempt.namesTokens,
      innerTokens: attempt.innerTokens,
      stateTokens: attempt.stateTokens,
      relationshipsTokens: attempt.relationshipsTokens,
      turningPointsTokens: attempt.turningPointsTokens,
      viewsTokens: attempt.viewsTokens,
      experiencesTokens: attempt.experiencesTokens,
      evidenceTokens: attempt.evidenceTokens,
      taskTokens: attempt.taskTokens,
      injectedTokens: attempt.tokens,
      effectiveBudget: attempt.effectiveBudget,
      headroomTokens: attempt.headroom,
      recentStoryChars: attempt.recentChars,
      contextBaseChars: attempt.baseChars,
      contextMaxChars: attempt.maxChars,
      cacheOverflowActive: attempt.cacheOverflowActive,
      cacheOverflowUsedTokens: attempt.cacheOverflowUsedTokens,
      cacheOverflowRemainingTokens: attempt.cacheOverflowRemainingTokens,
      portrayalTier: attempt.portrayalTier || "full",
      task: plan.task,
      owner: attempt.taskDelivered ? focus.name : "",
      selectedNames: attempt.selectedNames,
      omittedNames: attempt.omittedNames,
      selectedRelationships: attempt.selectedRelationships,
      omittedRelationships: attempt.omittedRelationships,
      selectedTurningPoints: attempt.selectedTurningPoints,
      omittedTurningPoints: attempt.omittedTurningPoints,
      selectedViews: attempt.selectedViews,
      omittedViews: attempt.omittedViews,
      selectedExperiences: attempt.selectedExperiences,
      omittedExperiences: attempt.omittedExperiences,
      suppliedEvidence: attempt.evidenceIds,
      suppliedSources: (plan.sourcePacket || []).map(source => source.id + "=" + source.prefix),
      sourcePacketTokens: plan.sourcePacketTokens || 0,
      suppliedTargets: attempt.targets.map(target => target.code + "=" + target.name)
    });
    if (attempt.cacheLimitedPortrayal) {
      CC.last.gracefulFallback = true;
      const fallbackMessage = attempt.portrayalTier === "emergency"
        ? (attempt.taskDelivered
          ? "Cache-compatible context used the focused NPC's complete emergency portrayal core so the complete operation packet could be preserved."
          : "Cache-compatible context used the focused NPC's complete emergency portrayal core.")
        : "Cache-compatible context used the focused NPC's complete compact Outer/Inner pair.";
      CC.last.warning = [
        CC.last.warning,
        fallbackMessage
      ].filter(Boolean).join(" ");
    }
    if (plan.opportunity && !attempt.taskDelivered && plan.selectedOperationKind) {
      CC.last.gracefulFallback = true;
      CC.last.warning = [
        CC.last.warning,
        "Operation deferred: " + (attempt.taskDeferredReason || "the complete packet was unavailable")
      ].filter(Boolean).join(" ");
    }
    CC.last.context = "Scene-relevant " + active.map(character => character.name).join(", ")
      + "; model-facing " + attempt.modelActive.map(character => character.name).join(", ")
      + "; focus " + focus.name + (attempt.taskDelivered
        ? "; one " + operationKindLabel(attempt.taskKind)
          + " CCO task delivered with its mandatory instruction in Front Memory."
        : ".");
    recordGenuineContextPlan(plan, attempt.taskDelivered ? "" : attempt.taskDeferredReason);
    return committedFrontMemory.text;
  }

  function candidateSourceLabel(sourceIds) {
    return (Array.isArray(sourceIds) ? sourceIds : []).join(",") || "no sources";
  }

  function operationOutcomeIdentity(owner, plan, parsedCandidate, result) {
    const selected = plan && plan.selectedCandidate && typeof plan.selectedCandidate === "object"
      ? plan.selectedCandidate
      : {};
    const candidate = parsedCandidate && typeof parsedCandidate === "object" ? parsedCandidate : {};
    const kind = keyOf(plan && plan.selectedOperationKind || candidate.kind || selected.kind);
    let targetKey = normalizedTargetKey(result && result.targetKey || selected.targetKey);
    if (!targetKey && kind === "state" && candidate.targetCode) {
      const target = targetForCode(plan, candidate.targetCode);
      targetKey = normalizedTargetKey(target && target.key);
    }
    if (!targetKey && kind === "relationship" && candidate.targetCode) {
      const target = targetForCode(plan, candidate.targetCode);
      targetKey = normalizedTargetKey(target && target.key);
    }
    if (!targetKey && kind === "view") {
      const field = textOf(candidate.targetField).trim();
      const fresh = field.match(/^NEW=(.+)$/i);
      if (fresh) {
        const target = canonicalViewTarget(owner, fresh[1]);
        targetKey = normalizedTargetKey(target && target.key);
      } else if (field) {
        const target = targetForCode(plan, field.toUpperCase());
        targetKey = normalizedTargetKey(target && target.key);
      }
    }
    if (!targetKey && kind === "name") targetKey = normalizedTargetKey(result && result.subjectKey || selected.targetKey);
    const field = line(result && result.field || candidate.field || selected.field, 80);
    let destination = line(candidate.destination || selected.destination, 120);
    if (!destination && kind === "name") destination = line(candidate.transition, 120);
    return {
      ownerKey: owner ? owner.key : line(plan && plan.ownerKey, 160),
      kind,
      targetKey,
      field,
      destination,
      evidenceSignature: line(plan && plan.selectedEvidenceSignature || selected.evidenceSignature, 500)
    };
  }

  function applyOperationOutcomeDrain(owner, plan, parsedCandidate, result, outcome) {
    const normalizedOutcome = keyOf(outcome);
    const points = {
      cutoff: 0,
      stale: 0,
      success: settings.OPERATION_POINTS.SUCCESS_DRAIN,
      unchanged: settings.OPERATION_POINTS.UNCHANGED_DRAIN,
      omitted: settings.OPERATION_POINTS.OMITTED_DRAIN,
      rejected: settings.OPERATION_POINTS.REJECTED_DRAIN,
      malformed: settings.OPERATION_POINTS.MALFORMED_DRAIN
    }[normalizedOutcome];
    if (!owner || !plan || !plan.taskDelivered || !Number.isFinite(Number(points))) return null;
    const identity = operationOutcomeIdentity(owner, plan, parsedCandidate, result);
    if (!MODEL_OPERATION_KINDS.includes(identity.kind) || !identity.ownerKey || !identity.evidenceSignature) return null;
    const opportunity = Math.max(0, Number(plan.ownerOpportunity) || Number(CC.ownerOpportunities[owner.key]) || 0);
    const priorMeter = normalizeOperationMeter(
      CC.operationState.owners[owner.key] && CC.operationState.owners[owner.key][identity.kind]
    );
    const transportOutcome = ["omitted", "cutoff"].includes(normalizedOutcome);
    const repeatedOmission = transportOutcome
      && keyOf(priorMeter.lastResult) === normalizedOutcome
      && priorMeter.lastSignature === identity.evidenceSignature;
    materializeOwnerDrainDecay(owner.key, opportunity);
    const key = operationDrainKey(identity);
    let record = (Array.isArray(CC.operationState.drains) ? CC.operationState.drains : [])
      .map(normalizeOperationDrainRecord)
      .find(item => item && item.key === key) || null;
    const priorValue = record ? effectiveOperationDrainValue(record, opportunity) : 0;
    const zeroDrainTransport = ["cutoff", "stale"].includes(normalizedOutcome);
    const repeated = zeroDrainTransport
      ? 0
      : (priorValue > 0 ? settings.OPERATION_POINTS.REPEATED_SIGNATURE_DRAIN : 0);
    const added = Math.max(0, Number(points) || 0) + Math.max(0, Number(repeated) || 0);
    if (zeroDrainTransport) {
      if (!record) {
        record = normalizeOperationDrainRecord({
          ...identity,
          value: 0,
          updatedOpportunity: opportunity,
          attempts: 0,
          lastResult: normalizedOutcome
        });
      }
      if (record) {
        record.value = priorValue;
        record.updatedOpportunity = opportunity;
        record.attempts = normalizedOutcome === "cutoff"
          ? (keyOf(record.lastResult) === "cutoff" ? record.attempts + 1 : 1)
          : 0;
        record.lastResult = normalizedOutcome;
        record.key = operationDrainKey(record);
        const otherRecords = (Array.isArray(CC.operationState.drains) ? CC.operationState.drains : [])
          .map(normalizeOperationDrainRecord)
          .filter(item => item && item.key !== record.key);
        CC.operationState.drains = otherRecords.concat(record)
          .sort((left, right) => left.updatedOpportunity - right.updatedOpportunity)
          .slice(-settings.MAX_OPERATION_DRAIN_RECORDS);
      }
      if (!CC.operationState.owners[owner.key]) CC.operationState.owners[owner.key] = blankOwnerOperationState();
      const meter = CC.operationState.owners[owner.key][identity.kind] || blankOperationMeter();
      meter.gain = Math.max(0, Number(plan.selectedGain) || 0);
      meter.drain = priorValue;
      meter.lastServedOpportunity = opportunity;
      meter.lastResult = normalizedOutcome;
      meter.lastSignature = identity.evidenceSignature;
      meter.lastTargetKey = identity.targetKey;
      meter.lastField = identity.field;
      CC.operationState.owners[owner.key][identity.kind] = normalizeOperationMeter(meter);
      const summary = operationKindLabel(identity.kind) + " " + normalizedOutcome
        + " added no drain; existing drain remains "
        + priorValue + " at owner opportunity " + opportunity + ".";
      CC.last.operationOutcome = operationKindLabel(identity.kind) + " " + normalizedOutcome;
      CC.last.operationDrainChange = summary;
      updatePendingOperationRetry(plan, normalizedOutcome);
      return { record, priorValue, base: 0, repeated: 0, summary };
    }
    if (!record) {
      record = normalizeOperationDrainRecord({
        ...identity,
        value: 0,
        updatedOpportunity: opportunity,
        attempts: repeatedOmission ? 1 : 0
      });
    }
    if (!record) return null;
    record.value = Math.min(settings.OPERATION_DRAIN_CAP, priorValue + added);
    record.updatedOpportunity = opportunity;
    record.attempts = normalizedOutcome === "omitted"
      ? (keyOf(record.lastResult) === "omitted" ? record.attempts + 1 : 1)
      : 0;
    record.lastResult = normalizedOutcome;
    record.key = operationDrainKey(record);
    const others = (Array.isArray(CC.operationState.drains) ? CC.operationState.drains : [])
      .map(normalizeOperationDrainRecord)
      .filter(item => item && item.key !== record.key);
    CC.operationState.drains = others.concat(record)
      .sort((left, right) => left.updatedOpportunity - right.updatedOpportunity)
      .slice(-settings.MAX_OPERATION_DRAIN_RECORDS);

    if (!CC.operationState.owners[owner.key]) CC.operationState.owners[owner.key] = blankOwnerOperationState();
    const meter = CC.operationState.owners[owner.key][identity.kind] || blankOperationMeter();
    meter.gain = Math.max(0, Number(plan.selectedGain) || 0);
    meter.drain = record.value;
    meter.lastServedOpportunity = opportunity;
    meter.lastResult = normalizedOutcome;
    meter.lastSignature = identity.evidenceSignature;
    meter.lastTargetKey = identity.targetKey;
    meter.lastField = identity.field;
    CC.operationState.owners[owner.key][identity.kind] = normalizeOperationMeter(meter);

    const summary = operationKindLabel(identity.kind) + " " + normalizedOutcome
      + " drain " + priorValue + " + " + Math.max(0, Number(points) || 0)
      + (repeated ? " + repeated " + repeated : "") + " = " + record.value
      + " at owner opportunity " + opportunity + ".";
    CC.last.operationOutcome = operationKindLabel(identity.kind) + " " + normalizedOutcome;
    CC.last.operationDrainChange = summary;
    updatePendingOperationRetry(plan, normalizedOutcome);
    return { record, priorValue, base: points, repeated, summary };
  }

  function processOutput(outputValue) {
    const plan = CC.currentPlan || { task: "none", taskDelivered: false, activeKeys: CC.activeKeys || [] };
    if (plan.opening) {
      CC.last.outputRawChars = textOf(outputValue).replace(/\r/g, "").trim().length;
      CC.last.outputStoryChars = 0;
      CC.last.outputRecordChars = 0;
      CC.last.outputRecordPosition = "none";
      CC.last.output = "Suppressed only the automatic output immediately following the retained opening prompt.";
      CC.last.candidate = "not requested";
      plan.completed = true;
      markActionCompleted(plan);
      return " ";
    }

    commitDeliveredOperationOpportunity(plan);

    const turningPointControl = stripTurningPointControlEchoes(outputValue);
    const rawFallback = stripOperationFallbackBlocks(turningPointControl.text, plan, true);
    const instructionEcho = stripOperationInstructionEchoes(rawFallback.text, plan);
    const residualFallback = stripOperationFallbackBlocks(instructionEcho.text, plan, false);
    const operationFallback = {
      text: residualFallback.text,
      count: rawFallback.count + residualFallback.count,
      sample: rawFallback.sample || residualFallback.sample,
      pattern: [rawFallback.pattern, residualFallback.pattern].filter(Boolean).join(" and "),
      kind: rawFallback.kind || residualFallback.kind,
      recoveredRecord: rawFallback.recoveredRecord,
      inferredEvidence: rawFallback.inferredEvidence === true
    };
    const cleanedHasProtocol = operationFallback.text.split("\n").some(value => {
      const presented = ccoPresentation(value);
      return presented.protocolLike || /\(\s*CCO\b/i.test(value);
    });
    const recoveryApplied = !!(operationFallback.recoveredRecord
      && (!cleanedHasProtocol || operationFallback.pattern.includes("split-protocol")));
    const preparedOutput = recoveryApplied
      ? (operationFallback.text ? operationFallback.text + "\n" : "")
        + operationFallback.recoveredRecord
      : operationFallback.text;
    const parsed = parseTerminalCandidate(outputValue, plan, preparedOutput);
    const outputMetrics = outputProtocolMetrics(outputValue, preparedOutput, parsed.story);
    CC.last.outputRawChars = outputMetrics.rawChars;
    CC.last.outputStoryChars = outputMetrics.storyChars;
    CC.last.outputRecordChars = outputMetrics.recordChars;
    CC.last.outputRecordPosition = outputMetrics.position;
    const normalizedCandidate = recoveryApplied && !!parsed.candidate;
    const cleanupNotes = [];
    if (turningPointControl.count > 0) {
      cleanupNotes.push("Turning Point portrayal control echo stripped (" + turningPointControl.count
        + " block" + (turningPointControl.count === 1 ? "" : "s") + ").");
    }
    if (instructionEcho.count > 0) {
      cleanupNotes.push("CC control echo stripped (" + instructionEcho.count + " line"
        + (instructionEcho.count === 1 ? "" : "s") + ").");
    }
    if (operationFallback.count > 0) {
      cleanupNotes.push("Visible " + operationKindLabel(operationFallback.kind) + " "
        + (operationFallback.pattern ? operationFallback.pattern + " " : "")
        + "fallback block " + (recoveryApplied
          ? "converted into a hidden CCO recovery candidate"
            + (operationFallback.inferredEvidence ? " with the single frozen evidence source" : "")
          : "stripped")
        + " (" + operationFallback.count + " line"
        + (operationFallback.count === 1 ? "" : "s") + ").");
    }
    if (cleanupNotes.length && !parsed.candidate && !parsed.unauthorized && !parsed.stale && !parsed.cutoff) {
      parsed.malformed = true;
      parsed.reason = cleanupNotes.join(" ")
        + (parsed.hadProtocol ? " " + parsed.reason : "");
      parsed.raw = operationFallback.sample || instructionEcho.sample || turningPointControl.sample;
    }
    const protocolSummary = parsed.hadProtocol
      ? parsed.reason + (parsed.raw ? " Record: " + line(parsed.raw, 180) : "")
      : (parsed.reason || "No CCO record");
    CC.last.protocol = cleanupNotes.length && parsed.candidate
      ? cleanupNotes.join(" ") + " " + protocolSummary
      : protocolSummary;
    const story = parsed.story.trim();
    if (!hasTerminallyPunctuatedStory(story)) {
      const owner = characters.find(character => character.key === plan.ownerKey) || null;

      CC.recoveryPending = true;
      CC.last.candidate = parsed.stale
        ? "stale contract stripped"
        : (parsed.unauthorized
          ? "unauthorized stripped"
          : (parsed.malformed
            ? "malformed stripped"
            : (parsed.cutoff
              ? "cutoff stripped"
            : (parsed.candidate
              ? (normalizedCandidate
                ? "normalized rejected: no punctuated story"
                : "rejected: no punctuated story")
              : "absent: no punctuated story"))));

      CC.last.operationOutcome = "None";
      CC.last.operationDrainChange = "No drain change";
      if (owner && plan.taskDelivered) {
        const outcome = parsed.stale
          ? "stale"
          : (parsed.cutoff
            ? "cutoff"
            : (parsed.malformed
            ? "malformed"
            : (parsed.unauthorized
              ? "rejected"
              : (parsed.candidate ? "rejected" : "omitted"))));
        applyOperationOutcomeDrain(owner, plan, parsed.candidate, null, outcome);
        if (plan.semanticAssessment === true && plan.semanticAssessmentResolved !== true) {
          updatePendingOperationRetry(plan, outcome);
          CC.last.operationOutcome = "Assessment " + outcome;
          CC.last.operationDrainChange = "No drain change";
        }
      }

      // Withholding the continuity bookkeeping here is right: an unfinished reply
      // is not safe to derive state from. Deleting the prose is not. AI Dungeon
      // truncates generations at the token limit routinely, so returning " " blanks
      // the turn the player waited for and loses text no other copy of exists.
      // Hand the prose back and leave recovery pending.
      CC.last.output = story
        ? "The response did not finish terminally punctuated prose, so it was delivered unchanged but no operation was applied and prose-only recovery remains pending."
        : "No story prose survived; no operation was applied and prose-only recovery remains pending.";
      CC.last.error = "The response did not finish terminally punctuated story prose.";
      recordGenuineOutputResolution(plan);
      return story ? story : " ";
    }

    const nextGeneration = CC.visibleGenerationCount + 1;
    const nextStateClock = CC.stateClock + 1;
    const storyTimeJump = TIME_JUMP.test(story);
    if (storyTimeJump) resetSceneForTimeJump();
    const owner = characters.find(character => character.key === plan.ownerKey) || null;
    const focus = characters.find(character => character.key === plan.focusKey) || owner || null;
    let result = null;
    let evidenceResult = null;
    const modelAuthoredPreparation = parsed.candidate
      && !parsed.candidate.noChange
      && owner
      && plan.semanticAssessment === true
      && keyOf(plan.selectedOperationKind) === ASSESSMENT_OPERATION_KIND
      ? prepareModelAuthoredOperation(owner, parsed.candidate, plan)
      : null;

    if (parsed.stale) {
      CC.last.candidate = "stale contract stripped";
      CC.last.warning = [CC.last.warning, parsed.reason].filter(Boolean).join(" ");
      CC.last.error = "";
    } else if (parsed.unauthorized) {
      CC.last.candidate = "unauthorized stripped";
      CC.last.error = parsed.reason || "An unauthorized CCO record was stripped while punctuated story prose survived.";
    } else if (parsed.malformed) {
      CC.last.candidate = "malformed stripped";
      CC.last.error = parsed.reason || "A malformed CCO record was stripped while punctuated story prose survived.";
    } else if (parsed.cutoff) {
      CC.last.candidate = "cutoff stripped";
      CC.last.warning = [CC.last.warning, parsed.reason].filter(Boolean).join(" ");
      CC.last.error = "";
    } else if (!parsed.candidate) {
      CC.last.candidate = plan.taskDelivered ? "omitted" : "not requested";
      CC.last.error = plan.taskDelivered
        ? "The model omitted the mandatory completed first-line CCO record."
        : "";
    } else if (parsed.candidate.noChange === true) {
      const assessedItems = unique(parsed.candidate.evidenceIds || [], 20).map(evidenceForId).filter(Boolean);
      const suppliedIds = new Set((Array.isArray(plan.sourcePacket) ? plan.sourcePacket : [])
        .map(source => continuitySourceId(source && source.id)).filter(Boolean));
      if (!owner || plan.semanticAssessment !== true
        || assessedItems.length !== parsed.candidate.evidenceIds.length
        || parsed.candidate.evidenceIds.some(id => !suppliedIds.has(id))) {
        result = { ok: false, error: "The completed no-change assessment did not resolve to its supplied owner and evidence packet." };
      } else {
        markNoChangeAssessment(assessedItems, owner, plan.ownerOpportunity);
        result = {
          ok: false,
          unchanged: true,
          assessment: true,
          summary: owner.name + " semantic assessment completed with continuity unchanged"
        };
        CC.last.operationOutcome = "Assessment unchanged";
        CC.last.operationDrainChange = "No drain change";
        CC.pendingOperationRetry = blankPendingOperationRetry();
      }
    } else if (modelAuthoredPreparation && !modelAuthoredPreparation.ok) {
      result = modelAuthoredPreparation;
    } else if (!owner || plan.task !== "operation" || !plan.taskDelivered) {
      result = { ok: false, error: "The parsed operation had no authorized fixed owner or delivered task." };
    } else if (parsed.candidate.kind !== keyOf(plan.selectedOperationKind)) {
      result = { ok: false, error: "The parsed operation kind did not match the scheduled operation contract." };
    } else if (parsed.candidate.kind === "name") {
      const subject = nameSubjectForCandidate(owner, parsed.candidate, plan);
      if (!subject.ok) result = subject;
      else {
        evidenceResult = citedEvidenceForOperation(owner, parsed.candidate, plan, subject.identity.key);
        result = evidenceResult.ok
          ? applyNameCandidate(owner, parsed.candidate, plan, evidenceResult.items)
          : evidenceResult;
        if (result.ok) {
          consumeNameEvidence(evidenceResult.items, result.subjectKey || subject.identity.key, result.aliasKey || nameKeyOf(parsed.candidate.alias));
          CC.last.lastName = result.nameDetail || result.summary;
        }
      }
    } else if (parsed.candidate.kind === "state") {
      const target = targetForCode(plan, parsed.candidate.targetCode);
      if (!target) result = { ok: false, error: "State used an About code outside the frozen target map." };
      else if (storyTimeJump) result = { ok: false, error: "A generated time jump cleared immediate State and blocked the pre-jump State operation." };
      else {
        evidenceResult = citedEvidenceForOperation(owner, parsed.candidate, plan, target.key);
        result = evidenceResult.ok
          ? applyStateCandidate(owner, parsed.candidate, nextStateClock, plan, evidenceResult.items)
          : evidenceResult;
        if (result.ok) consumeStateEvidence(evidenceResult.items, owner);
      }
    } else if (parsed.candidate.kind === "relationship") {
      const target = targetForCode(plan, parsed.candidate.targetCode);
      if (!target || target.relationship !== true) {
        result = { ok: false, error: "Relationship used a target outside the frozen directional target map." };
      } else {
        evidenceResult = citedEvidenceForOperation(owner, parsed.candidate, plan, target.key);
        if (!evidenceResult.ok) {
          result = evidenceResult;
        } else {
          const relationshipSnapshot = captureRelationshipProvenanceTransaction();
          result = applyRelationshipCandidate(owner, parsed.candidate, plan, evidenceResult.items);
          if (result.ok) {
            const provenance = commitRelationshipProvenance(owner, result, plan);
            if (!provenance.ok) {
              const restored = restoreRelationshipProvenanceTransaction(
                relationshipSnapshot,
                provenance.error
              );
              result = {
                ok: false,
                error: "Relationship mutation rolled back because R# provenance or narrow use could not commit: "
                  + provenance.error + (restored ? "" : " (managed-card rollback was incomplete)")
              };
            } else {
              result.provenanceId = provenance.record.id;
              consumeRelationshipEvidence(evidenceResult.items, owner, result.targetKey || target.key);
              CC.last.lastRelationship = (result.relationshipDetail || result.summary)
                + "; provenance " + provenance.record.id;
              CC.last.relationshipChange = "Actual stage " + (result.actualStage || "unknown")
                + "; numeric change " + Math.trunc(Number(result.actualChange) || 0)
                + "; stage " + (result.stageChanged ? "changed" : "unchanged")
                + "; description " + (result.descriptionChanged ? "changed" : "unchanged")
                + (result.recordRemoved ? "; empty record removed" : "");
              CC.last.relationshipSourceDiagnostics = unique(
                (CC.last.relationshipSourceDiagnostics || []).concat(
                  "5C-D accepted " + candidateSourceLabel(parsed.candidate.evidenceIds || [])
                    + " as " + parsed.candidate.eventKind + " for " + parsed.candidate.field
                    + "; actual stage " + (result.actualStage || "unknown")
                    + "; R# " + provenance.record.id
                    + "; derived narrow uses committed "
                    + ((result.narrowUses || []).length || 0)
                ), 500
              ).slice(-40);
            }
          }
        }
      }
    } else if (parsed.candidate.kind === "turning") {
      const target = targetForCode(plan, parsed.candidate.targetCode);
      if (!target || target.key !== "self") {
        result = { ok: false, error: "Turning Point used a target outside the frozen Self target." };
      } else {
        evidenceResult = citedEvidenceForOperation(owner, parsed.candidate, plan, target.key);
        result = evidenceResult.ok
          ? applyTurningPointCandidate(owner, parsed.candidate, plan, evidenceResult.items)
          : evidenceResult;
        if (result.ok) {
          consumeTurningPointEvidence(evidenceResult.items, owner, result.turningPointId);
          CC.last.lastTurningPoint = result.summary;
          CC.last.turningPointChange = result.mode + "; " + result.priorScore + " (" + result.priorStage
            + ") → " + result.score + " (" + result.stage + "); active card " + result.activeCard;
        }
      }
    } else if (parsed.candidate.kind === "view") {
      const targetResolution = resolveViewTarget(owner, parsed.candidate, plan);
      if (!targetResolution.ok) result = targetResolution;
      else {
        evidenceResult = citedEvidenceForOperation(owner, parsed.candidate, plan, targetResolution.target.key);
        if (!evidenceResult.ok) {
          result = evidenceResult;
        } else {
          const viewSnapshot = captureViewProvenanceTransaction();
          result = applyViewCandidate(owner, parsed.candidate, plan, evidenceResult.items);
          if (!result.ok && result.rollbackRequired) {
            const restored = restoreViewProvenanceTransaction(viewSnapshot, result.error);
            result = {
              ok: false,
              error: "View mutation rolled back because the managed write could not be verified: "
                + result.error + (restored ? "" : " (managed-card rollback was incomplete)")
            };
          } else if (result.ok) {
            const provenance = commitViewProvenance(owner, result, plan);
            if (!provenance.ok) {
              const restored = restoreViewProvenanceTransaction(viewSnapshot, provenance.error);
              result = {
                ok: false,
                error: "View mutation rolled back because V# provenance or narrow use could not commit: "
                  + provenance.error + (restored ? "" : " (managed-card rollback was incomplete)")
              };
            } else {
              result.provenanceId = provenance.record.id;
              consumeViewEvidence(evidenceResult.items, owner, result.targetKey || targetResolution.target.key);
              const derivedValidated = (evidenceResult.items || []).filter(item => item && item.source === "provenance");
              CC.last.viewSourceDiagnostics = unique((CC.last.viewSourceDiagnostics || []).concat(
                "5D-D accepted " + candidateSourceLabel(parsed.candidate.evidenceIds || [])
                  + " for " + parsed.candidate.destination
                  + " via " + result.operationMode
                  + "; V# " + provenance.record.id
                  + "; derived narrow uses committed " + ((result.narrowUses || []).length || 0)
              ), 500).slice(-40);
              CC.last.viewUseDiagnostics = unique((CC.last.viewUseDiagnostics || []).concat(
                derivedValidated.length
                  ? "Committed View uses: " + derivedValidated.map(item =>
                    item.id + ":" + item.destination + ":" + item.operationMode).join(", ")
                  : "Committed " + provenance.record.id + " from raw E# only; no derived View use."
              ), 500).slice(-40);
            }
          }
        }
      }
    }

    if (result) {
      if (result.ok) {
        CC.last.candidate = normalizedCandidate ? "normalized accepted" : "accepted";
        CC.last.update = result.summary;
        CC.last.error = "";
        if (result.warning) {
          CC.last.warning = [CC.last.warning, result.warning].filter(Boolean).join(" ");
        }
      } else {
        CC.last.candidate = result.assessment
          ? "assessed unchanged"
          : result.unchanged
          ? (normalizedCandidate ? "normalized unchanged" : "unchanged")
          : (normalizedCandidate ? "normalized rejected" : "rejected");
        CC.last.error = result.unchanged ? "" : result.error;
      }
    }
    if (owner && plan.taskDelivered) {
      const outcome = parsed.stale
        ? "stale"
        : (parsed.cutoff
          ? "cutoff"
          : (parsed.malformed
          ? "malformed"
          : (parsed.unauthorized
            ? "rejected"
            : (!parsed.candidate
                ? "omitted"
                : (result && result.ok
                  ? "success"
                  : (result && result.unchanged ? "unchanged" : "rejected"))))));
      applyOperationOutcomeDrain(owner, plan, parsed.candidate, result, outcome);
      if (plan.semanticAssessment === true && plan.semanticAssessmentResolved !== true) {
        updatePendingOperationRetry(plan, outcome);
        CC.last.operationOutcome = "Assessment " + outcome;
        CC.last.operationDrainChange = "No drain change";
      }
    }
    if (cleanupNotes.length && parsed.candidate) {
      CC.last.warning = [CC.last.warning, normalizedCandidate
        ? "A structured output fallback was normalized and validated before its hidden operation and story were processed."
        : "CC output residue was stripped before the valid CCO record and story were processed."]
        .filter(Boolean).join(" ");
    }

    CC.visibleGenerationCount = nextGeneration;
    CC.stateClock = nextStateClock;
    expireTemporaryState(CC.stateClock);
    CC.recoveryPending = false;
    if (focus) {
      updateScenePresence(story, focus.key, nextGeneration);
      CC.focusLastServed[focus.key] = nextGeneration;
    }
    const conversationKeys = Array.isArray(plan.modelActiveKeys) && plan.modelActiveKeys.length
      ? plan.modelActiveKeys
      : (Array.isArray(plan.activeKeys) ? plan.activeKeys : []);
    const conversationSpeaker = inferredConversationSpeaker(story, conversationKeys
      .map(key => characters.find(character => character.key === key)).filter(Boolean));
    CC.conversationKey = conversationSpeaker ? conversationSpeaker.key : "";
    plan.completed = true;
    markActionCompleted(plan);
    CC.lastVisibleOutputAnchor = outputAnchorFor(story, plan);
    const storyEvidence = addEvidence("story", story);
    if (storyTimeJump && storyEvidence) CC.lastTimeJumpEvidenceId = storyEvidence.id;
    CC.last.output = result && result.ok
      ? "Punctuated story prose survived and the " + (normalizedCandidate ? "normalized " : "accepted ")
        + parsed.candidate.kind + " operation committed transactionally."
      : result && result.unchanged
      ? (result.assessment
        ? "Punctuated story prose survived and the completed semantic assessment left continuity unchanged."
        : "Punctuated story prose survived; the proposed operation already matched and was not refreshed.")
      : "Punctuated story prose survived; " + (CC.last.candidate === "omitted"
          ? "the mandatory completed first-line CCO record was omitted and no continuity operation was applied."
        : (CC.last.candidate === "not requested" ? "no operation was scheduled." : "no continuity operation was applied."));
    recordGenuineOutputResolution(plan);
    return story;
  }

  function stateStatus(character) {
    const state = normalizeState(CC.npcs[character.key] && CC.npcs[character.key].state, CC.stateClock);
    const present = [["T", "thought"], ["F", "feeling"], ["G", "goal"], ["X", "tension"], ["S", "situation"]]
      .filter(([, field]) => state[field].value)
      .map(([label]) => label)
      .join("");
    const threshold = settings.SITUATION_EXPERIENCE_CONFIRMATIONS;
    return character.name + " " + (present || "empty")
      + (state.target.name ? " → " + state.target.name : "")
      + (state.triggers.value.length ? " [" + state.triggers.value.join(",") + "]" : "")
      + (state.situation.value ? " {Situation " + state.situation.confirmations + "/" + threshold
        + (state.situation.promotedSignature ? ", promoted" : "") + "}" : "");
  }

  function castStatus(character) {
    const cast = castFor(character);
    const label = cast.status === "main" ? "Main" : "Side";
    return character.name + " " + label + (cast.status === "main"
      ? " inactive " + cast.inactiveStreak + "/" + runtime.mainInactivityLimit
      : " interactions " + cast.interactionProgress + "/" + runtime.sidePromotionInteractions);
  }

  function outerStatus(character) {
    const maximum = settings.MAX_OUTER_CARD_CHARS;
    const warning = character.outerWarnings.length ? " [" + character.outerWarnings.join(" ") + "]" : " ready";
    return character.name + " " + character.outerRetainedChars + "/" + maximum + warning;
  }

  function innerStatus(character) {
    if (!character.innerCard) {
      return character.name + " missing ["
        + (character.innerWarnings.join(" ") || "Inner card missing.") + "]";
    }
    const maximum = settings.MAX_INNER_CARD_CHARS;
    const warning = character.innerWarnings.length ? " [" + character.innerWarnings.join(" ") + "]" : " ready";
    return character.name + " " + character.innerRetainedChars + "/" + maximum + warning;
  }

  function maintenanceStatusValue(kind, key, live, value, pending) {
    const cache = CC.maintenance.statusCache;
    if (!cache[kind] || typeof cache[kind] !== "object" || Array.isArray(cache[kind])) cache[kind] = {};
    if (live) {
      cache[kind][key] = value;
      return value;
    }
    return textOf(cache[kind][key]) || pending;
  }

  function viewsStatus(character) {
    const owner = viewsForOwner(character.key);
    const activeCount = owner ? owner.activeRecords.length : 0;
    const buriedCount = owner ? owner.buriedRecords.length : 0;
    const recoveringCount = Object.values(CC.recoveringViews).filter(marker => marker && marker.ownerKey === character.key).length;
    const value = character.name + " active " + activeCount + ", buried " + buriedCount + ", recovering " + recoveringCount;
    return maintenanceStatusValue("views", character.key, !!viewsStore, value, character.name + " deferred until context");
  }

  function relationshipsStatus(character) {
    const owner = relationshipsForOwner(character.key);
    const records = owner ? owner.records.filter(record => !record.duplicate).length : 0;
    const pages = owner ? owner.pages.length : 0;
    const value = character.name + " " + records + " records / " + pages + " pages";
    return maintenanceStatusValue(
      "relationships",
      character.key,
      !!relationshipsStore,
      value,
      character.name + " deferred until context"
    );
  }

  function turningPointsStatus(character) {
    const owner = turningPointsForOwner(character.key);
    const records = owner ? owner.contextRecords : [];
    const stages = records.map(record => record.id + "=" + record.progress.score + " (" + record.progress.stage + ")");
    const value = character.name + " " + records.length + " active definition" + (records.length === 1 ? "" : "s")
      + (stages.length ? " [" + stages.join(", ") + "]" : "");
    if (turningPointsStore) {
      CC.maintenance.statusCache.turningPointIds[character.key] = records.map(record => record.id);
    }
    return maintenanceStatusValue(
      "turningpoints",
      character.key,
      !!turningPointsStore,
      value,
      character.name + " deferred until context"
    );
  }

  function namesStatus(identity) {
    const identityData = namesForIdentity(identity.key);
    const records = identityData ? identityData.records.filter(record => !record.duplicate && !record.conflict) : [];
    const counts = NAME_STATUSES.map(status => status + " " + records.filter(record => record.status === status).length)
      .join(", ");
    const value = identity.headerOwner + " " + records.length + " aliases (" + counts + ") / "
      + (identityData ? identityData.pages.length : 0) + " pages";
    return maintenanceStatusValue(
      "names",
      identity.key,
      !!namesStore,
      value,
      identity.headerOwner + " deferred until context"
    );
  }

  function experiencesStatus(character) {
    const owner = experiencesForOwner(character.key);
    const records = owner ? owner.records.filter(record => !record.duplicate).length : 0;
    const pages = owner ? owner.pages.length : 0;
    const safe = owner ? owner.contextRecords.length : 0;
    const value = character.name + " " + records + " records, " + pages + " pages, " + safe + " context-safe";
    return maintenanceStatusValue(
      "experiences",
      character.key,
      !!experiencesStore,
      value,
      character.name + " deferred until context"
    );
  }

  function pendingEvidenceStatus(character) {
    const recent = CC.currentPlan && typeof CC.currentPlan.recentStory === "string"
      ? CC.currentPlan.recentStory
      : recentStoryFromContext(originalText);
    const available = CC.evidence.filter(item => {
      if (!openingEvidenceEligible(item, recent)) return false;
      const statePending = !item.usedStateBy[character.key] && CC.stateClock - item.stateClock < runtime.stateLifetime;
      const viewPending = viewEvidenceAge(item, character) < settings.VIEW_EVIDENCE_OPPORTUNITIES;
      const relationshipTargets = ["player"].concat(characters
        .filter(target => target.key !== character.key)
        .map(target => "npc:" + target.key));
      const relationshipUses = item.usedRelationshipsBy[character.key] || {};
      const relationshipPending = viewEvidenceAge(item, character) < settings.RELATIONSHIP_EVIDENCE_OPPORTUNITIES
        && relationshipTargets.some(targetKey => !relationshipUses[targetKey]);
      const turningUses = item.usedTurningPointsBy[character.key] || {};
      const turningOwner = turningPointsForOwner(character.key);
      const cachedTurningIds = Array.isArray(CC.maintenance.statusCache.turningPointIds[character.key])
        ? CC.maintenance.statusCache.turningPointIds[character.key]
        : [];
      const turningIds = turningOwner
        ? turningOwner.contextRecords.map(record => record.id)
        : cachedTurningIds;
      const turningPending = viewEvidenceAge(item, character) < settings.TURNING_POINT_EVIDENCE_OPPORTUNITIES
        && turningIds.some(id => !turningUses[id]);
      const namePending = viewEvidenceAge(item, character) < settings.NAME_EVIDENCE_OPPORTUNITIES;
      return statePending || viewPending || relationshipPending || turningPending || namePending;
    });
    const unreviewed = available.filter(item => !(item.assessedNoChangeBy
      && item.assessedNoChangeBy[character.key]));
    const oldest = available.length ? Math.max(...available.map(item => viewEvidenceAge(item, character))) : 0;
    return character.name + " " + available.length + " available, " + unreviewed.length
      + " unreviewed, oldest durable age " + oldest + "/"
      + Math.max(settings.VIEW_EVIDENCE_OPPORTUNITIES, settings.RELATIONSHIP_EVIDENCE_OPPORTUNITIES,
        settings.TURNING_POINT_EVIDENCE_OPPORTUNITIES, settings.NAME_EVIDENCE_OPPORTUNITIES);
  }


  function derivedRelationshipSources(plan) {
    const source = plan && typeof plan === "object" && !Array.isArray(plan) ? plan : {};
    return (Array.isArray(source.sourcePacket) ? source.sourcePacket : []).filter(item => {
      const id = continuitySourceId(item && item.id);
      return !!(id && /^[SX]/.test(id) && item.relationship === true);
    });
  }

  function derivedRelationshipSourceSummary(plan) {
    const derived = derivedRelationshipSources(plan);
    if (!derived.length) return "None";
    return derived.map(source => source.id + "["
      + ((source.allowedFields || []).join("/") || "no fields")
      + "; gain " + Math.max(0, Number(source.gain) || 0) + "]").join(", ");
  }

  function derivedRelationshipSourcesSupplied(plan) {
    return derivedRelationshipSources(plan).length > 0;
  }

  function derivedViewSources(plan) {
    const source = plan && typeof plan === "object" && !Array.isArray(plan) ? plan : {};
    return (Array.isArray(source.sourcePacket) ? source.sourcePacket : []).filter(item => {
      const id = continuitySourceId(item && item.id);
      return !!(id && ["R", "X"].includes(id.charAt(0)) && item.view === true);
    });
  }

  function derivedViewSourceSummary(plan) {
    const derived = derivedViewSources(plan);
    if (!derived.length) return "None";
    return derived.map(source => source.id + "[gain " + Math.max(0, Number(source.gain) || 0)
      + "; target " + (source.targetKey || "None")
      + "; eligible destinations " + ((source.allowedDestinations || []).join("/") || "None")
      + "; eligible modes " + ((source.allowedModes || []).join("/") || "None") + "]").join(", ");
  }

  function derivedViewSourcesSupplied(plan) {
    return derivedViewSources(plan).length > 0;
  }

  function provenanceStatusSnapshot(validate = true) {
    if (validate) refreshProvenanceActivity();
    const counts = Object.create(null);
    Object.keys(PROVENANCE_KINDS).forEach(prefix => {
      const records = CC.provenance.records.filter(record => record.id.charAt(0) === prefix);
      counts[prefix] = {
        total: records.length,
        active: records.filter(record => record.active).length
      };
    });
    const latest = CC.provenance.records.length
      ? CC.provenance.records[CC.provenance.records.length - 1]
      : null;
    const parsedUses = CC.provenance.records.flatMap(record =>
      provenanceUseSignatures(record.uses).map(parseProvenanceUseSignature).filter(Boolean)
    );
    const relationshipUses = new Set(parsedUses
      .filter(use => use.kind === "relationship").map(use => use.signature)).size;
    const viewUses = new Set(parsedUses
      .filter(use => use.kind === "view").map(use => use.signature)).size;
    return { counts, latest, relationshipUses, viewUses };
  }

  function provenanceDebugRows() {
    const snapshot = provenanceStatusSnapshot();
    const rows = [
      "Provenance creation: " + (CC.last.provenanceCreated || "None"),
      "Provenance counts: " + Object.keys(PROVENANCE_KINDS).map(prefix => prefix + "="
        + snapshot.counts[prefix].active + " active/" + snapshot.counts[prefix].total + " total").join(", "),
      "Derived Relationship sources supplied: " + derivedRelationshipSourceSummary(CC.currentPlan),
      "Derived View sources supplied: " + derivedViewSourceSummary(CC.currentPlan),
      "Relationship source diagnostics: " + ((CC.last.relationshipSourceDiagnostics || []).join("; ") || "None"),
      "Relationship use diagnostics: " + ((CC.last.relationshipUseDiagnostics || []).join("; ") || "None"),
      "Relationship narrow uses stored: " + snapshot.relationshipUses,
      "View source diagnostics: " + ((CC.last.viewSourceDiagnostics || []).join("; ") || "None"),
      "View use diagnostics: " + ((CC.last.viewUseDiagnostics || []).join("; ") || "None"),
      "View narrow uses stored: " + snapshot.viewUses,
      "Provenance transaction diagnostics: " + ((CC.last.provenanceDiagnostics || []).join("; ") || "None")
    ];
    derivedRelationshipSources(CC.currentPlan).forEach(source => {
      rows.push(source.id
        + " derived Relationship source"
        + " | owner " + (source.ownerKey || "None")
        + " | target " + (source.targetKey || "None")
        + " | fields " + ((source.allowedFields || []).join(",") || "None")
        + " | managed " + (source.managedSignature || "None")
        + " | raw lineage " + ((source.rawLineage || []).join(",") || "None")
        + " | gain " + Math.max(0, Number(source.gain) || 0)
        + " | authorisation A only"
        + " | uses " + (Object.keys(source.useSignatures || {}).map(field =>
          field + "=" + source.useSignatures[field]).join(",") || "None"));
    });
    derivedViewSources(CC.currentPlan).forEach(source => {
      rows.push(source.id
        + " derived View source"
        + " | owner " + (source.ownerKey || "None")
        + " | target " + (source.targetKey || "None")
        + " | destinations " + ((source.allowedDestinations || []).join(",") || "None")
        + " | modes " + ((source.allowedModes || []).join(",") || "None")
        + " | managed " + (source.managedSignature || "None")
        + " | raw lineage " + ((source.rawLineage || []).join(",") || "None")
        + " | gain " + Math.max(0, Number(source.gain) || 0)
        + " | routing fields limited by current managed-card mechanics"
        + " | uses " + (Object.keys(source.useSignatures || {}).map(interpretation =>
          interpretation + "=" + source.useSignatures[interpretation]).join(",") || "None"));
    });
    CC.provenance.records.slice(-12).reverse().forEach(record => {
      let detail = record.id + " " + record.kind
        + " | active " + (record.active ? "yes" : "no")
        + " | owner " + (record.ownerKey || "None")
        + " | target " + (record.targetKey || "None")
        + " | confirmation " + (record.confirmation || 0)
        + " | sources " + (record.sourceIds.join(",") || "None")
        + " | raw lineage " + (storyLineageForSources(record.sourceIds).join(",") || "None")
        + " | managed " + (record.managedSignature || "None")
        + " | valid " + (managedSignatureStillValid(record) ? "yes" : "no")
        + " | uses " + (provenanceUseSignatures(record.uses).join(" ; ") || "None");
      if (record.kind === "relationship") {
        detail += " | event " + (record.eventKind || "None")
          + " | field " + (record.field || "None")
          + " | change " + record.actualChange
          + " | prior " + (record.priorValue || "None")
          + " | result " + (record.resultingValue || "None")
          + " | stage " + (record.resultingStage || "None")
          + " | pace " + record.paceValue;
      }
      if (record.kind === "view") {
        detail += " | mode " + (record.viewOperationMode || "None")
          + " | severity " + (record.viewSeverity || "None")
          + " | prior category " + (record.priorCategory || "None")
          + " | result category " + (record.resultingCategory || "None")
          + " | prior state " + (record.priorViewState || "None")
          + " | result state " + (record.resultingViewState || "None");
      }
      rows.push(detail);
    });
    return rows;
  }

  function selectedOperationStatus(plan) {
    const source = plan && typeof plan === "object" && !Array.isArray(plan) ? plan : {};
    if (source.operationSelectionFrozen !== true) return "Not scored";
    return operationKindLabel(source.selectedOperationKind) + " | gain "
      + Math.max(0, Number(source.selectedGain) || 0) + " | drain "
      + Math.max(0, Number(source.selectedDrain) || 0) + " | net "
      + (Number(source.selectedNet) || 0);
  }

  function pendingOperationRetryStatus() {
    const current = CC.currentPlan && CC.currentPlan.pendingOperationRetry === true
      ? CC.currentPlan
      : null;
    const stored = normalizePendingOperationRetry(CC.pendingOperationRetry);
    const source = current || (stored.active ? stored.plan : null);
    if (!source) return "None";
    const ownerKey = normalizedTargetKey(source.ownerKey || source.retryFocusKey || stored.ownerKey);
    const owner = characters.find(character => character.key === ownerKey) || null;
    const kind = operationKindLabel(source.selectedOperationKind);
    const evidenceIds = unique(
      Array.isArray(source.evidenceIds) && source.evidenceIds.length
        ? source.evidenceIds
        : source.retryEvidenceIds,
      40
    );
    const state = current
      ? (source.taskDelivered ? "delivered this pass" : "queued; deferred this pass")
      : "queued";
    const sourceInput = Math.max(0, Math.floor(Number(
      source.pendingRetrySourceInputCount || stored.sourceInputCount
    ) || 0));
    const sourceAction = Number.isFinite(Number(source.pendingRetrySourceActionCount))
      ? Math.max(0, Math.floor(Number(source.pendingRetrySourceActionCount)))
      : stored.sourceActionCount;
    const sourceKind = line(source.pendingRetrySourceKind || stored.sourceKind, 40);
    return state + " | " + kind + " for " + (owner ? owner.name : ownerKey || "Unknown")
      + " | evidence " + (evidenceIds.join(",") || "None")
      + (sourceAction >= 0 ? " | source action " + sourceAction : "")
      + (sourceKind ? " (" + sourceKind + ")" : "")
      + (sourceAction < 0 ? " | source input " + (sourceInput || "Unknown") : "");
  }

  function currentPassStatus() {
    const plan = CC.currentPlan && typeof CC.currentPlan === "object" ? CC.currentPlan : {};
    if (hook === "input") return plan.retry ? "Retry action — awaiting context" : "Player action — awaiting context";
    if (hook === "output") {
      return plan.taskDelivered
        ? (plan.semanticAssessment === true
          ? "Output — action assessment resolution"
          : "Output — action operation resolution")
        : "Output — story only; no assessment task was delivered";
    }
    if (hook === "context" || hook === "contextAppend") {
      if (plan.kind === "preview") return "Context preview — action count unchanged; no assessment opportunity";
      if (plan.retry) return "Retry context — supplied assessment opportunity reused";
      if (plan.opening) return "Opening context — no assessment opportunity";
      return "Action context — semantic assessment opportunity";
    }
    return hook + " — no assessment opportunity";
  }

  function recordedCandidateStatus(candidate) {
    const source = recordedOperationCandidate(candidate);
    if (!source) return "None";
    const specificity = [source.targetKey, source.field, source.destination].filter(Boolean).join(" → ");
    return (specificity || "unspecified target")
      + " | sources " + (source.sourceIds.join(",") || "None")
      + " | signature " + (source.evidenceSignature || "None");
  }

  function lastGenuineTaskStatus() {
    const record = normalizeLastGenuineOperation(CC.lastGenuineOperation);
    if (record.actionCount < 0 && !record.inputCount) return "None";
    const actionLabel = record.actionCount >= 0
      ? "action " + record.actionCount
      : "player input " + record.inputCount;
    if (!record.taskDelivered) {
      return "none for " + actionLabel
        + (record.deferredReason ? " — " + record.deferredReason : "");
    }
    return operationKindLabel(record.operationKind) + " for " + (record.ownerName || record.ownerKey || "Unknown")
      + " | " + actionLabel
      + " | evidence " + (record.evidenceIds.join(",") || "None")
      + " | owner opportunity " + (record.ownerOpportunity || "None");
