      "Last Turning Point / change: " + (CC.last.lastTurningPoint || "None") + " / " + (CC.last.turningPointChange || "None")
    ];
    const repeatedPriorityLabels = [
      "Error:", "CCO parse:", "Current pass:", "Current task / owner:", "Current candidate / update:",
      "Current operation outcome / drain:", "Last action task:", "Last action resolution:",
      "Last Name:", "Last Relationship / change:", "Last Turning Point / change:"
    ];
    return writeDebugPages(priorityDebugRows.concat(debugRows.filter(row =>
      !repeatedPriorityLabels.some(label => textOf(row).startsWith(label))
    )));
  }

  // The platform supplies no safety net: an uncaught throw in any hook breaks the
  // player's turn outright. Every branch below degrades to passing the platform's
  // own text through untouched, which is always a valid result for every hook --
  // for contextAppend it is trivially append-only, so the cache contract holds.
  function hookFailure(error) {
    const detail = textOf(error && error.message ? error.message : error);
    try {
      CC.last.error = "The " + hook + " hook failed and its continuity work was withheld: "
        + line(detail, 300);
      writeStatusCard();
    } catch (ignored) {
      // State may be too damaged to report through; passing the text through still matters.
    }
    return finish(originalText);
  }

  if (hook === "input") {
    try {
      clearOwnedFrontMemoryState();
      beginInput(originalText);
      writeAllStateCards();
      writeStatusCard();
    } catch (error) {
      return hookFailure(error);
    }
    return finish(originalText);
  }

  if (hook === "context" || hook === "contextAppend") {
    let result;
    try {
      result = buildContext();
      if (appendOnlyContext && !textOf(result).startsWith(textOf(originalText))
        && !frontMemoryContextVerified) {
        CC.last.context = "Cache-compatible append guard preserved the original platform context.";
        CC.last.error = "The context result was not append-only, so its continuity addition was withheld.";
        result = originalText;
      }
      writeAllStateCards();
      writeStatusCard();
    } catch (error) {
      return hookFailure(error);
    }
    return finish(result);
  }

  if (hook === "output") {
    let result;
    try {
      clearOwnedFrontMemoryState();
      result = processOutput(originalText);
      writeAllStateCards();
      writeStatusCard();
    } catch (error) {
      return hookFailure(error);
    }
    return finish(result);
  }

  try {
    writeStatusCard();
  } catch (error) {
    return hookFailure(error);
  }
  return finish(originalText);
}

  function run(tab) {
    const currentText = MCPV5SafeText(globalThis.text, "\u200B");
    if (tab === "input") {
      return { text: CharacterContinuity("input", currentText) };
    }
    if (tab === "context") {
      // CC v2.02 supplies an append-only cache-compatible hook with owned
      // Front Memory handling. Use it when MMS is composing Context proposals;
      // standalone/Legacy Exact retains CC's ordinary context hook.
      const hookName = (
        MCPV5_ACTIVE_PLAN &&
        MCPV5_ACTIVE_PLAN.cooperative
      ) ? "contextAppend" : "context";
      return { text: CharacterContinuity(hookName, currentText) };
    }
    if (tab === "output") {
      return { text: CharacterContinuity("output", currentText) };
    }
    return { text: currentText };
  }

  return { run };
}

function MCPV5Create_living_meters() {
  // Dynamic read-through view: in cooperative Context mode, prevent the
  // original module from trimming AI Dungeon's base context itself. The host
  // budgets only the module's added directive afterward.
  const info = new Proxy(Object.create(null), {
    get(_target, property) {
      const engineInfo = globalThis.info && typeof globalThis.info === "object"
        ? globalThis.info
        : {};
      if (
        property === "maxChars" &&
        MCPV5_ACTIVE_PLAN &&
        MCPV5_ACTIVE_PLAN.cooperative
      ) {
        const nativeMax = Number(engineInfo.maxChars) || 0;
        const baseLength = String(globalThis.text || "").length;
        return Math.max(nativeMax, baseLength + 20000);
      }
      return engineInfo[property];
    }
  });

