/* ============================================================================
 * 2. FRAMEWORK — you should not need to edit below this line.
 * ==========================================================================*/

const RM = (function () {
  const VERSION = 1;
  const SENTINEL = "%RM%";          // story card key that will never trigger
  const BUILD_MARK = "%RM_NEW%";    // temporary title used to find a new card
  const DIFFICULTY = { easy: 0.5, normal: 1, hard: 1.75 };

  // ---- small utilities ----------------------------------------------------

  function isNum(n) {
    return typeof n === "number" && Number.isFinite(n);
  }

  function clamp(v, lo, hi) {
    if (!isNum(v)) return lo;
    return v < lo ? lo : v > hi ? hi : v;
  }

  function round2(v) {
    return Math.round(v * 100) / 100;
  }

  function hash32(s) {
    // FNV-1a. Cheap, good enough to tell "same output as last turn" apart.
    let h = 2166136261;
    for (let i = 0; i < s.length; i++) {
      h ^= s.charCodeAt(i);
      h = (h + ((h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24))) >>> 0;
    }
    return h >>> 0;
  }

  function dbg() {
    if (!RM_CONFIG.debug) return;
    try {
      log("[Living Meters] " + Array.from(arguments).map((a) =>
        typeof a === "string" ? a : JSON.stringify(a)).join(" "));
    } catch (e) { /* logging must never break a turn */ }
  }

  // ---- trigger compilation -----------------------------------------------

  // Config problems are collected here and reported to the creator rather than
  // silently swallowed — a trigger that never fires is very hard to notice.
  const PROBLEMS = [];

  function escapeRe(s) {
    return String(s).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  }

  // "loot"  → loot          (whole word only)
  // "loot*" → loot\w*       (word endings count)
  function wordToAlt(w) {
    const raw = String(w).trim();
    if (!raw) return null;
    if (raw.endsWith("*")) {
      const stem = raw.slice(0, -1).trim();
      return stem ? escapeRe(stem) + "\\w*" : null;
    }
    return escapeRe(raw);
  }

  // A trigger word inside a negated clause should not fire. Without this every
  // preset pays out for declining: "you do not eat" fed the character and "you
  // don't drink" watered them, because the pattern only asks whether the
  // word is present anywhere.
  //
  // Bare "no" and "none" are deliberately absent. They negate as often as not,
  // but they also appear in "no choice but to eat", where suppressing would be
  // wrong, and that phrasing is common in the survival prose these presets are
  // written for.
  const NEGATORS = /\bnot\b|n['’]t\b|\bnever\b|\bcannot\b|\brefus\w*|\bdeclin\w*|\bavoid\w*|\bwithout\b|\binstead of\b|\brather than\b|\bunable to\b|\bfail\w* to\b|\bdecid\w* against\b/i;

  // A cap for a very long sentence; the clause bound below usually bites first.
  const NEG_WINDOW = 80;

  function negated(src, at) {
    let clause = src.slice(Math.max(0, at - NEG_WINDOW), at);
    // Keep only what follows the last clause break, so "It was not a good day.
    // You eat." does not suppress the meal, and neither does "you do not eat the
    // berries, then you eat the fish".
    //
    // A comma counts as a break. That mis-reads a negated list, "you do not eat,
    // drink, or rest", where the later items should stay suppressed. It is still
    // the better default: getting a comma wrong means firing, which is exactly
    // what this framework did before the guard existed, while leaving the comma
    // out means silently withholding a payout the player earned. Prefer the
    // error that matches the old behaviour.
    const cut = clause.search(/[.!?;:,\n][^.!?;:,\n]*$/);
    if (cut !== -1) clause = clause.slice(cut + 1);
    return NEGATORS.test(clause);
  }

  // True if the word appears at least once OUTSIDE a negated clause. Every
  // occurrence is examined, so "you do not eat the berries, then you eat the
  // fish" still counts as eating.
  function fires(re, src) {
    re.lastIndex = 0;
    let m;
    while ((m = re.exec(src)) !== null) {
      if (m[0].length === 0) { re.lastIndex++; continue; }
      if (!RM_CONFIG.negationGuard || !negated(src, m.index)) return true;
    }
    return false;
  }

  // Turns a creator's trigger into { on, re, delta }, or records why it can't.
  function compileTrigger(resId, t, index) {
    const where = `${resId} trigger #${index + 1}`;

    if (!t || typeof t !== "object") {
      PROBLEMS.push(`${where}: not an object.`);
      return null;
    }
    if (!isNum(t.delta) || t.delta === 0) {
      PROBLEMS.push(`${where}: needs a non-zero numeric "delta".`);
      return null;
    }

    const on = t.on === "input" || t.on === "output" ? t.on : "both";

    // Escape hatch for authors who genuinely want their own pattern.
    if (t.match !== undefined) {
      if (!(t.match instanceof RegExp)) {
        PROBLEMS.push(
          `${where}: "match" must be a regular expression like /word/i, not a string. ` +
          `Use words: ["word"] instead.`
        );
        return null;
      }
      // Re-flagged with "g" so fires() can walk it. The author's own source
      // and case sensitivity are preserved.
      const gflags = t.match.flags.indexOf("g") === -1 ? t.match.flags + "g" : t.match.flags;
      return {
        on: on, re: new RegExp(t.match.source, gflags),
        delta: t.delta, words: ["(custom pattern)"],
      };
    }

    if (!Array.isArray(t.words) || !t.words.length) {
      PROBLEMS.push(`${where}: needs words: ["some", "word*"].`);
      return null;
    }

    const alts = [];
    for (const w of t.words) {
      const a = wordToAlt(w);
      if (a) alts.push(a);
      else PROBLEMS.push(`${where}: ignored an empty entry in "words".`);
    }
    if (!alts.length) {
      PROBLEMS.push(`${where}: no usable words.`);
      return null;
    }

    // Boundaries on both sides, so "rest" fires on "you rest" but not on
    // "restaurant" or "arrest". \b is not used because it needs a word
    // character to sit against, which breaks entries like "c++" or "o2!".
    // The leading alternative consumes a character, which shifts the reported
    // index back by one; harmless, because the guard reads the clause before it.
    try {
      return {
        on: on,
        // "g" so fires() can walk every occurrence, not only the first.
        re: new RegExp("(?:^|\\W)(?:" + alts.join("|") + ")(?!\\w)", "gi"),
        delta: t.delta,
        words: t.words.slice(),   // kept for introspection and testing
      };
    } catch (err) {
      PROBLEMS.push(`${where}: could not build a pattern from those words.`);
      return null;
    }
  }

  // ---- resource definitions ----------------------------------------------

  // Merge RM_CONFIG.resources over the chosen preset, matched by id.
  function buildDefs() {
    const preset = RM_PRESETS[RM_CONFIG.preset] || RM_PRESETS.none;
    const byId = new Map();

    for (const r of preset) byId.set(r.id, Object.assign({}, r));
    for (const r of RM_CONFIG.resources || []) {
      if (!r || typeof r.id !== "string") continue;
      byId.set(r.id, Object.assign({}, byId.get(r.id) || {}, r));
    }

    const out = [];
    for (const r of byId.values()) {
      if (typeof r.id !== "string") continue;

      const min = isNum(r.min) ? r.min : 0;
      const max = isNum(r.max) ? r.max : 100;
      if (max <= min) PROBLEMS.push(`${r.id}: max (${max}) must be greater than min (${min}).`);

      const triggers = [];
      const rawTriggers = Array.isArray(r.triggers) ? r.triggers : [];
      for (let i = 0; i < rawTriggers.length; i++) {
        const c = compileTrigger(r.id, rawTriggers[i], i);
        if (c) triggers.push(c);
      }

      out.push({
        id: r.id,
        label: typeof r.label === "string" ? r.label : r.id,
        icon: typeof r.icon === "string" ? r.icon : "",
        min: min,
        max: max,
        start: isNum(r.start) ? r.start : max,
        perTurn: isNum(r.perTurn) ? r.perTurn : 0,
        visible: r.visible !== false,
        enabled: r.enabled !== false,
        bands: Array.isArray(r.bands) ? r.bands.slice() : [],
        triggers: triggers,
      });
    }
    return out;
  }

  // Definitions live in the Library, never in state — state is JSON-serialized
  // between turns and would silently drop the regexes.
  let DEFS = null;
  function defs() {
    if (!DEFS) DEFS = buildDefs();
    return DEFS;
  }
  function def(id) {
    return defs().find((d) => d.id === id) || null;
  }

  function bandOf(d, value) {
    // First band whose `upTo` is >= the value wins. Bands are read low→high.
    const sorted = d.bands.slice().sort((a, b) => (a.upTo ?? 0) - (b.upTo ?? 0));
    for (const b of sorted) if (value <= (b.upTo ?? 0)) return b;
    return sorted.length ? sorted[sorted.length - 1] : { name: "", tell: "" };
  }

  // ---- state --------------------------------------------------------------

  function freshState() {
    const res = {};
    for (const d of defs()) res[d.id] = clamp(d.start, d.min, d.max);
    return {
      v: VERSION,
      res: res,
      band: {},        // id -> last announced band name
      turn: 0,         // our own turn counter, not info.actionCount
      // How much of history has been read for turn counting. It starts at the
      // current length, never at zero: an adventure can already have a long
      // history behind it when this script is first enabled, and that past is
      // not drift this run owes.
      hlen: Array.isArray(history) ? history.length : 0,
      hac: Number.isInteger(info?.actionCount) ? Math.abs(info.actionCount) : 0,
      owed: 0,         // generations charged before their AI action landed
      inflight: false, // this generation has already been charged for
      outHash: 0,      // hash of the last output we scanned
      cardOK: true,    // false once we detect story cards are unavailable
      warned: false,
      reply: "",          // a command answer waiting to leave as the output
      replyGen: 0,        // generations it has waited; more than one is late
      cmdTurn: false,     // this generation answers a command, so it will not tick
      pend: [],           // notices waiting for the next command answer
      answerHistory: [],  // exact delivered command answers, capped
      commandHistory: [], // exact LM commands whose story echoes may be scrubbed
      cfgWarned: false,   // config problems have been noticed once
      fired: {},          // trigger keys already counted this turn
      over: {},        // player overrides parsed from the story card
      overWarn: "",    // unknown card keys we have already flagged
    };
  }

  // Validate every field. A script upgrade mid-adventure must not corrupt a run.
  function hydrate() {
    const raw = state.RM;
    if (!raw || typeof raw !== "object" || raw.v !== VERSION) {
      dbg("initialising state");
      return freshState();
    }
    const s = freshState();
    if (raw.res && typeof raw.res === "object") {
      for (const d of defs()) {
        if (isNum(raw.res[d.id])) s.res[d.id] = clamp(raw.res[d.id], d.min, d.max);
      }
    }
    if (raw.band && typeof raw.band === "object") s.band = raw.band;
    if (isNum(raw.turn)) s.turn = raw.turn;
    if (isNum(raw.hlen)) s.hlen = raw.hlen;
    if (isNum(raw.hac)) s.hac = raw.hac;
    if (isNum(raw.owed)) s.owed = clamp(raw.owed, 0, 1);
    if (typeof raw.inflight === "boolean") s.inflight = raw.inflight;
    if (isNum(raw.outHash)) s.outHash = raw.outHash;
    if (typeof raw.cardOK === "boolean") s.cardOK = raw.cardOK;
    if (typeof raw.warned === "boolean") s.warned = raw.warned;
    if (typeof raw.reply === "string") s.reply = raw.reply;
    if (isNum(raw.replyGen)) s.replyGen = raw.replyGen;
    if (typeof raw.cmdTurn === "boolean") s.cmdTurn = raw.cmdTurn;
    if (Array.isArray(raw.pend)) {
      s.pend = raw.pend.filter((n) => typeof n === "string").slice(-PEND_MAX);
    }
    if (Array.isArray(raw.answerHistory)) {
      s.answerHistory = raw.answerHistory
        .filter((n) => typeof n === "string" && n.trim())
        .map((n) => n.replace(/\r/g, "").trim().slice(0, 6000))
        .slice(-8);
    }
    if (Array.isArray(raw.commandHistory)) {
      s.commandHistory = raw.commandHistory
        .filter((n) => typeof n === "string" && n.trim())
        .map((n) => n.trim().slice(0, 300))
        .slice(-12);
    }
    if (typeof raw.cfgWarned === "boolean") s.cfgWarned = raw.cfgWarned;
    if (raw.fired && typeof raw.fired === "object") s.fired = raw.fired;
    if (raw.over && typeof raw.over === "object") s.over = raw.over;
    if (typeof raw.overWarn === "string") s.overWarn = raw.overWarn;
    return s;
  }

  function persist(s) {
    state.RM = s;
  }

  // ---- player overrides, read from the story card -------------------------

  // The card's NOTES field is never shown to the AI, which makes it the right
  // place for machine-readable settings the player can edit.
  //
  //   difficulty = hard
  //   show = off
  //   hunger.perTurn = -3
  //   thirst.off
  //
  function parseOverrides(src) {
    const over = {};
    if (typeof src !== "string" || !src) return over;

    for (let line of src.split("\n")) {
      line = line.split("#")[0].trim();
      if (!line) continue;

      // "<id>.off" / "<id>.on"
      const toggle = line.match(/^([A-Za-z0-9_]+)\.(off|on)$/i);
      if (toggle) {
        over[toggle[1] + ".enabled"] = toggle[2].toLowerCase() === "on";
        continue;
      }

      const kv = line.match(/^([A-Za-z0-9_.]+)\s*[=:]\s*(.+)$/);
      if (!kv) continue;
      const key = kv[1].trim();
      const rawVal = kv[2].trim();
      const num = Number(rawVal);

      if (/^(on|true|yes)$/i.test(rawVal)) over[key] = true;
      else if (/^(off|false|no)$/i.test(rawVal)) over[key] = false;
      else if (Number.isFinite(num) && rawVal !== "") over[key] = num;
      else over[key] = rawVal;
    }
    return over;
  }

  // Every key the card can actually set. parseOverrides accepts any
  // "key = value" line, so without this a typo is stored forever and silently
  // ignored. That is how a player ends up convinced the card does nothing.
  const OVER_GLOBALS = ["difficulty"];
  const OVER_FIELDS = ["min", "max", "start", "perTurn", "visible", "enabled"];

  function isOverrideKey(key) {
    if (OVER_GLOBALS.indexOf(key) !== -1) return true;
    const dot = key.lastIndexOf(".");
    if (dot === -1) return false;
    return defs().some((d) => d.id === key.slice(0, dot))
      && OVER_FIELDS.indexOf(key.slice(dot + 1)) !== -1;
  }

  function checkOverrides(s) {
    const bad = [];
    for (const key of Object.keys(s.over)) {
      if (isOverrideKey(key)) continue;
      bad.push(key);
    }
    // Keyed on the exact set, so fixing the card stops the warning and a new
    // mistake raises a fresh one.
    const sig = bad.join(",");
    if (sig === s.overWarn) return;
    s.overWarn = sig;
    if (!bad.length) return;
    notice(s, "Living Meters card: " + bad.map((k) => '"' + k + '"').join(", ") +
      (bad.length > 1 ? " are not settings." : " is not a setting.") +
      " See the notes at the top of the card.");
  }

  function optNum(s, key, fallback) {
    const v = s.over[key];
    return isNum(v) ? v : fallback;
  }
  function optBool(s, key, fallback) {
    const v = s.over[key];
    return typeof v === "boolean" ? v : fallback;
  }

  // Effective definition for a resource, after player overrides.
  function eff(s, d) {
    return {
      id: d.id,
      label: d.label,
      icon: d.icon,
      min: optNum(s, d.id + ".min", d.min),
      max: optNum(s, d.id + ".max", d.max),
      start: optNum(s, d.id + ".start", d.start),
      perTurn: optNum(s, d.id + ".perTurn", d.perTurn),
      visible: optBool(s, d.id + ".visible", d.visible),
      enabled: optBool(s, d.id + ".enabled", d.enabled),
      bands: d.bands,
      triggers: d.triggers,
    };
  }

  function activeDefs(s) {
    return defs().map((d) => eff(s, d)).filter((d) => d.enabled);
  }

  function difficultyMul(s) {
    const key = String(s.over.difficulty || RM_CONFIG.difficulty || "normal").toLowerCase();
    return DIFFICULTY[key] ?? 1;
  }

  // ---- mutation -----------------------------------------------------------

  function setVal(s, id, value) {
    const d = def(id);
    if (!d) return null;
    const e = eff(s, d);
    const before = s.res[id] ?? e.min;
    s.res[id] = round2(clamp(value, e.min, e.max));
    return { id: id, before: before, after: s.res[id], def: e };
  }

  function addVal(s, id, delta, opts) {
    const d = def(id);
    if (!d || !isNum(delta) || delta === 0) return null;
    const e = eff(s, d);
    let amount = delta;
    // Difficulty scales losses only — a hard run drains faster but does not
    // hand out bigger rewards.
    if (amount < 0 && !(opts && opts.raw)) amount *= difficultyMul(s);
    return setVal(s, id, (s.res[id] ?? e.start ?? e.min) + amount);
  }

  // ---- turn detection -----------------------------------------------------

  // There is no "the turn advanced" API, and info.actionCount is not a clean
  // counter: it moves twice on a Do/Say/Story turn, once on a Continue, and a
  // Retry can move it backwards, or negative.
  //
  // What history does say honestly is how MANY generations have passed, not
  // merely that one has: each generation appends exactly one AI action to it,
  // whatever the player did to provoke that generation. Counting those in the
  // stretch not yet read means a hook that is skipped for a generation, or for
  // ten, costs no drift, and it cannot double count, because the stretch is
  // consumed as it is read.
  //
  // This module may NOT assume any particular hook runs every generation. This
  // host hands the whole Context tab, and the whole Output tab, to a single
  // module whenever a transaction is active, and Story Arc generation, an
  // Auto-Cards model task and Inner Self thought formation are all ordinary
  // play. A Continue never runs Input either. Counting from history is what
  // makes the drift survive all of that.
  //
  // history excludes the in-flight action, so counting it alone would pay for
  // a generation only once the NEXT one starts. The generation being lived
  // through is therefore charged on credit, and settled when its AI action
  // finally shows up, so drift lands on the turn that earned it.
  const AI_ACTION = "continue";

  // A pathological jump (an adventure imported with a long history behind it,
  // every hook silent for a very long time) must not dump an hour of drift
  // into a single turn.
  const TICK_MAX = 20;

  function turnsPassed(s, hook) {
    const hl = Array.isArray(history) ? history.length : 0;
    const ac = Number.isInteger(info?.actionCount) ? Math.abs(info.actionCount) : 0;

    // Undone actions, or the front trimmed harder than the back grew: take the
    // new length as the anchor and count nothing this time.
    if (hl < s.hlen) { s.hlen = hl; s.hac = ac; return 0; }

    if (hl > s.hlen) {
      // Input runs because a player action is about to be appended, so being
      // there is itself proof a generation has begun. Elsewhere the proof is a
      // player action already sitting in the stretch being read.
      let started = hook === "input";
      let done = 0;
      for (let i = s.hlen; i < hl; i++) {
        const a = history[i];
        if (!a) continue;
        if (a.type === AI_ACTION) done++;
        else started = true;
      }
      s.hlen = hl;
      s.hac = ac;           // keep the fallback's baseline current

      // Generations already charged on credit are settled here, not charged a
      // second time.
      const settled = Math.min(done, s.owed);
      s.owed -= settled;
      if (settled > 0) s.inflight = false;
      let n = done - settled;

      // Nothing has been charged for the generation being lived through, so
      // charge it now and remember the debt. Without the `started` proof this
      // would also charge for hooks that run outside any generation, and the
      // real next turn would then find its drift already spent.
      if (started && !s.inflight) {
        s.inflight = true;
        s.owed += 1;
        // A command's own generation exists only to carry the answer back, and
        // asking a question should not cost the character a turn of hunger. It
        // is still claimed and still owed, so no later hook charges for it and
        // the settle stays balanced. It simply costs nothing.
        if (s.cmdTurn) s.cmdTurn = false;
        else n += 1;
      }
      return n;
    }

    // history has stopped growing, so it is being truncated and its tail no
    // longer says anything new. actionCount is what is left. Context and
    // Output see the settled value; Input sees the intermediate one and would
    // have Context count the same turn again, so Input stops here. Credit
    // cannot be settled against a history that is not growing, so the ledger
    // is closed while we are down here.
    if (hook === "input") return 0;
    if (ac > s.hac) { s.hac = ac; s.owed = 0; s.inflight = false; return 1; }
    return 0;
  }

  // ---- per-turn drift -----------------------------------------------------

  function tick(s, times) {
    const want = Math.floor(times) || 1;
    const n = Math.max(1, Math.min(TICK_MAX, want));
    if (want > TICK_MAX) dbg("drift catch-up capped at", TICK_MAX, "of", want);
    const changes = [];
    for (const e of activeDefs(s)) {
      if (!e.perTurn) continue;
      // One clamped move of n turns rather than n moves: the same result
      // against the bounds, and it stays cheap when there is ground to make up.
      const r = addVal(s, e.id, e.perTurn * n);
      if (r && r.before !== r.after) changes.push(r);
    }
    s.turn += n;
    return changes;
  }

  // Apply whatever drift is owed, from wherever we happen to be standing. Any
  // hook may call this: whichever one runs first for a generation does the
  // work, and the others find nothing owed and return.
  function catchUp(s, hook) {
    const n = turnsPassed(s, hook);
    if (n <= 0) return 0;
    tick(s, n);
    announce(s);
    return n;
  }

  // ---- triggers -----------------------------------------------------------

  // A trigger fires at most ONCE per turn, even when its word appears in both
  // the player's action and the AI's narration. "You weld the plate" followed
  // by "You weld it down" is one weld, not two. s.fired is reset at the start
  // of the Input hook and cleared again at the end of the Output hook, so it
  // spans exactly one turn and behaves correctly on Continue actions too.
  function scan(s, src, phase) {
    if (typeof src !== "string" || !src) return [];
    if (!s.fired || typeof s.fired !== "object") s.fired = {};
    const changes = [];
    for (const e of activeDefs(s)) {
      for (let i = 0; i < e.triggers.length; i++) {
        const t = e.triggers[i];
        // Patterns are compiled and validated once in buildDefs, so anything
        // reaching here is known-good.
        if (t.on !== "both" && t.on !== phase) continue;
        const key = e.id + "#" + i;
        if (s.fired[key]) continue;
        if (!fires(t.re, src)) continue;
        s.fired[key] = 1;
        const r = addVal(s, e.id, t.delta);
        if (r && r.before !== r.after) changes.push(r);
      }
    }
    return changes;
  }

  // ---- presentation -------------------------------------------------------

  function bar(value, min, max) {
    const span = max - min;
    if (span <= 0) return "";
    const filled = Math.round(((value - min) / span) * 10);
    return "█".repeat(clamp(filled, 0, 10)) + "░".repeat(10 - clamp(filled, 0, 10));
  }

  function statusLine(s) {
    const parts = [];
    for (const e of activeDefs(s)) {
      if (!e.visible) continue;
      const v = s.res[e.id];
      parts.push(`${e.icon}${e.icon ? " " : ""}${e.label} ${Math.round(v)}/${Math.round(e.max)}`);
    }
    return parts.join("  ·  ");
  }

  // A space that survives whitespace collapsing.
  const NB = "\u00a0";

  function statusBlock(s) {
    const rows = [];
    for (const e of activeDefs(s)) {
      if (!e.visible) continue;
      const v = s.res[e.id];
      const b = bandOf(e, v);
      // Padded with U+00A0, not spaces. The story card keeps whitespace, but
      // the answer also leaves as story output, and a run of ordinary spaces
      // does not survive every output filter a host may run over it.
      rows.push(
        `${e.icon || "•"} ${e.label.padEnd(10, NB)}${NB}${bar(v, e.min, e.max)}${NB}` +
        `${String(Math.round(v)).padStart(4, NB)}/${Math.round(e.max)}` +
        (b.name ? `${NB}${NB}(${b.name})` : "")
      );
    }
    return rows.join("\n");
  }

  // What the AI is told. Complete sentences only: an unterminated fragment in
  // frontMemory invites the model to finish it.
  function directive(s) {
    const stats = [];
    const tells = [];
    for (const e of activeDefs(s)) {
      const v = s.res[e.id];
      const b = bandOf(e, v);
      if (e.visible) {
        stats.push(`${e.label} ${Math.round(v)}/${Math.round(e.max)}${b.name ? ` (${b.name})` : ""}`);
      }
      if (b.tell) tells.push(b.tell);
    }
    if (!stats.length && !tells.length) return "";

    let out = `[${RM_CONFIG.injectLabel}: ${stats.join(", ")}.`;
    if (tells.length) out += " " + tells.join(" ");
    out += " Reflect this in the narration through behaviour and sensation;" +
           " never state the numbers themselves.]";
    return out;
  }

  // ---- notices ------------------------------------------------------------

  // Anything worth telling the player that is NOT an answer to a command: a
  // band crossing, an unrecognised card key, a config problem.
  //
  // These used to be toasts written to state.message. That is a single slot
  // shared by every script on the scenario, and sharing it cooperatively does
  // not work: whoever writes last wins, the loser's message is gone, and a
  // module that politely yields to a value it does not recognise can end up
  // mute for the rest of the adventure. So this module no longer writes that
  // slot at all. A notice waits in state until a command asks for it and
  // rides out with the answer. Nothing is pushed at the player unasked.
  const PEND_MAX = 12;

  // How many generations an undelivered answer may wait for an Output hook.
  const REPLY_MAX_GEN = 3;
  const ANSWER_HISTORY_MAX = 8;
  const COMMAND_HISTORY_MAX = 12;

  function rememberCommand(s, raw) {
    const command = stripPrefix(raw);
    if (!command) return;
    if (s.commandHistory[s.commandHistory.length - 1] !== command) {
      s.commandHistory.push(command.slice(0, 300));
      while (s.commandHistory.length > COMMAND_HISTORY_MAX) s.commandHistory.shift();
    }
  }

  function rememberAnswer(s, raw) {
    const answer = String(raw || "").replace(/\r/g, "").trim().slice(0, 6000);
    if (!answer) return;
    if (s.answerHistory[s.answerHistory.length - 1] !== answer) {
      s.answerHistory.push(answer);
      while (s.answerHistory.length > ANSWER_HISTORY_MAX) s.answerHistory.shift();
    }
  }

  function notice(s, msg) {
    if (!s || !msg) return;
    // Only an immediate repeat is collapsed. The buffer outlives the hook now,
    // so treating it as a set would drop a meter's SECOND crossing back into a
    // band it has been in before, and leave the digest reading as though it had
    // stayed where it was.
    if (s.pend[s.pend.length - 1] === msg) return;
    s.pend.push(msg);
    while (s.pend.length > PEND_MAX) s.pend.shift();
  }

  // Everything that has happened since the last answer, then the answer itself.
  function compose(s, reply) {
    const notes = s.pend.slice();
    s.pend = [];
    return notes.length ? notes.join("\n") + "\n\n" + reply : reply;
  }

  // ---- story card ---------------------------------------------------------

  const CARD_HEADER = [
    "# Living Meters settings. Edit the lines below, then close this card.",
    "# Lines starting with # are ignored. Delete a line to use the default.",
    "#",
    "# Or use the /set command, e.g.  /set difficulty hard",
    "#",
    "#   difficulty  = easy | normal | hard",
    "#   <resource>.perTurn = -2      how much it drifts each turn",
    "#   <resource>.max     = 120     raise or lower the ceiling",
    "#   <resource>.min     = 10      raise or lower the floor",
    "#   <resource>.start   = 60      the value /reset restores",
    "#   <resource>.visible = off     keep tracking it, stop showing it",
    "#   <resource>.off               stop tracking it entirely",
    "#   <resource>.on                track it again",
    "#",
  ].join("\n");

  function findCard() {
    if (!Array.isArray(storyCards)) return null;
    for (const c of storyCards) {
      if (c && c.title === RM_CONFIG.playerCardTitle) return c;
    }
    return null;
  }

  // addStoryCard returns the new LENGTH (the help site says "index" — it is
  // wrong, and has been for years), and cannot set the description field.
  // Creating a card with a sentinel title and then finding it by that title
  // gets us a real object reference to mutate.
  function createCard(s) {
    try {
      addStoryCard(SENTINEL, " ", "Custom", BUILD_MARK, " ");
    } catch (e) {
      s.cardOK = false;
      return null;
    }
    for (const c of storyCards) {
      if (c && c.title === BUILD_MARK) {
        c.title = RM_CONFIG.playerCardTitle;
        c.keys = SENTINEL;
        c.type = "Custom";
        c.entry = " ";
        c.description = CARD_HEADER + "\ndifficulty = " + (RM_CONFIG.difficulty || "normal") + "\n";
        return c;
      }
    }
    // Story card writes silently fail when the Memory Bank feature is off.
    s.cardOK = false;
    return null;
  }

  function syncCard(s) {
    if (!RM_CONFIG.playerCard || !s.cardOK) return;

    let card = findCard();
    if (!card) card = createCard(s);
    if (!card) {
      if (!s.warned) {
        s.warned = true;
        notice(s, "Living Meters: story cards are unavailable. Enable Gameplay > Memory System > Memory Bank.");
      }
      return;
    }

    // The player owns `description`; we only ever read it.
    s.over = parseOverrides(card.description);
    checkOverrides(s);

    // We own `entry`, and it never reaches the AI because `keys` never matches.
    const block = statusBlock(s);
    const next = `Current status (read-only, updates every turn)\n\n${block}\n`;
    if (card.entry !== next) card.entry = next;
  }

  // ---- writing a setting back to the card ---------------------------------

  // syncCard re-parses the card on every hook and replaces s.over, so a command
  // that only wrote state would be erased inside the same turn. The card stays
  // the single source of truth; /set edits it and the player can see the result.
  function writeSetting(src, key, value) {
    const text = typeof src === "string" ? src : "";
    const re = new RegExp("^\\s*" + escapeRe(key) + "\\s*[=:]", "i");
    const out = [];
    let done = false;
    for (const line of text.split("\n")) {
      if (line.trim().startsWith("#") || !re.test(line)) {
        out.push(line);
        continue;
      }
      if (done) continue;                  // collapse an existing duplicate
      out.push(key + " = " + value);
      done = true;
    }
    while (out.length && out[out.length - 1].trim() === "") out.pop();
    if (!done) out.push(key + " = " + value);
    return out.join("\n") + "\n";
  }

  // ---- commands -----------------------------------------------------------

  function stripPrefix(raw) {
    // Player input arrives pre-processed: "\n> You say \"/status\"\n" and so on.
    // In third person the name replaces "You", so match loosely.
    let t = String(raw || "");
    t = t.replace(/^\s*>\s*/, "");
    t = t.replace(/^[^\s]+\s+(?:say|says|said)[,:]?\s*/i, "");
    t = t.replace(/^["'“”]+|["'“”\s]+$/g, "");
    return t.trim();
  }

  function helpText() {
    const p = RM_CONFIG.commandPrefix;
    return [
      `${p}status        show all resources`,
      `${p}<id> +N       add to a resource   (e.g. ${p}hp +10)`,
      `${p}<id> -N       subtract from it`,
      `${p}<id> =N       set it exactly`,
      `${p}set <k> <v>   change a setting  (e.g. ${p}set difficulty hard)`,
      `${p}set           show what you have changed`,
      `${p}reset         restore starting values`,
      `${p}help          this list`,
    ].join("\n");
  }

  // Whether this input is a command, decided without running it. The drift has
  // to know before the answer is produced: it is settled at the top of Input,
  // and a command's own generation must not be charged for. Kept in step with
  // handleCommand's two early returns below.
  function looksLikeCommand(raw) {
    const p = RM_CONFIG.commandPrefix;
    const t = stripPrefix(raw);
    if (!t.startsWith(p)) return false;
    const body = t.slice(p.length).trim();
    if (!body) return false;
    const cmd = body.split(/\s+/)[0].toLowerCase();
    if (["help", "status", "set", "reset"].includes(cmd)) return true;
    return !!def(cmd);
  }

  // Returns a message string if the input was a command, else null.
  function handleCommand(s, raw) {
    const p = RM_CONFIG.commandPrefix;
    const t = stripPrefix(raw);
    if (!t.startsWith(p)) return null;

    const body = t.slice(p.length).trim();
    if (!body) return null;
    const parts = body.split(/\s+/);
    const cmd = parts[0].toLowerCase();

    if (cmd === "help") return helpText();
    if (cmd === "status") return statusBlock(s) || "No resources are being tracked.";

    if (cmd === "set") {
      const key = parts[1];
      const value = parts.slice(2).join(" ");
      if (!key) {
        const keys = Object.keys(s.over);
        return keys.length
          ? "Your settings:\n" + keys.map((k) => k + " = " + s.over[k]).join("\n")
          : `Nothing changed yet. Try ${p}set difficulty hard`;
      }
      if (!isOverrideKey(key)) {
        return `"${key}" is not a setting you can change. Try ` +
          `${p}set difficulty hard, or ${p}set <resource>.perTurn -2. ` +
          `${p}help lists the rest.`;
      }
      if (!value) return `Usage: ${p}set ${key} <value>`;

      const card = findCard();
      if (!card) {
        return "The settings card is not available. Turn on Gameplay > Memory System > Memory Bank.";
      }
      card.description = writeSetting(card.description, key, value);
      s.over = parseOverrides(card.description);
      s.overWarn = "";                     // a new key may need flagging again
      return `${key} = ${value}`;
    }

    if (cmd === "reset") {
      // eff() rather than the raw definition, so a start set in the card
      // is what /reset restores.
      for (const d of defs()) setVal(s, d.id, eff(s, d).start);
      s.band = {};
      return "Meters reset.\n\n" + statusBlock(s);
    }

    // "<id> +10" / "<id> -5" / "<id> =80" / "<id>" to query one
    const d = def(cmd);
    if (d) {
      const arg = parts[1];
      if (!arg) {
        const e = eff(s, d);
        return `${e.label}: ${Math.round(s.res[d.id])}/${Math.round(e.max)} (${bandOf(e, s.res[d.id]).name || "-"})`;
      }
      const m = arg.match(/^([+\-=])?(\d+(?:\.\d+)?)$/);
      if (!m) return `Could not read "${arg}". Try ${p}${cmd} +10`;
      const n = Number(m[2]);
      const r = m[1] === "=" ? setVal(s, d.id, n)
              : m[1] === "-" ? addVal(s, d.id, -n, { raw: true })
              : addVal(s, d.id, n, { raw: true });
      if (!r) return "No change.";
      const e = eff(s, d);
      return `${e.label}: ${Math.round(r.before)} → ${Math.round(r.after)}/${Math.round(e.max)}`;
    }

    // MMS compatibility: do not consume slash commands owned by another
    // module. Unknown Living Meters commands therefore fall through unchanged.
    return null;
  }

  // ---- band-change announcements -----------------------------------------

  function announce(s) {
    if (!RM_CONFIG.announceBandChanges) return;
    const crossed = [];
    for (const e of activeDefs(s)) {
      const b = bandOf(e, s.res[e.id]);
      const name = b.name || "";
      if (s.band[e.id] !== name) {
        if (s.band[e.id] !== undefined && name) {
          crossed.push(`${e.icon || ""}${e.icon ? " " : ""}${e.label}: ${name}`);
        }
        s.band[e.id] = name;
      }
    }
    if (crossed.length) notice(s, crossed.join("\n"));
  }

  // ---- config problem reporting ------------------------------------------

  // A misconfigured trigger is invisible otherwise: it simply never fires.
  // Say so, once, rather than letting the creator wonder.
  function reportProblems(s) {
    defs();                       // force compilation so PROBLEMS is populated
    if (!PROBLEMS.length) return;
    for (const p of PROBLEMS) dbg("config:", p);
    if (s.cfgWarned && !RM_CONFIG.debug) return;
    s.cfgWarned = true;
    const shown = PROBLEMS.slice(0, 4);
    notice(s, "Living Meters, check your config:\n• " + shown.join("\n• ") +
      (PROBLEMS.length > shown.length ? `\n• …and ${PROBLEMS.length - shown.length} more` : ""));
  }

  // ---- keeping our own answers out of the AI's context --------------------

  // MMS keeps a capped ledger of the exact command answers it actually
  // delivered. Only those exact blocks, plus exact LM command echoes, are
  // removed from Recent Story. This avoids treating ordinary prose beginning
  // with a resource label (for example "Hull: ...") as machine output.
  function exactTrimmedLines(value) {
    return String(value || "")
      .replace(/\r/g, "")
      .split("\n")
      .map((line) => line.trim());
  }

  function removeExactAnswerBlocks(lines, block) {
    const wanted = exactTrimmedLines(block);
    while (wanted.length && !wanted[0]) wanted.shift();
    while (wanted.length && !wanted[wanted.length - 1]) wanted.pop();
    if (!wanted.length || wanted.length > lines.length) return 0;

    let removed = 0;
    for (let i = 0; i <= lines.length - wanted.length;) {
      let match = true;
      for (let j = 0; j < wanted.length; j++) {
        if (lines[i + j].trim() !== wanted[j]) {
          match = false;
          break;
        }
      }
      if (!match) {
        i += 1;
        continue;
      }
      lines.splice(i, wanted.length);
      removed += wanted.length;
    }
    return removed;
  }

  function scrubAnswers(s, text) {
    if (!RM_CONFIG.hideAnswersFromAI) return text;
    const src = typeof text === "string" ? text : "";
    const m = src.match(/(^|\n)Recent\s*Story\s*:[ \t]*\n/i);
    if (!m) return src;

    const cut = m.index + m[0].length;
    const lines = src.slice(cut).split("\n");
    let removed = 0;

    const answers = Array.isArray(s.answerHistory)
      ? s.answerHistory.slice(-ANSWER_HISTORY_MAX)
      : [];
    for (const answer of answers) {
      removed += removeExactAnswerBlocks(lines, answer);
    }

    const commands = new Set(
      (Array.isArray(s.commandHistory) ? s.commandHistory : [])
        .slice(-COMMAND_HISTORY_MAX)
        .map((value) => String(value || "").trim())
        .filter(Boolean)
    );

    for (let i = lines.length - 1; i >= 0; i--) {
      const normalized = stripPrefix(lines[i]);
      if (commands.has(normalized)) {
        lines.splice(i, 1);
        removed += 1;
      }
    }

    if (!removed) return src;
    dbg("scrubbed", removed, "exact Living Meters history lines");
    return src.slice(0, cut) + lines.join("\n").replace(/\n{3,}/g, "\n\n");
  }

  // ---- hook entry points --------------------------------------------------

  function onInput(inText) {
    const s = hydrate();
    let out = typeof inText === "string" ? inText : " ";

    try {
      s.fired = {};              // a new player action begins a new turn
      s.cmdTurn = looksLikeCommand(out);
      reportProblems(s);
      syncCard(s);

      // Input is the earliest hook of a generation and, unlike Context and
      // Output, this host never hands it to somebody else, so settle the drift
      // owed here. It must not fall back to actionCount: Input sees the
      // intermediate value and Context would count the same turn again.
      catchUp(s, "input");

      const reply = handleCommand(s, out);
      if (reply !== null) {
        rememberCommand(s, out);
        // Commands answer as the story output: the Output hook puts this in
        // place of the AI's response, so the answer reaches the player through
        // the story itself and the module never writes state.message.
        //
        // The answer is NOT composed with the pending notices here. If it is
        // never delivered, the notices have to survive for the next one.
        //
        // An answer already waiting is not discarded either. A host can defer
        // this module's Output hook for a whole generation, and a command that
        // moved a meter with no confirmation at all is worse than one answered
        // a turn late.
        s.reply = reply;
        s.replyGen = 0;
        s.cmdTurn = true;
        persist(s);
        return out;
      }

      if (RM_CONFIG.scanInput) scan(s, out, "input");
      announce(s);

      if (RM_CONFIG.inject === "frontMemory") {
        state.memory = state.memory || {};
        state.memory.frontMemory = directive(s);
      }
    } catch (err) {
      dbg("onInput error", String(err));
    }

    persist(s);
    return out;
  }

  function onContext(inText, inStop) {
    const s = hydrate();
    let out = typeof inText === "string" ? inText : " ";
    const halt = inStop === true;

    try {
      reportProblems(s);

      // Where a waiting answer ages. One generation is its own; beyond that
      // the Output hook was skipped and the answer is late. Give up after a
      // few, rather than let a forgotten answer surface in the middle of an
      // unrelated scene. If this hook is taken over the answer simply ages
      // more slowly, which errs towards delivering it rather than losing it.
      if (s.reply) {
        s.replyGen += 1;
        if (s.replyGen > REPLY_MAX_GEN) { s.reply = ""; s.replyGen = 0; }
      }

      // Context is where a Continue is first seen, since a Continue never runs
      // Input. It is not guaranteed to run either, so it settles what is owed
      // rather than assuming exactly one turn has passed since it last looked.
      // A command turn costs no drift; turnsPassed handles that, so that the
      // gate is the command turn itself and never "an answer is waiting" - an
      // answer can wait several generations, and those are ordinary turns that
      // must drift as usual.
      catchUp(s, "context");

      syncCard(s);

      out = scrubAnswers(s, out);

      if (RM_CONFIG.inject === "context") {
        const block = directive(s);
        if (block) {
          const maxChars = isNum(info?.maxChars) ? info.maxChars : 0;
          const joined = out + "\n" + block;
          // The server truncates whatever we return to info.maxChars, and it
          // trims from the front — so trim ourselves and keep our block.
          out = maxChars > 0 && joined.length > maxChars
            ? joined.slice(joined.length - maxChars)
            : joined;
        }
      } else if (RM_CONFIG.inject === "frontMemory") {
        state.memory = state.memory || {};
        state.memory.frontMemory = directive(s);
      }
    } catch (err) {
      dbg("onContext error", String(err));
    }

    persist(s);
    return [out, halt];
  }

  function onOutput(inText) {
    const s = hydrate();
    let out = typeof inText === "string" ? inText : " ";

    try {
      // Last chance for a generation whose Input and Context both went
      // elsewhere. Ahead of the early return below, so that delivering an
      // answer never costs the drift this generation owes.
      catchUp(s, "output");

      // A pending command answer leaves on this generation.
      let pending = "";
      let late = false;
      if (s.reply) {
        late = s.replyGen > 1;
        pending = s.reply;
        s.reply = "";
        s.replyGen = 0;
      }

      // On its own turn the answer REPLACES the response. The model was
      // replying to a slash command, so that text is dropped UNSCANNED: it
      // would otherwise fire triggers on words the story never contained.
      if (pending && !late) {
        s.fired = {};
        const answer = compose(s, pending);
        rememberAnswer(s, answer);
        persist(s);
        return answer;
      }

      if (RM_CONFIG.scanOutput && out.trim()) {
        // Retries reuse cached outputs, so the same text can arrive twice.
        // Hashing it stops a retry from applying every trigger a second time.
        const h = hash32(out);
        if (h !== s.outHash) {
          s.outHash = h;
          scan(s, out, "output");
          announce(s);
          syncCard(s);
        }
      }
      s.fired = {};              // the turn is over; release every trigger

      // A late answer is a different matter: this generation's narration is
      // real and has just been scanned like any other, so the answer joins it
      // rather than stealing it. Composed here, after the scan, so a band the
      // story just crossed is reported in the same breath.
      if (pending) {
        const answer = compose(s, pending);
        rememberAnswer(s, answer);
        persist(s);
        return out.trim() ? out + "\n\n" + answer : answer;
      }

    } catch (err) {
      dbg("onOutput error", String(err));
    }

    persist(s);
    // Never return an empty string: onOutput throws a player-visible error.
    return out.length ? out : " ";
  }

  // ---- public API (also usable from your own scripts) --------------------

  return {
    input: onInput,
    context: onContext,
    output: onOutput,

    get: (id) => (hydrate().res[id] ?? null),
    set: (id, v) => { const s = hydrate(); const r = setVal(s, id, v); persist(s); return r; },
    add: (id, v) => { const s = hydrate(); const r = addVal(s, id, v, { raw: true }); persist(s); return r; },
    all: () => hydrate().res,
    status: () => statusBlock(hydrate()),
    line: () => statusLine(hydrate()),
    directive: () => directive(hydrate()),

    // Effective definitions after player overrides, as plain JSON-safe data.
    // Compiled patterns are omitted; `words` is the author's original list.
    defs: () => {
      const s = hydrate();
      return defs().map((d) => {
        const e = eff(s, d);
        return {
          id: e.id, label: e.label, icon: e.icon,
          min: e.min, max: e.max, start: e.start, perTurn: e.perTurn,
          visible: e.visible, enabled: e.enabled,
          value: s.res[e.id],
          band: bandOf(e, s.res[e.id]).name || "",
          bands: e.bands.map((b) => ({ upTo: b.upTo, name: b.name, tell: b.tell || "" })),
          triggers: e.triggers.map((t) => ({ on: t.on, delta: t.delta, words: t.words })),
        };
      });
    },
    // Queue a line for the player. It waits with RM's own notices and leaves
    // with the next command answer, so an add-on can say something without
    // touching state.message and without racing anybody for it.
    notice: (msg) => { const s = hydrate(); notice(s, msg); persist(s); },

    problems: () => { defs(); return PROBLEMS.slice(); },
  };
})();

  function run(tab) {
    const currentText = MCPV5SafeText(globalThis.text, "\u200B");
    const beforeFrontMemory = (
      state.memory &&
      typeof state.memory === "object" &&
      !Array.isArray(state.memory) &&
      typeof state.memory.frontMemory === "string"
    ) ? state.memory.frontMemory : "";

    if (tab === "input") {
      const result = { text: MCPV5SafeText(RM.input(currentText), currentText) };
      if (RM_CONFIG.inject === "frontMemory") {
        MCPV5NormalizeLivingMetersFrontMemory(beforeFrontMemory);
      }
      return result;
    }
    if (tab === "context") {
      const result = RM.context(currentText, globalThis.stop === true);
      const nextText = Array.isArray(result)
        ? MCPV5SafeText(result[0], currentText)
        : currentText;
      const nextStop = !!(Array.isArray(result) && result[1] === true);
      if (RM_CONFIG.inject === "frontMemory") {
        MCPV5NormalizeLivingMetersFrontMemory(beforeFrontMemory);
      }
      return nextStop
        ? { text: nextText, stop: true }
        : { text: nextText };
    }
    if (tab === "output") {
      const result = { text: MCPV5SafeText(RM.output(currentText), currentText) };
      if (RM_CONFIG.inject === "frontMemory") {
        MCPV5NormalizeLivingMetersFrontMemory(beforeFrontMemory);
      }
      return result;
    }
    return { text: currentText };
  }

  return { run };
}

function MCPV5Create_story_card_extension() {

  const state = MCPV5StoryCardExtensionStateView();

const CONFIG_CARD_TITLE = "SCE Config";
const DEFAULT_CONFIG = {
    randomCardChance: 0.0,
    randomEventChance: 0.05,
    useOnlyAutouseCards: false,
    eventDuration: 2,
    useEventWeights: true,
    useCardWeights: true,
    currentEventTitle: "",
    currentEventDurationLeft: 0,
    alwaysIncludeCards: [],
    contextRecallEnabled: true,
    contextRecallThreshold: 0.05,
    contextWindowChars: 10000,
    contextRecallMaxCards: 5,
    customStopWords: [],
    recallInsertPosition: "bot",
    recallDecayRate: 0.995,
    cascadeEnabled: false,
    cascadePriorityMultiplier: 1.3
};

function getCardText(card) {
    if (card.entry) return card.entry;
    if (card.value) return card.value;
    if (card.content) return card.content;
    if (card.description) return card.description;
    if (card.text) return card.text;
    if (card.keys && card.keys.entry) return card.keys.entry;
    return null;
}

function getCardTitle(card) {
    return card.title || (card.keys && card.keys.title) || '';
}

function setCardText(card, newText) {
    if (card.entry !== undefined) {
        card.entry = newText;
    } else if (card.value !== undefined) {
        card.value = newText;
    } else if (card.content !== undefined) {
        card.content = newText;
    } else if (card.description !== undefined) {
        card.description = newText;
    } else if (card.text !== undefined) {
        card.text = newText;
    } else if (card.keys && card.keys.entry !== undefined) {
        card.keys.entry = newText;
    } else {
        card.entry = newText;
    }
}

function hasAutouseTrigger(card) {
    let keys = card.keys;
    if (!keys) return false;
    let keysStr = Array.isArray(keys) ? keys.join(' ') : keys;
    return keysStr.toLowerCase().includes('autouse');
}

function isEventCard(card) {
    let cardType = card.type || (card.keys && card.keys.type);
    let customType = card.customType || (card.keys && card.keys.customType);
    if (cardType === 'Event') return true;
    if (cardType === 'Custom' && customType === 'Event') return true;
    if (card.keys && card.keys.type === 'Custom' && card.keys.customType === 'Event') return true;
    return false;
}

function getAllStoryCards() {
    let cards = [];
    if (typeof storyCards !== 'undefined' && Array.isArray(storyCards)) cards = cards.concat(storyCards);
    if (typeof worldInfo !== 'undefined' && worldInfo && Array.isArray(worldInfo.storyCards)) cards = cards.concat(worldInfo.storyCards);
    if (typeof state !== 'undefined' && state && state.worldInfo && Array.isArray(state.worldInfo.storyCards)) cards = cards.concat(state.worldInfo.storyCards);
    if (typeof window !== 'undefined' && Array.isArray(window.storyCards)) cards = cards.concat(window.storyCards);
    return cards.length > 0 ? cards : null;
}

function categorizeCards(allCards, useOnlyAutouse) {
    let eventCards = [];
    let regularCandidates = [];
    for (let card of allCards) {
        let title = getCardTitle(card);
        if (title.toLowerCase().includes('config')) continue;

        if (isEventCard(card)) {
            eventCards.push(card);
        } else {
            regularCandidates.push(card);
        }
    }
    let regularCards = useOnlyAutouse
        ? regularCandidates.filter(card => hasAutouseTrigger(card))
        : regularCandidates;
    return { eventCards, regularCards };
}

function formatAlwaysCardsBlock(cards) {
    if (!cards || cards.length === 0) return null;
    let entries = [];
    for (let card of cards) {
        let title = getCardTitle(card);
        let content = getCardText(card);
        if (content) {
            entries.push(`• ${title}:\n{${content}};`);
        }
    }
    if (entries.length === 0) return null;
    return `[World Info:\n${entries.join('\n')}]`;
}

function formatRandomCard(card) {
    let title = getCardTitle(card);
    let content = getCardText(card);
    if (!content) return null;
    return `[Use the following information to enrich the story if it fits the current context:\n${title}. ${content}]`;
}

function formatEventCard(card) {
    let title = getCardTitle(card);
    let content = getCardText(card);
    if (!content) return null;
    return `[The following event may occur:\n${title}:\n{${content}}\nDescribe it if there are no contradictions.]`;
}

function formatRecallSingle(cards) {
    if (!cards || cards.length === 0) return null;
    let items = [];
    for (let card of cards) {
        let title = getCardTitle(card);
        let content = getCardText(card);
        if (content) {
            items.push(`• ${title}:\n{${content}};`);
        }
    }
    if (items.length === 0) return null;
    return `[The following information may be relevant to the current context:\n${items.join('\n')}]`;
}

function formatHierarchy(cards, definedSet) {
    if (!cards || cards.length === 0) return null;
    let items = [];

    for (let i = 0; i < cards.length; i++) {
        let card = cards[i];
        let title = getCardTitle(card);
        let content = getCardText(card);

        if (!content) continue;

        let pathTitles = [];
        for (let j = 0; j <= i; j++) {
            pathTitles.push(getCardTitle(cards[j]));
        }
        let breadcrumbs = `[${pathTitles.join(' > ')}]`;

        if (definedSet && definedSet.has(title)) {
            continue;
        } else {
            items.push(`${breadcrumbs}:\n${content}`);
        }
    }

    if (items.length === 0) return null;
    return items.join('\n');
}

function formatAllHierarchies(hierarchyStrings) {
    if (!hierarchyStrings || hierarchyStrings.length === 0) return null;
    let blocks = [];
    for (let i = 0; i < hierarchyStrings.length; i++) {
        blocks.push(`{Hierarchy ${i+1}.\n${hierarchyStrings[i]}}`);
    }
    let combined = blocks.join('\n\n');
    return `[Current hierarchies (each sub-item is part of the parent item above):\n${combined}\n]`;
}

function formatDefinitionsBlock(cards) {
    if (!cards || cards.length === 0) return null;
    let items = [];
    for (let card of cards) {
        let title = getCardTitle(card);
        let content = getCardText(card);
        if (!content) continue;
        let parentTitle = getCardParent(card);
        let displayTitle = title;
        if (parentTitle) {
            displayTitle = `${title} (part of ${parentTitle})`;
        }
        items.push(`• ${displayTitle}:\n{${content}};`);
    }
    if (items.length === 0) return null;
    return `[In the current context, the following terms refer to:\n${items.join('\n')}]`;
}

function formatRecallCandidate(candidate, definedSet) {
    if (candidate.type === 'single') {
        return formatRecallSingle(candidate.cards);
    } else {
        return formatHierarchy(candidate.cards, definedSet);
    }
}

function generateConfigHelpText() {
    return `===============================================
STORY CARD EXTENSION CONFIGURATION GUIDE
===============================================

This card stores settings for the StoryCard Extension script.
Edit the values below, then save the card. The script will automatically use the new settings.

-------------------------------------------------------
GENERAL
-------------------------------------------------------
useOnlyAutouseCards = true/false
  - true: Only cards with the trigger "autouse" will ever be used.
  - false: All story cards (except Events) are eligible for random selection and context recall.

-------------------------------------------------------
PARENT HIERARCHIES (linking cards)
-------------------------------------------------------
To create a hierarchy (e.g., City → Tavern), add parent=Title in the card's Triggers.
Example Triggers: parent=CityName
When a card is recalled, its entire parent chain (parent → parent of parent, etc.) is added automatically.
The context will show relations like "Card (part of ParentCard)".

-------------------------------------------------------
RECALL (KEYWORD-BASED CARD TRIGGERING)
-------------------------------------------------------
contextRecallEnabled = true/false
  - Master switch for the recall mechanic.

contextRecallThreshold = 0.005
  - Minimum coverage score (0.0 to 1.0) for a card to be recalled.
  - Now based on how much of the card's content is covered by the context.
  - Typically 0.15 works well; lower = more sensitive.

contextWindowChars = 10000
  - How many recent characters of the story are analyzed for keywords.

contextRecallMaxCards = 4
  - Maximum number of cards OR hierarchies recalled in one action.
  - Example: 2 single cards + 2 hierarchies, or 4 hierarchies, etc.

customStopWords = word1, word2, ...
  - Extra words to ignore (case-insensitive). Useful for character names that cause false triggers.
  - Example: customStopWords = YourCharacterName, shadow, eldrin

recallInsertPosition = top / bot
  - Where to insert recalled cards in the context.
  - "top" = right after always-include cards (near the beginning).
  - "bot" = near the end, just before events.

recallDecayRate = 1.0
  - Weight decay for tokens based on their distance from the end of the context.
  - 1.0 means no decay (all tokens weight equally).
  - Values < 1.0 make recent tokens count more. Example: 0.995 gives a mild recency bias.
  - Lower values (e.g. 0.9) strongly focus on the very last sentences.

-------------------------------------------------------
CASCADE (iterative expansion of context during recall)
-------------------------------------------------------
cascadeEnabled = true/false
  - If true, the script iteratively adds found cards to the working text, allowing deeper chains of related cards to be discovered.
  - If false, only a single pass is performed (no contextual expansion).

cascadePriorityMultiplier = 1.3
  - When cascadeEnabled = true, this multiplier is applied to the score of a card whose parent (or any ancestor) has already been selected.
  - Values > 1.0 give priority to direct descendants; set to 1.0 to disable the bonus.

-------------------------------------------------------
WEIGHT (affects random selection & recall sorting)
-------------------------------------------------------
Add weight=number in the card's Keys to increase (number>1) or decrease (0<number<1) its chance.
Examples: weight=2, weight=0.5

-------------------------------------------------------
EVENTS (cards marked as "Event" type)
-------------------------------------------------------
randomEventChance = 0.1
  - Probability (0.0 to 1.0) that a random Event card will trigger each action.

eventDuration = 2
  - How many actions the event will stay in the context after triggering.

useEventWeights = true/false
  - If true, respects weight=number triggers in the card's Keys for random selection.

-------------------------------------------------------
RANDOM CARDS (non-Event cards)
-------------------------------------------------------
randomCardChance = 0
  - Probability (0.0 to 1.0) that a random story card is added to context each action.

useCardWeights = true/false
  - If true, uses weight=number triggers for random card selection.

-------------------------------------------------------
ALWAYS INCLUDE
-------------------------------------------------------
alwaysIncludeCards = cardTitle1, cardTitle2, ...
  - Comma-separated list of story card titles that will be ALWAYS added to context.

-------------------------------------------------------
SYSTEM
-------------------------------------------------------
currentEventTitle / currentEventDurationLeft
  - Used internally to track active events.
=======================================================
`;
}

function findConfigCard() {
    let allCards = getAllStoryCards();
    if (!allCards) return null;
    return allCards.find(card => getCardTitle(card) === CONFIG_CARD_TITLE);
}

function readConfigFromCard(card) {
    let config = { ...DEFAULT_CONFIG };
    if (!card) return config;
    let content = getCardText(card);
    if (!content) return config;

    try {
        let parsed = JSON.parse(content);
        if (typeof parsed === 'object' && parsed !== null) {
            for (let key of Object.keys(DEFAULT_CONFIG)) {
                if (parsed.hasOwnProperty(key)) {
                    config[key] = parsed[key];
                }
            }
            return config;
        }
    } catch (e) {}

    let lines = content.split('\n');
    for (let line of lines) {
        line = line.trim();
        if (line === '' || line.startsWith('//') || line.startsWith('===')) continue;
        let eqPos = line.indexOf('=');
        if (eqPos === -1) eqPos = line.indexOf(':');
        if (eqPos === -1) continue;
        let key = line.slice(0, eqPos).trim();
        let value = line.slice(eqPos + 1).trim();
        switch (key) {
            case 'randomCardChance':
            case 'randomEventChance':
            case 'contextRecallThreshold':
            case 'recallDecayRate':
            case 'cascadePriorityMultiplier':
                config[key] = parseFloat(value);
                break;
            case 'eventDuration':
            case 'contextWindowChars':
            case 'contextRecallMaxCards':
            case 'currentEventDurationLeft':
                config[key] = parseInt(value, 10);
                break;
            case 'useOnlyAutouseCards':
            case 'useEventWeights':
            case 'useCardWeights':
            case 'contextRecallEnabled':
            case 'cascadeEnabled':
                config[key] = (value.toLowerCase() === 'true');
                break;
            case 'alwaysIncludeCards':
                config.alwaysIncludeCards = value.split(',').map(s => s.trim()).filter(s => s.length > 0);
                break;
            case 'customStopWords':
                config.customStopWords = value.split(',').map(s => s.trim().toLowerCase()).filter(s => s.length > 0);
                break;
            case 'recallInsertPosition':
                if (value.toLowerCase() === 'bot') config.recallInsertPosition = 'bot';
                else config.recallInsertPosition = 'top';
                break;
            case 'currentEventTitle':
                config.currentEventTitle = value;
                break;
        }
    }
    return config;
}

function writeConfigToCard(card, config) {
    if (!card) return;
    if (!card.description && card.description !== '') {
        card.description = generateConfigHelpText();
    }
    let lines = [];
    lines.push("// StoryCard Extension Configuration");
    lines.push("// Edit values below, save the card, and the changes will apply immediately.");
    lines.push("");
    lines.push("// ----- General -----");
    lines.push(`useOnlyAutouseCards = ${config.useOnlyAutouseCards}`);
    lines.push("");
    lines.push("// ----- Recall (keyword-based triggering) -----");
    lines.push(`contextRecallEnabled = ${config.contextRecallEnabled}`);
    lines.push(`contextRecallThreshold = ${config.contextRecallThreshold}`);
    lines.push(`contextWindowChars = ${config.contextWindowChars}`);
    lines.push(`contextRecallMaxCards = ${config.contextRecallMaxCards}`);
    lines.push(`customStopWords = ${(config.customStopWords || []).join(', ')}`);
    lines.push(`recallInsertPosition = ${config.recallInsertPosition === 'bot' ? 'bot' : 'top'}`);
    lines.push(`recallDecayRate = ${config.recallDecayRate}`);
    lines.push("");
    lines.push("// ----- Cascade Settings -----");
    lines.push(`cascadeEnabled = ${config.cascadeEnabled}`);
    lines.push(`cascadePriorityMultiplier = ${config.cascadePriorityMultiplier}`);
    lines.push("");
    lines.push("// ----- Events -----");
    lines.push(`randomEventChance = ${config.randomEventChance}`);
    lines.push(`eventDuration = ${config.eventDuration}`);
    lines.push(`useEventWeights = ${config.useEventWeights}`);
    lines.push("");
    lines.push("// ----- Random Cards -----");
    lines.push(`randomCardChance = ${config.randomCardChance}`);
    lines.push(`useCardWeights = ${config.useCardWeights}`);
    lines.push("");
    lines.push("// ----- Always Include (by story card title) -----");
    lines.push(`alwaysIncludeCards = ${(config.alwaysIncludeCards || []).join(', ')}`);
    lines.push("");
    lines.push("// ----- System -----");
    lines.push(`currentEventTitle = ${config.currentEventTitle || ''}`);
    lines.push(`currentEventDurationLeft = ${config.currentEventDurationLeft || 0}`);

    setCardText(card, lines.join('\n'));
}

function ensureConfigCard() {
    let existing = findConfigCard();
    if (existing) return existing;

    let newCard = {
        title: CONFIG_CARD_TITLE,
        entry: "",
        description: generateConfigHelpText(),
        keys: "",
        type: "Custom",
        customType: "Config"
    };

    let added = false;
    if (typeof storyCards !== 'undefined' && Array.isArray(storyCards)) {
        storyCards.push(newCard);
        added = true;
    } else if (typeof worldInfo !== 'undefined' && worldInfo && Array.isArray(worldInfo.storyCards)) {
        worldInfo.storyCards.push(newCard);
        added = true;
    } else if (typeof state !== 'undefined' && state && state.worldInfo && Array.isArray(state.worldInfo.storyCards)) {
        state.worldInfo.storyCards.push(newCard);
        added = true;
    } else if (typeof window !== 'undefined' && Array.isArray(window.storyCards)) {
        window.storyCards.push(newCard);
        added = true;
    }

    if (!added) {
        console.error("[SCE] Could not add config card – no suitable array found.");
        return null;
    }
    writeConfigToCard(newCard, DEFAULT_CONFIG);
    return newCard;
}

function getEventWeight(card) {
    let keys = card.keys;
    if (!keys) return 1;
    let keysStr = Array.isArray(keys) ? keys.join(' ') : keys;
    let match = keysStr.match(/weight=([\d.]+)/i);
    if (match) {
        let w = parseFloat(match[1]);
        return isNaN(w) ? 1 : Math.max(0, w);
    }
    return 1;
}

function getEventDuration(card, globalDuration) {
    let keys = card.keys;
    if (!keys) return globalDuration;
    let keysStr = Array.isArray(keys) ? keys.join(' ') : keys;
    let match = keysStr.match(/duration=(\d+)/i);
    if (match) {
        let d = parseInt(match[1], 10);
        return isNaN(d) ? globalDuration : Math.max(1, d);
    }
    return globalDuration;
}

function getCardWeight(card) {
    let keys = card.keys;
    if (!keys) return 1;
    let keysStr = Array.isArray(keys) ? keys.join(' ') : keys;
    let match = keysStr.match(/weight=([\d.]+)/i);
    if (match) {
        let w = parseFloat(match[1]);
        return isNaN(w) ? 1 : Math.max(0, w);
    }
    return 1;
}

function getCardParent(card) {
    let keys = card.keys;
    if (!keys) return null;
    let keysStr = Array.isArray(keys) ? keys.join(' ') : keys;
    let match = keysStr.match(/parent=([^;,\n]+)/i);
    if (match) {
        return match[1].trim();
    }
    return null;
}

function selectCardByWeight(cards) {
    if (!cards || cards.length === 0) return null;
    let weights = cards.map(c => getCardWeight(c));
    let totalWeight = weights.reduce((a, b) => a + b, 0);
    if (totalWeight <= 0) return null;
    let rand = Math.random() * totalWeight;
    let accum = 0;
    for (let i = 0; i < cards.length; i++) {
        accum += weights[i];
        if (rand < accum) return cards[i];
    }
    return cards[cards.length - 1];
}

function selectEventByWeight(events) {
    if (!events || events.length === 0) return null;
    let weights = events.map(e => getEventWeight(e));
    let totalWeight = weights.reduce((a, b) => a + b, 0);
    if (totalWeight <= 0) return null;
    let rand = Math.random() * totalWeight;
    let accum = 0;
    for (let i = 0; i < events.length; i++) {
        accum += weights[i];
        if (rand < accum) return events[i];
    }
    return events[events.length - 1];
}

function computeHash(str) {
    let hash = 5381;
    for (let i = 0; i < str.length; i++) {
        hash = ((hash << 5) + hash) ^ str.charCodeAt(i);
    }
    return hash >>> 0;
}

function computeCardHash(card) {
    let content = getCardText(card) || '';
    let title = getCardTitle(card);
    return computeHash(title + '###' + content);
}

const DEFAULT_STOP_WORDS = new Set([
    'a', 'an', 'and', 'are', 'as', 'at', 'be', 'by', 'can', 'do', 'for', 'from', 'had', 'has', 'have',
    'he', 'her', 'his', 'i', 'in', 'is', 'it', 'its', 'me', 'my', 'of', 'on', 'or', 'she', 'that',
    'the', 'their', 'them', 'they', 'this', 'to', 'was', 'we', 'were', 'with', 'you', 'your', 'yes',
    'no', 'not', 'but', 'so', 'for', 'yet', 'nor', 'then', 'now', 'well', 'very', 'just', 'like',
    'such', 'than', 'then', 'there', 'these', 'those', 'will', 'would', 'could', 'should', 'may',
    'might', 'must', 'both', 'each', 'every', 'more', 'most', 'some', 'any', 'no', 'only', 'own',
    'same', 'than', 'that', 'then', 'thence', 'there', 'these', 'they', 'this', 'those', 'through',
    'until', 'unto', 'upon', 'us', 'use', 'used', 'using', 'we', 'what', 'when', 'where', 'which',
    'while', 'who', 'whom', 'why', 'with', 'within', 'without', 'your', 'yours', 'yourself'
]);

function simpleTokenize(text, extraStopWords = []) {
    if (!text || typeof text !== 'string') return [];
    let words = text.toLowerCase().replace(/[^a-z0-9а-яё]/gi, ' ').split(/\s+/);
    let allStopWords = new Set(DEFAULT_STOP_WORDS);
    for (let w of extraStopWords) {
        allStopWords.add(w.toLowerCase());
    }
    return words.filter(w => w.length > 1 && !allStopWords.has(w));
}

function stripBrackets(text) {
    return text.replace(/\[[^\]]*\]/g, '').replace(/\{[^}]*\}/g, '');
}

function cardCoverageScore(cardTokens, cardNorm, contextWeightMap, idfMap) {
    if (!cardTokens || cardTokens.length === 0) return 0;
    if (!contextWeightMap || cardNorm <= 0) return 0;
    let intersectionWeight = 0;
    for (let t of cardTokens) {
        if (contextWeightMap.has(t)) {
            let idf = 1;
            if (idfMap && typeof idfMap.get === 'function') {
                idf = idfMap.get(t) || 0;
            }
            intersectionWeight += contextWeightMap.get(t) * idf;
        }
    }
    return intersectionWeight / cardNorm;
}

function getCardsSignature(regularCards) {
    let items = [];
    for (let card of regularCards) {
        let title = getCardTitle(card);
        let hash = computeCardHash(card);
        items.push(title + ':' + hash);
    }
    items.sort();
    return items.join('|');
}

function buildCardBags(regularCards, customStopWords) {
    let tokenLists = [];
    let totalCards = regularCards.length;
    for (let card of regularCards) {
        let title = getCardTitle(card);
        let content = getCardText(card) || '';
        let combined = (title ? title + ' ' : '') + content;
        let tokens = combined ? simpleTokenize(combined, customStopWords) : [];
        tokenLists.push({ title, tokens });
    }

    let docFreq = new Map();
    for (let { tokens } of tokenLists) {
        let uniqueTokens = new Set(tokens);
        for (let t of uniqueTokens) {
            docFreq.set(t, (docFreq.get(t) || 0) + 1);
        }
    }

    let idfMap = new Map();
    for (let [token, df] of docFreq.entries()) {
        let idf = Math.log((1 + totalCards) / (1 + df));
        idfMap.set(token, idf);
    }

    if (totalCards === 1 && idfMap.size > 0) {
        for (let token of idfMap.keys()) {
            idfMap.set(token, 1);
        }
    }

    let bags = {};
    for (let { title, tokens } of tokenLists) {
        let cardNormSq = 0;
        for (let t of tokens) {
            let idf = idfMap.get(t) || 0;
            cardNormSq += idf * idf;
        }
        let cardNorm = Math.sqrt(cardNormSq);
        bags[title] = {
            tokens: tokens,
            norm: cardNorm
        };
    }

    return { bags, idfMap };
}

function findCardByTitle(title, allCards) {
    if (!title) return null;
    let normTitle = title.trim().toLowerCase().replace(/\s+/g, ' ');
    return allCards.find(card => {
        let cardTitle = getCardTitle(card);
        if (!cardTitle) return false;
        let normCardTitle = cardTitle.trim().toLowerCase().replace(/\s+/g, ' ');
        return normCardTitle === normTitle;
    });
}

function getCardHierarchy(card, allCards, visited = new Set()) {
    if (!card) return [];
    let title = getCardTitle(card);
    if (visited.has(title)) {
        console.warn("[SCE] Cycle detected for", title);
        return [card];
    }
    visited.add(title);
    let parentTitle = getCardParent(card);
    if (parentTitle) {
        let parentCard = findCardByTitle(parentTitle, allCards);
        if (parentCard) {
            let parentHierarchy = getCardHierarchy(parentCard, allCards, visited);
            return [...parentHierarchy, card];
        }
    }
    return [card];
}

function hierarchySimilarity(hierarchyCards, contextWeightMap, customStopWords, state) {
    if (!hierarchyCards.length) return 0;
    let scores = [];
    for (let card of hierarchyCards) {
        let title = getCardTitle(card);
        let bag = state.__sceCardBags[title];
        if (!bag) continue;
        let score = cardCoverageScore(bag.tokens, bag.norm, contextWeightMap, state.__sceIdfMap);
        scores.push(score);
    }
    if (scores.length === 0) return 0;
    let product = scores.reduce((a, b) => a * b, 1);
    return Math.pow(product, 1 / scores.length);
}

function candidateToPlainText(cand) {
    if (cand.type === 'single') {
        let parts = [];
        for (let card of cand.cards) {
            let title = getCardTitle(card);
            let content = getCardText(card);
            if (content) parts.push(`${title}: ${content};`);
        }
        return parts.join('\n');
    } else {
        return formatHierarchy(cand.cards, new Set());
    }
}

function selectRecallCandidates(text, allCards, regularCards, config) {
    if (typeof state === 'undefined') { state = {}; }
    if (!regularCards || regularCards.length === 0) {
        console.log("[SCE] No regular cards for recall");
        return [];
    }
    if (!state.__sceCardBags) state.__sceCardBags = {};

    let currentSignature = getCardsSignature(regularCards);
    let needRebuild = (state.__sceRecallSignature !== currentSignature);
    let customStop = config.customStopWords || [];

    if (needRebuild) {
        let { bags, idfMap } = buildCardBags(regularCards, customStop);
        state.__sceCardBags = bags;
        state.__sceIdfMap = idfMap;
        state.__sceRecallSignature = currentSignature;
        console.log("[SCE] Rebuilt card bags with IDF. Cards:", regularCards.length);
    } else {
        if (!state.__sceIdfMap) {
            let { bags, idfMap } = buildCardBags(regularCards, customStop);
            state.__sceCardBags = bags;
            state.__sceIdfMap = idfMap;
        }
    }

    let decayRate = config.recallDecayRate !== undefined ? config.recallDecayRate : 1.0;
    decayRate = Math.min(1.0, Math.max(0.0, decayRate));
    let threshold = config.contextRecallThreshold !== undefined ? config.contextRecallThreshold : 0.001;
    let maxCards = config.contextRecallMaxCards || 1;
    let contextWindow = config.contextWindowChars || 3000;

    function buildWeightMap(txt) {
        let cleanText = stripBrackets(txt);
        let recentClean = cleanText.slice(-contextWindow);
        let recentRaw = txt.slice(-contextWindow);
        let tokensClean = simpleTokenize(recentClean, customStop);
        let tokensRaw = simpleTokenize(recentRaw, customStop);

        function makeMap(tokensArray) {
            let map = new Map();
            let n = tokensArray.length;
            for (let i = 0; i < n; i++) {
                let dist = n - 1 - i;
                let w = Math.pow(decayRate, dist);
                let token = tokensArray[i];
                let existing = map.get(token) || 0;
                if (w > existing) {
                    map.set(token, w);
                }
            }
            return map;
        }

        return {
            weightMapClean: makeMap(tokensClean),
            weightMapRaw: makeMap(tokensRaw)
        };
    }

    if (!config.cascadeEnabled) {
        let { weightMapClean, weightMapRaw } = buildWeightMap(text);
        let singles = [], hierarchies = [];

        for (let card of regularCards) {
            let title = getCardTitle(card);
            if (isEventCard(card) || title.toLowerCase().includes('config')) continue;
            if (getCardParent(card)) continue;

            let bag = state.__sceCardBags[title];
            if (!bag || bag.tokens.length === 0) continue;
            let score = cardCoverageScore(bag.tokens, bag.norm, weightMapClean, state.__sceIdfMap);
            if (score >= threshold) {
                let weight = getCardWeight(card);
                singles.push({
                    type: 'single',
                    card: card,
                    score: score,
                    weightedScore: score * weight,
                    cards: [card]
                });
            }
        }
        for (let card of regularCards) {
            let title = getCardTitle(card);
            if (isEventCard(card) || title.toLowerCase().includes('config')) continue;
            if (!getCardParent(card)) continue;

            let hierarchy = getCardHierarchy(card, allCards);
            if (!hierarchy.length) continue;

            let hierarchyScore = hierarchySimilarity(hierarchy, weightMapRaw, customStop, state);
            if (hierarchyScore >= threshold) {
                let weight = getCardWeight(card);
                hierarchies.push({
                    type: 'hierarchy',
                    hierarchy: hierarchy,
                    score: hierarchyScore,
                    weightedScore: hierarchyScore * weight,
                    leafCard: card,
                    cards: hierarchy
                });
            }
        }

        let allCandidates = [...singles, ...hierarchies];
        allCandidates.sort((a, b) => b.weightedScore - a.weightedScore);
        let selected = allCandidates.slice(0, maxCards);
        console.log(`[SCE] Single pass, selected: ${selected.length}`);
        return selected;
    }

    let cascadeMultiplier = config.cascadePriorityMultiplier || 1.0;
    let workingText = text;
    let usedOverallTitles = new Set();
    let allSelected = [];
    let maxIterations = 10;
    let firstIteration = true;

    for (let iter = 0; iter < maxIterations; iter++) {
        let { weightMapClean, weightMapRaw } = buildWeightMap(workingText);
        let singles = [], hierarchies = [];

        for (let card of regularCards) {
            let title = getCardTitle(card);
            if (isEventCard(card) || title.toLowerCase().includes('config')) continue;
            if (usedOverallTitles.has(title)) continue;
            if (getCardParent(card)) continue;

            let bag = state.__sceCardBags[title];
            if (!bag || bag.tokens.length === 0) continue;
            let score = cardCoverageScore(bag.tokens, bag.norm, weightMapClean, state.__sceIdfMap);
            if (score >= threshold) {
                let weight = getCardWeight(card);
                let weightedScore = score * weight;
                if (!firstIteration) {
                    weightedScore *= cascadeMultiplier;
                }
                singles.push({
                    type: 'single',
                    card: card,
                    score: score,
                    weightedScore: weightedScore,
                    cards: [card]
                });
            }
        }

        for (let card of regularCards) {
            let title = getCardTitle(card);
            if (isEventCard(card) || title.toLowerCase().includes('config')) continue;
            if (!getCardParent(card)) continue;
            if (usedOverallTitles.has(title)) continue;

            let hierarchy = getCardHierarchy(card, allCards);
            if (!hierarchy.length) continue;

            let hierarchyScore = hierarchySimilarity(hierarchy, weightMapRaw, customStop, state);
            if (hierarchyScore >= threshold) {
                let weight = getCardWeight(card);
                let weightedScore = hierarchyScore * weight;
                if (!firstIteration) {
                    weightedScore *= cascadeMultiplier;
                }
                hierarchies.push({
                    type: 'hierarchy',
                    hierarchy: hierarchy,
                    score: hierarchyScore,
                    weightedScore: weightedScore,
                    leafCard: card,
                    cards: hierarchy
                });
            }
        }

        let candidatesThisRound = [...singles, ...hierarchies];
        if (candidatesThisRound.length === 0) break;

        firstIteration = false;

        candidatesThisRound.sort((a, b) => b.weightedScore - a.weightedScore);

        if (allSelected.length < maxCards) {
            let slotsLeft = maxCards - allSelected.length;
            let toAdd = candidatesThisRound.slice(0, slotsLeft);
            for (let cand of toAdd) {
                for (let c of cand.cards) {
                    usedOverallTitles.add(getCardTitle(c));
                }
                allSelected.push(cand);
                let block = candidateToPlainText(cand);
                if (block) workingText += '\n' + block;
            }
        } else {
            let worstIdx = 0;
            for (let i = 1; i < allSelected.length; i++) {
                if (allSelected[i].weightedScore < allSelected[worstIdx].weightedScore) worstIdx = i;
            }
            let worstScore = allSelected[worstIdx].weightedScore;

            for (let cand of candidatesThisRound) {
                if (cand.weightedScore <= worstScore) break;
                allSelected[worstIdx] = cand;
                for (let c of cand.cards) {
                    usedOverallTitles.add(getCardTitle(c));
                }
                let block = candidateToPlainText(cand);
                if (block) workingText += '\n' + block;
                worstScore = Infinity;
                for (let i = 0; i < allSelected.length; i++) {
                    if (allSelected[i].weightedScore < worstScore) {
                        worstScore = allSelected[i].weightedScore;
                        worstIdx = i;
                    }
                }
            }
            if (worstScore >= allSelected[worstIdx].weightedScore) break;
        }
    }

    console.log(`[SCE] Cascade iterations completed, selected: ${allSelected.length}`);
    allSelected.sort((a, b) => b.weightedScore - a.weightedScore);
    return allSelected;
}

function StoryCardExtensionContext(text) {
