        for (let cand of candidates) {
            if (cand.type === 'hierarchy' && cand.cards && cand.cards.length > 1) {
                for (let i = 0; i < cand.cards.length - 1; i++) {
                    ancestorTitles.add(getCardTitle(cand.cards[i]));
                }
