        }

        const stripped = stripAcknowledgement(raw)
        const acknowledgementRemoved = stripped !== raw
        const core = stripped || raw

        const norm = canonical(core)
        const rawNorm = canonical(raw)
        const tokens = contentTokens(core)

        const wordCount = rawNorm
          ? rawNorm.split(" ").length
          : 0

        if (!norm || !tokens.length) {
          return {
            remove: false,
            shortLift: false
          }
        }

        let shortLift = false

        for (const ref of references) {
          // Exact recent dialogue reuse.
          if (norm === ref.norm) {
            return {
              remove: true,
              shortLift: false
            }
          }

          /*
           * "Money?"
           * "I'm sorry?"
           * "Cute."
           *
           * A short lifted fragment is marked first. It becomes a hard
           * removal when coupled to repetition narration such as
           * "she echoes" or "he repeated the word".
           */
          if (
            isQuote &&
            wordCount <= 4 &&
            containsWholePhrase(ref.norm, norm)
          ) {
            shortLift = true
          }

          const refSet = new Set(ref.tokens)

          let shared = 0
          let sharedWeight = 0
          let candidateWeight = 0

          for (const token of tokens) {
            const weight = tokenWeight(token)

            candidateWeight += weight

            if (refSet.has(token)) {
              shared++
              sharedWeight += weight
            }
          }

          if (!shared || !candidateWeight) continue

          const coverage = sharedWeight / candidateWeight

          // Large fact inventory.
          if (
            shared >= 4 &&
            coverage >= 0.50
          ) {
            return {
              remove: true,
              shortLift
            }
          }

          // Concentrated paraphrase.
          if (
            shared >= 3 &&
            coverage >= 0.68
          ) {
            return {
              remove: true,
              shortLift
            }
          }

          // Short near-restatement.
          if (
            tokens.length <= 6 &&
            shared >= 2 &&
            coverage >= 0.82
          ) {
            return {
              remove: true,
              shortLift
            }
          }

          /*
           * Catches:
           * "No kidding that's a lot."
           *
           * after:
           * "That's a lot of money."
           */
          if (
            acknowledgementRemoved &&
            tokens.length <= 3 &&
            shared >= 1 &&
            coverage >= 0.95
          ) {
            return {
              remove: true,
              shortLift
            }
          }
        }

        return {
          remove: false,
          shortLift
        }
      }

      const splitPieces = (value) => {
        const s = String(value || "")
        const spans = splitSentenceSpans(s)

        if (!spans.length) {
          return [{
            raw: s,
            fullSentence: false,
            removed: false,
            shortLift: false,
            semanticEcho: false
          }]
        }

        const pieces = []
        let cursor = 0

        for (const span of spans) {
          if (span.start > cursor) {
            pieces.push({
              raw: s.slice(cursor, span.start),
              fullSentence: false,
              removed: false,
              shortLift: false,
              semanticEcho: false
            })
          }

          pieces.push({
            raw: s.slice(span.start, span.end),
            fullSentence: true,
            removed: false,
            shortLift: false,
            semanticEcho: false
          })

          cursor = span.end
        }

        if (cursor < s.length) {
          pieces.push({
            raw: s.slice(cursor),
            fullSentence: false,
            removed: false,
            shortLift: false,
            semanticEcho: false
          })
        }

        return pieces
      }

      const isMetaEchoProse = (value) => {
        const s = String(value || "").trim()

        if (!s) return false

        if (
          /\b(?:repeat(?:s|ed|ing)?|echo(?:es|ed|ing)?|parrot(?:s|ed|ing)?|mimic(?:s|ked|king)?|recite(?:s|d|ing)?)\b/i.test(s)
        ) {
          return true
        }

        if (
          /\b(?:say|says|said|ask|asks|asked|whisper|whispers|whispered|murmur|murmurs|murmured)\s+(?:it\s+)?again\b/i.test(s)
        ) {
          return true
        }

        if (
          /\b(?:taste|tastes|tasted|tasting|savor|savors|savored|savoring|test|tests|tested|testing|roll|rolls|rolled|rolling|turn|turns|turned|turning)\b[^.!?]{0,55}\b(?:word|words|phrase)\b/i.test(s)
        ) {
          return true
        }

        if (
          /\b(?:word|words|phrase)\b[^.!?]{0,55}\b(?:tongue|mouth|lips)\b/i.test(s)
        ) {
          return true
        }

        return false
      }

      // ------------------------------------------------------------
      // Layer 1: exact previous-Continue sentence overlap
      // ------------------------------------------------------------

      let working = original
      let exactRemoved = 0

      if (Array.isArray(history)) {
        for (let i = history.length - 1; i >= 0; i--) {
          const action = history[i]

          if (
            action &&
            action.type === "continue" &&
            typeof action.text === "string" &&
            action.text.trim()
          ) {
            const exact = trimLeadingExactOverlap(
              action.text,
              working
            )

            working = exact.text
            exactRemoved = exact.removed
            break
          }
        }
      }

      // ------------------------------------------------------------
      // Layers 2-4: dialogue lifts, paraphrases, fact inventories
      // ------------------------------------------------------------

      const segments = splitQuotedSegments(working)

      let semanticRemoved = 0
      let metaRemoved = 0

      for (const segment of segments) {
        segment.pieces = splitPieces(segment.text)

        for (const piece of segment.pieces) {
          const candidate = piece.raw.trim()

          if (!candidate) continue

          /*
           * Quoted fragments may be incomplete sentences:
           * "Money,"
           *
           * Prose is semantic-filtered only when it is a full sentence.
           * This prevents accidental deletion of useful partial narration.
           */
          if (
            segment.kind !== "quote" &&
            !piece.fullSentence
          ) {
            continue
          }

          const result = compareCandidate(
            candidate,
            segment.kind === "quote"
          )

          piece.shortLift = result.shortLift

          if (result.remove) {
            piece.removed = true
            piece.semanticEcho = true
            semanticRemoved++
          }
        }
      }

      const firstActivePiece = (segment) => {
        if (!segment) return null

        for (const piece of segment.pieces) {
          if (
            !piece.removed &&
            piece.raw.trim()
          ) {
            return piece
          }
        }

        return null
      }

      const lastActivePiece = (segment) => {
        if (!segment) return null

        for (
          let i = segment.pieces.length - 1;
          i >= 0;
          i--
        ) {
          const piece = segment.pieces[i]

          if (
            !piece.removed &&
            piece.raw.trim()
          ) {
            return piece
          }
        }

        return null
      }

      const quoteNeedsMetaCleanup = (segment) => {
        if (
          !segment ||
          segment.kind !== "quote"
        ) {
          return false
        }

        let removedEcho = false
        let shortLift = false

        for (const piece of segment.pieces) {
          if (piece.semanticEcho) {
            removedEcho = true
          }

          if (
            !piece.removed &&
            piece.shortLift
          ) {
            shortLift = true
          }
        }

        return removedEcho || shortLift
      }

      // ------------------------------------------------------------
      // Layer 3: remove "he repeated the word" independently
      // from the genuinely new sentence that follows it.
      // ------------------------------------------------------------

      for (let i = 0; i < segments.length; i++) {
        const segment = segments[i]

        if (
          segment.kind !== "quote" ||
          !quoteNeedsMetaCleanup(segment)
        ) {
          continue
        }

        const previous =
          i > 0 &&
          segments[i - 1].kind === "prose"
            ? lastActivePiece(segments[i - 1])
            : null

        const next =
          i + 1 < segments.length &&
          segments[i + 1].kind === "prose"
            ? firstActivePiece(segments[i + 1])
            : null

        let linkedMetaRemoved = false

        if (
          previous &&
          isMetaEchoProse(previous.raw)
        ) {
          previous.removed = true
          metaRemoved++
          linkedMetaRemoved = true
        }

        if (
          next &&
          isMetaEchoProse(next.raw)
        ) {
          next.removed = true
          metaRemoved++
          linkedMetaRemoved = true
        }

        /*
         * A one-word/short lifted quote is only forced out when
         * the surrounding prose confirms it is an echo construction.
         */
        if (linkedMetaRemoved) {
          for (const piece of segment.pieces) {
            if (
              !piece.removed &&
              piece.shortLift
            ) {
              piece.removed = true
              semanticRemoved++
            }
          }
        }
      }

      // ------------------------------------------------------------
      // Reconstruction
      // ------------------------------------------------------------

      let filtered = ""

      for (const segment of segments) {
        const kept = segment.pieces
          .filter((piece) => !piece.removed)
          .map((piece) => piece.raw)
          .join("")

        if (!kept.trim()) continue

        if (segment.kind === "quote") {
          filtered +=
            segment.open +
            kept.trim() +
            segment.close
        } else {
          filtered += kept
        }
      }

      filtered = filtered
        .replace(/[ \t]{2,}/g, " ")
        .replace(/[ \t]+\n/g, "\n")
        .replace(/\n[ \t]+/g, "\n")
        .replace(/\s+([,;:.!?])/g, "$1")
        .replace(/\n{3,}/g, "\n\n")
        .replace(/^[,;:]+\s*/, "")
        .trim()

      // Output hook must never return empty text.
      if (!filtered) {
        filtered = "…"
      }

      if (
        CFG.debug &&
        (exactRemoved || semanticRemoved || metaRemoved)
      ) {
        log(
          "anti-echo:",
          "exact=" + exactRemoved,
          "semantic=" + semanticRemoved,
          "meta=" + metaRemoved
        )
      }

      return { text: filtered }
    } catch (e) {
      log("anti-echo output error:", e)
      return { text: original }
    }
  }

  function run(tab) {
    const currentText = MCPV5SafeText(globalThis.text, "\u200B");
    if (tab !== "output") return { text: currentText };
    try {
      const result = modifier(currentText);
      return (
        result &&
        typeof result === "object" &&
        typeof result.text === "string" &&
        result.text.length
      ) ? {
        text: String(result.text),
        ...(result.stop === true ? { stop: true } : {})
      } : { text: currentText };
    } catch (error) {
      log("MCP AR output error:", error);
      return { text: currentText };
    }
  }

  return { run };
}

