      let result = kept.join("");

      if (preciseRegex) {
        result = result.replace(preciseRegex, "");
      }

      result = result.replace(/\s+([,.;!?])/g, "$1");

      return result;
    } catch (e) {
      log("delete_cliches error:", e);
      return text;
    }
