  usc_e: MCPV5Create_usc_e,
  dice_roll: MCPV5Create_dice_roll,
  coin_flip: MCPV5Create_coin_flip
};

function MCPV5FactoryKey(id) {
  return (id === "inner_self" || id === "auto_cards")
    ? "inner_package"
    : id;
}

function MCPV5GetModule(id, incomingText) {
  const key = MCPV5FactoryKey(id);
  if (MCPV5_MODULE_CACHE[key]) return MCPV5_MODULE_CACHE[key];

  const factory = MCPV5_FACTORIES[key];
  if (typeof factory !== "function") return null;

  const oldText = globalThis.text;
  const oldStop = globalThis.stop;
  try {
    globalThis.text = MCPV5SafeText(incomingText, "\u200B");
    globalThis.stop = false;
    MCPV5_MODULE_CACHE[key] = factory();
    return MCPV5_MODULE_CACHE[key];
  } finally {
    try { globalThis.text = oldText; } catch {}
    try { globalThis.stop = oldStop; } catch {}
  }
}


function MCPV5AnchorRealmHeartContext(baseText, candidateText) {
  const base = MCPV5SafeText(baseText, "\u200B");
  const candidate = MCPV5SafeText(candidateText, base);
  if (candidate === base) return candidate;

  const marker =
    "[CURRENT WORLD STATE -- use this as ground truth for the scene.";
  const basePosition = candidate.indexOf(base);
  if (basePosition < 0) return candidate;

  const prefix = candidate.slice(0, basePosition);
  const suffix = candidate.slice(basePosition + base.length);

  // RealmHeart's original Context hook appends this hidden reference after the
  // latest player action. Keep the information but move it ahead of AI
  // Dungeon's base Context so the player action remains the final story text.
  if (suffix.indexOf(marker) < 0) return candidate;

  const worldState = suffix.trim();
  if (!worldState) return candidate;

  try {
    const root = MCPV5Root();
    root.realmHeartContextGuard = {
      action: Number.isFinite(info && info.actionCount)
        ? info.actionCount
        : -1,
      block: worldState.slice(0, 12000)
    };
  } catch {}

  const priorPrefix = prefix.trim();
  return (
    worldState +
    (priorPrefix ? "\n\n" + priorPrefix : "") +
    "\n\n" +
    base
  );
}

function MCPV5StripRealmHeartContextLeak(value, plan) {
  const original = MCPV5SafeText(value, "\u200B");
  try {
    if (
      !plan ||
      !plan.effective ||
      plan.effective.realmheart !== true
    ) {
      return original;
    }

    const root = MCPV5Root();
    const guard = root.realmHeartContextGuard;
    if (
      !guard ||
      typeof guard !== "object" ||
      typeof guard.block !== "string" ||
      !guard.block.length
    ) {
      return original;
    }

    const now = Number.isFinite(info && info.actionCount)
      ? info.actionCount
      : -1;
    const then = Number(guard.action);
    if (
      now >= 0 &&
      Number.isFinite(then) &&
      then >= 0 &&
      Math.abs(now - then) > 1
    ) {
      return original;
    }

    const block = guard.block;
    const at = original.indexOf(block);
    if (at < 0) return original;

    let before = original.slice(0, at);
    let after = original.slice(at + block.length);

    // If the model copied RealmHeart's leading separator separately from the
    // stored trimmed block, remove only that adjacent separator as well.
    before = before.replace(
      /(?:^|\n)[ \t]*={20,}[ \t]*\n?[ \t]*$/,
      before.includes("\n") ? "\n" : ""
    );
    after = after.replace(/^[ \t]*\n{0,2}/, "");

    const cleaned = (before + after)
      .replace(/\n{3,}/g, "\n\n")
      .trim();

    if (!MCPV5HasVisibleText(cleaned)) return original;

    MCPV5RecordDiagnostic(
      "realmheart-context-leak-removed",
      "Removed a copied CURRENT WORLD STATE block from visible Output."
    );
    return cleaned;
  } catch (error) {
    log("MCP V5.4.0 RealmHeart leak guard error:", error);
    return original;
  }
}

function MCPV5RunProfile(id, tab, incomingText, plan) {
  const original = MCPV5SafeText(incomingText, "\u200B");
  const root = MCPV5Root();
  const oldText = globalThis.text;
  const oldStop = globalThis.stop;
  const oldStoryCards = globalThis.storyCards;
  const oldAdd = globalThis.addStoryCard;
  const oldUpdate = globalThis.updateStoryCard;
  const oldRemove = globalThis.removeStoryCard;
  const globalSnapshot = MCPV5SnapshotModuleGlobals(
    !!(root.settings && root.settings.diagnostics)
  );
  const stateSnapshot = MCPV5SnapshotModuleState(id);
  const tracksInventory = (
    id === "true_auto_stats" ||
    id === "stackable_inventory" ||
    id === "realmheart"
  );
  const inventoryBefore = tracksInventory
    ? MCPV5CanonicalInventoryFromState(id)
    : null;

  let sandbox = MCPV5_CARD_SANDBOXES[id];
  if (
    !sandbox ||
    !["stackable_inventory", "realmheart"].includes(id)
  ) {
    sandbox = MCPV5CreateCardSandbox(id);
  }

  try {
    globalThis.storyCards = sandbox.storyCards;
    globalThis.addStoryCard = sandbox.addStoryCard;
    globalThis.updateStoryCard = sandbox.updateStoryCard;
    globalThis.removeStoryCard = sandbox.removeStoryCard;
    globalThis.text = original;
    globalThis.stop = false;
    MCPV5ActivateModuleGlobals(id);

    const module = MCPV5GetModule(id, original);
    if (!module) {
      sandbox.rollback();
      MCPV5RestoreModuleState(stateSnapshot);
      return { text: original, __mcpOk: false };
    }

    // Stackable Inventory and RealmHeart create a persistent private card API
    // during factory initialization. Use that exact transaction journal.
    if (MCPV5_CARD_SANDBOXES[id]) {
      sandbox = MCPV5_CARD_SANDBOXES[id];
      globalThis.storyCards = sandbox.storyCards;
      globalThis.addStoryCard = sandbox.addStoryCard;
      globalThis.updateStoryCard = sandbox.updateStoryCard;
      globalThis.removeStoryCard = sandbox.removeStoryCard;
    }

    let result;
    if (id === "inner_self") {
      MCPV5ForceInnerSelfSettings(
        plan.effective.inner_self === true,
        plan.effective.auto_cards === true
      );
      result = module.runInner(tab);
    } else if (id === "auto_cards") {
      result = module.runAutoCards(tab);
    } else {
      result = module.run(tab);
    }

    if (
      id === "realmheart" &&
      tab === "context" &&
      result &&
      typeof result === "object" &&
      typeof result.text === "string" &&
      result.text.length
    ) {
      result.text = MCPV5AnchorRealmHeartContext(
        original,
        result.text
      );
    }

    if (
      result &&
      typeof result === "object" &&
      typeof result.text === "string" &&
      result.text.length
    ) {
      if (
        !MCPV5NormalizeModuleState(id, stateSnapshot) ||
        !sandbox.makeCloneSafe()
      ) {
        try { sandbox.rollback(); } catch {}
        MCPV5RestoreModuleState(stateSnapshot);
        return { text: original, __mcpOk: false };
      }

      MCPV5StoreModuleGlobals(id);
      sandbox.commit();
      if (tracksInventory) {
        MCPV5RecordInventoryAudit(
          id,
          inventoryBefore,
          MCPV5CanonicalInventoryFromState(id),
          plan
        );
      }
      return {
        text: result.text,
        stop: result.stop === true,
        __mcpOk: true
      };
    }

    MCPV5StoreModuleGlobals(id);
    sandbox.rollback();
    MCPV5RestoreModuleState(stateSnapshot);
    MCPV5RecordDiagnostic(
      "invalid-return",
      MCPV5Name(id) + " / " + tab
    );
    return { text: original, __mcpOk: false };
  } catch (error) {
    try { MCPV5StoreModuleGlobals(id); } catch {}
    try { sandbox.rollback(); } catch {}
    MCPV5RestoreModuleState(stateSnapshot);
    MCPV5RecordDiagnostic(
      "module-error",
      MCPV5Name(id) + " / " + tab + " / " +
      String(error && error.message ? error.message : error)
    );
    log("MCP V5.4.0 module error:", MCPV5Name(id), tab, error);
    return { text: original, __mcpOk: false };
  } finally {
    MCPV5RestoreModuleGlobals(globalSnapshot);
    try { globalThis.storyCards = oldStoryCards; } catch {}
    try { globalThis.addStoryCard = oldAdd; } catch {}
    try { globalThis.updateStoryCard = oldUpdate; } catch {}
    try { globalThis.removeStoryCard = oldRemove; } catch {}
    try { globalThis.text = oldText; } catch {}
    try { globalThis.stop = oldStop; } catch {}
  }
}

function MCPV5TrackActionHealth(tab, plan, schedule, ran, failed, skipped, elapsedMs) {
  const root = MCPV5Root();
  const scheduler = root.scheduler;
  if (!scheduler.heartbeat || typeof scheduler.heartbeat !== "object") {
    scheduler.heartbeat = {};
  }
  const action = Number.isFinite(info && info.actionCount)
    ? info.actionCount : -1;
  const ranSet = new Set(ran || []);
  const failedSet = new Set(failed || []);
  const skippedSet = new Set(skipped || []);
  for (const id of MCPV5_PROFILE_ORDER) {
    if (!plan.effective || plan.effective[id] !== true) continue;
    const beat = scheduler.heartbeat[id] || {
      runs: 0, deferrals: 0, failures: 0, deferStreak: 0,
      maxDeferStreak: 0, lastInput: -1, lastContext: -1, lastOutput: -1
    };
    const lastKey = "last" + tab.charAt(0).toUpperCase() + tab.slice(1);
    const duplicate = action >= 0 && beat[lastKey] === action;
    if (!duplicate) {
      if (ranSet.has(id)) {
        beat.runs = Math.min(1000000, beat.runs + 1);
        if (tab === "output") beat.deferStreak = 0;
      } else if (skippedSet.has(id)) {
        beat.deferrals = Math.min(1000000, beat.deferrals + 1);
        if (tab === "output") {
          beat.deferStreak = Math.min(100, beat.deferStreak + 1);
          beat.maxDeferStreak = Math.max(beat.maxDeferStreak, beat.deferStreak);
        }
      }
      if (failedSet.has(id)) beat.failures = Math.min(1000000, beat.failures + 1);
      beat[lastKey] = action;
    }
    scheduler.heartbeat[id] = beat;
  }
  for (const id of Object.keys(scheduler.heartbeat)) {
    if (!MCPV5_PROFILE_NAMES[id]) delete scheduler.heartbeat[id];
  }
  if (!root.performance || typeof root.performance !== "object") {
    root.performance = {
      peakMs: 0, overruns: 0, lastMs: 0, lastAction: -1
    };
  }
  const perf = root.performance;
  const measured = Math.min(60000, Math.max(0, Number(elapsedMs) || 0));
  perf.peakMs = Math.max(0, Math.min(60000, perf.peakMs || 0), measured);
  perf.lastMs = measured;
  if (tab === "output" && perf.lastAction !== action) {
    const settings = root.settings || MCPV5DefaultSettings();
    if (measured > settings.hookBudgetMs) {
      perf.overruns = Math.min(1000000, (perf.overruns || 0) + 1);
      if (settings.diagnostics) {
        MCPV5RecordDiagnostic("hook-budget-warning",
          tab + ": " + measured + " ms against " + settings.hookBudgetMs + " ms");
      }
    }
    perf.lastAction = action;
  }
}

function MCPV5SAEExclusiveTurn(tab, plan) {
  const transaction = MCPV5ActiveTransaction(tab, plan);
  return !!(
    transaction &&
    transaction.owner === "story_arc_engine"
  );
}

function MCPV5ExecutionOrder(tab, plan, schedule) {
  const transaction = MCPV5ActiveTransaction(tab, plan);
  if (transaction) return [transaction.owner];

  const base = tab === "input"
    ? MCPV5_INPUT_ORDER
    : tab === "context"
    ? MCPV5_CONTEXT_ORDER
    : MCPV5_OUTPUT_ORDER;

  const allowed = new Set(
    schedule && Array.isArray(schedule.modules)
      ? schedule.modules
      : MCPV5EligibleModules(plan)
  );

  const out = [];
  for (let i = 0; i < base.length; i++) {
    const id = base[i];
    if (!plan.effective || plan.effective[id] !== true) continue;
    if (!allowed.has(id)) continue;

    // Auto-Cards runs through Inner Self when Inner Self is active,
    // including Stackable Inventory's original bundled dependency.
    if (
      id === "auto_cards" &&
      plan.effective.inner_self === true &&
      !(plan.dependencyOnly && plan.dependencyOnly.inner_self)
    ) continue;
    out.push(id);
  }
  if (tab === "input") {
    const hint = MCPV5CommandHint(schedule && schedule.inputText, plan);
    if (hint && out.includes(hint)) {
      return [hint].concat(out.filter(id => id !== hint));
    }
  }
  return out;
}

function MCPV5ApplyOutputGuard(id, candidate, before, original) {
  if (!MCPV5HasVisibleText(candidate)) {
    if (MCPV5HasVisibleText(before)) {
      MCPV5RecordDiagnostic(
        "blank-output-blocked",
        MCPV5Name(id)
      );
      return before;
    }
    return MCPV5SafeText(original, "\u200B");
  }

  return candidate;
}

function MCPV5CleanupRemovedModulesOnce() {
  const root = MCPV5Root();
  if (!root.migrations || typeof root.migrations !== "object") {
    root.migrations = {};
  }

  // Slow Burn is installed again. V5.3.9 could still run the older one-time
  // removal migration and delete a legitimate user/Slow-Burn State marker.
  // Retire that migration without mutating Author's Note.
  if (root.migrations.removedSlowBurnAndFirewall !== true) {
    root.migrations.removedSlowBurnAndFirewall = true;
  }
}

function MCPV5Run(tab, incomingText) {
  const original = MCPV5SafeText(incomingText, "\u200B");
  MCPV5CleanupRemovedModulesOnce();
  const plan = MCPV5SyncControls();

  if (
    !plan ||
    !Array.isArray(plan.selected) ||
    plan.selected.length === 0
  ) {
    return { text: original };
  }

  MCPV5PrepareInventoryCards(plan);

  const root = MCPV5Root();
  const settings = root.settings || MCPV5DefaultSettings();
  const schedule = MCPV5EnsureActionSchedule(
    tab,
    plan,
    settings,
    tab === "input" ? original : ""
  );
  const order = MCPV5ExecutionOrder(tab, plan, schedule);
  if (tab === "input" && MCPV5CommandAmbiguous(original, plan)) {
    MCPV5RecordDiagnostic("ambiguous-command",
      "Original module handlers will resolve " + original.slice(0, 60));
  }
  let transaction = MCPV5ActiveTransaction(tab, plan);
  const startedAt = Date.now();

  const sharedBase = plan.cooperative
    ? MCPV5SnapshotSharedState()
    : null;
  const sharedRecords = [];
  const ran = [];
  const failed = [];
  let stopped = false;

  function execute(id, inputText) {
    if (plan.cooperative && sharedBase) {
      MCPV5RestoreSharedState(sharedBase);
    }

    const moduleStarted = Date.now();
    const result = MCPV5RunProfile(id, tab, inputText, plan);
    MCPV5UpdateTiming(tab, id, Date.now() - moduleStarted);

    if (plan.cooperative && sharedBase) {
      if (result && result.__mcpOk === true) {
        sharedRecords.push({
          id,
          after: MCPV5SnapshotSharedState()
        });
      }
      MCPV5RestoreSharedState(sharedBase);
    }

    if (result && result.__mcpOk === true) {
      ran.push(id);
    } else {
      failed.push(id);
    }
    return result;
  }

  let current = original;

  const realmheartControlStage = !!(
    tab !== "input" && schedule && schedule.commandOwner === "realmheart"
  );
  if ((!plan.cooperative && !realmheartControlStage) || tab === "input") {
    for (let i = 0; i < order.length; i++) {
      const id = order[i];
      const before = current;
      const messageBeforeExists = Object.prototype.hasOwnProperty.call(state, "message");
      const messageBefore = messageBeforeExists ? state.message : undefined;
      const sharedRecordStart = sharedRecords.length;
      const result = execute(id, current);
      const moduleSharedAfter = (
        plan.cooperative &&
        sharedRecords.length > sharedRecordStart
      ) ? sharedRecords[sharedRecords.length - 1].after : null;
      const messageAfterExists = moduleSharedAfter
        ? moduleSharedAfter.messageExists
        : Object.prototype.hasOwnProperty.call(state, "message");
      const messageAfter = moduleSharedAfter
        ? moduleSharedAfter.message
        : (messageAfterExists ? state.message : undefined);
      const messageChanged = (
        messageAfterExists !== messageBeforeExists ||
        messageAfter !== messageBefore
      );
      if (
        result &&
        result.__mcpOk === true &&
        typeof result.text === "string" &&
        result.text.length
      ) {
        let candidate = result.text;
        if (tab === "output") {
          candidate = MCPV5ApplyOutputGuard(
            id,
            candidate,
            before,
            original
          );
        } else if (tab === "context") {
          candidate = MCPV5FitContext(candidate, before);
        }

        current = MCPV5SafeText(candidate, before);

        if (tab === "input" && id === "realmheart" && result.__mcpOk === true) {
          const rootForCommand = MCPV5Root();
          const action = Number.isFinite(info && info.actionCount)
            ? info.actionCount : -1;
          // Only a verified v2.5 RealmHeart command reply enters this bridge.
          if (MCPV5RealmHeartCommandReply(current)) {
            rootForCommand.realmheartCommand = {
              action,
              signature: schedule.signature,
              reply: MCPV5RealmHeartControlFeedback(before, current).slice(0, 14000)
            };
            schedule.commandOwner = "realmheart";
            schedule.controlOutput = "realmheart";
            current = before; // Never put the reply into the player's input.
            break; // Command is exclusive; other scripts must not process it.
          }
          if (
            state.ubis &&
            typeof state.ubis === "object" &&
            state.ubis.pendingGambleResult &&
            typeof state.ubis.pendingGambleResult === "object"
          ) {
            rootForCommand.realmheartGambleAction = {
              action,
              signature: schedule.signature
            };
          } else {
            rootForCommand.realmheartGambleAction = null;
          }
        }

        if (
          tab === "input" &&
          id === "living_meters" &&
          state.RM &&
          typeof state.RM === "object" &&
          typeof state.RM.reply === "string" &&
          state.RM.reply.trim()
        ) {
          // LM's command lifecycle deliberately leaves Input unchanged and
          // stores its answer for Output, so the legacy command-owner heuristic
          // cannot see it. Claim the command only after LM actually queued a
          // reply; unknown slash commands remain unclaimed.
          schedule.commandOwner = "living_meters";
          schedule.controlOutput = "living_meters";
        } else if (
          tab === "input" &&
          /^\s*\//.test(original) &&
          !schedule.commandOwner &&
          (
            result.stop === true ||
            current !== before ||
            (
              messageChanged &&
              typeof messageAfter === "string" &&
              messageAfter.trim()
            )
          )
        ) {
          schedule.commandOwner = id;
        }

        if (
          tab === "input" &&
          id === "living_meters" &&
          schedule.commandOwner === "living_meters"
        ) {
          // A recognized LM command is control input. Do not let unrelated
          // narrative modules interpret it as story prose or start a protected
          // model task on the generation whose response will be discarded.
          break;
        }

        if (result.stop === true) {
          stopped = true;
          break;
        }
      }
    }
  } else if (tab === "context") {
    if (!transaction && schedule && schedule.commandOwner === "realmheart") {
      // RealmHeart's command was already applied in Input. No model task or
      // unrelated Context module should process its control text.
      current = original;
    } else if (
      !transaction &&
      schedule &&
      schedule.commandOwner === "living_meters" &&
      order.includes("living_meters")
    ) {
      const result = execute("living_meters", original);
      if (
        result &&
        result.__mcpOk === true &&
        typeof result.text === "string"
      ) {
        current = MCPV5FitContext(result.text, original);
        stopped = result.stop === true;
      }
    } else if (transaction) {
      const result = execute(transaction.owner, original);
      if (
        result &&
        result.__mcpOk === true &&
        typeof result.text === "string"
      ) {
        current = MCPV5FitContext(result.text, original);
        stopped = result.stop === true;
      }
    } else {
      const proposals = [];
      let exclusiveTaskText = null;

      for (let i = 0; i < order.length; i++) {
        const id = order[i];
        const result = execute(id, original);
        if (
          result &&
          result.__mcpOk === true &&
          typeof result.text === "string"
        ) {
          const startedTask = MCPV5ActiveTransaction("output", plan);
          if (
            startedTask &&
            (
              startedTask.owner === id ||
              (
                startedTask.name === "Auto-Cards model task" &&
                id === MCPV5AutoCardsTransactionOwner(plan)
              )
            )
          ) {
            exclusiveTaskText = result.text;
            transaction = startedTask;
            if (result.stop === true) stopped = true;
            break;
          }

          if (result.stop === true) {
            exclusiveTaskText = result.text;
            stopped = true;
            MCPV5RecordDiagnostic(
              "context-stop-owner",
              MCPV5Name(id)
            );
            break;
          }

          proposals.push({
            id,
            index: i,
            text: result.text
          });
        }
      }

      current = exclusiveTaskText !== null
        ? MCPV5FitContext(exclusiveTaskText, original)
        : MCPV5ComposeContextProposals(
            original,
            proposals,
            plan
          );
    }
  } else if (tab === "output") {
    if (!transaction && schedule && schedule.commandOwner === "realmheart") {
      // Discard the generated acknowledgement; show the exact answer created
      // by RealmHeart v2.5 in Input. Skip all narrative/protocol decorators.
      current = MCPV5RealmHeartReplyForAction(root, schedule) || original;
      root.realmheartCommand = null;
    } else if (
      !transaction &&
      schedule &&
      schedule.commandOwner === "living_meters" &&
      order.includes("living_meters")
    ) {
      // LM control output bypasses protocol consumers and narrative decorators.
      const result = execute("living_meters", original);
      if (
        result &&
        result.__mcpOk === true &&
        typeof result.text === "string"
      ) {
        current = MCPV5ApplyOutputGuard(
          "living_meters",
          result.text,
          original,
          original
        );
        stopped = result.stop === true;
      }
    } else if (transaction) {
      const result = execute(transaction.owner, original);
      if (
        result &&
        result.__mcpOk === true &&
        typeof result.text === "string"
      ) {
        current = MCPV5ApplyOutputGuard(
          transaction.owner,
          result.text,
          original,
          original
        );
        stopped = result.stop === true;
      } else if (
        transaction.owner === "inner_self" &&
        state.InnerSelf &&
        typeof state.InnerSelf === "object"
      ) {
        state.InnerSelf.agent = "";
      }
    } else {
      const protocolSet = new Set([
        "inner_self",
        "auto_cards",
        "living_characters",
        "story_arc_engine",
        "character_continuity"
      ]);
      const protocol = order.filter(id => protocolSet.has(id));
      const finalFilterOrder = ["ar", "usc_e"].filter(id => order.includes(id));
      const finalFilterSet = new Set(finalFilterOrder);
      const slowBurnSelected = order.includes("slow_burn");
      const outcomeRollId = (
        plan.outcomeRollAuthority &&
        order.includes(plan.outcomeRollAuthority)
      ) ? plan.outcomeRollAuthority : "";
      const observers = order.filter(id => (
        !protocolSet.has(id) &&
        !finalFilterSet.has(id) &&
        id !== "slow_burn" &&
        id !== "dice_roll" &&
        id !== "coin_flip"
      ));

      // Protocol consumers are intentionally chained: each removes only its
      // own machine envelope before the next consumer sees the response.
      let protocolText = original;
      for (let i = 0; i < protocol.length; i++) {
        const id = protocol[i];
        const before = protocolText;
        const result = execute(id, protocolText);
        if (
          result &&
          result.__mcpOk === true &&
          typeof result.text === "string"
        ) {
          protocolText = MCPV5ApplyOutputGuard(
            id,
            result.text,
            before,
            original
          );
          if (result.stop === true) {
            stopped = true;
            break;
          }
        }
      }

      const proposals = [];
      if (!stopped) {
        for (let i = 0; i < observers.length; i++) {
          const id = observers[i];
          const result = execute(id, protocolText);
          if (
            result &&
            result.__mcpOk === true &&
            typeof result.text === "string"
          ) {
            proposals.push({
              id,
              index: i,
              text: result.text
            });
            if (result.stop === true) stopped = true;
          }
        }
      }

      current = MCPV5SelectOutputProposal(
        protocolText,
        proposals,
        plan,
        schedule.commandOwner || ""
      );

      // RealmHeart's world-state block is hidden Context. If the model ever
      // echoes the exact block anyway, remove only that stored block before
      // visible-text cleanup filters run.
      current = MCPV5StripRealmHeartContextLeak(
        current,
        plan
      );

      // AR and USC-E are final visible-text filters. They run only after
      // protocol consumers and ordinary Output arbitration, so neither can
      // corrupt Inner Self/Auto-Cards/LC/SAE/CC machine envelopes.
      if (!stopped) {
        for (let i = 0; i < finalFilterOrder.length; i++) {
          const id = finalFilterOrder[i];
          const before = current;
          const result = execute(id, current);
          if (
            result &&
            result.__mcpOk === true &&
            typeof result.text === "string"
          ) {
            current = MCPV5ApplyOutputGuard(
              id,
              result.text,
              before,
              original
            );
            if (result.stop === true) {
              stopped = true;
              break;
            }
          }
        }
      }

      // Slow Burn scores only the cleaned visible narrative. Its host wrapper
      // keeps state.npc private and publishes only its owned Author's Note marker.
      if (!stopped && slowBurnSelected) {
        const before = current;
        const result = execute("slow_burn", current);
        if (
          result &&
          result.__mcpOk === true &&
          typeof result.text === "string"
        ) {
          current = MCPV5ApplyOutputGuard(
            "slow_burn",
            result.text,
            before,
            original
          );
          if (result.stop === true) stopped = true;
        }
      }

      // Dice Roll and Coin Flip compete for one Outcome Roll capability. Only
      // the elected authority may decorate a normal visible story response.
      const gambleRecord = root.realmheartGambleAction;
      const realmheartGambleTurn = !!(
        plan.effective && plan.effective.realmheart === true &&
        gambleRecord &&
        gambleRecord.action === schedule.action &&
        gambleRecord.signature === schedule.signature
      );
      if (!stopped && outcomeRollId && !realmheartGambleTurn) {
        const before = current;
        const result = execute(outcomeRollId, current);
        if (
          result &&
          result.__mcpOk === true &&
          typeof result.text === "string"
        ) {
          current = MCPV5ApplyOutputGuard(
            outcomeRollId,
            result.text,
            before,
            original
          );
          if (result.stop === true) stopped = true;
        }
      }
    }
  }

  // The sequential path does not pass through the cooperative Output broker.
  // Preserve the RealmHeart world-state echo guard for RealmHeart-only setups.
  if (
    tab === "output" && !plan.cooperative &&
    plan.effective && plan.effective.realmheart === true &&
    !realmheartControlStage && !transaction
  ) {
    current = MCPV5StripRealmHeartContextLeak(current, plan);
  }

  if (plan.cooperative && sharedBase) {
    MCPV5RestoreSharedState(sharedBase);
    MCPV5CommitSharedState(sharedBase, sharedRecords, plan);
    MCPV5TrackSharedMemoryOwnership(sharedBase, sharedRecords);
  }

  MCPV5MarkScheduleStage(schedule, tab);

  const transactionDeferred = transaction
    ? schedule.modules.filter(id => id !== transaction.owner)
    : [];
  const skipped = MCPV5UniqueStrings(
    (schedule.skipped || [])
      .concat(transactionDeferred)
      .filter(id => !transaction || id !== transaction.owner)
  );

  if (transaction && tab === "context") {
    MCPV5RegisterTransaction(transaction, tab);
  } else if (tab === "output") {
    if (transaction) MCPV5ClearTransaction(transaction.owner);
    MCPV5FinalizeInventoryLedger(plan);
  }

  if (skipped.length) {
    MCPV5RecordDiagnostic(
      transaction ? "transaction-deferral" : "action-workload-plan",
      tab + " deferred: " + skipped.map(MCPV5Name).join(", ")
    );
  }

  root.lastRun = {
    action: Number.isFinite(info && info.actionCount)
      ? info.actionCount
      : -1,
    build: MCPV5_BUILD_VERSION,
    tab,
    elapsedMs: Math.max(0, Date.now() - startedAt),
    transaction: transaction ? transaction.name : "",
    ran: ran.slice(0, 16),
    failed: failed.slice(0, 16),
    skipped: skipped.slice(0, 16),
    actionModules: schedule.modules.slice(0, 16),
    commandOwner: schedule.commandOwner || "",
    commandHint: schedule.commandHint || ""
  };

  const finalText = tab === "output" && !MCPV5HasVisibleText(current)
    ? original
    : MCPV5SafeText(current, original);

  MCPV5TrackActionHealth(
    tab, plan, schedule, ran, failed, skipped,
    root.lastRun.elapsedMs
  );
  MCPV5NormalizeSharedPersistentState();
  MCPV5NormalizeHostState();

  return stopped
    ? { text: String(finalText), stop: true }
    : { text: String(finalText) };
}

try {
  MCPV5SyncControls();
} catch (error) {
  log("MCP V5.4.0 initialization error:", error);
}
